-- ============================================================================
-- IBM Db2 (LUW) ERP demo seed  --  SQL PL
-- Schema: DB2INST1   Container: db2   Database: anlzdb   User: db2inst1
-- Entry procedure for static analysis: ERP_USP_RUN_CYCLE
--
-- Loader:
--   db2 connect to anlzdb
--   db2 -td@ -f db2.sql        (statement terminator is '@')
--
-- Idempotent: every CREATE is preceded by a DROP.  On a first run the DROP
-- statements fail because the object does not yet exist; that is EXPECTED and
-- non-fatal -- the CLP reports the error and continues.  Safe to re-run.
--
-- Deep call chain (depth >= 12) for a rich static-analysis tree:
--   ERP_USP_RUN_CYCLE
--     -> ERP_USP_PROCESS_DAY
--          -> ERP_USP_PROCESS_ORDERS
--               -> ERP_USP_PROCESS_ORDER
--                    -> ERP_USP_ALLOCATE_INVENTORY
--                         -> ERP_USP_RESERVE_STOCK
--                              -> ERP_USP_REPLENISH_STOCK
--                                   -> ERP_USP_CREATE_WORK_ORDER
--                                        -> ERP_USP_SCHEDULE_OPS
--                                             -> ERP_USP_CREATE_SHIPMENT
--                                                  -> ERP_USP_CREATE_INVOICE
--                                                       -> ERP_USP_POST_GL
--                                                            -> ERP_USP_APPLY_PAYMENT
--                                   -> ERP_USP_PROCURE_MATERIAL
-- Plus scalar functions (ERP_FN_*), a MODULE (ERP_MOD_PRICING), triggers,
-- views, MQTs, sequences and global variables.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- DROP existing objects (errors on first run are expected / non-fatal)
-- ---------------------------------------------------------------------------
-- module
DROP MODULE ERP_MOD_PRICING @
-- triggers
DROP TRIGGER ERP_TRG_SO_BI @
DROP TRIGGER ERP_TRG_SO_AU @
DROP TRIGGER ERP_TRG_INV_TXN_AI @
DROP TRIGGER ERP_TRG_GL_ENTRY_BI @
DROP TRIGGER ERP_TRG_AUDIT_STMT_AI @
DROP TRIGGER ERP_TRG_INVOICE_AU @
-- cross-schema ERP_REF objects (drop before primary-schema objects)
DROP TRIGGER ERP_REF.TRG_REF_REGION @
DROP PROCEDURE DB2INST1.ERP_USP_XSCHEMA_TOUCH @
DROP PROCEDURE ERP_REF.USP_REF_LOG @
DROP FUNCTION ERP_REF.FN_REGION_NAME @
DROP VIEW ERP_REF.VW_REGION @
DROP TABLE ERP_REF.REF_REGION @
DROP TABLE ERP_REF.REF_AUDIT @
DROP SCHEMA ERP_REF RESTRICT @
-- MQTs and views
DROP TABLE ERP_MQT_CUSTOMER_REV @
DROP TABLE ERP_MQT_PRODUCT_MARGIN @
DROP VIEW ERP_VW_ORDER_SUMMARY @
DROP VIEW ERP_VW_OPEN_AR @
DROP VIEW ERP_VW_INVENTORY_STATUS @
-- procedures
DROP PROCEDURE ERP_USP_RUN_CYCLE @
DROP PROCEDURE ERP_USP_STAGE_01 @
DROP PROCEDURE ERP_USP_STAGE_02 @
DROP PROCEDURE ERP_USP_STAGE_03 @
DROP PROCEDURE ERP_USP_STAGE_04 @
DROP PROCEDURE ERP_USP_STAGE_05 @
DROP PROCEDURE ERP_USP_STAGE_06 @
DROP PROCEDURE ERP_USP_STAGE_07 @
DROP PROCEDURE ERP_USP_STAGE_08 @
DROP PROCEDURE ERP_USP_STAGE_09 @
DROP PROCEDURE ERP_USP_STAGE_10 @
DROP PROCEDURE ERP_USP_STAGE_11 @
DROP PROCEDURE ERP_USP_STAGE_12 @
DROP PROCEDURE ERP_USP_STAGE_13 @
DROP PROCEDURE ERP_USP_STAGE_14 @
DROP PROCEDURE ERP_USP_STAGE_15 @
DROP PROCEDURE ERP_USP_STAGE_16 @
DROP PROCEDURE ERP_USP_PROCESS_DAY @
DROP PROCEDURE ERP_USP_PROCESS_ORDERS @
DROP PROCEDURE ERP_USP_PROCESS_ORDER @
DROP PROCEDURE ERP_USP_ALLOCATE_INVENTORY @
DROP PROCEDURE ERP_USP_RESERVE_STOCK @
DROP PROCEDURE ERP_USP_REPLENISH_STOCK @
DROP PROCEDURE ERP_USP_CREATE_WORK_ORDER @
DROP PROCEDURE ERP_USP_SCHEDULE_OPS @
DROP PROCEDURE ERP_USP_PROCURE_MATERIAL @
DROP PROCEDURE ERP_USP_CREATE_SHIPMENT @
DROP PROCEDURE ERP_USP_CREATE_INVOICE @
DROP PROCEDURE ERP_USP_POST_GL @
DROP PROCEDURE ERP_USP_APPLY_PAYMENT @
DROP PROCEDURE ERP_USP_EDGE_OPS @
DROP PROCEDURE ERP_USP_RECONCILE_GL @
DROP PROCEDURE ERP_USP_CLOSE_PERIOD @
DROP PROCEDURE ERP_USP_REBUILD_MQT @
DROP PROCEDURE ERP_USP_ARCHIVE_AUDIT @
DROP PROCEDURE ERP_USP_EXPLODE_BOM @
DROP PROCEDURE ERP_USP_WALK_UP @
DROP PROCEDURE ERP_USP_WALK_DOWN @
DROP PROCEDURE ERP_USP_REPORT_AR @
DROP PROCEDURE ERP_USP_AUDIT @
-- functions
DROP FUNCTION ERP_FN_LINE_TOTAL @
DROP FUNCTION ERP_FN_ORDER_SUBTOTAL @
DROP FUNCTION ERP_FN_TAX @
DROP FUNCTION ERP_FN_FX_CONVERT @
DROP FUNCTION ERP_FN_DISCOUNT_PCT @
DROP FUNCTION ERP_FN_CREDIT_OK @
DROP FUNCTION ERP_FN_CUSTOMER_BALANCE @
DROP FUNCTION ERP_FN_MARGIN @
DROP FUNCTION ERP_FN_BOM_COST @
DROP FUNCTION ERP_FN_INVENTORY_ONHAND @
DROP FUNCTION ERP_FN_REORDER_QTY @
DROP FUNCTION ERP_FN_FISCAL_PERIOD @
DROP FUNCTION ERP_FN_BOM_DEPTH @
-- sequences
DROP SEQUENCE ERP_SEQ_ORDER @
DROP SEQUENCE ERP_SEQ_INVOICE @
DROP SEQUENCE ERP_SEQ_WORK_ORDER @
DROP SEQUENCE ERP_SEQ_PO @
-- global variables
DROP VARIABLE ERP_GV_RUN_ID @
DROP VARIABLE ERP_GV_BASE_CCY @
DROP VARIABLE ERP_GV_TENANT @
-- tables
DROP TABLE ERP_SHIPMENT_LINE @
DROP TABLE ERP_SHIPMENT @
DROP TABLE ERP_CARRIER @
DROP TABLE ERP_PAYMENT_ALLOC @
DROP TABLE ERP_PAYMENT @
DROP TABLE ERP_INVOICE @
DROP TABLE ERP_GL_ENTRY @
DROP TABLE ERP_GL_ACCOUNT @
DROP TABLE ERP_PO_LINE @
DROP TABLE ERP_PURCHASE_ORDER @
DROP TABLE ERP_WORK_ORDER @
DROP TABLE ERP_INVENTORY_TXN @
DROP TABLE ERP_INVENTORY @
DROP TABLE ERP_LOCATION @
DROP TABLE ERP_WAREHOUSE @
DROP TABLE ERP_BOM @
DROP TABLE ERP_RAW_MATERIAL @
DROP TABLE ERP_SUPPLIER @
DROP TABLE ERP_PRODUCT_PRICE @
DROP TABLE ERP_PRICE_LIST @
DROP TABLE ERP_SALES_ORDER_LINE @
DROP TABLE ERP_SALES_ORDER @
DROP TABLE ERP_PRODUCT @
DROP TABLE ERP_PRODUCT_CATEGORY @
DROP TABLE ERP_EMPLOYEE @
DROP TABLE ERP_DEPARTMENT @
DROP TABLE ERP_CUSTOMER @
DROP TABLE ERP_EXCHANGE_RATE @
DROP TABLE ERP_TAX_RATE @
DROP TABLE ERP_CURRENCY @
DROP TABLE ERP_COUNTRY @
DROP TABLE ERP_AUDIT_LOG @

-- ---------------------------------------------------------------------------
-- SEQUENCES
-- ---------------------------------------------------------------------------
CREATE SEQUENCE ERP_SEQ_ORDER      AS INTEGER START WITH 1000 INCREMENT BY 1 NO CYCLE CACHE 20 @
CREATE SEQUENCE ERP_SEQ_INVOICE    AS INTEGER START WITH 5000 INCREMENT BY 1 NO CYCLE CACHE 20 @
CREATE SEQUENCE ERP_SEQ_WORK_ORDER AS INTEGER START WITH 7000 INCREMENT BY 1 NO CYCLE CACHE 20 @
CREATE SEQUENCE ERP_SEQ_PO         AS INTEGER START WITH 9000 INCREMENT BY 1 NO CYCLE CACHE 20 @

-- ---------------------------------------------------------------------------
-- GLOBAL VARIABLES (session/global scope, contrast with block-local DECLARE)
-- ---------------------------------------------------------------------------
CREATE VARIABLE ERP_GV_RUN_ID   INTEGER      DEFAULT 0 @
CREATE VARIABLE ERP_GV_BASE_CCY INTEGER      DEFAULT 1 @
CREATE VARIABLE ERP_GV_TENANT   VARCHAR(20)  DEFAULT 'DEFAULT' @

-- ---------------------------------------------------------------------------
-- TABLES (~32 erp_* tables with PK / FK / indexes)
-- ---------------------------------------------------------------------------
CREATE TABLE ERP_COUNTRY (
    id          INTEGER NOT NULL PRIMARY KEY,
    iso_code    VARCHAR(3),
    name        VARCHAR(80),
    region      VARCHAR(40)
) @

CREATE TABLE ERP_CURRENCY (
    id          INTEGER NOT NULL PRIMARY KEY,
    iso_code    VARCHAR(3),
    name        VARCHAR(60)
) @

CREATE TABLE ERP_EXCHANGE_RATE (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    from_ccy    INTEGER NOT NULL,
    to_ccy      INTEGER NOT NULL,
    rate        DECIMAL(16,6) DEFAULT 1,
    rate_date   DATE,
    CONSTRAINT fk_fxr_from FOREIGN KEY (from_ccy) REFERENCES ERP_CURRENCY(id),
    CONSTRAINT fk_fxr_to   FOREIGN KEY (to_ccy)   REFERENCES ERP_CURRENCY(id)
) @

CREATE TABLE ERP_TAX_RATE (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    country_id  INTEGER NOT NULL,
    rate        DECIMAL(6,4) DEFAULT 0,
    CONSTRAINT fk_tax_ctry FOREIGN KEY (country_id) REFERENCES ERP_COUNTRY(id)
) @

CREATE TABLE ERP_DEPARTMENT (
    id          INTEGER NOT NULL PRIMARY KEY,
    parent_id   INTEGER,
    name        VARCHAR(80),
    CONSTRAINT fk_dept_parent FOREIGN KEY (parent_id) REFERENCES ERP_DEPARTMENT(id)
) @

CREATE TABLE ERP_EMPLOYEE (
    id          INTEGER NOT NULL PRIMARY KEY,
    dept_id     INTEGER,
    name        VARCHAR(120),
    manager_id  INTEGER,
    salary      DECIMAL(14,2) DEFAULT 0,
    CONSTRAINT fk_emp_dept FOREIGN KEY (dept_id) REFERENCES ERP_DEPARTMENT(id)
) @

CREATE TABLE ERP_CUSTOMER (
    id            INTEGER NOT NULL PRIMARY KEY,
    name          VARCHAR(120),
    country_id    INTEGER,
    credit_limit  DECIMAL(16,2) DEFAULT 0,
    CONSTRAINT fk_cust_ctry FOREIGN KEY (country_id) REFERENCES ERP_COUNTRY(id)
) @

CREATE TABLE ERP_PRODUCT_CATEGORY (
    id          INTEGER NOT NULL PRIMARY KEY,
    name        VARCHAR(80),
    parent_id   INTEGER
) @

CREATE TABLE ERP_PRODUCT (
    id              INTEGER NOT NULL PRIMARY KEY,
    sku             VARCHAR(40),
    name            VARCHAR(120),
    category_id     INTEGER,
    std_cost        DECIMAL(16,2) DEFAULT 0,
    list_price      DECIMAL(16,2) DEFAULT 0,
    is_manufactured SMALLINT DEFAULT 0,
    reorder_point   DECIMAL(16,4) DEFAULT 0,
    CONSTRAINT fk_prod_cat FOREIGN KEY (category_id) REFERENCES ERP_PRODUCT_CATEGORY(id)
) @

CREATE TABLE ERP_PRICE_LIST (
    id          INTEGER NOT NULL PRIMARY KEY,
    name        VARCHAR(80),
    ccy_id      INTEGER,
    CONSTRAINT fk_pl_ccy FOREIGN KEY (ccy_id) REFERENCES ERP_CURRENCY(id)
) @

CREATE TABLE ERP_PRODUCT_PRICE (
    id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    product_id    INTEGER NOT NULL,
    price_list_id INTEGER NOT NULL,
    price         DECIMAL(14,2) DEFAULT 0,
    CONSTRAINT fk_pp_prod FOREIGN KEY (product_id)    REFERENCES ERP_PRODUCT(id),
    CONSTRAINT fk_pp_pl   FOREIGN KEY (price_list_id) REFERENCES ERP_PRICE_LIST(id)
) @

CREATE TABLE ERP_SALES_ORDER (
    id           INTEGER NOT NULL PRIMARY KEY,
    customer_id  INTEGER,
    ccy_id       INTEGER,
    order_date   DATE,
    subtotal     DECIMAL(16,2) DEFAULT 0,
    tax          DECIMAL(16,2) DEFAULT 0,
    status       VARCHAR(20) DEFAULT 'NEW',
    CONSTRAINT fk_so_cust FOREIGN KEY (customer_id) REFERENCES ERP_CUSTOMER(id),
    CONSTRAINT fk_so_ccy  FOREIGN KEY (ccy_id)      REFERENCES ERP_CURRENCY(id)
) @

CREATE TABLE ERP_SALES_ORDER_LINE (
    id           INTEGER NOT NULL PRIMARY KEY,
    so_id        INTEGER,
    product_id   INTEGER,
    qty          DECIMAL(16,2) DEFAULT 1,
    unit_price   DECIMAL(16,2) DEFAULT 0,
    discount_pct DECIMAL(16,2) DEFAULT 0,
    CONSTRAINT fk_sol_so   FOREIGN KEY (so_id)      REFERENCES ERP_SALES_ORDER(id),
    CONSTRAINT fk_sol_prod FOREIGN KEY (product_id) REFERENCES ERP_PRODUCT(id)
) @

CREATE TABLE ERP_WAREHOUSE (
    id          INTEGER NOT NULL PRIMARY KEY,
    code        VARCHAR(20),
    country_id  INTEGER,
    CONSTRAINT fk_wh_ctry FOREIGN KEY (country_id) REFERENCES ERP_COUNTRY(id)
) @

CREATE TABLE ERP_LOCATION (
    id           INTEGER NOT NULL PRIMARY KEY,
    warehouse_id INTEGER,
    code         VARCHAR(20),
    CONSTRAINT fk_loc_wh FOREIGN KEY (warehouse_id) REFERENCES ERP_WAREHOUSE(id)
) @

CREATE TABLE ERP_INVENTORY (
    id           INTEGER NOT NULL PRIMARY KEY,
    product_id   INTEGER,
    location_id  INTEGER,
    on_hand      DECIMAL(16,4) DEFAULT 0,
    reserved     DECIMAL(16,4) DEFAULT 0,
    CONSTRAINT fk_inv_prod FOREIGN KEY (product_id)  REFERENCES ERP_PRODUCT(id),
    CONSTRAINT fk_inv_loc  FOREIGN KEY (location_id) REFERENCES ERP_LOCATION(id)
) @

CREATE TABLE ERP_INVENTORY_TXN (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    inventory_id INTEGER,
    txn_type     VARCHAR(20),
    qty          DECIMAL(16,4) DEFAULT 0,
    txn_ts       TIMESTAMP DEFAULT CURRENT TIMESTAMP,
    CONSTRAINT fk_itxn_inv FOREIGN KEY (inventory_id) REFERENCES ERP_INVENTORY(id)
) @

CREATE TABLE ERP_SUPPLIER (
    id          INTEGER NOT NULL PRIMARY KEY,
    name        VARCHAR(120),
    country_id  INTEGER,
    CONSTRAINT fk_sup_ctry FOREIGN KEY (country_id) REFERENCES ERP_COUNTRY(id)
) @

CREATE TABLE ERP_RAW_MATERIAL (
    id           INTEGER NOT NULL PRIMARY KEY,
    name         VARCHAR(120),
    supplier_id  INTEGER,
    unit_cost    DECIMAL(14,4) DEFAULT 0,
    CONSTRAINT fk_rm_sup FOREIGN KEY (supplier_id) REFERENCES ERP_SUPPLIER(id)
) @

CREATE TABLE ERP_BOM (
    id              INTEGER NOT NULL PRIMARY KEY,
    product_id      INTEGER,
    raw_material_id INTEGER,
    parent_bom_id   INTEGER,
    qty_per         DECIMAL(14,4) DEFAULT 0,
    CONSTRAINT fk_bom_prod FOREIGN KEY (product_id)      REFERENCES ERP_PRODUCT(id),
    CONSTRAINT fk_bom_rm   FOREIGN KEY (raw_material_id) REFERENCES ERP_RAW_MATERIAL(id)
) @

CREATE TABLE ERP_PURCHASE_ORDER (
    id           INTEGER NOT NULL PRIMARY KEY,
    supplier_id  INTEGER,
    order_date   DATE,
    status       VARCHAR(20) DEFAULT 'OPEN',
    CONSTRAINT fk_po_sup FOREIGN KEY (supplier_id) REFERENCES ERP_SUPPLIER(id)
) @

CREATE TABLE ERP_PO_LINE (
    id              INTEGER NOT NULL PRIMARY KEY,
    po_id           INTEGER,
    raw_material_id INTEGER,
    qty             DECIMAL(16,4) DEFAULT 0,
    unit_cost       DECIMAL(14,4) DEFAULT 0,
    CONSTRAINT fk_pol_po FOREIGN KEY (po_id)           REFERENCES ERP_PURCHASE_ORDER(id),
    CONSTRAINT fk_pol_rm FOREIGN KEY (raw_material_id) REFERENCES ERP_RAW_MATERIAL(id)
) @

CREATE TABLE ERP_WORK_ORDER (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    product_id   INTEGER,
    qty          DECIMAL(16,4) DEFAULT 0,
    status       VARCHAR(20) DEFAULT 'OPEN',
    start_date   DATE,
    CONSTRAINT fk_wo_prod FOREIGN KEY (product_id) REFERENCES ERP_PRODUCT(id)
) @

CREATE TABLE ERP_GL_ACCOUNT (
    id          INTEGER NOT NULL PRIMARY KEY,
    code        VARCHAR(10),
    name        VARCHAR(120),
    acct_type   VARCHAR(20)
) @

CREATE TABLE ERP_GL_ENTRY (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    account_id  INTEGER,
    entry_date  DATE,
    debit       DECIMAL(18,2) DEFAULT 0,
    credit      DECIMAL(18,2) DEFAULT 0,
    ref_doc     INTEGER,
    memo        VARCHAR(200),
    CONSTRAINT fk_gle_acct FOREIGN KEY (account_id) REFERENCES ERP_GL_ACCOUNT(id)
) @

CREATE TABLE ERP_INVOICE (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    so_id        INTEGER,
    invoice_date DATE,
    amount       DECIMAL(16,2) DEFAULT 0,
    tax          DECIMAL(16,2) DEFAULT 0,
    status       VARCHAR(20) DEFAULT 'OPEN',
    CONSTRAINT fk_inv_so FOREIGN KEY (so_id) REFERENCES ERP_SALES_ORDER(id)
) @

CREATE TABLE ERP_PAYMENT (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id  INTEGER,
    pay_date     DATE,
    amount       DECIMAL(16,2) DEFAULT 0,
    CONSTRAINT fk_pay_cust FOREIGN KEY (customer_id) REFERENCES ERP_CUSTOMER(id)
) @

CREATE TABLE ERP_PAYMENT_ALLOC (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    payment_id  INTEGER,
    invoice_id  INTEGER,
    amount      DECIMAL(16,2) DEFAULT 0,
    CONSTRAINT fk_pa_pay FOREIGN KEY (payment_id) REFERENCES ERP_PAYMENT(id),
    CONSTRAINT fk_pa_inv FOREIGN KEY (invoice_id) REFERENCES ERP_INVOICE(id)
) @

CREATE TABLE ERP_CARRIER (
    id          INTEGER NOT NULL PRIMARY KEY,
    name        VARCHAR(80),
    scac        VARCHAR(10)
) @

CREATE TABLE ERP_SHIPMENT (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    so_id        INTEGER,
    carrier_id   INTEGER,
    ship_date    DATE,
    status       VARCHAR(20) DEFAULT 'PENDING',
    CONSTRAINT fk_sh_so  FOREIGN KEY (so_id)      REFERENCES ERP_SALES_ORDER(id),
    CONSTRAINT fk_sh_car FOREIGN KEY (carrier_id) REFERENCES ERP_CARRIER(id)
) @

CREATE TABLE ERP_SHIPMENT_LINE (
    id           INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    shipment_id  INTEGER,
    product_id   INTEGER,
    qty_shipped  DECIMAL(16,4) DEFAULT 0,
    CONSTRAINT fk_shl_sh   FOREIGN KEY (shipment_id) REFERENCES ERP_SHIPMENT(id),
    CONSTRAINT fk_shl_prod FOREIGN KEY (product_id)  REFERENCES ERP_PRODUCT(id)
) @

CREATE TABLE ERP_AUDIT_LOG (
    audit_id   INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    entity     VARCHAR(60),
    entity_id  INTEGER,
    action     VARCHAR(30),
    detail     VARCHAR(400),
    logged_ts  TIMESTAMP DEFAULT CURRENT TIMESTAMP
) @

-- ---------------------------------------------------------------------------
-- INDEXES
-- ---------------------------------------------------------------------------
CREATE INDEX ERP_IX_SOL_SO ON ERP_SALES_ORDER_LINE(so_id) @
CREATE INDEX ERP_IX_SOL_PROD ON ERP_SALES_ORDER_LINE(product_id) @
CREATE INDEX ERP_IX_SO_CUST ON ERP_SALES_ORDER(customer_id) @
CREATE INDEX ERP_IX_INV_PROD ON ERP_INVENTORY(product_id) @
CREATE INDEX ERP_IX_INV_LOC ON ERP_INVENTORY(location_id) @
CREATE INDEX ERP_IX_GLE_ACCT ON ERP_GL_ENTRY(account_id) @
CREATE INDEX ERP_IX_INV_SO ON ERP_INVOICE(so_id) @
CREATE INDEX ERP_IX_PA_INV ON ERP_PAYMENT_ALLOC(invoice_id) @
CREATE INDEX ERP_IX_SHL_SH ON ERP_SHIPMENT_LINE(shipment_id) @
CREATE INDEX ERP_IX_BOM_PROD ON ERP_BOM(product_id) @
CREATE INDEX ERP_IX_EMP_DEPT ON ERP_EMPLOYEE(dept_id) @

