-- ---------------------------------------------------------------------------
-- SCALAR FUNCTIONS (ERP_FN_*)
-- ---------------------------------------------------------------------------
CREATE FUNCTION ERP_FN_LINE_TOTAL(p_qty DECIMAL(16,2), p_price DECIMAL(16,2), p_disc DECIMAL(16,2))
RETURNS DECIMAL(16,2)
LANGUAGE SQL
BEGIN ATOMIC
    RETURN COALESCE(p_qty,0) * COALESCE(p_price,0) * (1 - COALESCE(p_disc,0)/100);
END @

CREATE FUNCTION ERP_FN_ORDER_SUBTOTAL(p_so_id INTEGER)
RETURNS DECIMAL(16,2)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_total DECIMAL(16,2) DEFAULT 0;
    SET v_total = (SELECT COALESCE(SUM(ERP_FN_LINE_TOTAL(qty, unit_price, discount_pct)),0)
                   FROM ERP_SALES_ORDER_LINE WHERE so_id = p_so_id);
    RETURN v_total;
END @

CREATE FUNCTION ERP_FN_TAX(p_country_id INTEGER, p_amount DECIMAL(16,2))
RETURNS DECIMAL(16,2)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_rate DECIMAL(6,4) DEFAULT 0;
    SET v_rate = (SELECT COALESCE(MAX(rate),0) FROM ERP_TAX_RATE WHERE country_id = p_country_id);
    RETURN COALESCE(p_amount,0) * v_rate;
END @

CREATE FUNCTION ERP_FN_FX_CONVERT(p_from INTEGER, p_to INTEGER, p_amount DECIMAL(16,2))
RETURNS DECIMAL(16,2)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_rate DECIMAL(16,6) DEFAULT 1;
    IF p_from = p_to THEN RETURN p_amount; END IF;
    SET v_rate = (SELECT COALESCE(MAX(rate),1) FROM ERP_EXCHANGE_RATE
                  WHERE from_ccy = p_from AND to_ccy = p_to);
    RETURN CAST(COALESCE(p_amount,0) * v_rate AS DECIMAL(16,2));
END @

CREATE FUNCTION ERP_FN_DISCOUNT_PCT(p_customer_id INTEGER, p_qty DECIMAL(16,2))
RETURNS DECIMAL(16,2)
LANGUAGE SQL
BEGIN ATOMIC
    RETURN CASE
             WHEN p_qty >= 50 THEN 20
             WHEN p_qty >= 20 THEN 15
             WHEN p_qty >= 10 THEN 10
             ELSE 0
           END;
END @

CREATE FUNCTION ERP_FN_CUSTOMER_BALANCE(p_customer_id INTEGER)
RETURNS DECIMAL(18,2)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_inv DECIMAL(18,2) DEFAULT 0;
    DECLARE v_paid DECIMAL(18,2) DEFAULT 0;
    SET v_inv = (SELECT COALESCE(SUM(i.amount + i.tax),0)
                 FROM ERP_INVOICE i
                 JOIN ERP_SALES_ORDER so ON so.id = i.so_id
                 WHERE so.customer_id = p_customer_id);
    SET v_paid = (SELECT COALESCE(SUM(pa.amount),0)
                  FROM ERP_PAYMENT_ALLOC pa
                  JOIN ERP_PAYMENT p ON p.id = pa.payment_id
                  WHERE p.customer_id = p_customer_id);
    RETURN v_inv - v_paid;
END @

CREATE FUNCTION ERP_FN_CREDIT_OK(p_customer_id INTEGER, p_amount DECIMAL(16,2))
RETURNS SMALLINT
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_limit DECIMAL(16,2) DEFAULT 0;
    DECLARE v_bal DECIMAL(18,2) DEFAULT 0;
    SET v_limit = (SELECT COALESCE(credit_limit,0) FROM ERP_CUSTOMER WHERE id = p_customer_id);
    SET v_bal = ERP_FN_CUSTOMER_BALANCE(p_customer_id);
    IF v_bal + COALESCE(p_amount,0) <= v_limit THEN RETURN 1; END IF;
    RETURN 0;
END @

CREATE FUNCTION ERP_FN_MARGIN(p_product_id INTEGER)
RETURNS DECIMAL(16,4)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_cost DECIMAL(16,4) DEFAULT 0;
    DECLARE v_price DECIMAL(16,4) DEFAULT 0;
    SET v_cost = (SELECT COALESCE(std_cost,0) FROM ERP_PRODUCT WHERE id = p_product_id);
    SET v_price = (SELECT COALESCE(list_price,0) FROM ERP_PRODUCT WHERE id = p_product_id);
    IF v_price = 0 THEN RETURN 0; END IF;
    RETURN (v_price - v_cost) / v_price;
END @

CREATE FUNCTION ERP_FN_BOM_COST(p_product_id INTEGER)
RETURNS DECIMAL(18,4)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_cost DECIMAL(18,4) DEFAULT 0;
    SET v_cost = (SELECT COALESCE(SUM(b.qty_per * rm.unit_cost),0)
                  FROM ERP_BOM b
                  JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
                  WHERE b.product_id = p_product_id);
    RETURN v_cost;
END @

CREATE FUNCTION ERP_FN_INVENTORY_ONHAND(p_product_id INTEGER)
RETURNS DECIMAL(16,4)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_oh DECIMAL(16,4) DEFAULT 0;
    SET v_oh = (SELECT COALESCE(SUM(on_hand - reserved),0)
                FROM ERP_INVENTORY WHERE product_id = p_product_id);
    RETURN v_oh;
END @

CREATE FUNCTION ERP_FN_REORDER_QTY(p_product_id INTEGER, p_target DECIMAL(16,4))
RETURNS DECIMAL(16,4)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_avail DECIMAL(16,4) DEFAULT 0;
    SET v_avail = ERP_FN_INVENTORY_ONHAND(p_product_id);
    IF v_avail >= p_target THEN RETURN 0; END IF;
    RETURN CAST(p_target - v_avail AS DECIMAL(16,4));
END @

CREATE FUNCTION ERP_FN_FISCAL_PERIOD(p_d DATE)
RETURNS INTEGER
LANGUAGE SQL
BEGIN ATOMIC
    RETURN YEAR(p_d) * 100 + MONTH(p_d);
END @

CREATE FUNCTION ERP_FN_BOM_DEPTH(p_product_id INTEGER)
RETURNS INTEGER
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_depth INTEGER DEFAULT 0;
    DECLARE v_cur INTEGER DEFAULT 0;
    DECLARE v_next INTEGER DEFAULT 0;
    -- iterative (non-CTE) BOM descent, depth-guarded to 8 levels
    SET v_cur = (SELECT MIN(b.raw_material_id)
                 FROM ERP_BOM b
                 WHERE b.product_id = p_product_id AND b.parent_bom_id IS NULL);
    WHILE v_cur IS NOT NULL AND v_depth < 8 DO
        SET v_depth = v_depth + 1;
        SET v_next = (SELECT MIN(b2.raw_material_id)
                      FROM ERP_BOM b2 WHERE b2.parent_bom_id = v_cur);
        SET v_cur = v_next;
    END WHILE;
    RETURN v_depth;
END @

-- ---------------------------------------------------------------------------
-- VIEWS
-- ---------------------------------------------------------------------------
CREATE VIEW ERP_VW_ORDER_SUMMARY AS
    SELECT so.id AS so_id, so.customer_id, c.name AS customer_name,
           so.ccy_id, so.subtotal, so.tax,
           (so.subtotal + so.tax) AS gross_total, so.status
    FROM ERP_SALES_ORDER so
    JOIN ERP_CUSTOMER c ON c.id = so.customer_id @

CREATE VIEW ERP_VW_OPEN_AR AS
    SELECT i.id AS invoice_id, so.customer_id,
           i.amount + i.tax AS invoiced,
           COALESCE((SELECT SUM(pa.amount) FROM ERP_PAYMENT_ALLOC pa
                     WHERE pa.invoice_id = i.id),0) AS allocated
    FROM ERP_INVOICE i
    JOIN ERP_SALES_ORDER so ON so.id = i.so_id @

CREATE VIEW ERP_VW_INVENTORY_STATUS AS
    SELECT p.id AS product_id, p.sku,
           COALESCE(SUM(inv.on_hand),0) AS on_hand,
           COALESCE(SUM(inv.reserved),0) AS reserved,
           p.reorder_point
    FROM ERP_PRODUCT p
    LEFT JOIN ERP_INVENTORY inv ON inv.product_id = p.id
    GROUP BY p.id, p.sku, p.reorder_point @

-- ---------------------------------------------------------------------------
-- MATERIALIZED QUERY TABLES (MQTs ~ materialized views)
-- ---------------------------------------------------------------------------
CREATE TABLE ERP_MQT_CUSTOMER_REV AS (
    SELECT so.customer_id,
           COUNT(*) AS order_count,
           SUM(so.subtotal + so.tax) AS gross_revenue
    FROM ERP_SALES_ORDER so
    GROUP BY so.customer_id
) DATA INITIALLY DEFERRED REFRESH DEFERRED @

CREATE TABLE ERP_MQT_PRODUCT_MARGIN AS (
    SELECT p.id AS product_id,
           p.std_cost,
           p.list_price,
           (p.list_price - p.std_cost) AS unit_margin
    FROM ERP_PRODUCT p
) DATA INITIALLY DEFERRED REFRESH DEFERRED @

-- ---------------------------------------------------------------------------
-- TRIGGERS (BEFORE / AFTER, row-level and statement-level)
-- ---------------------------------------------------------------------------
CREATE TRIGGER ERP_TRG_SO_BI
    NO CASCADE BEFORE INSERT ON ERP_SALES_ORDER
    REFERENCING NEW AS n
    FOR EACH ROW
    WHEN (n.order_date IS NULL)
    SET n.order_date = CURRENT DATE @

CREATE TRIGGER ERP_TRG_SO_AU
    AFTER UPDATE OF status ON ERP_SALES_ORDER
    REFERENCING OLD AS o NEW AS n
    FOR EACH ROW
    WHEN (o.status <> n.status)
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('ERP_SALES_ORDER', n.id, 'STATUS',
            o.status || '->' || n.status, CURRENT TIMESTAMP) @

CREATE TRIGGER ERP_TRG_INV_TXN_AI
    AFTER INSERT ON ERP_INVENTORY_TXN
    REFERENCING NEW AS n
    FOR EACH ROW
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('ERP_INVENTORY_TXN', n.inventory_id, n.txn_type,
            'qty=' || RTRIM(CHAR(CAST(n.qty AS INTEGER))), CURRENT TIMESTAMP) @

CREATE TRIGGER ERP_TRG_GL_ENTRY_BI
    NO CASCADE BEFORE INSERT ON ERP_GL_ENTRY
    REFERENCING NEW AS n
    FOR EACH ROW
    WHEN (n.entry_date IS NULL)
    SET n.entry_date = CURRENT DATE @

CREATE TRIGGER ERP_TRG_AUDIT_STMT_AI
    AFTER INSERT ON ERP_GL_ENTRY
    REFERENCING NEW TABLE AS newrows
    FOR EACH STATEMENT
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    SELECT 'GL_BATCH', COUNT(*), 'POST',
           'batch debit=' || RTRIM(CHAR(CAST(COALESCE(SUM(debit),0) AS INTEGER))),
           CURRENT TIMESTAMP
    FROM newrows @

CREATE TRIGGER ERP_TRG_INVOICE_AU
    AFTER UPDATE OF status ON ERP_INVOICE
    REFERENCING OLD AS o NEW AS n
    FOR EACH ROW
    WHEN (o.status <> n.status)
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('ERP_INVOICE', n.id, 'STATUS', o.status || '->' || n.status, CURRENT TIMESTAMP) @

-- ---------------------------------------------------------------------------
-- PROCEDURES
-- ---------------------------------------------------------------------------
CREATE PROCEDURE ERP_USP_AUDIT(
    IN p_entity VARCHAR(60), IN p_entity_id INTEGER,
    IN p_action VARCHAR(30), IN p_detail VARCHAR(400))
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES (p_entity, p_entity_id, p_action, p_detail, CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_APPLY_PAYMENT(IN p_invoice_id INTEGER, IN p_amount DECIMAL(16,2))
LANGUAGE SQL
BEGIN
    DECLARE v_cust INTEGER DEFAULT 0;
    DECLARE v_pay_id INTEGER DEFAULT 0;
    DECLARE v_open DECIMAL(18,2) DEFAULT 0;
    DECLARE v_bal DECIMAL(18,2) DEFAULT 0;
    DECLARE SQLSTATE CHAR(5);
    DECLARE v_sqlcode INTEGER DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLWARNING
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PAYMENT', p_invoice_id, 'WARN', 'sql warning on apply', CURRENT TIMESTAMP);
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('PAYMENT', p_invoice_id, 'ERROR', 'apply payment failed');
    END;
    SAVEPOINT sp_pay ON ROLLBACK RETAIN CURSORS;
    SELECT so.customer_id INTO v_cust
    FROM ERP_INVOICE i JOIN ERP_SALES_ORDER so ON so.id = i.so_id
    WHERE i.id = p_invoice_id;
    INSERT INTO ERP_PAYMENT(customer_id, pay_date, amount)
    VALUES (v_cust, CURRENT DATE, p_amount);
    SET v_pay_id = IDENTITY_VAL_LOCAL();
    INSERT INTO ERP_PAYMENT_ALLOC(payment_id, invoice_id, amount)
    VALUES (v_pay_id, p_invoice_id, p_amount);
    SET v_bal = ERP_FN_CUSTOMER_BALANCE(v_cust);
    UPDATE ERP_INVOICE SET status = 'PAID' WHERE id = p_invoice_id;
    CALL ERP_USP_AUDIT('PAYMENT', p_invoice_id, 'APPLY', 'payment applied');
    -- order/customer/country/currency revenue scan [ap00]
    BEGIN
        DECLARE v_so_ap00 INTEGER DEFAULT 0;
        DECLARE v_cust_ap00 INTEGER DEFAULT 0;
        DECLARE v_ctry_ap00 INTEGER DEFAULT 0;
        DECLARE v_ccy_ap00 INTEGER DEFAULT 0;
        DECLARE v_sub_ap00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ap00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ap00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ap00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ap00 INTEGER DEFAULT 0;
        DECLARE v_done_ap00 INTEGER DEFAULT 0;
        DECLARE c_ap00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap00 = 1;
        OPEN c_ap00;
        loop_ap00: LOOP
            FETCH c_ap00 INTO v_so_ap00, v_cust_ap00, v_ctry_ap00, v_ccy_ap00, v_sub_ap00;
            IF v_done_ap00 = 1 THEN LEAVE loop_ap00; END IF;
            SET v_tax_ap00 = ERP_FN_TAX(v_ctry_ap00, v_sub_ap00);
            SET v_fx_ap00 = ERP_FN_FX_CONVERT(v_ccy_ap00, 1, v_sub_ap00 + v_tax_ap00);
            SET v_acc_ap00 = v_acc_ap00 + v_fx_ap00;
            SET v_cnt_ap00 = v_cnt_ap00 + 1;
        END LOOP;
        CLOSE c_ap00;
        IF v_cnt_ap00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ap00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ap00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ap01]
    BEGIN
        DECLARE v_pid_ap01 INTEGER DEFAULT 0;
        DECLARE v_oh_ap01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ap01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ap01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ap01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ap01 INTEGER DEFAULT 0;
        DECLARE c_ap01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap01 = 1;
        OPEN c_ap01;
        loop_ap01: LOOP
            FETCH c_ap01 INTO v_pid_ap01, v_oh_ap01, v_cost_ap01;
            IF v_done_ap01 = 1 THEN LEAVE loop_ap01; END IF;
            SET v_avail_ap01 = ERP_FN_INVENTORY_ONHAND(v_pid_ap01);
            SET v_val_ap01 = v_val_ap01 + CAST(COALESCE(v_oh_ap01,0) * COALESCE(v_cost_ap01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ap01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ap01;
        END LOOP;
        CLOSE c_ap01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ap01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ap02]
    BEGIN
        DECLARE v_prod_ap02 INTEGER DEFAULT 0;
        DECLARE v_rm_ap02 INTEGER DEFAULT 0;
        DECLARE v_supp_ap02 INTEGER DEFAULT 0;
        DECLARE v_qper_ap02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ap02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ap02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ap02 INTEGER DEFAULT 0;
        DECLARE c_ap02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap02 = 1;
        OPEN c_ap02;
        loop_ap02: LOOP
            FETCH c_ap02 INTO v_prod_ap02, v_rm_ap02, v_supp_ap02, v_qper_ap02, v_uc_ap02;
            IF v_done_ap02 = 1 THEN LEAVE loop_ap02; END IF;
            SET v_roll_ap02 = v_roll_ap02 + COALESCE(v_qper_ap02,0) * COALESCE(v_uc_ap02,0);
        END LOOP;
        CLOSE c_ap02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ap02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ap03]
    BEGIN
        DECLARE v_acct_ap03 INTEGER DEFAULT 0;
        DECLARE v_deb_ap03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ap03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ap03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap03 INTEGER DEFAULT 0;
        DECLARE c_ap03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap03 = 1;
        OPEN c_ap03;
        loop_ap03: LOOP
            FETCH c_ap03 INTO v_acct_ap03, v_deb_ap03, v_cred_ap03;
            IF v_done_ap03 = 1 THEN LEAVE loop_ap03; END IF;
            SET v_net_ap03 = v_net_ap03 + (v_deb_ap03 - v_cred_ap03);
        END LOOP;
        CLOSE c_ap03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ap03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ap04]
    BEGIN
        DECLARE v_pid_ap04 INTEGER DEFAULT 0;
        DECLARE v_lp_ap04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ap04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ap04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ap04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ap04 INTEGER DEFAULT 0;
        DECLARE c_ap04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap04 = 1;
        OPEN c_ap04;
        loop_ap04: LOOP
            FETCH c_ap04 INTO v_pid_ap04, v_lp_ap04, v_pp_ap04;
            IF v_done_ap04 = 1 THEN LEAVE loop_ap04; END IF;
            SET v_var_ap04 = v_var_ap04 + (COALESCE(v_lp_ap04,0) - COALESCE(v_pp_ap04,0));
            SET v_marg_ap04 = ERP_FN_MARGIN(v_pid_ap04);
        END LOOP;
        CLOSE c_ap04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ap04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ap05]
    BEGIN
        DECLARE v_inv_ap05 INTEGER DEFAULT 0;
        DECLARE v_amt_ap05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ap05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ap05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap05 INTEGER DEFAULT 0;
        DECLARE c_ap05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap05 = 1;
        OPEN c_ap05;
        loop_ap05: LOOP
            FETCH c_ap05 INTO v_inv_ap05, v_amt_ap05, v_alloc_ap05;
            IF v_done_ap05 = 1 THEN LEAVE loop_ap05; END IF;
            SET v_open_ap05 = v_open_ap05 + (v_amt_ap05 - v_alloc_ap05);
        END LOOP;
        CLOSE c_ap05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ap05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ap06]
    BEGIN
        DECLARE v_lvl_ap06 INTEGER DEFAULT 0;
        DECLARE v_dept_ap06 INTEGER DEFAULT 0;
        DECLARE v_head_ap06 INTEGER DEFAULT 0;
        DECLARE v_done_ap06 INTEGER DEFAULT 0;
        DECLARE c_ap06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap06 = 1;
        OPEN c_ap06;
        loop_ap06: LOOP
            FETCH c_ap06 INTO v_dept_ap06, v_lvl_ap06, v_head_ap06;
            IF v_done_ap06 = 1 THEN LEAVE loop_ap06; END IF;
        END LOOP;
        CLOSE c_ap06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ap06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ap06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ap07]
    BEGIN
        DECLARE v_sh_ap07 INTEGER DEFAULT 0;
        DECLARE v_car_ap07 INTEGER DEFAULT 0;
        DECLARE v_qty_ap07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ap07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ap07 INTEGER DEFAULT 0;
        DECLARE c_ap07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap07 = 1;
        OPEN c_ap07;
        loop_ap07: LOOP
            FETCH c_ap07 INTO v_sh_ap07, v_car_ap07, v_qty_ap07;
            IF v_done_ap07 = 1 THEN LEAVE loop_ap07; END IF;
            SET v_tot_ap07 = v_tot_ap07 + v_qty_ap07;
        END LOOP;
        CLOSE c_ap07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ap07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ap08]
    BEGIN
        DECLARE v_sql_ap08 VARCHAR(1000);
        DECLARE v_n_ap08 INTEGER DEFAULT 0;
        SET v_sql_ap08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ap08 FROM v_sql_ap08;
        EXECUTE st_ap08;
        SELECT COUNT(*) INTO v_n_ap08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ap08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ap09]
    BEGIN
        DECLARE v_key_ap09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ap09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ap09' AS VARCHAR(40)), v_key_ap09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ap10]
    BEGIN
        DECLARE v_so_ap10 INTEGER DEFAULT 0;
        DECLARE v_cust_ap10 INTEGER DEFAULT 0;
        DECLARE v_rk_ap10 INTEGER DEFAULT 0;
        DECLARE v_run_ap10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap10 INTEGER DEFAULT 0;
        DECLARE c_ap10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap10 = 1;
        OPEN c_ap10;
        loop_ap10: LOOP
            FETCH c_ap10 INTO v_so_ap10, v_cust_ap10, v_rk_ap10, v_run_ap10;
            IF v_done_ap10 = 1 THEN LEAVE loop_ap10; END IF;
        END LOOP;
        CLOSE c_ap10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ap10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ap10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ap11]
    BEGIN
        DECLARE v_hi_ap11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ap11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ap11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ap12]
    BEGIN
        DECLARE v_pairs_ap12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ap12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ap12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ap13]
    BEGIN
        DECLARE v_rows_ap13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ap13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ap13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ap13 FROM SESSION.TMP_ap13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ap13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ap14]
    BEGIN
        DECLARE v_rc_ap14 INTEGER DEFAULT 0;
        DECLARE v_band_ap14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ap14 = ROW_COUNT;
        SET v_band_ap14 = CASE
                            WHEN v_rc_ap14 = 0 THEN 'NONE'
                            WHEN v_rc_ap14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ap14, 'COUNT', 'band=' || v_band_ap14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ap15]
    BEGIN
        DECLARE v_i_ap15 INTEGER DEFAULT 0;
        SAVEPOINT sp_ap15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ap15 < 4 DO
            SET v_i_ap15 = v_i_ap15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ap15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ap15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ap15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ap16]
    BEGIN
        DECLARE v_j_ap16 INTEGER DEFAULT 0;
        DECLARE v_sum_ap16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ap16 = v_j_ap16 + 1;
        UNTIL v_j_ap16 >= 3 END REPEAT;
        FOR row_ap16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ap16 = v_sum_ap16 + COALESCE(row_ap16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ap16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ap16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ap17]
    BEGIN
        DECLARE v_n_ap17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ap17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ap17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [ap18]
    BEGIN
        DECLARE v_levels_ap18 INTEGER DEFAULT 0;
        DECLARE c_ap18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_ap18 = 0;
        OPEN c_ap18;
        FETCH c_ap18 INTO v_levels_ap18;
        CLOSE c_ap18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_ap18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ap19]
    BEGIN
        DECLARE v_sql_ap19 VARCHAR(1000);
        DECLARE v_n_ap19 INTEGER DEFAULT 0;
        SET v_sql_ap19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_ap19 FROM v_sql_ap19;
        EXECUTE st_ap19;
        SELECT COUNT(*) INTO v_n_ap19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ap19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ap20]
    BEGIN
        DECLARE v_key_ap20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ap20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ap20' AS VARCHAR(40)), v_key_ap20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [ap21]
    BEGIN
        DECLARE v_so_ap21 INTEGER DEFAULT 0;
        DECLARE v_cust_ap21 INTEGER DEFAULT 0;
        DECLARE v_ctry_ap21 INTEGER DEFAULT 0;
        DECLARE v_ccy_ap21 INTEGER DEFAULT 0;
        DECLARE v_sub_ap21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ap21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ap21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ap21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ap21 INTEGER DEFAULT 0;
        DECLARE v_done_ap21 INTEGER DEFAULT 0;
        DECLARE c_ap21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap21 = 1;
        OPEN c_ap21;
        loop_ap21: LOOP
            FETCH c_ap21 INTO v_so_ap21, v_cust_ap21, v_ctry_ap21, v_ccy_ap21, v_sub_ap21;
            IF v_done_ap21 = 1 THEN LEAVE loop_ap21; END IF;
            SET v_tax_ap21 = ERP_FN_TAX(v_ctry_ap21, v_sub_ap21);
            SET v_fx_ap21 = ERP_FN_FX_CONVERT(v_ccy_ap21, 1, v_sub_ap21 + v_tax_ap21);
            SET v_acc_ap21 = v_acc_ap21 + v_fx_ap21;
            SET v_cnt_ap21 = v_cnt_ap21 + 1;
        END LOOP;
        CLOSE c_ap21;
        IF v_cnt_ap21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ap21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ap21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ap22]
    BEGIN
        DECLARE v_pid_ap22 INTEGER DEFAULT 0;
        DECLARE v_oh_ap22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ap22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ap22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ap22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ap22 INTEGER DEFAULT 0;
        DECLARE c_ap22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap22 = 1;
        OPEN c_ap22;
        loop_ap22: LOOP
            FETCH c_ap22 INTO v_pid_ap22, v_oh_ap22, v_cost_ap22;
            IF v_done_ap22 = 1 THEN LEAVE loop_ap22; END IF;
            SET v_avail_ap22 = ERP_FN_INVENTORY_ONHAND(v_pid_ap22);
            SET v_val_ap22 = v_val_ap22 + CAST(COALESCE(v_oh_ap22,0) * COALESCE(v_cost_ap22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ap22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ap22;
        END LOOP;
        CLOSE c_ap22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ap22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ap23]
    BEGIN
        DECLARE v_prod_ap23 INTEGER DEFAULT 0;
        DECLARE v_rm_ap23 INTEGER DEFAULT 0;
        DECLARE v_supp_ap23 INTEGER DEFAULT 0;
        DECLARE v_qper_ap23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ap23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ap23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ap23 INTEGER DEFAULT 0;
        DECLARE c_ap23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap23 = 1;
        OPEN c_ap23;
        loop_ap23: LOOP
            FETCH c_ap23 INTO v_prod_ap23, v_rm_ap23, v_supp_ap23, v_qper_ap23, v_uc_ap23;
            IF v_done_ap23 = 1 THEN LEAVE loop_ap23; END IF;
            SET v_roll_ap23 = v_roll_ap23 + COALESCE(v_qper_ap23,0) * COALESCE(v_uc_ap23,0);
        END LOOP;
        CLOSE c_ap23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ap23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ap24]
    BEGIN
        DECLARE v_acct_ap24 INTEGER DEFAULT 0;
        DECLARE v_deb_ap24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ap24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ap24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap24 INTEGER DEFAULT 0;
        DECLARE c_ap24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap24 = 1;
        OPEN c_ap24;
        loop_ap24: LOOP
            FETCH c_ap24 INTO v_acct_ap24, v_deb_ap24, v_cred_ap24;
            IF v_done_ap24 = 1 THEN LEAVE loop_ap24; END IF;
            SET v_net_ap24 = v_net_ap24 + (v_deb_ap24 - v_cred_ap24);
        END LOOP;
        CLOSE c_ap24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ap24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ap25]
    BEGIN
        DECLARE v_pid_ap25 INTEGER DEFAULT 0;
        DECLARE v_lp_ap25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ap25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ap25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ap25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ap25 INTEGER DEFAULT 0;
        DECLARE c_ap25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap25 = 1;
        OPEN c_ap25;
        loop_ap25: LOOP
            FETCH c_ap25 INTO v_pid_ap25, v_lp_ap25, v_pp_ap25;
            IF v_done_ap25 = 1 THEN LEAVE loop_ap25; END IF;
            SET v_var_ap25 = v_var_ap25 + (COALESCE(v_lp_ap25,0) - COALESCE(v_pp_ap25,0));
            SET v_marg_ap25 = ERP_FN_MARGIN(v_pid_ap25);
        END LOOP;
        CLOSE c_ap25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ap25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ap26]
    BEGIN
        DECLARE v_inv_ap26 INTEGER DEFAULT 0;
        DECLARE v_amt_ap26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ap26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ap26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap26 INTEGER DEFAULT 0;
        DECLARE c_ap26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap26 = 1;
        OPEN c_ap26;
        loop_ap26: LOOP
            FETCH c_ap26 INTO v_inv_ap26, v_amt_ap26, v_alloc_ap26;
            IF v_done_ap26 = 1 THEN LEAVE loop_ap26; END IF;
            SET v_open_ap26 = v_open_ap26 + (v_amt_ap26 - v_alloc_ap26);
        END LOOP;
        CLOSE c_ap26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ap26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ap27]
    BEGIN
        DECLARE v_lvl_ap27 INTEGER DEFAULT 0;
        DECLARE v_dept_ap27 INTEGER DEFAULT 0;
        DECLARE v_head_ap27 INTEGER DEFAULT 0;
        DECLARE v_done_ap27 INTEGER DEFAULT 0;
        DECLARE c_ap27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap27 = 1;
        OPEN c_ap27;
        loop_ap27: LOOP
            FETCH c_ap27 INTO v_dept_ap27, v_lvl_ap27, v_head_ap27;
            IF v_done_ap27 = 1 THEN LEAVE loop_ap27; END IF;
        END LOOP;
        CLOSE c_ap27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ap27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ap27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ap28]
    BEGIN
        DECLARE v_sh_ap28 INTEGER DEFAULT 0;
        DECLARE v_car_ap28 INTEGER DEFAULT 0;
        DECLARE v_qty_ap28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ap28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ap28 INTEGER DEFAULT 0;
        DECLARE c_ap28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap28 = 1;
        OPEN c_ap28;
        loop_ap28: LOOP
            FETCH c_ap28 INTO v_sh_ap28, v_car_ap28, v_qty_ap28;
            IF v_done_ap28 = 1 THEN LEAVE loop_ap28; END IF;
            SET v_tot_ap28 = v_tot_ap28 + v_qty_ap28;
        END LOOP;
        CLOSE c_ap28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ap28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ap29]
    BEGIN
        DECLARE v_sql_ap29 VARCHAR(1000);
        DECLARE v_n_ap29 INTEGER DEFAULT 0;
        SET v_sql_ap29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ap29 FROM v_sql_ap29;
        EXECUTE st_ap29;
        SELECT COUNT(*) INTO v_n_ap29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ap29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ap30]
    BEGIN
        DECLARE v_key_ap30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ap30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ap30' AS VARCHAR(40)), v_key_ap30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ap31]
    BEGIN
        DECLARE v_so_ap31 INTEGER DEFAULT 0;
        DECLARE v_cust_ap31 INTEGER DEFAULT 0;
        DECLARE v_rk_ap31 INTEGER DEFAULT 0;
        DECLARE v_run_ap31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap31 INTEGER DEFAULT 0;
        DECLARE c_ap31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap31 = 1;
        OPEN c_ap31;
        loop_ap31: LOOP
            FETCH c_ap31 INTO v_so_ap31, v_cust_ap31, v_rk_ap31, v_run_ap31;
            IF v_done_ap31 = 1 THEN LEAVE loop_ap31; END IF;
        END LOOP;
        CLOSE c_ap31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ap31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ap31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ap32]
    BEGIN
        DECLARE v_hi_ap32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ap32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ap32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ap33]
    BEGIN
        DECLARE v_pairs_ap33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ap33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ap33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ap34]
    BEGIN
        DECLARE v_rows_ap34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ap34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ap34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ap34 FROM SESSION.TMP_ap34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ap34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ap35]
    BEGIN
        DECLARE v_rc_ap35 INTEGER DEFAULT 0;
        DECLARE v_band_ap35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ap35 = ROW_COUNT;
        SET v_band_ap35 = CASE
                            WHEN v_rc_ap35 = 0 THEN 'NONE'
                            WHEN v_rc_ap35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ap35, 'COUNT', 'band=' || v_band_ap35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ap36]
    BEGIN
        DECLARE v_i_ap36 INTEGER DEFAULT 0;
        SAVEPOINT sp_ap36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ap36 < 4 DO
            SET v_i_ap36 = v_i_ap36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ap36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ap36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ap36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ap37]
    BEGIN
        DECLARE v_j_ap37 INTEGER DEFAULT 0;
        DECLARE v_sum_ap37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ap37 = v_j_ap37 + 1;
        UNTIL v_j_ap37 >= 3 END REPEAT;
        FOR row_ap37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ap37 = v_sum_ap37 + COALESCE(row_ap37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ap37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ap37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ap38]
    BEGIN
        DECLARE v_n_ap38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ap38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ap38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [ap39]
    BEGIN
        DECLARE v_levels_ap39 INTEGER DEFAULT 0;
        DECLARE c_ap39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_ap39 = 0;
        OPEN c_ap39;
        FETCH c_ap39 INTO v_levels_ap39;
        CLOSE c_ap39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_ap39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ap40]
    BEGIN
        DECLARE v_sql_ap40 VARCHAR(1000);
        DECLARE v_n_ap40 INTEGER DEFAULT 0;
        SET v_sql_ap40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_ap40 FROM v_sql_ap40;
        EXECUTE st_ap40;
        SELECT COUNT(*) INTO v_n_ap40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ap40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ap41]
    BEGIN
        DECLARE v_key_ap41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ap41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ap41' AS VARCHAR(40)), v_key_ap41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [ap42]
    BEGIN
        DECLARE v_so_ap42 INTEGER DEFAULT 0;
        DECLARE v_cust_ap42 INTEGER DEFAULT 0;
        DECLARE v_ctry_ap42 INTEGER DEFAULT 0;
        DECLARE v_ccy_ap42 INTEGER DEFAULT 0;
        DECLARE v_sub_ap42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ap42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ap42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ap42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ap42 INTEGER DEFAULT 0;
        DECLARE v_done_ap42 INTEGER DEFAULT 0;
        DECLARE c_ap42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap42 = 1;
        OPEN c_ap42;
        loop_ap42: LOOP
            FETCH c_ap42 INTO v_so_ap42, v_cust_ap42, v_ctry_ap42, v_ccy_ap42, v_sub_ap42;
            IF v_done_ap42 = 1 THEN LEAVE loop_ap42; END IF;
            SET v_tax_ap42 = ERP_FN_TAX(v_ctry_ap42, v_sub_ap42);
            SET v_fx_ap42 = ERP_FN_FX_CONVERT(v_ccy_ap42, 1, v_sub_ap42 + v_tax_ap42);
            SET v_acc_ap42 = v_acc_ap42 + v_fx_ap42;
            SET v_cnt_ap42 = v_cnt_ap42 + 1;
        END LOOP;
        CLOSE c_ap42;
        IF v_cnt_ap42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ap42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ap42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ap43]
    BEGIN
        DECLARE v_pid_ap43 INTEGER DEFAULT 0;
        DECLARE v_oh_ap43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ap43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ap43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ap43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ap43 INTEGER DEFAULT 0;
        DECLARE c_ap43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap43 = 1;
        OPEN c_ap43;
        loop_ap43: LOOP
            FETCH c_ap43 INTO v_pid_ap43, v_oh_ap43, v_cost_ap43;
            IF v_done_ap43 = 1 THEN LEAVE loop_ap43; END IF;
            SET v_avail_ap43 = ERP_FN_INVENTORY_ONHAND(v_pid_ap43);
            SET v_val_ap43 = v_val_ap43 + CAST(COALESCE(v_oh_ap43,0) * COALESCE(v_cost_ap43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ap43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ap43;
        END LOOP;
        CLOSE c_ap43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ap43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ap44]
    BEGIN
        DECLARE v_prod_ap44 INTEGER DEFAULT 0;
        DECLARE v_rm_ap44 INTEGER DEFAULT 0;
        DECLARE v_supp_ap44 INTEGER DEFAULT 0;
        DECLARE v_qper_ap44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ap44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ap44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ap44 INTEGER DEFAULT 0;
        DECLARE c_ap44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap44 = 1;
        OPEN c_ap44;
        loop_ap44: LOOP
            FETCH c_ap44 INTO v_prod_ap44, v_rm_ap44, v_supp_ap44, v_qper_ap44, v_uc_ap44;
            IF v_done_ap44 = 1 THEN LEAVE loop_ap44; END IF;
            SET v_roll_ap44 = v_roll_ap44 + COALESCE(v_qper_ap44,0) * COALESCE(v_uc_ap44,0);
        END LOOP;
        CLOSE c_ap44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ap44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ap45]
    BEGIN
        DECLARE v_acct_ap45 INTEGER DEFAULT 0;
        DECLARE v_deb_ap45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ap45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ap45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap45 INTEGER DEFAULT 0;
        DECLARE c_ap45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap45 = 1;
        OPEN c_ap45;
        loop_ap45: LOOP
            FETCH c_ap45 INTO v_acct_ap45, v_deb_ap45, v_cred_ap45;
            IF v_done_ap45 = 1 THEN LEAVE loop_ap45; END IF;
            SET v_net_ap45 = v_net_ap45 + (v_deb_ap45 - v_cred_ap45);
        END LOOP;
        CLOSE c_ap45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ap45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ap46]
    BEGIN
        DECLARE v_pid_ap46 INTEGER DEFAULT 0;
        DECLARE v_lp_ap46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ap46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ap46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ap46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ap46 INTEGER DEFAULT 0;
        DECLARE c_ap46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap46 = 1;
        OPEN c_ap46;
        loop_ap46: LOOP
            FETCH c_ap46 INTO v_pid_ap46, v_lp_ap46, v_pp_ap46;
            IF v_done_ap46 = 1 THEN LEAVE loop_ap46; END IF;
            SET v_var_ap46 = v_var_ap46 + (COALESCE(v_lp_ap46,0) - COALESCE(v_pp_ap46,0));
            SET v_marg_ap46 = ERP_FN_MARGIN(v_pid_ap46);
        END LOOP;
        CLOSE c_ap46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ap46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ap47]
    BEGIN
        DECLARE v_inv_ap47 INTEGER DEFAULT 0;
        DECLARE v_amt_ap47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ap47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ap47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap47 INTEGER DEFAULT 0;
        DECLARE c_ap47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap47 = 1;
        OPEN c_ap47;
        loop_ap47: LOOP
            FETCH c_ap47 INTO v_inv_ap47, v_amt_ap47, v_alloc_ap47;
            IF v_done_ap47 = 1 THEN LEAVE loop_ap47; END IF;
            SET v_open_ap47 = v_open_ap47 + (v_amt_ap47 - v_alloc_ap47);
        END LOOP;
        CLOSE c_ap47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ap47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ap48]
    BEGIN
        DECLARE v_lvl_ap48 INTEGER DEFAULT 0;
        DECLARE v_dept_ap48 INTEGER DEFAULT 0;
        DECLARE v_head_ap48 INTEGER DEFAULT 0;
        DECLARE v_done_ap48 INTEGER DEFAULT 0;
        DECLARE c_ap48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap48 = 1;
        OPEN c_ap48;
        loop_ap48: LOOP
            FETCH c_ap48 INTO v_dept_ap48, v_lvl_ap48, v_head_ap48;
            IF v_done_ap48 = 1 THEN LEAVE loop_ap48; END IF;
        END LOOP;
        CLOSE c_ap48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ap48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ap48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ap49]
    BEGIN
        DECLARE v_sh_ap49 INTEGER DEFAULT 0;
        DECLARE v_car_ap49 INTEGER DEFAULT 0;
        DECLARE v_qty_ap49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ap49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ap49 INTEGER DEFAULT 0;
        DECLARE c_ap49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap49 = 1;
        OPEN c_ap49;
        loop_ap49: LOOP
            FETCH c_ap49 INTO v_sh_ap49, v_car_ap49, v_qty_ap49;
            IF v_done_ap49 = 1 THEN LEAVE loop_ap49; END IF;
            SET v_tot_ap49 = v_tot_ap49 + v_qty_ap49;
        END LOOP;
        CLOSE c_ap49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ap49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ap50]
    BEGIN
        DECLARE v_sql_ap50 VARCHAR(1000);
        DECLARE v_n_ap50 INTEGER DEFAULT 0;
        SET v_sql_ap50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ap50 FROM v_sql_ap50;
        EXECUTE st_ap50;
        SELECT COUNT(*) INTO v_n_ap50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ap50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ap51]
    BEGIN
        DECLARE v_key_ap51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ap51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ap51' AS VARCHAR(40)), v_key_ap51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ap52]
    BEGIN
        DECLARE v_so_ap52 INTEGER DEFAULT 0;
        DECLARE v_cust_ap52 INTEGER DEFAULT 0;
        DECLARE v_rk_ap52 INTEGER DEFAULT 0;
        DECLARE v_run_ap52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ap52 INTEGER DEFAULT 0;
        DECLARE c_ap52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ap52 = 1;
        OPEN c_ap52;
        loop_ap52: LOOP
            FETCH c_ap52 INTO v_so_ap52, v_cust_ap52, v_rk_ap52, v_run_ap52;
            IF v_done_ap52 = 1 THEN LEAVE loop_ap52; END IF;
        END LOOP;
        CLOSE c_ap52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ap52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ap52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ap53]
    BEGIN
        DECLARE v_hi_ap53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ap53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ap53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ap54]
    BEGIN
        DECLARE v_pairs_ap54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ap54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ap54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ap55]
    BEGIN
        DECLARE v_rows_ap55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ap55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ap55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ap55 FROM SESSION.TMP_ap55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ap55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ap56]
    BEGIN
        DECLARE v_rc_ap56 INTEGER DEFAULT 0;
        DECLARE v_band_ap56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ap56 = ROW_COUNT;
        SET v_band_ap56 = CASE
                            WHEN v_rc_ap56 = 0 THEN 'NONE'
                            WHEN v_rc_ap56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ap56, 'COUNT', 'band=' || v_band_ap56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ap57]
    BEGIN
        DECLARE v_i_ap57 INTEGER DEFAULT 0;
        SAVEPOINT sp_ap57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ap57 < 4 DO
            SET v_i_ap57 = v_i_ap57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ap57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ap57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ap57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ap58]
    BEGIN
        DECLARE v_j_ap58 INTEGER DEFAULT 0;
        DECLARE v_sum_ap58 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ap58 = v_j_ap58 + 1;
        UNTIL v_j_ap58 >= 3 END REPEAT;
        FOR row_ap58 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ap58 = v_sum_ap58 + COALESCE(row_ap58.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ap58, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ap58 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ap59]
    BEGIN
        DECLARE v_n_ap59 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ap59
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ap59, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_POST_GL(IN p_invoice_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_amount DECIMAL(16,2) DEFAULT 0;
    DECLARE v_tax DECIMAL(16,2) DEFAULT 0;
    DECLARE v_ar INTEGER; DECLARE v_rev INTEGER; DECLARE v_taxacct INTEGER;
    DECLARE v_sql VARCHAR(500);
    DECLARE v_rc INTEGER DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('GL', p_invoice_id, 'ERROR', 'post gl failed');
    END;
    SELECT COALESCE(amount,0), COALESCE(tax,0) INTO v_amount, v_tax
    FROM ERP_INVOICE WHERE id = p_invoice_id;
    SELECT MIN(id) INTO v_ar FROM ERP_GL_ACCOUNT WHERE code = '1200';
    SELECT MIN(id) INTO v_rev FROM ERP_GL_ACCOUNT WHERE code = '4000';
    SELECT MIN(id) INTO v_taxacct FROM ERP_GL_ACCOUNT WHERE code = '2200';
    INSERT INTO ERP_GL_ENTRY(account_id, entry_date, debit, credit, ref_doc, memo)
    VALUES (v_ar, CURRENT DATE, v_amount + v_tax, 0, p_invoice_id, 'AR for invoice');
    GET DIAGNOSTICS v_rc = ROW_COUNT;
    SET v_sql = 'INSERT INTO ERP_GL_ENTRY(account_id, entry_date, debit, credit, ref_doc, memo) VALUES (?, CURRENT DATE, 0, ?, ?, ?)';
    PREPARE gstmt FROM v_sql;
    EXECUTE gstmt USING v_rev, v_amount, p_invoice_id, 'Revenue';
    EXECUTE gstmt USING v_taxacct, v_tax, p_invoice_id, 'Tax payable';
    CALL ERP_USP_APPLY_PAYMENT(p_invoice_id, v_amount + v_tax);
    CALL ERP_USP_AUDIT('GL', p_invoice_id, 'POST', 'gl posted rows=' || RTRIM(CHAR(v_rc)));
    -- order/customer/country/currency revenue scan [pg00]
    BEGIN
        DECLARE v_so_pg00 INTEGER DEFAULT 0;
        DECLARE v_cust_pg00 INTEGER DEFAULT 0;
        DECLARE v_ctry_pg00 INTEGER DEFAULT 0;
        DECLARE v_ccy_pg00 INTEGER DEFAULT 0;
        DECLARE v_sub_pg00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pg00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pg00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pg00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pg00 INTEGER DEFAULT 0;
        DECLARE v_done_pg00 INTEGER DEFAULT 0;
        DECLARE c_pg00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg00 = 1;
        OPEN c_pg00;
        loop_pg00: LOOP
            FETCH c_pg00 INTO v_so_pg00, v_cust_pg00, v_ctry_pg00, v_ccy_pg00, v_sub_pg00;
            IF v_done_pg00 = 1 THEN LEAVE loop_pg00; END IF;
            SET v_tax_pg00 = ERP_FN_TAX(v_ctry_pg00, v_sub_pg00);
            SET v_fx_pg00 = ERP_FN_FX_CONVERT(v_ccy_pg00, 1, v_sub_pg00 + v_tax_pg00);
            SET v_acc_pg00 = v_acc_pg00 + v_fx_pg00;
            SET v_cnt_pg00 = v_cnt_pg00 + 1;
        END LOOP;
        CLOSE c_pg00;
        IF v_cnt_pg00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pg00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pg00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pg01]
    BEGIN
        DECLARE v_pid_pg01 INTEGER DEFAULT 0;
        DECLARE v_oh_pg01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pg01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pg01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pg01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pg01 INTEGER DEFAULT 0;
        DECLARE c_pg01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg01 = 1;
        OPEN c_pg01;
        loop_pg01: LOOP
            FETCH c_pg01 INTO v_pid_pg01, v_oh_pg01, v_cost_pg01;
            IF v_done_pg01 = 1 THEN LEAVE loop_pg01; END IF;
            SET v_avail_pg01 = ERP_FN_INVENTORY_ONHAND(v_pid_pg01);
            SET v_val_pg01 = v_val_pg01 + CAST(COALESCE(v_oh_pg01,0) * COALESCE(v_cost_pg01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pg01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pg01;
        END LOOP;
        CLOSE c_pg01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pg01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pg02]
    BEGIN
        DECLARE v_prod_pg02 INTEGER DEFAULT 0;
        DECLARE v_rm_pg02 INTEGER DEFAULT 0;
        DECLARE v_supp_pg02 INTEGER DEFAULT 0;
        DECLARE v_qper_pg02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pg02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pg02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pg02 INTEGER DEFAULT 0;
        DECLARE c_pg02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg02 = 1;
        OPEN c_pg02;
        loop_pg02: LOOP
            FETCH c_pg02 INTO v_prod_pg02, v_rm_pg02, v_supp_pg02, v_qper_pg02, v_uc_pg02;
            IF v_done_pg02 = 1 THEN LEAVE loop_pg02; END IF;
            SET v_roll_pg02 = v_roll_pg02 + COALESCE(v_qper_pg02,0) * COALESCE(v_uc_pg02,0);
        END LOOP;
        CLOSE c_pg02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pg02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pg03]
    BEGIN
        DECLARE v_acct_pg03 INTEGER DEFAULT 0;
        DECLARE v_deb_pg03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pg03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pg03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg03 INTEGER DEFAULT 0;
        DECLARE c_pg03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg03 = 1;
        OPEN c_pg03;
        loop_pg03: LOOP
            FETCH c_pg03 INTO v_acct_pg03, v_deb_pg03, v_cred_pg03;
            IF v_done_pg03 = 1 THEN LEAVE loop_pg03; END IF;
            SET v_net_pg03 = v_net_pg03 + (v_deb_pg03 - v_cred_pg03);
        END LOOP;
        CLOSE c_pg03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pg03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pg04]
    BEGIN
        DECLARE v_pid_pg04 INTEGER DEFAULT 0;
        DECLARE v_lp_pg04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pg04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pg04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pg04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pg04 INTEGER DEFAULT 0;
        DECLARE c_pg04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg04 = 1;
        OPEN c_pg04;
        loop_pg04: LOOP
            FETCH c_pg04 INTO v_pid_pg04, v_lp_pg04, v_pp_pg04;
            IF v_done_pg04 = 1 THEN LEAVE loop_pg04; END IF;
            SET v_var_pg04 = v_var_pg04 + (COALESCE(v_lp_pg04,0) - COALESCE(v_pp_pg04,0));
            SET v_marg_pg04 = ERP_FN_MARGIN(v_pid_pg04);
        END LOOP;
        CLOSE c_pg04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pg04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pg05]
    BEGIN
        DECLARE v_inv_pg05 INTEGER DEFAULT 0;
        DECLARE v_amt_pg05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pg05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pg05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg05 INTEGER DEFAULT 0;
        DECLARE c_pg05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg05 = 1;
        OPEN c_pg05;
        loop_pg05: LOOP
            FETCH c_pg05 INTO v_inv_pg05, v_amt_pg05, v_alloc_pg05;
            IF v_done_pg05 = 1 THEN LEAVE loop_pg05; END IF;
            SET v_open_pg05 = v_open_pg05 + (v_amt_pg05 - v_alloc_pg05);
        END LOOP;
        CLOSE c_pg05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pg05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pg06]
    BEGIN
        DECLARE v_lvl_pg06 INTEGER DEFAULT 0;
        DECLARE v_dept_pg06 INTEGER DEFAULT 0;
        DECLARE v_head_pg06 INTEGER DEFAULT 0;
        DECLARE v_done_pg06 INTEGER DEFAULT 0;
        DECLARE c_pg06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg06 = 1;
        OPEN c_pg06;
        loop_pg06: LOOP
            FETCH c_pg06 INTO v_dept_pg06, v_lvl_pg06, v_head_pg06;
            IF v_done_pg06 = 1 THEN LEAVE loop_pg06; END IF;
        END LOOP;
        CLOSE c_pg06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pg06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pg06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pg07]
    BEGIN
        DECLARE v_sh_pg07 INTEGER DEFAULT 0;
        DECLARE v_car_pg07 INTEGER DEFAULT 0;
        DECLARE v_qty_pg07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pg07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pg07 INTEGER DEFAULT 0;
        DECLARE c_pg07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg07 = 1;
        OPEN c_pg07;
        loop_pg07: LOOP
            FETCH c_pg07 INTO v_sh_pg07, v_car_pg07, v_qty_pg07;
            IF v_done_pg07 = 1 THEN LEAVE loop_pg07; END IF;
            SET v_tot_pg07 = v_tot_pg07 + v_qty_pg07;
        END LOOP;
        CLOSE c_pg07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pg07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pg08]
    BEGIN
        DECLARE v_sql_pg08 VARCHAR(1000);
        DECLARE v_n_pg08 INTEGER DEFAULT 0;
        SET v_sql_pg08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pg08 FROM v_sql_pg08;
        EXECUTE st_pg08;
        SELECT COUNT(*) INTO v_n_pg08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pg08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pg09]
    BEGIN
        DECLARE v_key_pg09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pg09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pg09' AS VARCHAR(40)), v_key_pg09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pg10]
    BEGIN
        DECLARE v_so_pg10 INTEGER DEFAULT 0;
        DECLARE v_cust_pg10 INTEGER DEFAULT 0;
        DECLARE v_rk_pg10 INTEGER DEFAULT 0;
        DECLARE v_run_pg10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg10 INTEGER DEFAULT 0;
        DECLARE c_pg10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg10 = 1;
        OPEN c_pg10;
        loop_pg10: LOOP
            FETCH c_pg10 INTO v_so_pg10, v_cust_pg10, v_rk_pg10, v_run_pg10;
            IF v_done_pg10 = 1 THEN LEAVE loop_pg10; END IF;
        END LOOP;
        CLOSE c_pg10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pg10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pg10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [pg11]
    BEGIN
        DECLARE v_hi_pg11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_pg11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_pg11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [pg12]
    BEGIN
        DECLARE v_pairs_pg12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_pg12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_pg12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [pg13]
    BEGIN
        DECLARE v_rows_pg13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_pg13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_pg13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_pg13 FROM SESSION.TMP_pg13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_pg13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [pg14]
    BEGIN
        DECLARE v_rc_pg14 INTEGER DEFAULT 0;
        DECLARE v_band_pg14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_pg14 = ROW_COUNT;
        SET v_band_pg14 = CASE
                            WHEN v_rc_pg14 = 0 THEN 'NONE'
                            WHEN v_rc_pg14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_pg14, 'COUNT', 'band=' || v_band_pg14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [pg15]
    BEGIN
        DECLARE v_i_pg15 INTEGER DEFAULT 0;
        SAVEPOINT sp_pg15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_pg15 < 4 DO
            SET v_i_pg15 = v_i_pg15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_pg15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_pg15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_pg15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [pg16]
    BEGIN
        DECLARE v_j_pg16 INTEGER DEFAULT 0;
        DECLARE v_sum_pg16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_pg16 = v_j_pg16 + 1;
        UNTIL v_j_pg16 >= 3 END REPEAT;
        FOR row_pg16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_pg16 = v_sum_pg16 + COALESCE(row_pg16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_pg16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_pg16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [pg17]
    BEGIN
        DECLARE v_n_pg17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_pg17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_pg17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [pg18]
    BEGIN
        DECLARE v_levels_pg18 INTEGER DEFAULT 0;
        DECLARE c_pg18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_pg18 = 0;
        OPEN c_pg18;
        FETCH c_pg18 INTO v_levels_pg18;
        CLOSE c_pg18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_pg18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pg19]
    BEGIN
        DECLARE v_sql_pg19 VARCHAR(1000);
        DECLARE v_n_pg19 INTEGER DEFAULT 0;
        SET v_sql_pg19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_pg19 FROM v_sql_pg19;
        EXECUTE st_pg19;
        SELECT COUNT(*) INTO v_n_pg19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pg19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pg20]
    BEGIN
        DECLARE v_key_pg20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pg20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pg20' AS VARCHAR(40)), v_key_pg20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [pg21]
    BEGIN
        DECLARE v_so_pg21 INTEGER DEFAULT 0;
        DECLARE v_cust_pg21 INTEGER DEFAULT 0;
        DECLARE v_ctry_pg21 INTEGER DEFAULT 0;
        DECLARE v_ccy_pg21 INTEGER DEFAULT 0;
        DECLARE v_sub_pg21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pg21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pg21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pg21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pg21 INTEGER DEFAULT 0;
        DECLARE v_done_pg21 INTEGER DEFAULT 0;
        DECLARE c_pg21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg21 = 1;
        OPEN c_pg21;
        loop_pg21: LOOP
            FETCH c_pg21 INTO v_so_pg21, v_cust_pg21, v_ctry_pg21, v_ccy_pg21, v_sub_pg21;
            IF v_done_pg21 = 1 THEN LEAVE loop_pg21; END IF;
            SET v_tax_pg21 = ERP_FN_TAX(v_ctry_pg21, v_sub_pg21);
            SET v_fx_pg21 = ERP_FN_FX_CONVERT(v_ccy_pg21, 1, v_sub_pg21 + v_tax_pg21);
            SET v_acc_pg21 = v_acc_pg21 + v_fx_pg21;
            SET v_cnt_pg21 = v_cnt_pg21 + 1;
        END LOOP;
        CLOSE c_pg21;
        IF v_cnt_pg21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pg21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pg21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pg22]
    BEGIN
        DECLARE v_pid_pg22 INTEGER DEFAULT 0;
        DECLARE v_oh_pg22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pg22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pg22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pg22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pg22 INTEGER DEFAULT 0;
        DECLARE c_pg22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg22 = 1;
        OPEN c_pg22;
        loop_pg22: LOOP
            FETCH c_pg22 INTO v_pid_pg22, v_oh_pg22, v_cost_pg22;
            IF v_done_pg22 = 1 THEN LEAVE loop_pg22; END IF;
            SET v_avail_pg22 = ERP_FN_INVENTORY_ONHAND(v_pid_pg22);
            SET v_val_pg22 = v_val_pg22 + CAST(COALESCE(v_oh_pg22,0) * COALESCE(v_cost_pg22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pg22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pg22;
        END LOOP;
        CLOSE c_pg22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pg22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pg23]
    BEGIN
        DECLARE v_prod_pg23 INTEGER DEFAULT 0;
        DECLARE v_rm_pg23 INTEGER DEFAULT 0;
        DECLARE v_supp_pg23 INTEGER DEFAULT 0;
        DECLARE v_qper_pg23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pg23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pg23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pg23 INTEGER DEFAULT 0;
        DECLARE c_pg23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg23 = 1;
        OPEN c_pg23;
        loop_pg23: LOOP
            FETCH c_pg23 INTO v_prod_pg23, v_rm_pg23, v_supp_pg23, v_qper_pg23, v_uc_pg23;
            IF v_done_pg23 = 1 THEN LEAVE loop_pg23; END IF;
            SET v_roll_pg23 = v_roll_pg23 + COALESCE(v_qper_pg23,0) * COALESCE(v_uc_pg23,0);
        END LOOP;
        CLOSE c_pg23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pg23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pg24]
    BEGIN
        DECLARE v_acct_pg24 INTEGER DEFAULT 0;
        DECLARE v_deb_pg24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pg24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pg24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg24 INTEGER DEFAULT 0;
        DECLARE c_pg24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg24 = 1;
        OPEN c_pg24;
        loop_pg24: LOOP
            FETCH c_pg24 INTO v_acct_pg24, v_deb_pg24, v_cred_pg24;
            IF v_done_pg24 = 1 THEN LEAVE loop_pg24; END IF;
            SET v_net_pg24 = v_net_pg24 + (v_deb_pg24 - v_cred_pg24);
        END LOOP;
        CLOSE c_pg24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pg24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pg25]
    BEGIN
        DECLARE v_pid_pg25 INTEGER DEFAULT 0;
        DECLARE v_lp_pg25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pg25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pg25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pg25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pg25 INTEGER DEFAULT 0;
        DECLARE c_pg25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg25 = 1;
        OPEN c_pg25;
        loop_pg25: LOOP
            FETCH c_pg25 INTO v_pid_pg25, v_lp_pg25, v_pp_pg25;
            IF v_done_pg25 = 1 THEN LEAVE loop_pg25; END IF;
            SET v_var_pg25 = v_var_pg25 + (COALESCE(v_lp_pg25,0) - COALESCE(v_pp_pg25,0));
            SET v_marg_pg25 = ERP_FN_MARGIN(v_pid_pg25);
        END LOOP;
        CLOSE c_pg25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pg25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pg26]
    BEGIN
        DECLARE v_inv_pg26 INTEGER DEFAULT 0;
        DECLARE v_amt_pg26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pg26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pg26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg26 INTEGER DEFAULT 0;
        DECLARE c_pg26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg26 = 1;
        OPEN c_pg26;
        loop_pg26: LOOP
            FETCH c_pg26 INTO v_inv_pg26, v_amt_pg26, v_alloc_pg26;
            IF v_done_pg26 = 1 THEN LEAVE loop_pg26; END IF;
            SET v_open_pg26 = v_open_pg26 + (v_amt_pg26 - v_alloc_pg26);
        END LOOP;
        CLOSE c_pg26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pg26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pg27]
    BEGIN
        DECLARE v_lvl_pg27 INTEGER DEFAULT 0;
        DECLARE v_dept_pg27 INTEGER DEFAULT 0;
        DECLARE v_head_pg27 INTEGER DEFAULT 0;
        DECLARE v_done_pg27 INTEGER DEFAULT 0;
        DECLARE c_pg27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg27 = 1;
        OPEN c_pg27;
        loop_pg27: LOOP
            FETCH c_pg27 INTO v_dept_pg27, v_lvl_pg27, v_head_pg27;
            IF v_done_pg27 = 1 THEN LEAVE loop_pg27; END IF;
        END LOOP;
        CLOSE c_pg27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pg27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pg27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pg28]
    BEGIN
        DECLARE v_sh_pg28 INTEGER DEFAULT 0;
        DECLARE v_car_pg28 INTEGER DEFAULT 0;
        DECLARE v_qty_pg28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pg28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pg28 INTEGER DEFAULT 0;
        DECLARE c_pg28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg28 = 1;
        OPEN c_pg28;
        loop_pg28: LOOP
            FETCH c_pg28 INTO v_sh_pg28, v_car_pg28, v_qty_pg28;
            IF v_done_pg28 = 1 THEN LEAVE loop_pg28; END IF;
            SET v_tot_pg28 = v_tot_pg28 + v_qty_pg28;
        END LOOP;
        CLOSE c_pg28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pg28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pg29]
    BEGIN
        DECLARE v_sql_pg29 VARCHAR(1000);
        DECLARE v_n_pg29 INTEGER DEFAULT 0;
        SET v_sql_pg29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pg29 FROM v_sql_pg29;
        EXECUTE st_pg29;
        SELECT COUNT(*) INTO v_n_pg29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pg29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pg30]
    BEGIN
        DECLARE v_key_pg30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pg30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pg30' AS VARCHAR(40)), v_key_pg30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pg31]
    BEGIN
        DECLARE v_so_pg31 INTEGER DEFAULT 0;
        DECLARE v_cust_pg31 INTEGER DEFAULT 0;
        DECLARE v_rk_pg31 INTEGER DEFAULT 0;
        DECLARE v_run_pg31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg31 INTEGER DEFAULT 0;
        DECLARE c_pg31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg31 = 1;
        OPEN c_pg31;
        loop_pg31: LOOP
            FETCH c_pg31 INTO v_so_pg31, v_cust_pg31, v_rk_pg31, v_run_pg31;
            IF v_done_pg31 = 1 THEN LEAVE loop_pg31; END IF;
        END LOOP;
        CLOSE c_pg31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pg31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pg31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [pg32]
    BEGIN
        DECLARE v_hi_pg32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_pg32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_pg32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [pg33]
    BEGIN
        DECLARE v_pairs_pg33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_pg33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_pg33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [pg34]
    BEGIN
        DECLARE v_rows_pg34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_pg34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_pg34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_pg34 FROM SESSION.TMP_pg34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_pg34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [pg35]
    BEGIN
        DECLARE v_rc_pg35 INTEGER DEFAULT 0;
        DECLARE v_band_pg35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_pg35 = ROW_COUNT;
        SET v_band_pg35 = CASE
                            WHEN v_rc_pg35 = 0 THEN 'NONE'
                            WHEN v_rc_pg35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_pg35, 'COUNT', 'band=' || v_band_pg35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [pg36]
    BEGIN
        DECLARE v_i_pg36 INTEGER DEFAULT 0;
        SAVEPOINT sp_pg36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_pg36 < 4 DO
            SET v_i_pg36 = v_i_pg36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_pg36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_pg36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_pg36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [pg37]
    BEGIN
        DECLARE v_j_pg37 INTEGER DEFAULT 0;
        DECLARE v_sum_pg37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_pg37 = v_j_pg37 + 1;
        UNTIL v_j_pg37 >= 3 END REPEAT;
        FOR row_pg37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_pg37 = v_sum_pg37 + COALESCE(row_pg37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_pg37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_pg37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [pg38]
    BEGIN
        DECLARE v_n_pg38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_pg38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_pg38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [pg39]
    BEGIN
        DECLARE v_levels_pg39 INTEGER DEFAULT 0;
        DECLARE c_pg39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_pg39 = 0;
        OPEN c_pg39;
        FETCH c_pg39 INTO v_levels_pg39;
        CLOSE c_pg39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_pg39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pg40]
    BEGIN
        DECLARE v_sql_pg40 VARCHAR(1000);
        DECLARE v_n_pg40 INTEGER DEFAULT 0;
        SET v_sql_pg40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_pg40 FROM v_sql_pg40;
        EXECUTE st_pg40;
        SELECT COUNT(*) INTO v_n_pg40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pg40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pg41]
    BEGIN
        DECLARE v_key_pg41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pg41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pg41' AS VARCHAR(40)), v_key_pg41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [pg42]
    BEGIN
        DECLARE v_so_pg42 INTEGER DEFAULT 0;
        DECLARE v_cust_pg42 INTEGER DEFAULT 0;
        DECLARE v_ctry_pg42 INTEGER DEFAULT 0;
        DECLARE v_ccy_pg42 INTEGER DEFAULT 0;
        DECLARE v_sub_pg42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pg42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pg42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pg42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pg42 INTEGER DEFAULT 0;
        DECLARE v_done_pg42 INTEGER DEFAULT 0;
        DECLARE c_pg42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg42 = 1;
        OPEN c_pg42;
        loop_pg42: LOOP
            FETCH c_pg42 INTO v_so_pg42, v_cust_pg42, v_ctry_pg42, v_ccy_pg42, v_sub_pg42;
            IF v_done_pg42 = 1 THEN LEAVE loop_pg42; END IF;
            SET v_tax_pg42 = ERP_FN_TAX(v_ctry_pg42, v_sub_pg42);
            SET v_fx_pg42 = ERP_FN_FX_CONVERT(v_ccy_pg42, 1, v_sub_pg42 + v_tax_pg42);
            SET v_acc_pg42 = v_acc_pg42 + v_fx_pg42;
            SET v_cnt_pg42 = v_cnt_pg42 + 1;
        END LOOP;
        CLOSE c_pg42;
        IF v_cnt_pg42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pg42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pg42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pg43]
    BEGIN
        DECLARE v_pid_pg43 INTEGER DEFAULT 0;
        DECLARE v_oh_pg43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pg43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pg43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pg43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pg43 INTEGER DEFAULT 0;
        DECLARE c_pg43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg43 = 1;
        OPEN c_pg43;
        loop_pg43: LOOP
            FETCH c_pg43 INTO v_pid_pg43, v_oh_pg43, v_cost_pg43;
            IF v_done_pg43 = 1 THEN LEAVE loop_pg43; END IF;
            SET v_avail_pg43 = ERP_FN_INVENTORY_ONHAND(v_pid_pg43);
            SET v_val_pg43 = v_val_pg43 + CAST(COALESCE(v_oh_pg43,0) * COALESCE(v_cost_pg43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pg43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pg43;
        END LOOP;
        CLOSE c_pg43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pg43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pg44]
    BEGIN
        DECLARE v_prod_pg44 INTEGER DEFAULT 0;
        DECLARE v_rm_pg44 INTEGER DEFAULT 0;
        DECLARE v_supp_pg44 INTEGER DEFAULT 0;
        DECLARE v_qper_pg44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pg44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pg44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pg44 INTEGER DEFAULT 0;
        DECLARE c_pg44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg44 = 1;
        OPEN c_pg44;
        loop_pg44: LOOP
            FETCH c_pg44 INTO v_prod_pg44, v_rm_pg44, v_supp_pg44, v_qper_pg44, v_uc_pg44;
            IF v_done_pg44 = 1 THEN LEAVE loop_pg44; END IF;
            SET v_roll_pg44 = v_roll_pg44 + COALESCE(v_qper_pg44,0) * COALESCE(v_uc_pg44,0);
        END LOOP;
        CLOSE c_pg44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pg44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pg45]
    BEGIN
        DECLARE v_acct_pg45 INTEGER DEFAULT 0;
        DECLARE v_deb_pg45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pg45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pg45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg45 INTEGER DEFAULT 0;
        DECLARE c_pg45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg45 = 1;
        OPEN c_pg45;
        loop_pg45: LOOP
            FETCH c_pg45 INTO v_acct_pg45, v_deb_pg45, v_cred_pg45;
            IF v_done_pg45 = 1 THEN LEAVE loop_pg45; END IF;
            SET v_net_pg45 = v_net_pg45 + (v_deb_pg45 - v_cred_pg45);
        END LOOP;
        CLOSE c_pg45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pg45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pg46]
    BEGIN
        DECLARE v_pid_pg46 INTEGER DEFAULT 0;
        DECLARE v_lp_pg46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pg46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pg46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pg46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pg46 INTEGER DEFAULT 0;
        DECLARE c_pg46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg46 = 1;
        OPEN c_pg46;
        loop_pg46: LOOP
            FETCH c_pg46 INTO v_pid_pg46, v_lp_pg46, v_pp_pg46;
            IF v_done_pg46 = 1 THEN LEAVE loop_pg46; END IF;
            SET v_var_pg46 = v_var_pg46 + (COALESCE(v_lp_pg46,0) - COALESCE(v_pp_pg46,0));
            SET v_marg_pg46 = ERP_FN_MARGIN(v_pid_pg46);
        END LOOP;
        CLOSE c_pg46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pg46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pg47]
    BEGIN
        DECLARE v_inv_pg47 INTEGER DEFAULT 0;
        DECLARE v_amt_pg47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pg47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pg47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg47 INTEGER DEFAULT 0;
        DECLARE c_pg47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg47 = 1;
        OPEN c_pg47;
        loop_pg47: LOOP
            FETCH c_pg47 INTO v_inv_pg47, v_amt_pg47, v_alloc_pg47;
            IF v_done_pg47 = 1 THEN LEAVE loop_pg47; END IF;
            SET v_open_pg47 = v_open_pg47 + (v_amt_pg47 - v_alloc_pg47);
        END LOOP;
        CLOSE c_pg47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pg47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pg48]
    BEGIN
        DECLARE v_lvl_pg48 INTEGER DEFAULT 0;
        DECLARE v_dept_pg48 INTEGER DEFAULT 0;
        DECLARE v_head_pg48 INTEGER DEFAULT 0;
        DECLARE v_done_pg48 INTEGER DEFAULT 0;
        DECLARE c_pg48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg48 = 1;
        OPEN c_pg48;
        loop_pg48: LOOP
            FETCH c_pg48 INTO v_dept_pg48, v_lvl_pg48, v_head_pg48;
            IF v_done_pg48 = 1 THEN LEAVE loop_pg48; END IF;
        END LOOP;
        CLOSE c_pg48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pg48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pg48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pg49]
    BEGIN
        DECLARE v_sh_pg49 INTEGER DEFAULT 0;
        DECLARE v_car_pg49 INTEGER DEFAULT 0;
        DECLARE v_qty_pg49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pg49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pg49 INTEGER DEFAULT 0;
        DECLARE c_pg49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg49 = 1;
        OPEN c_pg49;
        loop_pg49: LOOP
            FETCH c_pg49 INTO v_sh_pg49, v_car_pg49, v_qty_pg49;
            IF v_done_pg49 = 1 THEN LEAVE loop_pg49; END IF;
            SET v_tot_pg49 = v_tot_pg49 + v_qty_pg49;
        END LOOP;
        CLOSE c_pg49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pg49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pg50]
    BEGIN
        DECLARE v_sql_pg50 VARCHAR(1000);
        DECLARE v_n_pg50 INTEGER DEFAULT 0;
        SET v_sql_pg50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pg50 FROM v_sql_pg50;
        EXECUTE st_pg50;
        SELECT COUNT(*) INTO v_n_pg50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pg50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pg51]
    BEGIN
        DECLARE v_key_pg51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pg51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pg51' AS VARCHAR(40)), v_key_pg51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pg52]
    BEGIN
        DECLARE v_so_pg52 INTEGER DEFAULT 0;
        DECLARE v_cust_pg52 INTEGER DEFAULT 0;
        DECLARE v_rk_pg52 INTEGER DEFAULT 0;
        DECLARE v_run_pg52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pg52 INTEGER DEFAULT 0;
        DECLARE c_pg52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pg52 = 1;
        OPEN c_pg52;
        loop_pg52: LOOP
            FETCH c_pg52 INTO v_so_pg52, v_cust_pg52, v_rk_pg52, v_run_pg52;
            IF v_done_pg52 = 1 THEN LEAVE loop_pg52; END IF;
        END LOOP;
        CLOSE c_pg52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pg52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pg52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [pg53]
    BEGIN
        DECLARE v_hi_pg53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_pg53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_pg53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [pg54]
    BEGIN
        DECLARE v_pairs_pg54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_pg54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_pg54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [pg55]
    BEGIN
        DECLARE v_rows_pg55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_pg55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_pg55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_pg55 FROM SESSION.TMP_pg55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_pg55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [pg56]
    BEGIN
        DECLARE v_rc_pg56 INTEGER DEFAULT 0;
        DECLARE v_band_pg56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_pg56 = ROW_COUNT;
        SET v_band_pg56 = CASE
                            WHEN v_rc_pg56 = 0 THEN 'NONE'
                            WHEN v_rc_pg56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_pg56, 'COUNT', 'band=' || v_band_pg56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [pg57]
    BEGIN
        DECLARE v_i_pg57 INTEGER DEFAULT 0;
        SAVEPOINT sp_pg57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_pg57 < 4 DO
            SET v_i_pg57 = v_i_pg57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_pg57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_pg57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_pg57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [pg58]
    BEGIN
        DECLARE v_j_pg58 INTEGER DEFAULT 0;
        DECLARE v_sum_pg58 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_pg58 = v_j_pg58 + 1;
        UNTIL v_j_pg58 >= 3 END REPEAT;
        FOR row_pg58 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_pg58 = v_sum_pg58 + COALESCE(row_pg58.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_pg58, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_pg58 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [pg59]
    BEGIN
        DECLARE v_n_pg59 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_pg59
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_pg59, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_CREATE_INVOICE(IN p_so_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_sub DECIMAL(16,2) DEFAULT 0;
    DECLARE v_tax DECIMAL(16,2) DEFAULT 0;
    DECLARE v_ctry INTEGER DEFAULT 0;
    DECLARE v_inv_id INTEGER DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('INVOICE', p_so_id, 'ERROR', 'create invoice failed');
    END;
    SET v_sub = ERP_FN_ORDER_SUBTOTAL(p_so_id);
    SELECT c.country_id INTO v_ctry
    FROM ERP_SALES_ORDER so JOIN ERP_CUSTOMER c ON c.id = so.customer_id
    WHERE so.id = p_so_id;
    SET v_tax = ERP_FN_TAX(v_ctry, v_sub);
    INSERT INTO ERP_INVOICE(so_id, invoice_date, amount, tax, status)
    VALUES (p_so_id, CURRENT DATE, v_sub, v_tax, 'OPEN');
    SET v_inv_id = IDENTITY_VAL_LOCAL();
    CALL ERP_USP_POST_GL(v_inv_id);
    CALL ERP_USP_AUDIT('INVOICE', v_inv_id, 'CREATE', 'invoice created');
    -- order/customer/country/currency revenue scan [ci00]
    BEGIN
        DECLARE v_so_ci00 INTEGER DEFAULT 0;
        DECLARE v_cust_ci00 INTEGER DEFAULT 0;
        DECLARE v_ctry_ci00 INTEGER DEFAULT 0;
        DECLARE v_ccy_ci00 INTEGER DEFAULT 0;
        DECLARE v_sub_ci00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ci00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ci00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ci00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ci00 INTEGER DEFAULT 0;
        DECLARE v_done_ci00 INTEGER DEFAULT 0;
        DECLARE c_ci00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci00 = 1;
        OPEN c_ci00;
        loop_ci00: LOOP
            FETCH c_ci00 INTO v_so_ci00, v_cust_ci00, v_ctry_ci00, v_ccy_ci00, v_sub_ci00;
            IF v_done_ci00 = 1 THEN LEAVE loop_ci00; END IF;
            SET v_tax_ci00 = ERP_FN_TAX(v_ctry_ci00, v_sub_ci00);
            SET v_fx_ci00 = ERP_FN_FX_CONVERT(v_ccy_ci00, 1, v_sub_ci00 + v_tax_ci00);
            SET v_acc_ci00 = v_acc_ci00 + v_fx_ci00;
            SET v_cnt_ci00 = v_cnt_ci00 + 1;
        END LOOP;
        CLOSE c_ci00;
        IF v_cnt_ci00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ci00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ci00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ci01]
    BEGIN
        DECLARE v_pid_ci01 INTEGER DEFAULT 0;
        DECLARE v_oh_ci01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ci01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ci01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ci01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ci01 INTEGER DEFAULT 0;
        DECLARE c_ci01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci01 = 1;
        OPEN c_ci01;
        loop_ci01: LOOP
            FETCH c_ci01 INTO v_pid_ci01, v_oh_ci01, v_cost_ci01;
            IF v_done_ci01 = 1 THEN LEAVE loop_ci01; END IF;
            SET v_avail_ci01 = ERP_FN_INVENTORY_ONHAND(v_pid_ci01);
            SET v_val_ci01 = v_val_ci01 + CAST(COALESCE(v_oh_ci01,0) * COALESCE(v_cost_ci01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ci01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ci01;
        END LOOP;
        CLOSE c_ci01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ci01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ci02]
    BEGIN
        DECLARE v_prod_ci02 INTEGER DEFAULT 0;
        DECLARE v_rm_ci02 INTEGER DEFAULT 0;
        DECLARE v_supp_ci02 INTEGER DEFAULT 0;
        DECLARE v_qper_ci02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ci02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ci02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ci02 INTEGER DEFAULT 0;
        DECLARE c_ci02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci02 = 1;
        OPEN c_ci02;
        loop_ci02: LOOP
            FETCH c_ci02 INTO v_prod_ci02, v_rm_ci02, v_supp_ci02, v_qper_ci02, v_uc_ci02;
            IF v_done_ci02 = 1 THEN LEAVE loop_ci02; END IF;
            SET v_roll_ci02 = v_roll_ci02 + COALESCE(v_qper_ci02,0) * COALESCE(v_uc_ci02,0);
        END LOOP;
        CLOSE c_ci02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ci02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ci03]
    BEGIN
        DECLARE v_acct_ci03 INTEGER DEFAULT 0;
        DECLARE v_deb_ci03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ci03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ci03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci03 INTEGER DEFAULT 0;
        DECLARE c_ci03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci03 = 1;
        OPEN c_ci03;
        loop_ci03: LOOP
            FETCH c_ci03 INTO v_acct_ci03, v_deb_ci03, v_cred_ci03;
            IF v_done_ci03 = 1 THEN LEAVE loop_ci03; END IF;
            SET v_net_ci03 = v_net_ci03 + (v_deb_ci03 - v_cred_ci03);
        END LOOP;
        CLOSE c_ci03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ci03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ci04]
    BEGIN
        DECLARE v_pid_ci04 INTEGER DEFAULT 0;
        DECLARE v_lp_ci04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ci04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ci04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ci04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ci04 INTEGER DEFAULT 0;
        DECLARE c_ci04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci04 = 1;
        OPEN c_ci04;
        loop_ci04: LOOP
            FETCH c_ci04 INTO v_pid_ci04, v_lp_ci04, v_pp_ci04;
            IF v_done_ci04 = 1 THEN LEAVE loop_ci04; END IF;
            SET v_var_ci04 = v_var_ci04 + (COALESCE(v_lp_ci04,0) - COALESCE(v_pp_ci04,0));
            SET v_marg_ci04 = ERP_FN_MARGIN(v_pid_ci04);
        END LOOP;
        CLOSE c_ci04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ci04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ci05]
    BEGIN
        DECLARE v_inv_ci05 INTEGER DEFAULT 0;
        DECLARE v_amt_ci05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ci05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ci05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci05 INTEGER DEFAULT 0;
        DECLARE c_ci05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci05 = 1;
        OPEN c_ci05;
        loop_ci05: LOOP
            FETCH c_ci05 INTO v_inv_ci05, v_amt_ci05, v_alloc_ci05;
            IF v_done_ci05 = 1 THEN LEAVE loop_ci05; END IF;
            SET v_open_ci05 = v_open_ci05 + (v_amt_ci05 - v_alloc_ci05);
        END LOOP;
        CLOSE c_ci05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ci05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ci06]
    BEGIN
        DECLARE v_lvl_ci06 INTEGER DEFAULT 0;
        DECLARE v_dept_ci06 INTEGER DEFAULT 0;
        DECLARE v_head_ci06 INTEGER DEFAULT 0;
        DECLARE v_done_ci06 INTEGER DEFAULT 0;
        DECLARE c_ci06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci06 = 1;
        OPEN c_ci06;
        loop_ci06: LOOP
            FETCH c_ci06 INTO v_dept_ci06, v_lvl_ci06, v_head_ci06;
            IF v_done_ci06 = 1 THEN LEAVE loop_ci06; END IF;
        END LOOP;
        CLOSE c_ci06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ci06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ci06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ci07]
    BEGIN
        DECLARE v_sh_ci07 INTEGER DEFAULT 0;
        DECLARE v_car_ci07 INTEGER DEFAULT 0;
        DECLARE v_qty_ci07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ci07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ci07 INTEGER DEFAULT 0;
        DECLARE c_ci07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci07 = 1;
        OPEN c_ci07;
        loop_ci07: LOOP
            FETCH c_ci07 INTO v_sh_ci07, v_car_ci07, v_qty_ci07;
            IF v_done_ci07 = 1 THEN LEAVE loop_ci07; END IF;
            SET v_tot_ci07 = v_tot_ci07 + v_qty_ci07;
        END LOOP;
        CLOSE c_ci07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ci07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ci08]
    BEGIN
        DECLARE v_sql_ci08 VARCHAR(1000);
        DECLARE v_n_ci08 INTEGER DEFAULT 0;
        SET v_sql_ci08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ci08 FROM v_sql_ci08;
        EXECUTE st_ci08;
        SELECT COUNT(*) INTO v_n_ci08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ci08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ci09]
    BEGIN
        DECLARE v_key_ci09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ci09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ci09' AS VARCHAR(40)), v_key_ci09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ci10]
    BEGIN
        DECLARE v_so_ci10 INTEGER DEFAULT 0;
        DECLARE v_cust_ci10 INTEGER DEFAULT 0;
        DECLARE v_rk_ci10 INTEGER DEFAULT 0;
        DECLARE v_run_ci10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci10 INTEGER DEFAULT 0;
        DECLARE c_ci10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci10 = 1;
        OPEN c_ci10;
        loop_ci10: LOOP
            FETCH c_ci10 INTO v_so_ci10, v_cust_ci10, v_rk_ci10, v_run_ci10;
            IF v_done_ci10 = 1 THEN LEAVE loop_ci10; END IF;
        END LOOP;
        CLOSE c_ci10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ci10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ci10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ci11]
    BEGIN
        DECLARE v_hi_ci11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ci11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ci11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ci12]
    BEGIN
        DECLARE v_pairs_ci12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ci12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ci12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ci13]
    BEGIN
        DECLARE v_rows_ci13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ci13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ci13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ci13 FROM SESSION.TMP_ci13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ci13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ci14]
    BEGIN
        DECLARE v_rc_ci14 INTEGER DEFAULT 0;
        DECLARE v_band_ci14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ci14 = ROW_COUNT;
        SET v_band_ci14 = CASE
                            WHEN v_rc_ci14 = 0 THEN 'NONE'
                            WHEN v_rc_ci14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ci14, 'COUNT', 'band=' || v_band_ci14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ci15]
    BEGIN
        DECLARE v_i_ci15 INTEGER DEFAULT 0;
        SAVEPOINT sp_ci15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ci15 < 4 DO
            SET v_i_ci15 = v_i_ci15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ci15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ci15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ci15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ci16]
    BEGIN
        DECLARE v_j_ci16 INTEGER DEFAULT 0;
        DECLARE v_sum_ci16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ci16 = v_j_ci16 + 1;
        UNTIL v_j_ci16 >= 3 END REPEAT;
        FOR row_ci16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ci16 = v_sum_ci16 + COALESCE(row_ci16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ci16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ci16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ci17]
    BEGIN
        DECLARE v_n_ci17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ci17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ci17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [ci18]
    BEGIN
        DECLARE v_levels_ci18 INTEGER DEFAULT 0;
        DECLARE c_ci18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_ci18 = 0;
        OPEN c_ci18;
        FETCH c_ci18 INTO v_levels_ci18;
        CLOSE c_ci18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_ci18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ci19]
    BEGIN
        DECLARE v_sql_ci19 VARCHAR(1000);
        DECLARE v_n_ci19 INTEGER DEFAULT 0;
        SET v_sql_ci19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_ci19 FROM v_sql_ci19;
        EXECUTE st_ci19;
        SELECT COUNT(*) INTO v_n_ci19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ci19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ci20]
    BEGIN
        DECLARE v_key_ci20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ci20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ci20' AS VARCHAR(40)), v_key_ci20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [ci21]
    BEGIN
        DECLARE v_so_ci21 INTEGER DEFAULT 0;
        DECLARE v_cust_ci21 INTEGER DEFAULT 0;
        DECLARE v_ctry_ci21 INTEGER DEFAULT 0;
        DECLARE v_ccy_ci21 INTEGER DEFAULT 0;
        DECLARE v_sub_ci21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ci21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ci21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ci21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ci21 INTEGER DEFAULT 0;
        DECLARE v_done_ci21 INTEGER DEFAULT 0;
        DECLARE c_ci21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci21 = 1;
        OPEN c_ci21;
        loop_ci21: LOOP
            FETCH c_ci21 INTO v_so_ci21, v_cust_ci21, v_ctry_ci21, v_ccy_ci21, v_sub_ci21;
            IF v_done_ci21 = 1 THEN LEAVE loop_ci21; END IF;
            SET v_tax_ci21 = ERP_FN_TAX(v_ctry_ci21, v_sub_ci21);
            SET v_fx_ci21 = ERP_FN_FX_CONVERT(v_ccy_ci21, 1, v_sub_ci21 + v_tax_ci21);
            SET v_acc_ci21 = v_acc_ci21 + v_fx_ci21;
            SET v_cnt_ci21 = v_cnt_ci21 + 1;
        END LOOP;
        CLOSE c_ci21;
        IF v_cnt_ci21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ci21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ci21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ci22]
    BEGIN
        DECLARE v_pid_ci22 INTEGER DEFAULT 0;
        DECLARE v_oh_ci22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ci22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ci22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ci22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ci22 INTEGER DEFAULT 0;
        DECLARE c_ci22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci22 = 1;
        OPEN c_ci22;
        loop_ci22: LOOP
            FETCH c_ci22 INTO v_pid_ci22, v_oh_ci22, v_cost_ci22;
            IF v_done_ci22 = 1 THEN LEAVE loop_ci22; END IF;
            SET v_avail_ci22 = ERP_FN_INVENTORY_ONHAND(v_pid_ci22);
            SET v_val_ci22 = v_val_ci22 + CAST(COALESCE(v_oh_ci22,0) * COALESCE(v_cost_ci22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ci22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ci22;
        END LOOP;
        CLOSE c_ci22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ci22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ci23]
    BEGIN
        DECLARE v_prod_ci23 INTEGER DEFAULT 0;
        DECLARE v_rm_ci23 INTEGER DEFAULT 0;
        DECLARE v_supp_ci23 INTEGER DEFAULT 0;
        DECLARE v_qper_ci23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ci23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ci23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ci23 INTEGER DEFAULT 0;
        DECLARE c_ci23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci23 = 1;
        OPEN c_ci23;
        loop_ci23: LOOP
            FETCH c_ci23 INTO v_prod_ci23, v_rm_ci23, v_supp_ci23, v_qper_ci23, v_uc_ci23;
            IF v_done_ci23 = 1 THEN LEAVE loop_ci23; END IF;
            SET v_roll_ci23 = v_roll_ci23 + COALESCE(v_qper_ci23,0) * COALESCE(v_uc_ci23,0);
        END LOOP;
        CLOSE c_ci23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ci23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ci24]
    BEGIN
        DECLARE v_acct_ci24 INTEGER DEFAULT 0;
        DECLARE v_deb_ci24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ci24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ci24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci24 INTEGER DEFAULT 0;
        DECLARE c_ci24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci24 = 1;
        OPEN c_ci24;
        loop_ci24: LOOP
            FETCH c_ci24 INTO v_acct_ci24, v_deb_ci24, v_cred_ci24;
            IF v_done_ci24 = 1 THEN LEAVE loop_ci24; END IF;
            SET v_net_ci24 = v_net_ci24 + (v_deb_ci24 - v_cred_ci24);
        END LOOP;
        CLOSE c_ci24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ci24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ci25]
    BEGIN
        DECLARE v_pid_ci25 INTEGER DEFAULT 0;
        DECLARE v_lp_ci25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ci25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ci25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ci25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ci25 INTEGER DEFAULT 0;
        DECLARE c_ci25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci25 = 1;
        OPEN c_ci25;
        loop_ci25: LOOP
            FETCH c_ci25 INTO v_pid_ci25, v_lp_ci25, v_pp_ci25;
            IF v_done_ci25 = 1 THEN LEAVE loop_ci25; END IF;
            SET v_var_ci25 = v_var_ci25 + (COALESCE(v_lp_ci25,0) - COALESCE(v_pp_ci25,0));
            SET v_marg_ci25 = ERP_FN_MARGIN(v_pid_ci25);
        END LOOP;
        CLOSE c_ci25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ci25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ci26]
    BEGIN
        DECLARE v_inv_ci26 INTEGER DEFAULT 0;
        DECLARE v_amt_ci26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ci26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ci26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci26 INTEGER DEFAULT 0;
        DECLARE c_ci26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci26 = 1;
        OPEN c_ci26;
        loop_ci26: LOOP
            FETCH c_ci26 INTO v_inv_ci26, v_amt_ci26, v_alloc_ci26;
            IF v_done_ci26 = 1 THEN LEAVE loop_ci26; END IF;
            SET v_open_ci26 = v_open_ci26 + (v_amt_ci26 - v_alloc_ci26);
        END LOOP;
        CLOSE c_ci26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ci26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ci27]
    BEGIN
        DECLARE v_lvl_ci27 INTEGER DEFAULT 0;
        DECLARE v_dept_ci27 INTEGER DEFAULT 0;
        DECLARE v_head_ci27 INTEGER DEFAULT 0;
        DECLARE v_done_ci27 INTEGER DEFAULT 0;
        DECLARE c_ci27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci27 = 1;
        OPEN c_ci27;
        loop_ci27: LOOP
            FETCH c_ci27 INTO v_dept_ci27, v_lvl_ci27, v_head_ci27;
            IF v_done_ci27 = 1 THEN LEAVE loop_ci27; END IF;
        END LOOP;
        CLOSE c_ci27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ci27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ci27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ci28]
    BEGIN
        DECLARE v_sh_ci28 INTEGER DEFAULT 0;
        DECLARE v_car_ci28 INTEGER DEFAULT 0;
        DECLARE v_qty_ci28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ci28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ci28 INTEGER DEFAULT 0;
        DECLARE c_ci28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci28 = 1;
        OPEN c_ci28;
        loop_ci28: LOOP
            FETCH c_ci28 INTO v_sh_ci28, v_car_ci28, v_qty_ci28;
            IF v_done_ci28 = 1 THEN LEAVE loop_ci28; END IF;
            SET v_tot_ci28 = v_tot_ci28 + v_qty_ci28;
        END LOOP;
        CLOSE c_ci28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ci28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ci29]
    BEGIN
        DECLARE v_sql_ci29 VARCHAR(1000);
        DECLARE v_n_ci29 INTEGER DEFAULT 0;
        SET v_sql_ci29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ci29 FROM v_sql_ci29;
        EXECUTE st_ci29;
        SELECT COUNT(*) INTO v_n_ci29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ci29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ci30]
    BEGIN
        DECLARE v_key_ci30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ci30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ci30' AS VARCHAR(40)), v_key_ci30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ci31]
    BEGIN
        DECLARE v_so_ci31 INTEGER DEFAULT 0;
        DECLARE v_cust_ci31 INTEGER DEFAULT 0;
        DECLARE v_rk_ci31 INTEGER DEFAULT 0;
        DECLARE v_run_ci31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci31 INTEGER DEFAULT 0;
        DECLARE c_ci31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci31 = 1;
        OPEN c_ci31;
        loop_ci31: LOOP
            FETCH c_ci31 INTO v_so_ci31, v_cust_ci31, v_rk_ci31, v_run_ci31;
            IF v_done_ci31 = 1 THEN LEAVE loop_ci31; END IF;
        END LOOP;
        CLOSE c_ci31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ci31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ci31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ci32]
    BEGIN
        DECLARE v_hi_ci32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ci32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ci32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ci33]
    BEGIN
        DECLARE v_pairs_ci33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ci33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ci33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ci34]
    BEGIN
        DECLARE v_rows_ci34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ci34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ci34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ci34 FROM SESSION.TMP_ci34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ci34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ci35]
    BEGIN
        DECLARE v_rc_ci35 INTEGER DEFAULT 0;
        DECLARE v_band_ci35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ci35 = ROW_COUNT;
        SET v_band_ci35 = CASE
                            WHEN v_rc_ci35 = 0 THEN 'NONE'
                            WHEN v_rc_ci35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ci35, 'COUNT', 'band=' || v_band_ci35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ci36]
    BEGIN
        DECLARE v_i_ci36 INTEGER DEFAULT 0;
        SAVEPOINT sp_ci36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ci36 < 4 DO
            SET v_i_ci36 = v_i_ci36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ci36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ci36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ci36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ci37]
    BEGIN
        DECLARE v_j_ci37 INTEGER DEFAULT 0;
        DECLARE v_sum_ci37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ci37 = v_j_ci37 + 1;
        UNTIL v_j_ci37 >= 3 END REPEAT;
        FOR row_ci37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ci37 = v_sum_ci37 + COALESCE(row_ci37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ci37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ci37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ci38]
    BEGIN
        DECLARE v_n_ci38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ci38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ci38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [ci39]
    BEGIN
        DECLARE v_levels_ci39 INTEGER DEFAULT 0;
        DECLARE c_ci39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_ci39 = 0;
        OPEN c_ci39;
        FETCH c_ci39 INTO v_levels_ci39;
        CLOSE c_ci39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_ci39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ci40]
    BEGIN
        DECLARE v_sql_ci40 VARCHAR(1000);
        DECLARE v_n_ci40 INTEGER DEFAULT 0;
        SET v_sql_ci40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_ci40 FROM v_sql_ci40;
        EXECUTE st_ci40;
        SELECT COUNT(*) INTO v_n_ci40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ci40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ci41]
    BEGIN
        DECLARE v_key_ci41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ci41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ci41' AS VARCHAR(40)), v_key_ci41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [ci42]
    BEGIN
        DECLARE v_so_ci42 INTEGER DEFAULT 0;
        DECLARE v_cust_ci42 INTEGER DEFAULT 0;
        DECLARE v_ctry_ci42 INTEGER DEFAULT 0;
        DECLARE v_ccy_ci42 INTEGER DEFAULT 0;
        DECLARE v_sub_ci42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ci42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ci42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ci42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ci42 INTEGER DEFAULT 0;
        DECLARE v_done_ci42 INTEGER DEFAULT 0;
        DECLARE c_ci42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci42 = 1;
        OPEN c_ci42;
        loop_ci42: LOOP
            FETCH c_ci42 INTO v_so_ci42, v_cust_ci42, v_ctry_ci42, v_ccy_ci42, v_sub_ci42;
            IF v_done_ci42 = 1 THEN LEAVE loop_ci42; END IF;
            SET v_tax_ci42 = ERP_FN_TAX(v_ctry_ci42, v_sub_ci42);
            SET v_fx_ci42 = ERP_FN_FX_CONVERT(v_ccy_ci42, 1, v_sub_ci42 + v_tax_ci42);
            SET v_acc_ci42 = v_acc_ci42 + v_fx_ci42;
            SET v_cnt_ci42 = v_cnt_ci42 + 1;
        END LOOP;
        CLOSE c_ci42;
        IF v_cnt_ci42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ci42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ci42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ci43]
    BEGIN
        DECLARE v_pid_ci43 INTEGER DEFAULT 0;
        DECLARE v_oh_ci43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ci43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ci43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ci43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ci43 INTEGER DEFAULT 0;
        DECLARE c_ci43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci43 = 1;
        OPEN c_ci43;
        loop_ci43: LOOP
            FETCH c_ci43 INTO v_pid_ci43, v_oh_ci43, v_cost_ci43;
            IF v_done_ci43 = 1 THEN LEAVE loop_ci43; END IF;
            SET v_avail_ci43 = ERP_FN_INVENTORY_ONHAND(v_pid_ci43);
            SET v_val_ci43 = v_val_ci43 + CAST(COALESCE(v_oh_ci43,0) * COALESCE(v_cost_ci43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ci43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ci43;
        END LOOP;
        CLOSE c_ci43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ci43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ci44]
    BEGIN
        DECLARE v_prod_ci44 INTEGER DEFAULT 0;
        DECLARE v_rm_ci44 INTEGER DEFAULT 0;
        DECLARE v_supp_ci44 INTEGER DEFAULT 0;
        DECLARE v_qper_ci44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ci44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ci44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ci44 INTEGER DEFAULT 0;
        DECLARE c_ci44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci44 = 1;
        OPEN c_ci44;
        loop_ci44: LOOP
            FETCH c_ci44 INTO v_prod_ci44, v_rm_ci44, v_supp_ci44, v_qper_ci44, v_uc_ci44;
            IF v_done_ci44 = 1 THEN LEAVE loop_ci44; END IF;
            SET v_roll_ci44 = v_roll_ci44 + COALESCE(v_qper_ci44,0) * COALESCE(v_uc_ci44,0);
        END LOOP;
        CLOSE c_ci44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ci44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ci45]
    BEGIN
        DECLARE v_acct_ci45 INTEGER DEFAULT 0;
        DECLARE v_deb_ci45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ci45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ci45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci45 INTEGER DEFAULT 0;
        DECLARE c_ci45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci45 = 1;
        OPEN c_ci45;
        loop_ci45: LOOP
            FETCH c_ci45 INTO v_acct_ci45, v_deb_ci45, v_cred_ci45;
            IF v_done_ci45 = 1 THEN LEAVE loop_ci45; END IF;
            SET v_net_ci45 = v_net_ci45 + (v_deb_ci45 - v_cred_ci45);
        END LOOP;
        CLOSE c_ci45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ci45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ci46]
    BEGIN
        DECLARE v_pid_ci46 INTEGER DEFAULT 0;
        DECLARE v_lp_ci46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ci46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ci46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ci46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ci46 INTEGER DEFAULT 0;
        DECLARE c_ci46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci46 = 1;
        OPEN c_ci46;
        loop_ci46: LOOP
            FETCH c_ci46 INTO v_pid_ci46, v_lp_ci46, v_pp_ci46;
            IF v_done_ci46 = 1 THEN LEAVE loop_ci46; END IF;
            SET v_var_ci46 = v_var_ci46 + (COALESCE(v_lp_ci46,0) - COALESCE(v_pp_ci46,0));
            SET v_marg_ci46 = ERP_FN_MARGIN(v_pid_ci46);
        END LOOP;
        CLOSE c_ci46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ci46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ci47]
    BEGIN
        DECLARE v_inv_ci47 INTEGER DEFAULT 0;
        DECLARE v_amt_ci47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ci47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ci47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci47 INTEGER DEFAULT 0;
        DECLARE c_ci47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci47 = 1;
        OPEN c_ci47;
        loop_ci47: LOOP
            FETCH c_ci47 INTO v_inv_ci47, v_amt_ci47, v_alloc_ci47;
            IF v_done_ci47 = 1 THEN LEAVE loop_ci47; END IF;
            SET v_open_ci47 = v_open_ci47 + (v_amt_ci47 - v_alloc_ci47);
        END LOOP;
        CLOSE c_ci47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ci47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ci48]
    BEGIN
        DECLARE v_lvl_ci48 INTEGER DEFAULT 0;
        DECLARE v_dept_ci48 INTEGER DEFAULT 0;
        DECLARE v_head_ci48 INTEGER DEFAULT 0;
        DECLARE v_done_ci48 INTEGER DEFAULT 0;
        DECLARE c_ci48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci48 = 1;
        OPEN c_ci48;
        loop_ci48: LOOP
            FETCH c_ci48 INTO v_dept_ci48, v_lvl_ci48, v_head_ci48;
            IF v_done_ci48 = 1 THEN LEAVE loop_ci48; END IF;
        END LOOP;
        CLOSE c_ci48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ci48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ci48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ci49]
    BEGIN
        DECLARE v_sh_ci49 INTEGER DEFAULT 0;
        DECLARE v_car_ci49 INTEGER DEFAULT 0;
        DECLARE v_qty_ci49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ci49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ci49 INTEGER DEFAULT 0;
        DECLARE c_ci49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci49 = 1;
        OPEN c_ci49;
        loop_ci49: LOOP
            FETCH c_ci49 INTO v_sh_ci49, v_car_ci49, v_qty_ci49;
            IF v_done_ci49 = 1 THEN LEAVE loop_ci49; END IF;
            SET v_tot_ci49 = v_tot_ci49 + v_qty_ci49;
        END LOOP;
        CLOSE c_ci49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ci49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ci50]
    BEGIN
        DECLARE v_sql_ci50 VARCHAR(1000);
        DECLARE v_n_ci50 INTEGER DEFAULT 0;
        SET v_sql_ci50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ci50 FROM v_sql_ci50;
        EXECUTE st_ci50;
        SELECT COUNT(*) INTO v_n_ci50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ci50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ci51]
    BEGIN
        DECLARE v_key_ci51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ci51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ci51' AS VARCHAR(40)), v_key_ci51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ci52]
    BEGIN
        DECLARE v_so_ci52 INTEGER DEFAULT 0;
        DECLARE v_cust_ci52 INTEGER DEFAULT 0;
        DECLARE v_rk_ci52 INTEGER DEFAULT 0;
        DECLARE v_run_ci52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ci52 INTEGER DEFAULT 0;
        DECLARE c_ci52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ci52 = 1;
        OPEN c_ci52;
        loop_ci52: LOOP
            FETCH c_ci52 INTO v_so_ci52, v_cust_ci52, v_rk_ci52, v_run_ci52;
            IF v_done_ci52 = 1 THEN LEAVE loop_ci52; END IF;
        END LOOP;
        CLOSE c_ci52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ci52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ci52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ci53]
    BEGIN
        DECLARE v_hi_ci53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ci53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ci53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ci54]
    BEGIN
        DECLARE v_pairs_ci54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ci54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ci54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ci55]
    BEGIN
        DECLARE v_rows_ci55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ci55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ci55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ci55 FROM SESSION.TMP_ci55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ci55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ci56]
    BEGIN
        DECLARE v_rc_ci56 INTEGER DEFAULT 0;
        DECLARE v_band_ci56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ci56 = ROW_COUNT;
        SET v_band_ci56 = CASE
                            WHEN v_rc_ci56 = 0 THEN 'NONE'
                            WHEN v_rc_ci56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ci56, 'COUNT', 'band=' || v_band_ci56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ci57]
    BEGIN
        DECLARE v_i_ci57 INTEGER DEFAULT 0;
        SAVEPOINT sp_ci57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ci57 < 4 DO
            SET v_i_ci57 = v_i_ci57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ci57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ci57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ci57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_CREATE_SHIPMENT(IN p_so_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_sh_id INTEGER DEFAULT 0;
    DECLARE v_carrier INTEGER DEFAULT 0;
    DECLARE v_pid INTEGER DEFAULT 0;
    DECLARE v_qty DECIMAL(16,4) DEFAULT 0;
    DECLARE v_done INTEGER DEFAULT 0;
    DECLARE c_lines CURSOR WITH HOLD FOR
        SELECT sol.product_id, sol.qty FROM ERP_SALES_ORDER_LINE sol
        WHERE sol.so_id = p_so_id ORDER BY sol.id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('SHIPMENT', p_so_id, 'ERROR', 'create shipment failed');
    END;
    SELECT MIN(id) INTO v_carrier FROM ERP_CARRIER;
    INSERT INTO ERP_SHIPMENT(so_id, carrier_id, ship_date, status)
    VALUES (p_so_id, v_carrier, CURRENT DATE, 'PENDING');
    SET v_sh_id = IDENTITY_VAL_LOCAL();
    OPEN c_lines;
    ship_loop: LOOP
        FETCH c_lines INTO v_pid, v_qty;
        IF v_done = 1 THEN LEAVE ship_loop; END IF;
        INSERT INTO ERP_SHIPMENT_LINE(shipment_id, product_id, qty_shipped)
        VALUES (v_sh_id, v_pid, v_qty);
    END LOOP;
    CLOSE c_lines;
    CALL ERP_USP_CREATE_INVOICE(p_so_id);
    CALL ERP_USP_AUDIT('SHIPMENT', v_sh_id, 'CREATE', 'shipment created');
    -- order/customer/country/currency revenue scan [cs00]
    BEGIN
        DECLARE v_so_cs00 INTEGER DEFAULT 0;
        DECLARE v_cust_cs00 INTEGER DEFAULT 0;
        DECLARE v_ctry_cs00 INTEGER DEFAULT 0;
        DECLARE v_ccy_cs00 INTEGER DEFAULT 0;
        DECLARE v_sub_cs00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cs00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cs00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cs00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cs00 INTEGER DEFAULT 0;
        DECLARE v_done_cs00 INTEGER DEFAULT 0;
        DECLARE c_cs00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs00 = 1;
        OPEN c_cs00;
        loop_cs00: LOOP
            FETCH c_cs00 INTO v_so_cs00, v_cust_cs00, v_ctry_cs00, v_ccy_cs00, v_sub_cs00;
            IF v_done_cs00 = 1 THEN LEAVE loop_cs00; END IF;
            SET v_tax_cs00 = ERP_FN_TAX(v_ctry_cs00, v_sub_cs00);
            SET v_fx_cs00 = ERP_FN_FX_CONVERT(v_ccy_cs00, 1, v_sub_cs00 + v_tax_cs00);
            SET v_acc_cs00 = v_acc_cs00 + v_fx_cs00;
            SET v_cnt_cs00 = v_cnt_cs00 + 1;
        END LOOP;
        CLOSE c_cs00;
        IF v_cnt_cs00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cs00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cs00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cs01]
    BEGIN
        DECLARE v_pid_cs01 INTEGER DEFAULT 0;
        DECLARE v_oh_cs01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cs01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cs01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cs01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cs01 INTEGER DEFAULT 0;
        DECLARE c_cs01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs01 = 1;
        OPEN c_cs01;
        loop_cs01: LOOP
            FETCH c_cs01 INTO v_pid_cs01, v_oh_cs01, v_cost_cs01;
            IF v_done_cs01 = 1 THEN LEAVE loop_cs01; END IF;
            SET v_avail_cs01 = ERP_FN_INVENTORY_ONHAND(v_pid_cs01);
            SET v_val_cs01 = v_val_cs01 + CAST(COALESCE(v_oh_cs01,0) * COALESCE(v_cost_cs01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cs01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cs01;
        END LOOP;
        CLOSE c_cs01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cs01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cs02]
    BEGIN
        DECLARE v_prod_cs02 INTEGER DEFAULT 0;
        DECLARE v_rm_cs02 INTEGER DEFAULT 0;
        DECLARE v_supp_cs02 INTEGER DEFAULT 0;
        DECLARE v_qper_cs02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cs02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cs02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cs02 INTEGER DEFAULT 0;
        DECLARE c_cs02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs02 = 1;
        OPEN c_cs02;
        loop_cs02: LOOP
            FETCH c_cs02 INTO v_prod_cs02, v_rm_cs02, v_supp_cs02, v_qper_cs02, v_uc_cs02;
            IF v_done_cs02 = 1 THEN LEAVE loop_cs02; END IF;
            SET v_roll_cs02 = v_roll_cs02 + COALESCE(v_qper_cs02,0) * COALESCE(v_uc_cs02,0);
        END LOOP;
        CLOSE c_cs02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cs02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cs03]
    BEGIN
        DECLARE v_acct_cs03 INTEGER DEFAULT 0;
        DECLARE v_deb_cs03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cs03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cs03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs03 INTEGER DEFAULT 0;
        DECLARE c_cs03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs03 = 1;
        OPEN c_cs03;
        loop_cs03: LOOP
            FETCH c_cs03 INTO v_acct_cs03, v_deb_cs03, v_cred_cs03;
            IF v_done_cs03 = 1 THEN LEAVE loop_cs03; END IF;
            SET v_net_cs03 = v_net_cs03 + (v_deb_cs03 - v_cred_cs03);
        END LOOP;
        CLOSE c_cs03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cs03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cs04]
    BEGIN
        DECLARE v_pid_cs04 INTEGER DEFAULT 0;
        DECLARE v_lp_cs04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cs04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cs04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cs04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cs04 INTEGER DEFAULT 0;
        DECLARE c_cs04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs04 = 1;
        OPEN c_cs04;
        loop_cs04: LOOP
            FETCH c_cs04 INTO v_pid_cs04, v_lp_cs04, v_pp_cs04;
            IF v_done_cs04 = 1 THEN LEAVE loop_cs04; END IF;
            SET v_var_cs04 = v_var_cs04 + (COALESCE(v_lp_cs04,0) - COALESCE(v_pp_cs04,0));
            SET v_marg_cs04 = ERP_FN_MARGIN(v_pid_cs04);
        END LOOP;
        CLOSE c_cs04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cs04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cs05]
    BEGIN
        DECLARE v_inv_cs05 INTEGER DEFAULT 0;
        DECLARE v_amt_cs05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cs05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cs05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs05 INTEGER DEFAULT 0;
        DECLARE c_cs05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs05 = 1;
        OPEN c_cs05;
        loop_cs05: LOOP
            FETCH c_cs05 INTO v_inv_cs05, v_amt_cs05, v_alloc_cs05;
            IF v_done_cs05 = 1 THEN LEAVE loop_cs05; END IF;
            SET v_open_cs05 = v_open_cs05 + (v_amt_cs05 - v_alloc_cs05);
        END LOOP;
        CLOSE c_cs05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cs05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [cs06]
    BEGIN
        DECLARE v_lvl_cs06 INTEGER DEFAULT 0;
        DECLARE v_dept_cs06 INTEGER DEFAULT 0;
        DECLARE v_head_cs06 INTEGER DEFAULT 0;
        DECLARE v_done_cs06 INTEGER DEFAULT 0;
        DECLARE c_cs06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs06 = 1;
        OPEN c_cs06;
        loop_cs06: LOOP
            FETCH c_cs06 INTO v_dept_cs06, v_lvl_cs06, v_head_cs06;
            IF v_done_cs06 = 1 THEN LEAVE loop_cs06; END IF;
        END LOOP;
        CLOSE c_cs06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_cs06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_cs06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [cs07]
    BEGIN
        DECLARE v_sh_cs07 INTEGER DEFAULT 0;
        DECLARE v_car_cs07 INTEGER DEFAULT 0;
        DECLARE v_qty_cs07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_cs07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cs07 INTEGER DEFAULT 0;
        DECLARE c_cs07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs07 = 1;
        OPEN c_cs07;
        loop_cs07: LOOP
            FETCH c_cs07 INTO v_sh_cs07, v_car_cs07, v_qty_cs07;
            IF v_done_cs07 = 1 THEN LEAVE loop_cs07; END IF;
            SET v_tot_cs07 = v_tot_cs07 + v_qty_cs07;
        END LOOP;
        CLOSE c_cs07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_cs07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cs08]
    BEGIN
        DECLARE v_sql_cs08 VARCHAR(1000);
        DECLARE v_n_cs08 INTEGER DEFAULT 0;
        SET v_sql_cs08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_cs08 FROM v_sql_cs08;
        EXECUTE st_cs08;
        SELECT COUNT(*) INTO v_n_cs08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cs08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cs09]
    BEGIN
        DECLARE v_key_cs09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cs09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cs09' AS VARCHAR(40)), v_key_cs09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [cs10]
    BEGIN
        DECLARE v_so_cs10 INTEGER DEFAULT 0;
        DECLARE v_cust_cs10 INTEGER DEFAULT 0;
        DECLARE v_rk_cs10 INTEGER DEFAULT 0;
        DECLARE v_run_cs10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs10 INTEGER DEFAULT 0;
        DECLARE c_cs10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs10 = 1;
        OPEN c_cs10;
        loop_cs10: LOOP
            FETCH c_cs10 INTO v_so_cs10, v_cust_cs10, v_rk_cs10, v_run_cs10;
            IF v_done_cs10 = 1 THEN LEAVE loop_cs10; END IF;
        END LOOP;
        CLOSE c_cs10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_cs10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_cs10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [cs11]
    BEGIN
        DECLARE v_hi_cs11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_cs11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_cs11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [cs12]
    BEGIN
        DECLARE v_pairs_cs12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_cs12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_cs12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [cs13]
    BEGIN
        DECLARE v_rows_cs13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_cs13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_cs13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_cs13 FROM SESSION.TMP_cs13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_cs13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [cs14]
    BEGIN
        DECLARE v_rc_cs14 INTEGER DEFAULT 0;
        DECLARE v_band_cs14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_cs14 = ROW_COUNT;
        SET v_band_cs14 = CASE
                            WHEN v_rc_cs14 = 0 THEN 'NONE'
                            WHEN v_rc_cs14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_cs14, 'COUNT', 'band=' || v_band_cs14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [cs15]
    BEGIN
        DECLARE v_i_cs15 INTEGER DEFAULT 0;
        SAVEPOINT sp_cs15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_cs15 < 4 DO
            SET v_i_cs15 = v_i_cs15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_cs15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_cs15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_cs15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [cs16]
    BEGIN
        DECLARE v_j_cs16 INTEGER DEFAULT 0;
        DECLARE v_sum_cs16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_cs16 = v_j_cs16 + 1;
        UNTIL v_j_cs16 >= 3 END REPEAT;
        FOR row_cs16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_cs16 = v_sum_cs16 + COALESCE(row_cs16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_cs16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_cs16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [cs17]
    BEGIN
        DECLARE v_n_cs17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_cs17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_cs17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [cs18]
    BEGIN
        DECLARE v_levels_cs18 INTEGER DEFAULT 0;
        DECLARE c_cs18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_cs18 = 0;
        OPEN c_cs18;
        FETCH c_cs18 INTO v_levels_cs18;
        CLOSE c_cs18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_cs18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cs19]
    BEGIN
        DECLARE v_sql_cs19 VARCHAR(1000);
        DECLARE v_n_cs19 INTEGER DEFAULT 0;
        SET v_sql_cs19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_cs19 FROM v_sql_cs19;
        EXECUTE st_cs19;
        SELECT COUNT(*) INTO v_n_cs19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cs19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cs20]
    BEGIN
        DECLARE v_key_cs20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cs20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cs20' AS VARCHAR(40)), v_key_cs20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [cs21]
    BEGIN
        DECLARE v_so_cs21 INTEGER DEFAULT 0;
        DECLARE v_cust_cs21 INTEGER DEFAULT 0;
        DECLARE v_ctry_cs21 INTEGER DEFAULT 0;
        DECLARE v_ccy_cs21 INTEGER DEFAULT 0;
        DECLARE v_sub_cs21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cs21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cs21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cs21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cs21 INTEGER DEFAULT 0;
        DECLARE v_done_cs21 INTEGER DEFAULT 0;
        DECLARE c_cs21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs21 = 1;
        OPEN c_cs21;
        loop_cs21: LOOP
            FETCH c_cs21 INTO v_so_cs21, v_cust_cs21, v_ctry_cs21, v_ccy_cs21, v_sub_cs21;
            IF v_done_cs21 = 1 THEN LEAVE loop_cs21; END IF;
            SET v_tax_cs21 = ERP_FN_TAX(v_ctry_cs21, v_sub_cs21);
            SET v_fx_cs21 = ERP_FN_FX_CONVERT(v_ccy_cs21, 1, v_sub_cs21 + v_tax_cs21);
            SET v_acc_cs21 = v_acc_cs21 + v_fx_cs21;
            SET v_cnt_cs21 = v_cnt_cs21 + 1;
        END LOOP;
        CLOSE c_cs21;
        IF v_cnt_cs21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cs21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cs21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cs22]
    BEGIN
        DECLARE v_pid_cs22 INTEGER DEFAULT 0;
        DECLARE v_oh_cs22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cs22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cs22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cs22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cs22 INTEGER DEFAULT 0;
        DECLARE c_cs22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs22 = 1;
        OPEN c_cs22;
        loop_cs22: LOOP
            FETCH c_cs22 INTO v_pid_cs22, v_oh_cs22, v_cost_cs22;
            IF v_done_cs22 = 1 THEN LEAVE loop_cs22; END IF;
            SET v_avail_cs22 = ERP_FN_INVENTORY_ONHAND(v_pid_cs22);
            SET v_val_cs22 = v_val_cs22 + CAST(COALESCE(v_oh_cs22,0) * COALESCE(v_cost_cs22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cs22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cs22;
        END LOOP;
        CLOSE c_cs22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cs22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cs23]
    BEGIN
        DECLARE v_prod_cs23 INTEGER DEFAULT 0;
        DECLARE v_rm_cs23 INTEGER DEFAULT 0;
        DECLARE v_supp_cs23 INTEGER DEFAULT 0;
        DECLARE v_qper_cs23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cs23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cs23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cs23 INTEGER DEFAULT 0;
        DECLARE c_cs23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs23 = 1;
        OPEN c_cs23;
        loop_cs23: LOOP
            FETCH c_cs23 INTO v_prod_cs23, v_rm_cs23, v_supp_cs23, v_qper_cs23, v_uc_cs23;
            IF v_done_cs23 = 1 THEN LEAVE loop_cs23; END IF;
            SET v_roll_cs23 = v_roll_cs23 + COALESCE(v_qper_cs23,0) * COALESCE(v_uc_cs23,0);
        END LOOP;
        CLOSE c_cs23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cs23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cs24]
    BEGIN
        DECLARE v_acct_cs24 INTEGER DEFAULT 0;
        DECLARE v_deb_cs24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cs24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cs24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs24 INTEGER DEFAULT 0;
        DECLARE c_cs24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs24 = 1;
        OPEN c_cs24;
        loop_cs24: LOOP
            FETCH c_cs24 INTO v_acct_cs24, v_deb_cs24, v_cred_cs24;
            IF v_done_cs24 = 1 THEN LEAVE loop_cs24; END IF;
            SET v_net_cs24 = v_net_cs24 + (v_deb_cs24 - v_cred_cs24);
        END LOOP;
        CLOSE c_cs24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cs24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cs25]
    BEGIN
        DECLARE v_pid_cs25 INTEGER DEFAULT 0;
        DECLARE v_lp_cs25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cs25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cs25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cs25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cs25 INTEGER DEFAULT 0;
        DECLARE c_cs25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs25 = 1;
        OPEN c_cs25;
        loop_cs25: LOOP
            FETCH c_cs25 INTO v_pid_cs25, v_lp_cs25, v_pp_cs25;
            IF v_done_cs25 = 1 THEN LEAVE loop_cs25; END IF;
            SET v_var_cs25 = v_var_cs25 + (COALESCE(v_lp_cs25,0) - COALESCE(v_pp_cs25,0));
            SET v_marg_cs25 = ERP_FN_MARGIN(v_pid_cs25);
        END LOOP;
        CLOSE c_cs25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cs25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cs26]
    BEGIN
        DECLARE v_inv_cs26 INTEGER DEFAULT 0;
        DECLARE v_amt_cs26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cs26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cs26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs26 INTEGER DEFAULT 0;
        DECLARE c_cs26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs26 = 1;
        OPEN c_cs26;
        loop_cs26: LOOP
            FETCH c_cs26 INTO v_inv_cs26, v_amt_cs26, v_alloc_cs26;
            IF v_done_cs26 = 1 THEN LEAVE loop_cs26; END IF;
            SET v_open_cs26 = v_open_cs26 + (v_amt_cs26 - v_alloc_cs26);
        END LOOP;
        CLOSE c_cs26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cs26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [cs27]
    BEGIN
        DECLARE v_lvl_cs27 INTEGER DEFAULT 0;
        DECLARE v_dept_cs27 INTEGER DEFAULT 0;
        DECLARE v_head_cs27 INTEGER DEFAULT 0;
        DECLARE v_done_cs27 INTEGER DEFAULT 0;
        DECLARE c_cs27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs27 = 1;
        OPEN c_cs27;
        loop_cs27: LOOP
            FETCH c_cs27 INTO v_dept_cs27, v_lvl_cs27, v_head_cs27;
            IF v_done_cs27 = 1 THEN LEAVE loop_cs27; END IF;
        END LOOP;
        CLOSE c_cs27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_cs27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_cs27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [cs28]
    BEGIN
        DECLARE v_sh_cs28 INTEGER DEFAULT 0;
        DECLARE v_car_cs28 INTEGER DEFAULT 0;
        DECLARE v_qty_cs28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_cs28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cs28 INTEGER DEFAULT 0;
        DECLARE c_cs28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs28 = 1;
        OPEN c_cs28;
        loop_cs28: LOOP
            FETCH c_cs28 INTO v_sh_cs28, v_car_cs28, v_qty_cs28;
            IF v_done_cs28 = 1 THEN LEAVE loop_cs28; END IF;
            SET v_tot_cs28 = v_tot_cs28 + v_qty_cs28;
        END LOOP;
        CLOSE c_cs28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_cs28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cs29]
    BEGIN
        DECLARE v_sql_cs29 VARCHAR(1000);
        DECLARE v_n_cs29 INTEGER DEFAULT 0;
        SET v_sql_cs29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_cs29 FROM v_sql_cs29;
        EXECUTE st_cs29;
        SELECT COUNT(*) INTO v_n_cs29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cs29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cs30]
    BEGIN
        DECLARE v_key_cs30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cs30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cs30' AS VARCHAR(40)), v_key_cs30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [cs31]
    BEGIN
        DECLARE v_so_cs31 INTEGER DEFAULT 0;
        DECLARE v_cust_cs31 INTEGER DEFAULT 0;
        DECLARE v_rk_cs31 INTEGER DEFAULT 0;
        DECLARE v_run_cs31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs31 INTEGER DEFAULT 0;
        DECLARE c_cs31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs31 = 1;
        OPEN c_cs31;
        loop_cs31: LOOP
            FETCH c_cs31 INTO v_so_cs31, v_cust_cs31, v_rk_cs31, v_run_cs31;
            IF v_done_cs31 = 1 THEN LEAVE loop_cs31; END IF;
        END LOOP;
        CLOSE c_cs31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_cs31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_cs31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [cs32]
    BEGIN
        DECLARE v_hi_cs32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_cs32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_cs32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [cs33]
    BEGIN
        DECLARE v_pairs_cs33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_cs33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_cs33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [cs34]
    BEGIN
        DECLARE v_rows_cs34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_cs34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_cs34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_cs34 FROM SESSION.TMP_cs34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_cs34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [cs35]
    BEGIN
        DECLARE v_rc_cs35 INTEGER DEFAULT 0;
        DECLARE v_band_cs35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_cs35 = ROW_COUNT;
        SET v_band_cs35 = CASE
                            WHEN v_rc_cs35 = 0 THEN 'NONE'
                            WHEN v_rc_cs35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_cs35, 'COUNT', 'band=' || v_band_cs35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [cs36]
    BEGIN
        DECLARE v_i_cs36 INTEGER DEFAULT 0;
        SAVEPOINT sp_cs36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_cs36 < 4 DO
            SET v_i_cs36 = v_i_cs36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_cs36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_cs36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_cs36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [cs37]
    BEGIN
        DECLARE v_j_cs37 INTEGER DEFAULT 0;
        DECLARE v_sum_cs37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_cs37 = v_j_cs37 + 1;
        UNTIL v_j_cs37 >= 3 END REPEAT;
        FOR row_cs37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_cs37 = v_sum_cs37 + COALESCE(row_cs37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_cs37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_cs37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [cs38]
    BEGIN
        DECLARE v_n_cs38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_cs38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_cs38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [cs39]
    BEGIN
        DECLARE v_levels_cs39 INTEGER DEFAULT 0;
        DECLARE c_cs39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_cs39 = 0;
        OPEN c_cs39;
        FETCH c_cs39 INTO v_levels_cs39;
        CLOSE c_cs39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_cs39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cs40]
    BEGIN
        DECLARE v_sql_cs40 VARCHAR(1000);
        DECLARE v_n_cs40 INTEGER DEFAULT 0;
        SET v_sql_cs40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_cs40 FROM v_sql_cs40;
        EXECUTE st_cs40;
        SELECT COUNT(*) INTO v_n_cs40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cs40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cs41]
    BEGIN
        DECLARE v_key_cs41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cs41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cs41' AS VARCHAR(40)), v_key_cs41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [cs42]
    BEGIN
        DECLARE v_so_cs42 INTEGER DEFAULT 0;
        DECLARE v_cust_cs42 INTEGER DEFAULT 0;
        DECLARE v_ctry_cs42 INTEGER DEFAULT 0;
        DECLARE v_ccy_cs42 INTEGER DEFAULT 0;
        DECLARE v_sub_cs42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cs42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cs42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cs42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cs42 INTEGER DEFAULT 0;
        DECLARE v_done_cs42 INTEGER DEFAULT 0;
        DECLARE c_cs42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs42 = 1;
        OPEN c_cs42;
        loop_cs42: LOOP
            FETCH c_cs42 INTO v_so_cs42, v_cust_cs42, v_ctry_cs42, v_ccy_cs42, v_sub_cs42;
            IF v_done_cs42 = 1 THEN LEAVE loop_cs42; END IF;
            SET v_tax_cs42 = ERP_FN_TAX(v_ctry_cs42, v_sub_cs42);
            SET v_fx_cs42 = ERP_FN_FX_CONVERT(v_ccy_cs42, 1, v_sub_cs42 + v_tax_cs42);
            SET v_acc_cs42 = v_acc_cs42 + v_fx_cs42;
            SET v_cnt_cs42 = v_cnt_cs42 + 1;
        END LOOP;
        CLOSE c_cs42;
        IF v_cnt_cs42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cs42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cs42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cs43]
    BEGIN
        DECLARE v_pid_cs43 INTEGER DEFAULT 0;
        DECLARE v_oh_cs43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cs43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cs43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cs43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cs43 INTEGER DEFAULT 0;
        DECLARE c_cs43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs43 = 1;
        OPEN c_cs43;
        loop_cs43: LOOP
            FETCH c_cs43 INTO v_pid_cs43, v_oh_cs43, v_cost_cs43;
            IF v_done_cs43 = 1 THEN LEAVE loop_cs43; END IF;
            SET v_avail_cs43 = ERP_FN_INVENTORY_ONHAND(v_pid_cs43);
            SET v_val_cs43 = v_val_cs43 + CAST(COALESCE(v_oh_cs43,0) * COALESCE(v_cost_cs43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cs43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cs43;
        END LOOP;
        CLOSE c_cs43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cs43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cs44]
    BEGIN
        DECLARE v_prod_cs44 INTEGER DEFAULT 0;
        DECLARE v_rm_cs44 INTEGER DEFAULT 0;
        DECLARE v_supp_cs44 INTEGER DEFAULT 0;
        DECLARE v_qper_cs44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cs44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cs44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cs44 INTEGER DEFAULT 0;
        DECLARE c_cs44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs44 = 1;
        OPEN c_cs44;
        loop_cs44: LOOP
            FETCH c_cs44 INTO v_prod_cs44, v_rm_cs44, v_supp_cs44, v_qper_cs44, v_uc_cs44;
            IF v_done_cs44 = 1 THEN LEAVE loop_cs44; END IF;
            SET v_roll_cs44 = v_roll_cs44 + COALESCE(v_qper_cs44,0) * COALESCE(v_uc_cs44,0);
        END LOOP;
        CLOSE c_cs44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cs44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cs45]
    BEGIN
        DECLARE v_acct_cs45 INTEGER DEFAULT 0;
        DECLARE v_deb_cs45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cs45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cs45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs45 INTEGER DEFAULT 0;
        DECLARE c_cs45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs45 = 1;
        OPEN c_cs45;
        loop_cs45: LOOP
            FETCH c_cs45 INTO v_acct_cs45, v_deb_cs45, v_cred_cs45;
            IF v_done_cs45 = 1 THEN LEAVE loop_cs45; END IF;
            SET v_net_cs45 = v_net_cs45 + (v_deb_cs45 - v_cred_cs45);
        END LOOP;
        CLOSE c_cs45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cs45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cs46]
    BEGIN
        DECLARE v_pid_cs46 INTEGER DEFAULT 0;
        DECLARE v_lp_cs46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cs46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cs46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cs46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cs46 INTEGER DEFAULT 0;
        DECLARE c_cs46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs46 = 1;
        OPEN c_cs46;
        loop_cs46: LOOP
            FETCH c_cs46 INTO v_pid_cs46, v_lp_cs46, v_pp_cs46;
            IF v_done_cs46 = 1 THEN LEAVE loop_cs46; END IF;
            SET v_var_cs46 = v_var_cs46 + (COALESCE(v_lp_cs46,0) - COALESCE(v_pp_cs46,0));
            SET v_marg_cs46 = ERP_FN_MARGIN(v_pid_cs46);
        END LOOP;
        CLOSE c_cs46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cs46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cs47]
    BEGIN
        DECLARE v_inv_cs47 INTEGER DEFAULT 0;
        DECLARE v_amt_cs47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cs47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cs47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs47 INTEGER DEFAULT 0;
        DECLARE c_cs47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs47 = 1;
        OPEN c_cs47;
        loop_cs47: LOOP
            FETCH c_cs47 INTO v_inv_cs47, v_amt_cs47, v_alloc_cs47;
            IF v_done_cs47 = 1 THEN LEAVE loop_cs47; END IF;
            SET v_open_cs47 = v_open_cs47 + (v_amt_cs47 - v_alloc_cs47);
        END LOOP;
        CLOSE c_cs47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cs47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [cs48]
    BEGIN
        DECLARE v_lvl_cs48 INTEGER DEFAULT 0;
        DECLARE v_dept_cs48 INTEGER DEFAULT 0;
        DECLARE v_head_cs48 INTEGER DEFAULT 0;
        DECLARE v_done_cs48 INTEGER DEFAULT 0;
        DECLARE c_cs48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs48 = 1;
        OPEN c_cs48;
        loop_cs48: LOOP
            FETCH c_cs48 INTO v_dept_cs48, v_lvl_cs48, v_head_cs48;
            IF v_done_cs48 = 1 THEN LEAVE loop_cs48; END IF;
        END LOOP;
        CLOSE c_cs48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_cs48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_cs48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [cs49]
    BEGIN
        DECLARE v_sh_cs49 INTEGER DEFAULT 0;
        DECLARE v_car_cs49 INTEGER DEFAULT 0;
        DECLARE v_qty_cs49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_cs49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cs49 INTEGER DEFAULT 0;
        DECLARE c_cs49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs49 = 1;
        OPEN c_cs49;
        loop_cs49: LOOP
            FETCH c_cs49 INTO v_sh_cs49, v_car_cs49, v_qty_cs49;
            IF v_done_cs49 = 1 THEN LEAVE loop_cs49; END IF;
            SET v_tot_cs49 = v_tot_cs49 + v_qty_cs49;
        END LOOP;
        CLOSE c_cs49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_cs49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cs50]
    BEGIN
        DECLARE v_sql_cs50 VARCHAR(1000);
        DECLARE v_n_cs50 INTEGER DEFAULT 0;
        SET v_sql_cs50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_cs50 FROM v_sql_cs50;
        EXECUTE st_cs50;
        SELECT COUNT(*) INTO v_n_cs50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cs50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cs51]
    BEGIN
        DECLARE v_key_cs51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cs51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cs51' AS VARCHAR(40)), v_key_cs51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [cs52]
    BEGIN
        DECLARE v_so_cs52 INTEGER DEFAULT 0;
        DECLARE v_cust_cs52 INTEGER DEFAULT 0;
        DECLARE v_rk_cs52 INTEGER DEFAULT 0;
        DECLARE v_run_cs52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cs52 INTEGER DEFAULT 0;
        DECLARE c_cs52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cs52 = 1;
        OPEN c_cs52;
        loop_cs52: LOOP
            FETCH c_cs52 INTO v_so_cs52, v_cust_cs52, v_rk_cs52, v_run_cs52;
            IF v_done_cs52 = 1 THEN LEAVE loop_cs52; END IF;
        END LOOP;
        CLOSE c_cs52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_cs52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_cs52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [cs53]
    BEGIN
        DECLARE v_hi_cs53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_cs53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_cs53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [cs54]
    BEGIN
        DECLARE v_pairs_cs54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_cs54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_cs54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [cs55]
    BEGIN
        DECLARE v_rows_cs55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_cs55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_cs55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_cs55 FROM SESSION.TMP_cs55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_cs55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [cs56]
    BEGIN
        DECLARE v_rc_cs56 INTEGER DEFAULT 0;
        DECLARE v_band_cs56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_cs56 = ROW_COUNT;
        SET v_band_cs56 = CASE
                            WHEN v_rc_cs56 = 0 THEN 'NONE'
                            WHEN v_rc_cs56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_cs56, 'COUNT', 'band=' || v_band_cs56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [cs57]
    BEGIN
        DECLARE v_i_cs57 INTEGER DEFAULT 0;
        SAVEPOINT sp_cs57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_cs57 < 4 DO
            SET v_i_cs57 = v_i_cs57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_cs57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_cs57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_cs57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_SCHEDULE_OPS(IN p_wo_id INTEGER, IN p_so_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_i INTEGER DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('SCHED', p_wo_id, 'ERROR', 'schedule ops failed');
    END;
    WHILE v_i < 3 DO
        SET v_i = v_i + 1;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SCHED', p_wo_id, 'OP', 'op step ' || RTRIM(CHAR(v_i)), CURRENT TIMESTAMP);
    END WHILE;
    CALL ERP_USP_CREATE_SHIPMENT(p_so_id);
    CALL ERP_USP_AUDIT('SCHED', p_wo_id, 'DONE', 'ops scheduled');
    -- order/customer/country/currency revenue scan [so00]
    BEGIN
        DECLARE v_so_so00 INTEGER DEFAULT 0;
        DECLARE v_cust_so00 INTEGER DEFAULT 0;
        DECLARE v_ctry_so00 INTEGER DEFAULT 0;
        DECLARE v_ccy_so00 INTEGER DEFAULT 0;
        DECLARE v_sub_so00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_so00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_so00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_so00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_so00 INTEGER DEFAULT 0;
        DECLARE v_done_so00 INTEGER DEFAULT 0;
        DECLARE c_so00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so00 = 1;
        OPEN c_so00;
        loop_so00: LOOP
            FETCH c_so00 INTO v_so_so00, v_cust_so00, v_ctry_so00, v_ccy_so00, v_sub_so00;
            IF v_done_so00 = 1 THEN LEAVE loop_so00; END IF;
            SET v_tax_so00 = ERP_FN_TAX(v_ctry_so00, v_sub_so00);
            SET v_fx_so00 = ERP_FN_FX_CONVERT(v_ccy_so00, 1, v_sub_so00 + v_tax_so00);
            SET v_acc_so00 = v_acc_so00 + v_fx_so00;
            SET v_cnt_so00 = v_cnt_so00 + 1;
        END LOOP;
        CLOSE c_so00;
        IF v_cnt_so00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_so00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_so00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [so01]
    BEGIN
        DECLARE v_pid_so01 INTEGER DEFAULT 0;
        DECLARE v_oh_so01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_so01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_so01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_so01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_so01 INTEGER DEFAULT 0;
        DECLARE c_so01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so01 = 1;
        OPEN c_so01;
        loop_so01: LOOP
            FETCH c_so01 INTO v_pid_so01, v_oh_so01, v_cost_so01;
            IF v_done_so01 = 1 THEN LEAVE loop_so01; END IF;
            SET v_avail_so01 = ERP_FN_INVENTORY_ONHAND(v_pid_so01);
            SET v_val_so01 = v_val_so01 + CAST(COALESCE(v_oh_so01,0) * COALESCE(v_cost_so01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_so01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_so01;
        END LOOP;
        CLOSE c_so01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_so01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [so02]
    BEGIN
        DECLARE v_prod_so02 INTEGER DEFAULT 0;
        DECLARE v_rm_so02 INTEGER DEFAULT 0;
        DECLARE v_supp_so02 INTEGER DEFAULT 0;
        DECLARE v_qper_so02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_so02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_so02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_so02 INTEGER DEFAULT 0;
        DECLARE c_so02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so02 = 1;
        OPEN c_so02;
        loop_so02: LOOP
            FETCH c_so02 INTO v_prod_so02, v_rm_so02, v_supp_so02, v_qper_so02, v_uc_so02;
            IF v_done_so02 = 1 THEN LEAVE loop_so02; END IF;
            SET v_roll_so02 = v_roll_so02 + COALESCE(v_qper_so02,0) * COALESCE(v_uc_so02,0);
        END LOOP;
        CLOSE c_so02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_so02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [so03]
    BEGIN
        DECLARE v_acct_so03 INTEGER DEFAULT 0;
        DECLARE v_deb_so03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_so03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_so03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so03 INTEGER DEFAULT 0;
        DECLARE c_so03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so03 = 1;
        OPEN c_so03;
        loop_so03: LOOP
            FETCH c_so03 INTO v_acct_so03, v_deb_so03, v_cred_so03;
            IF v_done_so03 = 1 THEN LEAVE loop_so03; END IF;
            SET v_net_so03 = v_net_so03 + (v_deb_so03 - v_cred_so03);
        END LOOP;
        CLOSE c_so03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_so03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [so04]
    BEGIN
        DECLARE v_pid_so04 INTEGER DEFAULT 0;
        DECLARE v_lp_so04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_so04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_so04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_so04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_so04 INTEGER DEFAULT 0;
        DECLARE c_so04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so04 = 1;
        OPEN c_so04;
        loop_so04: LOOP
            FETCH c_so04 INTO v_pid_so04, v_lp_so04, v_pp_so04;
            IF v_done_so04 = 1 THEN LEAVE loop_so04; END IF;
            SET v_var_so04 = v_var_so04 + (COALESCE(v_lp_so04,0) - COALESCE(v_pp_so04,0));
            SET v_marg_so04 = ERP_FN_MARGIN(v_pid_so04);
        END LOOP;
        CLOSE c_so04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_so04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [so05]
    BEGIN
        DECLARE v_inv_so05 INTEGER DEFAULT 0;
        DECLARE v_amt_so05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_so05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_so05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so05 INTEGER DEFAULT 0;
        DECLARE c_so05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so05 = 1;
        OPEN c_so05;
        loop_so05: LOOP
            FETCH c_so05 INTO v_inv_so05, v_amt_so05, v_alloc_so05;
            IF v_done_so05 = 1 THEN LEAVE loop_so05; END IF;
            SET v_open_so05 = v_open_so05 + (v_amt_so05 - v_alloc_so05);
        END LOOP;
        CLOSE c_so05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_so05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [so06]
    BEGIN
        DECLARE v_lvl_so06 INTEGER DEFAULT 0;
        DECLARE v_dept_so06 INTEGER DEFAULT 0;
        DECLARE v_head_so06 INTEGER DEFAULT 0;
        DECLARE v_done_so06 INTEGER DEFAULT 0;
        DECLARE c_so06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so06 = 1;
        OPEN c_so06;
        loop_so06: LOOP
            FETCH c_so06 INTO v_dept_so06, v_lvl_so06, v_head_so06;
            IF v_done_so06 = 1 THEN LEAVE loop_so06; END IF;
        END LOOP;
        CLOSE c_so06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_so06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_so06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [so07]
    BEGIN
        DECLARE v_sh_so07 INTEGER DEFAULT 0;
        DECLARE v_car_so07 INTEGER DEFAULT 0;
        DECLARE v_qty_so07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_so07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_so07 INTEGER DEFAULT 0;
        DECLARE c_so07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so07 = 1;
        OPEN c_so07;
        loop_so07: LOOP
            FETCH c_so07 INTO v_sh_so07, v_car_so07, v_qty_so07;
            IF v_done_so07 = 1 THEN LEAVE loop_so07; END IF;
            SET v_tot_so07 = v_tot_so07 + v_qty_so07;
        END LOOP;
        CLOSE c_so07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_so07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [so08]
    BEGIN
        DECLARE v_sql_so08 VARCHAR(1000);
        DECLARE v_n_so08 INTEGER DEFAULT 0;
        SET v_sql_so08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_so08 FROM v_sql_so08;
        EXECUTE st_so08;
        SELECT COUNT(*) INTO v_n_so08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_so08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [so09]
    BEGIN
        DECLARE v_key_so09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_so09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_so09' AS VARCHAR(40)), v_key_so09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [so10]
    BEGIN
        DECLARE v_so_so10 INTEGER DEFAULT 0;
        DECLARE v_cust_so10 INTEGER DEFAULT 0;
        DECLARE v_rk_so10 INTEGER DEFAULT 0;
        DECLARE v_run_so10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so10 INTEGER DEFAULT 0;
        DECLARE c_so10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so10 = 1;
        OPEN c_so10;
        loop_so10: LOOP
            FETCH c_so10 INTO v_so_so10, v_cust_so10, v_rk_so10, v_run_so10;
            IF v_done_so10 = 1 THEN LEAVE loop_so10; END IF;
        END LOOP;
        CLOSE c_so10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_so10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_so10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [so11]
    BEGIN
        DECLARE v_hi_so11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_so11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_so11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [so12]
    BEGIN
        DECLARE v_pairs_so12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_so12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_so12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [so13]
    BEGIN
        DECLARE v_rows_so13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_so13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_so13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_so13 FROM SESSION.TMP_so13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_so13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [so14]
    BEGIN
        DECLARE v_rc_so14 INTEGER DEFAULT 0;
        DECLARE v_band_so14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_so14 = ROW_COUNT;
        SET v_band_so14 = CASE
                            WHEN v_rc_so14 = 0 THEN 'NONE'
                            WHEN v_rc_so14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_so14, 'COUNT', 'band=' || v_band_so14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [so15]
    BEGIN
        DECLARE v_i_so15 INTEGER DEFAULT 0;
        SAVEPOINT sp_so15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_so15 < 4 DO
            SET v_i_so15 = v_i_so15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_so15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_so15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_so15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [so16]
    BEGIN
        DECLARE v_j_so16 INTEGER DEFAULT 0;
        DECLARE v_sum_so16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_so16 = v_j_so16 + 1;
        UNTIL v_j_so16 >= 3 END REPEAT;
        FOR row_so16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_so16 = v_sum_so16 + COALESCE(row_so16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_so16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_so16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [so17]
    BEGIN
        DECLARE v_n_so17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_so17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_so17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [so18]
    BEGIN
        DECLARE v_levels_so18 INTEGER DEFAULT 0;
        DECLARE c_so18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_so18 = 0;
        OPEN c_so18;
        FETCH c_so18 INTO v_levels_so18;
        CLOSE c_so18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_so18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [so19]
    BEGIN
        DECLARE v_sql_so19 VARCHAR(1000);
        DECLARE v_n_so19 INTEGER DEFAULT 0;
        SET v_sql_so19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_so19 FROM v_sql_so19;
        EXECUTE st_so19;
        SELECT COUNT(*) INTO v_n_so19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_so19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [so20]
    BEGIN
        DECLARE v_key_so20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_so20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_so20' AS VARCHAR(40)), v_key_so20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [so21]
    BEGIN
        DECLARE v_so_so21 INTEGER DEFAULT 0;
        DECLARE v_cust_so21 INTEGER DEFAULT 0;
        DECLARE v_ctry_so21 INTEGER DEFAULT 0;
        DECLARE v_ccy_so21 INTEGER DEFAULT 0;
        DECLARE v_sub_so21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_so21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_so21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_so21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_so21 INTEGER DEFAULT 0;
        DECLARE v_done_so21 INTEGER DEFAULT 0;
        DECLARE c_so21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so21 = 1;
        OPEN c_so21;
        loop_so21: LOOP
            FETCH c_so21 INTO v_so_so21, v_cust_so21, v_ctry_so21, v_ccy_so21, v_sub_so21;
            IF v_done_so21 = 1 THEN LEAVE loop_so21; END IF;
            SET v_tax_so21 = ERP_FN_TAX(v_ctry_so21, v_sub_so21);
            SET v_fx_so21 = ERP_FN_FX_CONVERT(v_ccy_so21, 1, v_sub_so21 + v_tax_so21);
            SET v_acc_so21 = v_acc_so21 + v_fx_so21;
            SET v_cnt_so21 = v_cnt_so21 + 1;
        END LOOP;
        CLOSE c_so21;
        IF v_cnt_so21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_so21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_so21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [so22]
    BEGIN
        DECLARE v_pid_so22 INTEGER DEFAULT 0;
        DECLARE v_oh_so22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_so22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_so22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_so22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_so22 INTEGER DEFAULT 0;
        DECLARE c_so22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so22 = 1;
        OPEN c_so22;
        loop_so22: LOOP
            FETCH c_so22 INTO v_pid_so22, v_oh_so22, v_cost_so22;
            IF v_done_so22 = 1 THEN LEAVE loop_so22; END IF;
            SET v_avail_so22 = ERP_FN_INVENTORY_ONHAND(v_pid_so22);
            SET v_val_so22 = v_val_so22 + CAST(COALESCE(v_oh_so22,0) * COALESCE(v_cost_so22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_so22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_so22;
        END LOOP;
        CLOSE c_so22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_so22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [so23]
    BEGIN
        DECLARE v_prod_so23 INTEGER DEFAULT 0;
        DECLARE v_rm_so23 INTEGER DEFAULT 0;
        DECLARE v_supp_so23 INTEGER DEFAULT 0;
        DECLARE v_qper_so23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_so23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_so23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_so23 INTEGER DEFAULT 0;
        DECLARE c_so23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so23 = 1;
        OPEN c_so23;
        loop_so23: LOOP
            FETCH c_so23 INTO v_prod_so23, v_rm_so23, v_supp_so23, v_qper_so23, v_uc_so23;
            IF v_done_so23 = 1 THEN LEAVE loop_so23; END IF;
            SET v_roll_so23 = v_roll_so23 + COALESCE(v_qper_so23,0) * COALESCE(v_uc_so23,0);
        END LOOP;
        CLOSE c_so23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_so23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [so24]
    BEGIN
        DECLARE v_acct_so24 INTEGER DEFAULT 0;
        DECLARE v_deb_so24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_so24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_so24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so24 INTEGER DEFAULT 0;
        DECLARE c_so24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so24 = 1;
        OPEN c_so24;
        loop_so24: LOOP
            FETCH c_so24 INTO v_acct_so24, v_deb_so24, v_cred_so24;
            IF v_done_so24 = 1 THEN LEAVE loop_so24; END IF;
            SET v_net_so24 = v_net_so24 + (v_deb_so24 - v_cred_so24);
        END LOOP;
        CLOSE c_so24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_so24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [so25]
    BEGIN
        DECLARE v_pid_so25 INTEGER DEFAULT 0;
        DECLARE v_lp_so25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_so25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_so25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_so25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_so25 INTEGER DEFAULT 0;
        DECLARE c_so25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so25 = 1;
        OPEN c_so25;
        loop_so25: LOOP
            FETCH c_so25 INTO v_pid_so25, v_lp_so25, v_pp_so25;
            IF v_done_so25 = 1 THEN LEAVE loop_so25; END IF;
            SET v_var_so25 = v_var_so25 + (COALESCE(v_lp_so25,0) - COALESCE(v_pp_so25,0));
            SET v_marg_so25 = ERP_FN_MARGIN(v_pid_so25);
        END LOOP;
        CLOSE c_so25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_so25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [so26]
    BEGIN
        DECLARE v_inv_so26 INTEGER DEFAULT 0;
        DECLARE v_amt_so26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_so26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_so26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so26 INTEGER DEFAULT 0;
        DECLARE c_so26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so26 = 1;
        OPEN c_so26;
        loop_so26: LOOP
            FETCH c_so26 INTO v_inv_so26, v_amt_so26, v_alloc_so26;
            IF v_done_so26 = 1 THEN LEAVE loop_so26; END IF;
            SET v_open_so26 = v_open_so26 + (v_amt_so26 - v_alloc_so26);
        END LOOP;
        CLOSE c_so26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_so26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [so27]
    BEGIN
        DECLARE v_lvl_so27 INTEGER DEFAULT 0;
        DECLARE v_dept_so27 INTEGER DEFAULT 0;
        DECLARE v_head_so27 INTEGER DEFAULT 0;
        DECLARE v_done_so27 INTEGER DEFAULT 0;
        DECLARE c_so27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so27 = 1;
        OPEN c_so27;
        loop_so27: LOOP
            FETCH c_so27 INTO v_dept_so27, v_lvl_so27, v_head_so27;
            IF v_done_so27 = 1 THEN LEAVE loop_so27; END IF;
        END LOOP;
        CLOSE c_so27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_so27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_so27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [so28]
    BEGIN
        DECLARE v_sh_so28 INTEGER DEFAULT 0;
        DECLARE v_car_so28 INTEGER DEFAULT 0;
        DECLARE v_qty_so28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_so28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_so28 INTEGER DEFAULT 0;
        DECLARE c_so28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so28 = 1;
        OPEN c_so28;
        loop_so28: LOOP
            FETCH c_so28 INTO v_sh_so28, v_car_so28, v_qty_so28;
            IF v_done_so28 = 1 THEN LEAVE loop_so28; END IF;
            SET v_tot_so28 = v_tot_so28 + v_qty_so28;
        END LOOP;
        CLOSE c_so28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_so28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [so29]
    BEGIN
        DECLARE v_sql_so29 VARCHAR(1000);
        DECLARE v_n_so29 INTEGER DEFAULT 0;
        SET v_sql_so29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_so29 FROM v_sql_so29;
        EXECUTE st_so29;
        SELECT COUNT(*) INTO v_n_so29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_so29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [so30]
    BEGIN
        DECLARE v_key_so30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_so30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_so30' AS VARCHAR(40)), v_key_so30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [so31]
    BEGIN
        DECLARE v_so_so31 INTEGER DEFAULT 0;
        DECLARE v_cust_so31 INTEGER DEFAULT 0;
        DECLARE v_rk_so31 INTEGER DEFAULT 0;
        DECLARE v_run_so31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so31 INTEGER DEFAULT 0;
        DECLARE c_so31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so31 = 1;
        OPEN c_so31;
        loop_so31: LOOP
            FETCH c_so31 INTO v_so_so31, v_cust_so31, v_rk_so31, v_run_so31;
            IF v_done_so31 = 1 THEN LEAVE loop_so31; END IF;
        END LOOP;
        CLOSE c_so31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_so31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_so31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [so32]
    BEGIN
        DECLARE v_hi_so32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_so32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_so32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [so33]
    BEGIN
        DECLARE v_pairs_so33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_so33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_so33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [so34]
    BEGIN
        DECLARE v_rows_so34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_so34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_so34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_so34 FROM SESSION.TMP_so34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_so34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [so35]
    BEGIN
        DECLARE v_rc_so35 INTEGER DEFAULT 0;
        DECLARE v_band_so35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_so35 = ROW_COUNT;
        SET v_band_so35 = CASE
                            WHEN v_rc_so35 = 0 THEN 'NONE'
                            WHEN v_rc_so35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_so35, 'COUNT', 'band=' || v_band_so35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [so36]
    BEGIN
        DECLARE v_i_so36 INTEGER DEFAULT 0;
        SAVEPOINT sp_so36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_so36 < 4 DO
            SET v_i_so36 = v_i_so36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_so36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_so36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_so36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [so37]
    BEGIN
        DECLARE v_j_so37 INTEGER DEFAULT 0;
        DECLARE v_sum_so37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_so37 = v_j_so37 + 1;
        UNTIL v_j_so37 >= 3 END REPEAT;
        FOR row_so37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_so37 = v_sum_so37 + COALESCE(row_so37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_so37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_so37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [so38]
    BEGIN
        DECLARE v_n_so38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_so38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_so38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [so39]
    BEGIN
        DECLARE v_levels_so39 INTEGER DEFAULT 0;
        DECLARE c_so39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_so39 = 0;
        OPEN c_so39;
        FETCH c_so39 INTO v_levels_so39;
        CLOSE c_so39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_so39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [so40]
    BEGIN
        DECLARE v_sql_so40 VARCHAR(1000);
        DECLARE v_n_so40 INTEGER DEFAULT 0;
        SET v_sql_so40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_so40 FROM v_sql_so40;
        EXECUTE st_so40;
        SELECT COUNT(*) INTO v_n_so40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_so40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [so41]
    BEGIN
        DECLARE v_key_so41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_so41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_so41' AS VARCHAR(40)), v_key_so41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [so42]
    BEGIN
        DECLARE v_so_so42 INTEGER DEFAULT 0;
        DECLARE v_cust_so42 INTEGER DEFAULT 0;
        DECLARE v_ctry_so42 INTEGER DEFAULT 0;
        DECLARE v_ccy_so42 INTEGER DEFAULT 0;
        DECLARE v_sub_so42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_so42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_so42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_so42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_so42 INTEGER DEFAULT 0;
        DECLARE v_done_so42 INTEGER DEFAULT 0;
        DECLARE c_so42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so42 = 1;
        OPEN c_so42;
        loop_so42: LOOP
            FETCH c_so42 INTO v_so_so42, v_cust_so42, v_ctry_so42, v_ccy_so42, v_sub_so42;
            IF v_done_so42 = 1 THEN LEAVE loop_so42; END IF;
            SET v_tax_so42 = ERP_FN_TAX(v_ctry_so42, v_sub_so42);
            SET v_fx_so42 = ERP_FN_FX_CONVERT(v_ccy_so42, 1, v_sub_so42 + v_tax_so42);
            SET v_acc_so42 = v_acc_so42 + v_fx_so42;
            SET v_cnt_so42 = v_cnt_so42 + 1;
        END LOOP;
        CLOSE c_so42;
        IF v_cnt_so42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_so42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_so42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [so43]
    BEGIN
        DECLARE v_pid_so43 INTEGER DEFAULT 0;
        DECLARE v_oh_so43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_so43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_so43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_so43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_so43 INTEGER DEFAULT 0;
        DECLARE c_so43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so43 = 1;
        OPEN c_so43;
        loop_so43: LOOP
            FETCH c_so43 INTO v_pid_so43, v_oh_so43, v_cost_so43;
            IF v_done_so43 = 1 THEN LEAVE loop_so43; END IF;
            SET v_avail_so43 = ERP_FN_INVENTORY_ONHAND(v_pid_so43);
            SET v_val_so43 = v_val_so43 + CAST(COALESCE(v_oh_so43,0) * COALESCE(v_cost_so43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_so43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_so43;
        END LOOP;
        CLOSE c_so43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_so43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [so44]
    BEGIN
        DECLARE v_prod_so44 INTEGER DEFAULT 0;
        DECLARE v_rm_so44 INTEGER DEFAULT 0;
        DECLARE v_supp_so44 INTEGER DEFAULT 0;
        DECLARE v_qper_so44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_so44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_so44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_so44 INTEGER DEFAULT 0;
        DECLARE c_so44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so44 = 1;
        OPEN c_so44;
        loop_so44: LOOP
            FETCH c_so44 INTO v_prod_so44, v_rm_so44, v_supp_so44, v_qper_so44, v_uc_so44;
            IF v_done_so44 = 1 THEN LEAVE loop_so44; END IF;
            SET v_roll_so44 = v_roll_so44 + COALESCE(v_qper_so44,0) * COALESCE(v_uc_so44,0);
        END LOOP;
        CLOSE c_so44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_so44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [so45]
    BEGIN
        DECLARE v_acct_so45 INTEGER DEFAULT 0;
        DECLARE v_deb_so45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_so45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_so45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so45 INTEGER DEFAULT 0;
        DECLARE c_so45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so45 = 1;
        OPEN c_so45;
        loop_so45: LOOP
            FETCH c_so45 INTO v_acct_so45, v_deb_so45, v_cred_so45;
            IF v_done_so45 = 1 THEN LEAVE loop_so45; END IF;
            SET v_net_so45 = v_net_so45 + (v_deb_so45 - v_cred_so45);
        END LOOP;
        CLOSE c_so45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_so45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [so46]
    BEGIN
        DECLARE v_pid_so46 INTEGER DEFAULT 0;
        DECLARE v_lp_so46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_so46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_so46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_so46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_so46 INTEGER DEFAULT 0;
        DECLARE c_so46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so46 = 1;
        OPEN c_so46;
        loop_so46: LOOP
            FETCH c_so46 INTO v_pid_so46, v_lp_so46, v_pp_so46;
            IF v_done_so46 = 1 THEN LEAVE loop_so46; END IF;
            SET v_var_so46 = v_var_so46 + (COALESCE(v_lp_so46,0) - COALESCE(v_pp_so46,0));
            SET v_marg_so46 = ERP_FN_MARGIN(v_pid_so46);
        END LOOP;
        CLOSE c_so46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_so46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [so47]
    BEGIN
        DECLARE v_inv_so47 INTEGER DEFAULT 0;
        DECLARE v_amt_so47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_so47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_so47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so47 INTEGER DEFAULT 0;
        DECLARE c_so47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so47 = 1;
        OPEN c_so47;
        loop_so47: LOOP
            FETCH c_so47 INTO v_inv_so47, v_amt_so47, v_alloc_so47;
            IF v_done_so47 = 1 THEN LEAVE loop_so47; END IF;
            SET v_open_so47 = v_open_so47 + (v_amt_so47 - v_alloc_so47);
        END LOOP;
        CLOSE c_so47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_so47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [so48]
    BEGIN
        DECLARE v_lvl_so48 INTEGER DEFAULT 0;
        DECLARE v_dept_so48 INTEGER DEFAULT 0;
        DECLARE v_head_so48 INTEGER DEFAULT 0;
        DECLARE v_done_so48 INTEGER DEFAULT 0;
        DECLARE c_so48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so48 = 1;
        OPEN c_so48;
        loop_so48: LOOP
            FETCH c_so48 INTO v_dept_so48, v_lvl_so48, v_head_so48;
            IF v_done_so48 = 1 THEN LEAVE loop_so48; END IF;
        END LOOP;
        CLOSE c_so48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_so48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_so48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [so49]
    BEGIN
        DECLARE v_sh_so49 INTEGER DEFAULT 0;
        DECLARE v_car_so49 INTEGER DEFAULT 0;
        DECLARE v_qty_so49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_so49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_so49 INTEGER DEFAULT 0;
        DECLARE c_so49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so49 = 1;
        OPEN c_so49;
        loop_so49: LOOP
            FETCH c_so49 INTO v_sh_so49, v_car_so49, v_qty_so49;
            IF v_done_so49 = 1 THEN LEAVE loop_so49; END IF;
            SET v_tot_so49 = v_tot_so49 + v_qty_so49;
        END LOOP;
        CLOSE c_so49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_so49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [so50]
    BEGIN
        DECLARE v_sql_so50 VARCHAR(1000);
        DECLARE v_n_so50 INTEGER DEFAULT 0;
        SET v_sql_so50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_so50 FROM v_sql_so50;
        EXECUTE st_so50;
        SELECT COUNT(*) INTO v_n_so50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_so50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [so51]
    BEGIN
        DECLARE v_key_so51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_so51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_so51' AS VARCHAR(40)), v_key_so51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [so52]
    BEGIN
        DECLARE v_so_so52 INTEGER DEFAULT 0;
        DECLARE v_cust_so52 INTEGER DEFAULT 0;
        DECLARE v_rk_so52 INTEGER DEFAULT 0;
        DECLARE v_run_so52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_so52 INTEGER DEFAULT 0;
        DECLARE c_so52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_so52 = 1;
        OPEN c_so52;
        loop_so52: LOOP
            FETCH c_so52 INTO v_so_so52, v_cust_so52, v_rk_so52, v_run_so52;
            IF v_done_so52 = 1 THEN LEAVE loop_so52; END IF;
        END LOOP;
        CLOSE c_so52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_so52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_so52)), CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_PROCURE_MATERIAL(IN p_product_id INTEGER, IN p_qty DECIMAL(16,4))
LANGUAGE SQL
BEGIN
    DECLARE v_po_id INTEGER DEFAULT 0;
    DECLARE v_supp INTEGER DEFAULT 0;
    DECLARE v_rm INTEGER DEFAULT 0;
    DECLARE v_done INTEGER DEFAULT 0;
    DECLARE c_rm CURSOR FOR
        SELECT rm.id, rm.supplier_id FROM ERP_BOM b
        JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
        WHERE b.product_id = p_product_id ORDER BY rm.id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('PROCURE', p_product_id, 'ERROR', 'procure failed');
    END;
    OPEN c_rm;
    rm_loop: LOOP
        FETCH c_rm INTO v_rm, v_supp;
        IF v_done = 1 THEN LEAVE rm_loop; END IF;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PROCURE', v_rm, 'RM', 'material needed', CURRENT TIMESTAMP);
    END LOOP;
    CLOSE c_rm;
    CALL ERP_USP_AUDIT('PROCURE', p_product_id, 'DONE', 'materials procured');
    -- order/customer/country/currency revenue scan [pm00]
    BEGIN
        DECLARE v_so_pm00 INTEGER DEFAULT 0;
        DECLARE v_cust_pm00 INTEGER DEFAULT 0;
        DECLARE v_ctry_pm00 INTEGER DEFAULT 0;
        DECLARE v_ccy_pm00 INTEGER DEFAULT 0;
        DECLARE v_sub_pm00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pm00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pm00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pm00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pm00 INTEGER DEFAULT 0;
        DECLARE v_done_pm00 INTEGER DEFAULT 0;
        DECLARE c_pm00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm00 = 1;
        OPEN c_pm00;
        loop_pm00: LOOP
            FETCH c_pm00 INTO v_so_pm00, v_cust_pm00, v_ctry_pm00, v_ccy_pm00, v_sub_pm00;
            IF v_done_pm00 = 1 THEN LEAVE loop_pm00; END IF;
            SET v_tax_pm00 = ERP_FN_TAX(v_ctry_pm00, v_sub_pm00);
            SET v_fx_pm00 = ERP_FN_FX_CONVERT(v_ccy_pm00, 1, v_sub_pm00 + v_tax_pm00);
            SET v_acc_pm00 = v_acc_pm00 + v_fx_pm00;
            SET v_cnt_pm00 = v_cnt_pm00 + 1;
        END LOOP;
        CLOSE c_pm00;
        IF v_cnt_pm00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pm00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pm00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pm01]
    BEGIN
        DECLARE v_pid_pm01 INTEGER DEFAULT 0;
        DECLARE v_oh_pm01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pm01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pm01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pm01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pm01 INTEGER DEFAULT 0;
        DECLARE c_pm01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm01 = 1;
        OPEN c_pm01;
        loop_pm01: LOOP
            FETCH c_pm01 INTO v_pid_pm01, v_oh_pm01, v_cost_pm01;
            IF v_done_pm01 = 1 THEN LEAVE loop_pm01; END IF;
            SET v_avail_pm01 = ERP_FN_INVENTORY_ONHAND(v_pid_pm01);
            SET v_val_pm01 = v_val_pm01 + CAST(COALESCE(v_oh_pm01,0) * COALESCE(v_cost_pm01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pm01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pm01;
        END LOOP;
        CLOSE c_pm01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pm01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pm02]
    BEGIN
        DECLARE v_prod_pm02 INTEGER DEFAULT 0;
        DECLARE v_rm_pm02 INTEGER DEFAULT 0;
        DECLARE v_supp_pm02 INTEGER DEFAULT 0;
        DECLARE v_qper_pm02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pm02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pm02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pm02 INTEGER DEFAULT 0;
        DECLARE c_pm02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm02 = 1;
        OPEN c_pm02;
        loop_pm02: LOOP
            FETCH c_pm02 INTO v_prod_pm02, v_rm_pm02, v_supp_pm02, v_qper_pm02, v_uc_pm02;
            IF v_done_pm02 = 1 THEN LEAVE loop_pm02; END IF;
            SET v_roll_pm02 = v_roll_pm02 + COALESCE(v_qper_pm02,0) * COALESCE(v_uc_pm02,0);
        END LOOP;
        CLOSE c_pm02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pm02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pm03]
    BEGIN
        DECLARE v_acct_pm03 INTEGER DEFAULT 0;
        DECLARE v_deb_pm03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pm03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pm03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm03 INTEGER DEFAULT 0;
        DECLARE c_pm03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm03 = 1;
        OPEN c_pm03;
        loop_pm03: LOOP
            FETCH c_pm03 INTO v_acct_pm03, v_deb_pm03, v_cred_pm03;
            IF v_done_pm03 = 1 THEN LEAVE loop_pm03; END IF;
            SET v_net_pm03 = v_net_pm03 + (v_deb_pm03 - v_cred_pm03);
        END LOOP;
        CLOSE c_pm03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pm03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pm04]
    BEGIN
        DECLARE v_pid_pm04 INTEGER DEFAULT 0;
        DECLARE v_lp_pm04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pm04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pm04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pm04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pm04 INTEGER DEFAULT 0;
        DECLARE c_pm04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm04 = 1;
        OPEN c_pm04;
        loop_pm04: LOOP
            FETCH c_pm04 INTO v_pid_pm04, v_lp_pm04, v_pp_pm04;
            IF v_done_pm04 = 1 THEN LEAVE loop_pm04; END IF;
            SET v_var_pm04 = v_var_pm04 + (COALESCE(v_lp_pm04,0) - COALESCE(v_pp_pm04,0));
            SET v_marg_pm04 = ERP_FN_MARGIN(v_pid_pm04);
        END LOOP;
        CLOSE c_pm04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pm04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pm05]
    BEGIN
        DECLARE v_inv_pm05 INTEGER DEFAULT 0;
        DECLARE v_amt_pm05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pm05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pm05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm05 INTEGER DEFAULT 0;
        DECLARE c_pm05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm05 = 1;
        OPEN c_pm05;
        loop_pm05: LOOP
            FETCH c_pm05 INTO v_inv_pm05, v_amt_pm05, v_alloc_pm05;
            IF v_done_pm05 = 1 THEN LEAVE loop_pm05; END IF;
            SET v_open_pm05 = v_open_pm05 + (v_amt_pm05 - v_alloc_pm05);
        END LOOP;
        CLOSE c_pm05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pm05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pm06]
    BEGIN
        DECLARE v_lvl_pm06 INTEGER DEFAULT 0;
        DECLARE v_dept_pm06 INTEGER DEFAULT 0;
        DECLARE v_head_pm06 INTEGER DEFAULT 0;
        DECLARE v_done_pm06 INTEGER DEFAULT 0;
        DECLARE c_pm06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm06 = 1;
        OPEN c_pm06;
        loop_pm06: LOOP
            FETCH c_pm06 INTO v_dept_pm06, v_lvl_pm06, v_head_pm06;
            IF v_done_pm06 = 1 THEN LEAVE loop_pm06; END IF;
        END LOOP;
        CLOSE c_pm06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pm06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pm06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pm07]
    BEGIN
        DECLARE v_sh_pm07 INTEGER DEFAULT 0;
        DECLARE v_car_pm07 INTEGER DEFAULT 0;
        DECLARE v_qty_pm07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pm07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pm07 INTEGER DEFAULT 0;
        DECLARE c_pm07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm07 = 1;
        OPEN c_pm07;
        loop_pm07: LOOP
            FETCH c_pm07 INTO v_sh_pm07, v_car_pm07, v_qty_pm07;
            IF v_done_pm07 = 1 THEN LEAVE loop_pm07; END IF;
            SET v_tot_pm07 = v_tot_pm07 + v_qty_pm07;
        END LOOP;
        CLOSE c_pm07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pm07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pm08]
    BEGIN
        DECLARE v_sql_pm08 VARCHAR(1000);
        DECLARE v_n_pm08 INTEGER DEFAULT 0;
        SET v_sql_pm08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pm08 FROM v_sql_pm08;
        EXECUTE st_pm08;
        SELECT COUNT(*) INTO v_n_pm08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pm08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pm09]
    BEGIN
        DECLARE v_key_pm09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pm09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pm09' AS VARCHAR(40)), v_key_pm09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pm10]
    BEGIN
        DECLARE v_so_pm10 INTEGER DEFAULT 0;
        DECLARE v_cust_pm10 INTEGER DEFAULT 0;
        DECLARE v_rk_pm10 INTEGER DEFAULT 0;
        DECLARE v_run_pm10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm10 INTEGER DEFAULT 0;
        DECLARE c_pm10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm10 = 1;
        OPEN c_pm10;
        loop_pm10: LOOP
            FETCH c_pm10 INTO v_so_pm10, v_cust_pm10, v_rk_pm10, v_run_pm10;
            IF v_done_pm10 = 1 THEN LEAVE loop_pm10; END IF;
        END LOOP;
        CLOSE c_pm10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pm10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pm10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [pm11]
    BEGIN
        DECLARE v_hi_pm11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_pm11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_pm11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [pm12]
    BEGIN
        DECLARE v_pairs_pm12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_pm12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_pm12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [pm13]
    BEGIN
        DECLARE v_rows_pm13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_pm13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_pm13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_pm13 FROM SESSION.TMP_pm13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_pm13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [pm14]
    BEGIN
        DECLARE v_rc_pm14 INTEGER DEFAULT 0;
        DECLARE v_band_pm14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_pm14 = ROW_COUNT;
        SET v_band_pm14 = CASE
                            WHEN v_rc_pm14 = 0 THEN 'NONE'
                            WHEN v_rc_pm14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_pm14, 'COUNT', 'band=' || v_band_pm14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [pm15]
    BEGIN
        DECLARE v_i_pm15 INTEGER DEFAULT 0;
        SAVEPOINT sp_pm15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_pm15 < 4 DO
            SET v_i_pm15 = v_i_pm15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_pm15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_pm15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_pm15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [pm16]
    BEGIN
        DECLARE v_j_pm16 INTEGER DEFAULT 0;
        DECLARE v_sum_pm16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_pm16 = v_j_pm16 + 1;
        UNTIL v_j_pm16 >= 3 END REPEAT;
        FOR row_pm16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_pm16 = v_sum_pm16 + COALESCE(row_pm16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_pm16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_pm16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [pm17]
    BEGIN
        DECLARE v_n_pm17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_pm17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_pm17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [pm18]
    BEGIN
        DECLARE v_levels_pm18 INTEGER DEFAULT 0;
        DECLARE c_pm18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_pm18 = 0;
        OPEN c_pm18;
        FETCH c_pm18 INTO v_levels_pm18;
        CLOSE c_pm18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_pm18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pm19]
    BEGIN
        DECLARE v_sql_pm19 VARCHAR(1000);
        DECLARE v_n_pm19 INTEGER DEFAULT 0;
        SET v_sql_pm19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_pm19 FROM v_sql_pm19;
        EXECUTE st_pm19;
        SELECT COUNT(*) INTO v_n_pm19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pm19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pm20]
    BEGIN
        DECLARE v_key_pm20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pm20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pm20' AS VARCHAR(40)), v_key_pm20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [pm21]
    BEGIN
        DECLARE v_so_pm21 INTEGER DEFAULT 0;
        DECLARE v_cust_pm21 INTEGER DEFAULT 0;
        DECLARE v_ctry_pm21 INTEGER DEFAULT 0;
        DECLARE v_ccy_pm21 INTEGER DEFAULT 0;
        DECLARE v_sub_pm21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pm21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pm21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pm21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pm21 INTEGER DEFAULT 0;
        DECLARE v_done_pm21 INTEGER DEFAULT 0;
        DECLARE c_pm21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm21 = 1;
        OPEN c_pm21;
        loop_pm21: LOOP
            FETCH c_pm21 INTO v_so_pm21, v_cust_pm21, v_ctry_pm21, v_ccy_pm21, v_sub_pm21;
            IF v_done_pm21 = 1 THEN LEAVE loop_pm21; END IF;
            SET v_tax_pm21 = ERP_FN_TAX(v_ctry_pm21, v_sub_pm21);
            SET v_fx_pm21 = ERP_FN_FX_CONVERT(v_ccy_pm21, 1, v_sub_pm21 + v_tax_pm21);
            SET v_acc_pm21 = v_acc_pm21 + v_fx_pm21;
            SET v_cnt_pm21 = v_cnt_pm21 + 1;
        END LOOP;
        CLOSE c_pm21;
        IF v_cnt_pm21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pm21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pm21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pm22]
    BEGIN
        DECLARE v_pid_pm22 INTEGER DEFAULT 0;
        DECLARE v_oh_pm22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pm22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pm22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pm22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pm22 INTEGER DEFAULT 0;
        DECLARE c_pm22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm22 = 1;
        OPEN c_pm22;
        loop_pm22: LOOP
            FETCH c_pm22 INTO v_pid_pm22, v_oh_pm22, v_cost_pm22;
            IF v_done_pm22 = 1 THEN LEAVE loop_pm22; END IF;
            SET v_avail_pm22 = ERP_FN_INVENTORY_ONHAND(v_pid_pm22);
            SET v_val_pm22 = v_val_pm22 + CAST(COALESCE(v_oh_pm22,0) * COALESCE(v_cost_pm22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pm22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pm22;
        END LOOP;
        CLOSE c_pm22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pm22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pm23]
    BEGIN
        DECLARE v_prod_pm23 INTEGER DEFAULT 0;
        DECLARE v_rm_pm23 INTEGER DEFAULT 0;
        DECLARE v_supp_pm23 INTEGER DEFAULT 0;
        DECLARE v_qper_pm23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pm23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pm23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pm23 INTEGER DEFAULT 0;
        DECLARE c_pm23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm23 = 1;
        OPEN c_pm23;
        loop_pm23: LOOP
            FETCH c_pm23 INTO v_prod_pm23, v_rm_pm23, v_supp_pm23, v_qper_pm23, v_uc_pm23;
            IF v_done_pm23 = 1 THEN LEAVE loop_pm23; END IF;
            SET v_roll_pm23 = v_roll_pm23 + COALESCE(v_qper_pm23,0) * COALESCE(v_uc_pm23,0);
        END LOOP;
        CLOSE c_pm23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pm23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pm24]
    BEGIN
        DECLARE v_acct_pm24 INTEGER DEFAULT 0;
        DECLARE v_deb_pm24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pm24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pm24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm24 INTEGER DEFAULT 0;
        DECLARE c_pm24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm24 = 1;
        OPEN c_pm24;
        loop_pm24: LOOP
            FETCH c_pm24 INTO v_acct_pm24, v_deb_pm24, v_cred_pm24;
            IF v_done_pm24 = 1 THEN LEAVE loop_pm24; END IF;
            SET v_net_pm24 = v_net_pm24 + (v_deb_pm24 - v_cred_pm24);
        END LOOP;
        CLOSE c_pm24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pm24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pm25]
    BEGIN
        DECLARE v_pid_pm25 INTEGER DEFAULT 0;
        DECLARE v_lp_pm25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pm25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pm25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pm25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pm25 INTEGER DEFAULT 0;
        DECLARE c_pm25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm25 = 1;
        OPEN c_pm25;
        loop_pm25: LOOP
            FETCH c_pm25 INTO v_pid_pm25, v_lp_pm25, v_pp_pm25;
            IF v_done_pm25 = 1 THEN LEAVE loop_pm25; END IF;
            SET v_var_pm25 = v_var_pm25 + (COALESCE(v_lp_pm25,0) - COALESCE(v_pp_pm25,0));
            SET v_marg_pm25 = ERP_FN_MARGIN(v_pid_pm25);
        END LOOP;
        CLOSE c_pm25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pm25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pm26]
    BEGIN
        DECLARE v_inv_pm26 INTEGER DEFAULT 0;
        DECLARE v_amt_pm26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pm26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pm26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm26 INTEGER DEFAULT 0;
        DECLARE c_pm26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm26 = 1;
        OPEN c_pm26;
        loop_pm26: LOOP
            FETCH c_pm26 INTO v_inv_pm26, v_amt_pm26, v_alloc_pm26;
            IF v_done_pm26 = 1 THEN LEAVE loop_pm26; END IF;
            SET v_open_pm26 = v_open_pm26 + (v_amt_pm26 - v_alloc_pm26);
        END LOOP;
        CLOSE c_pm26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pm26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pm27]
    BEGIN
        DECLARE v_lvl_pm27 INTEGER DEFAULT 0;
        DECLARE v_dept_pm27 INTEGER DEFAULT 0;
        DECLARE v_head_pm27 INTEGER DEFAULT 0;
        DECLARE v_done_pm27 INTEGER DEFAULT 0;
        DECLARE c_pm27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm27 = 1;
        OPEN c_pm27;
        loop_pm27: LOOP
            FETCH c_pm27 INTO v_dept_pm27, v_lvl_pm27, v_head_pm27;
            IF v_done_pm27 = 1 THEN LEAVE loop_pm27; END IF;
        END LOOP;
        CLOSE c_pm27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pm27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pm27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pm28]
    BEGIN
        DECLARE v_sh_pm28 INTEGER DEFAULT 0;
        DECLARE v_car_pm28 INTEGER DEFAULT 0;
        DECLARE v_qty_pm28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pm28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pm28 INTEGER DEFAULT 0;
        DECLARE c_pm28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm28 = 1;
        OPEN c_pm28;
        loop_pm28: LOOP
            FETCH c_pm28 INTO v_sh_pm28, v_car_pm28, v_qty_pm28;
            IF v_done_pm28 = 1 THEN LEAVE loop_pm28; END IF;
            SET v_tot_pm28 = v_tot_pm28 + v_qty_pm28;
        END LOOP;
        CLOSE c_pm28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pm28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pm29]
    BEGIN
        DECLARE v_sql_pm29 VARCHAR(1000);
        DECLARE v_n_pm29 INTEGER DEFAULT 0;
        SET v_sql_pm29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pm29 FROM v_sql_pm29;
        EXECUTE st_pm29;
        SELECT COUNT(*) INTO v_n_pm29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pm29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pm30]
    BEGIN
        DECLARE v_key_pm30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pm30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pm30' AS VARCHAR(40)), v_key_pm30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pm31]
    BEGIN
        DECLARE v_so_pm31 INTEGER DEFAULT 0;
        DECLARE v_cust_pm31 INTEGER DEFAULT 0;
        DECLARE v_rk_pm31 INTEGER DEFAULT 0;
        DECLARE v_run_pm31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm31 INTEGER DEFAULT 0;
        DECLARE c_pm31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm31 = 1;
        OPEN c_pm31;
        loop_pm31: LOOP
            FETCH c_pm31 INTO v_so_pm31, v_cust_pm31, v_rk_pm31, v_run_pm31;
            IF v_done_pm31 = 1 THEN LEAVE loop_pm31; END IF;
        END LOOP;
        CLOSE c_pm31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pm31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pm31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [pm32]
    BEGIN
        DECLARE v_hi_pm32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_pm32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_pm32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [pm33]
    BEGIN
        DECLARE v_pairs_pm33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_pm33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_pm33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [pm34]
    BEGIN
        DECLARE v_rows_pm34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_pm34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_pm34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_pm34 FROM SESSION.TMP_pm34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_pm34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [pm35]
    BEGIN
        DECLARE v_rc_pm35 INTEGER DEFAULT 0;
        DECLARE v_band_pm35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_pm35 = ROW_COUNT;
        SET v_band_pm35 = CASE
                            WHEN v_rc_pm35 = 0 THEN 'NONE'
                            WHEN v_rc_pm35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_pm35, 'COUNT', 'band=' || v_band_pm35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [pm36]
    BEGIN
        DECLARE v_i_pm36 INTEGER DEFAULT 0;
        SAVEPOINT sp_pm36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_pm36 < 4 DO
            SET v_i_pm36 = v_i_pm36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_pm36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_pm36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_pm36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [pm37]
    BEGIN
        DECLARE v_j_pm37 INTEGER DEFAULT 0;
        DECLARE v_sum_pm37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_pm37 = v_j_pm37 + 1;
        UNTIL v_j_pm37 >= 3 END REPEAT;
        FOR row_pm37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_pm37 = v_sum_pm37 + COALESCE(row_pm37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_pm37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_pm37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [pm38]
    BEGIN
        DECLARE v_n_pm38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_pm38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_pm38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [pm39]
    BEGIN
        DECLARE v_levels_pm39 INTEGER DEFAULT 0;
        DECLARE c_pm39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_pm39 = 0;
        OPEN c_pm39;
        FETCH c_pm39 INTO v_levels_pm39;
        CLOSE c_pm39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_pm39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pm40]
    BEGIN
        DECLARE v_sql_pm40 VARCHAR(1000);
        DECLARE v_n_pm40 INTEGER DEFAULT 0;
        SET v_sql_pm40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_pm40 FROM v_sql_pm40;
        EXECUTE st_pm40;
        SELECT COUNT(*) INTO v_n_pm40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pm40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pm41]
    BEGIN
        DECLARE v_key_pm41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pm41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pm41' AS VARCHAR(40)), v_key_pm41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [pm42]
    BEGIN
        DECLARE v_so_pm42 INTEGER DEFAULT 0;
        DECLARE v_cust_pm42 INTEGER DEFAULT 0;
        DECLARE v_ctry_pm42 INTEGER DEFAULT 0;
        DECLARE v_ccy_pm42 INTEGER DEFAULT 0;
        DECLARE v_sub_pm42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pm42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pm42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pm42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pm42 INTEGER DEFAULT 0;
        DECLARE v_done_pm42 INTEGER DEFAULT 0;
        DECLARE c_pm42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm42 = 1;
        OPEN c_pm42;
        loop_pm42: LOOP
            FETCH c_pm42 INTO v_so_pm42, v_cust_pm42, v_ctry_pm42, v_ccy_pm42, v_sub_pm42;
            IF v_done_pm42 = 1 THEN LEAVE loop_pm42; END IF;
            SET v_tax_pm42 = ERP_FN_TAX(v_ctry_pm42, v_sub_pm42);
            SET v_fx_pm42 = ERP_FN_FX_CONVERT(v_ccy_pm42, 1, v_sub_pm42 + v_tax_pm42);
            SET v_acc_pm42 = v_acc_pm42 + v_fx_pm42;
            SET v_cnt_pm42 = v_cnt_pm42 + 1;
        END LOOP;
        CLOSE c_pm42;
        IF v_cnt_pm42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pm42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pm42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pm43]
    BEGIN
        DECLARE v_pid_pm43 INTEGER DEFAULT 0;
        DECLARE v_oh_pm43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pm43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pm43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pm43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pm43 INTEGER DEFAULT 0;
        DECLARE c_pm43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm43 = 1;
        OPEN c_pm43;
        loop_pm43: LOOP
            FETCH c_pm43 INTO v_pid_pm43, v_oh_pm43, v_cost_pm43;
            IF v_done_pm43 = 1 THEN LEAVE loop_pm43; END IF;
            SET v_avail_pm43 = ERP_FN_INVENTORY_ONHAND(v_pid_pm43);
            SET v_val_pm43 = v_val_pm43 + CAST(COALESCE(v_oh_pm43,0) * COALESCE(v_cost_pm43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pm43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pm43;
        END LOOP;
        CLOSE c_pm43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pm43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pm44]
    BEGIN
        DECLARE v_prod_pm44 INTEGER DEFAULT 0;
        DECLARE v_rm_pm44 INTEGER DEFAULT 0;
        DECLARE v_supp_pm44 INTEGER DEFAULT 0;
        DECLARE v_qper_pm44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pm44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pm44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pm44 INTEGER DEFAULT 0;
        DECLARE c_pm44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm44 = 1;
        OPEN c_pm44;
        loop_pm44: LOOP
            FETCH c_pm44 INTO v_prod_pm44, v_rm_pm44, v_supp_pm44, v_qper_pm44, v_uc_pm44;
            IF v_done_pm44 = 1 THEN LEAVE loop_pm44; END IF;
            SET v_roll_pm44 = v_roll_pm44 + COALESCE(v_qper_pm44,0) * COALESCE(v_uc_pm44,0);
        END LOOP;
        CLOSE c_pm44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pm44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pm45]
    BEGIN
        DECLARE v_acct_pm45 INTEGER DEFAULT 0;
        DECLARE v_deb_pm45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pm45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pm45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm45 INTEGER DEFAULT 0;
        DECLARE c_pm45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm45 = 1;
        OPEN c_pm45;
        loop_pm45: LOOP
            FETCH c_pm45 INTO v_acct_pm45, v_deb_pm45, v_cred_pm45;
            IF v_done_pm45 = 1 THEN LEAVE loop_pm45; END IF;
            SET v_net_pm45 = v_net_pm45 + (v_deb_pm45 - v_cred_pm45);
        END LOOP;
        CLOSE c_pm45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pm45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pm46]
    BEGIN
        DECLARE v_pid_pm46 INTEGER DEFAULT 0;
        DECLARE v_lp_pm46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pm46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pm46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pm46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pm46 INTEGER DEFAULT 0;
        DECLARE c_pm46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm46 = 1;
        OPEN c_pm46;
        loop_pm46: LOOP
            FETCH c_pm46 INTO v_pid_pm46, v_lp_pm46, v_pp_pm46;
            IF v_done_pm46 = 1 THEN LEAVE loop_pm46; END IF;
            SET v_var_pm46 = v_var_pm46 + (COALESCE(v_lp_pm46,0) - COALESCE(v_pp_pm46,0));
            SET v_marg_pm46 = ERP_FN_MARGIN(v_pid_pm46);
        END LOOP;
        CLOSE c_pm46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pm46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pm47]
    BEGIN
        DECLARE v_inv_pm47 INTEGER DEFAULT 0;
        DECLARE v_amt_pm47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pm47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pm47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm47 INTEGER DEFAULT 0;
        DECLARE c_pm47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm47 = 1;
        OPEN c_pm47;
        loop_pm47: LOOP
            FETCH c_pm47 INTO v_inv_pm47, v_amt_pm47, v_alloc_pm47;
            IF v_done_pm47 = 1 THEN LEAVE loop_pm47; END IF;
            SET v_open_pm47 = v_open_pm47 + (v_amt_pm47 - v_alloc_pm47);
        END LOOP;
        CLOSE c_pm47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pm47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pm48]
    BEGIN
        DECLARE v_lvl_pm48 INTEGER DEFAULT 0;
        DECLARE v_dept_pm48 INTEGER DEFAULT 0;
        DECLARE v_head_pm48 INTEGER DEFAULT 0;
        DECLARE v_done_pm48 INTEGER DEFAULT 0;
        DECLARE c_pm48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm48 = 1;
        OPEN c_pm48;
        loop_pm48: LOOP
            FETCH c_pm48 INTO v_dept_pm48, v_lvl_pm48, v_head_pm48;
            IF v_done_pm48 = 1 THEN LEAVE loop_pm48; END IF;
        END LOOP;
        CLOSE c_pm48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pm48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pm48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pm49]
    BEGIN
        DECLARE v_sh_pm49 INTEGER DEFAULT 0;
        DECLARE v_car_pm49 INTEGER DEFAULT 0;
        DECLARE v_qty_pm49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pm49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pm49 INTEGER DEFAULT 0;
        DECLARE c_pm49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm49 = 1;
        OPEN c_pm49;
        loop_pm49: LOOP
            FETCH c_pm49 INTO v_sh_pm49, v_car_pm49, v_qty_pm49;
            IF v_done_pm49 = 1 THEN LEAVE loop_pm49; END IF;
            SET v_tot_pm49 = v_tot_pm49 + v_qty_pm49;
        END LOOP;
        CLOSE c_pm49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pm49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pm50]
    BEGIN
        DECLARE v_sql_pm50 VARCHAR(1000);
        DECLARE v_n_pm50 INTEGER DEFAULT 0;
        SET v_sql_pm50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pm50 FROM v_sql_pm50;
        EXECUTE st_pm50;
        SELECT COUNT(*) INTO v_n_pm50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pm50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pm51]
    BEGIN
        DECLARE v_key_pm51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pm51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pm51' AS VARCHAR(40)), v_key_pm51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pm52]
    BEGIN
        DECLARE v_so_pm52 INTEGER DEFAULT 0;
        DECLARE v_cust_pm52 INTEGER DEFAULT 0;
        DECLARE v_rk_pm52 INTEGER DEFAULT 0;
        DECLARE v_run_pm52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pm52 INTEGER DEFAULT 0;
        DECLARE c_pm52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pm52 = 1;
        OPEN c_pm52;
        loop_pm52: LOOP
            FETCH c_pm52 INTO v_so_pm52, v_cust_pm52, v_rk_pm52, v_run_pm52;
            IF v_done_pm52 = 1 THEN LEAVE loop_pm52; END IF;
        END LOOP;
        CLOSE c_pm52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pm52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pm52)), CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_CREATE_WORK_ORDER(IN p_product_id INTEGER, IN p_qty DECIMAL(16,4), IN p_so_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_wo_id INTEGER;
    DECLARE v_manufactured SMALLINT DEFAULT 0;
    DECLARE v_bom_cost DECIMAL(18,4) DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('WORK_ORDER', p_product_id, 'ERROR', 'create wo failed');
    END;
    SELECT COALESCE(is_manufactured,0) INTO v_manufactured FROM ERP_PRODUCT WHERE id = p_product_id;
    SET v_bom_cost = ERP_FN_BOM_COST(p_product_id);
    IF v_manufactured = 1 THEN
        INSERT INTO ERP_WORK_ORDER(product_id, qty, status, start_date)
        VALUES (p_product_id, p_qty, 'OPEN', CURRENT DATE);
        SET v_wo_id = IDENTITY_VAL_LOCAL();
        CALL ERP_USP_SCHEDULE_OPS(v_wo_id, p_so_id);
    ELSE
        CALL ERP_USP_CREATE_SHIPMENT(p_so_id);
    END IF;
    CALL ERP_USP_AUDIT('WORK_ORDER', p_product_id, 'CREATE', 'work order created');
    -- order/customer/country/currency revenue scan [cw00]
    BEGIN
        DECLARE v_so_cw00 INTEGER DEFAULT 0;
        DECLARE v_cust_cw00 INTEGER DEFAULT 0;
        DECLARE v_ctry_cw00 INTEGER DEFAULT 0;
        DECLARE v_ccy_cw00 INTEGER DEFAULT 0;
        DECLARE v_sub_cw00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cw00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cw00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cw00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cw00 INTEGER DEFAULT 0;
        DECLARE v_done_cw00 INTEGER DEFAULT 0;
        DECLARE c_cw00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw00 = 1;
        OPEN c_cw00;
        loop_cw00: LOOP
            FETCH c_cw00 INTO v_so_cw00, v_cust_cw00, v_ctry_cw00, v_ccy_cw00, v_sub_cw00;
            IF v_done_cw00 = 1 THEN LEAVE loop_cw00; END IF;
            SET v_tax_cw00 = ERP_FN_TAX(v_ctry_cw00, v_sub_cw00);
            SET v_fx_cw00 = ERP_FN_FX_CONVERT(v_ccy_cw00, 1, v_sub_cw00 + v_tax_cw00);
            SET v_acc_cw00 = v_acc_cw00 + v_fx_cw00;
            SET v_cnt_cw00 = v_cnt_cw00 + 1;
        END LOOP;
        CLOSE c_cw00;
        IF v_cnt_cw00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cw00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cw00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cw01]
    BEGIN
        DECLARE v_pid_cw01 INTEGER DEFAULT 0;
        DECLARE v_oh_cw01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cw01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cw01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cw01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cw01 INTEGER DEFAULT 0;
        DECLARE c_cw01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw01 = 1;
        OPEN c_cw01;
        loop_cw01: LOOP
            FETCH c_cw01 INTO v_pid_cw01, v_oh_cw01, v_cost_cw01;
            IF v_done_cw01 = 1 THEN LEAVE loop_cw01; END IF;
            SET v_avail_cw01 = ERP_FN_INVENTORY_ONHAND(v_pid_cw01);
            SET v_val_cw01 = v_val_cw01 + CAST(COALESCE(v_oh_cw01,0) * COALESCE(v_cost_cw01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cw01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cw01;
        END LOOP;
        CLOSE c_cw01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cw01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cw02]
    BEGIN
        DECLARE v_prod_cw02 INTEGER DEFAULT 0;
        DECLARE v_rm_cw02 INTEGER DEFAULT 0;
        DECLARE v_supp_cw02 INTEGER DEFAULT 0;
        DECLARE v_qper_cw02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cw02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cw02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cw02 INTEGER DEFAULT 0;
        DECLARE c_cw02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw02 = 1;
        OPEN c_cw02;
        loop_cw02: LOOP
            FETCH c_cw02 INTO v_prod_cw02, v_rm_cw02, v_supp_cw02, v_qper_cw02, v_uc_cw02;
            IF v_done_cw02 = 1 THEN LEAVE loop_cw02; END IF;
            SET v_roll_cw02 = v_roll_cw02 + COALESCE(v_qper_cw02,0) * COALESCE(v_uc_cw02,0);
        END LOOP;
        CLOSE c_cw02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cw02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cw03]
    BEGIN
        DECLARE v_acct_cw03 INTEGER DEFAULT 0;
        DECLARE v_deb_cw03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cw03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cw03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw03 INTEGER DEFAULT 0;
        DECLARE c_cw03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw03 = 1;
        OPEN c_cw03;
        loop_cw03: LOOP
            FETCH c_cw03 INTO v_acct_cw03, v_deb_cw03, v_cred_cw03;
            IF v_done_cw03 = 1 THEN LEAVE loop_cw03; END IF;
            SET v_net_cw03 = v_net_cw03 + (v_deb_cw03 - v_cred_cw03);
        END LOOP;
        CLOSE c_cw03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cw03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cw04]
    BEGIN
        DECLARE v_pid_cw04 INTEGER DEFAULT 0;
        DECLARE v_lp_cw04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cw04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cw04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cw04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cw04 INTEGER DEFAULT 0;
        DECLARE c_cw04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw04 = 1;
        OPEN c_cw04;
        loop_cw04: LOOP
            FETCH c_cw04 INTO v_pid_cw04, v_lp_cw04, v_pp_cw04;
            IF v_done_cw04 = 1 THEN LEAVE loop_cw04; END IF;
            SET v_var_cw04 = v_var_cw04 + (COALESCE(v_lp_cw04,0) - COALESCE(v_pp_cw04,0));
            SET v_marg_cw04 = ERP_FN_MARGIN(v_pid_cw04);
        END LOOP;
        CLOSE c_cw04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cw04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cw05]
    BEGIN
        DECLARE v_inv_cw05 INTEGER DEFAULT 0;
        DECLARE v_amt_cw05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cw05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cw05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw05 INTEGER DEFAULT 0;
        DECLARE c_cw05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw05 = 1;
        OPEN c_cw05;
        loop_cw05: LOOP
            FETCH c_cw05 INTO v_inv_cw05, v_amt_cw05, v_alloc_cw05;
            IF v_done_cw05 = 1 THEN LEAVE loop_cw05; END IF;
            SET v_open_cw05 = v_open_cw05 + (v_amt_cw05 - v_alloc_cw05);
        END LOOP;
        CLOSE c_cw05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cw05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [cw06]
    BEGIN
        DECLARE v_lvl_cw06 INTEGER DEFAULT 0;
        DECLARE v_dept_cw06 INTEGER DEFAULT 0;
        DECLARE v_head_cw06 INTEGER DEFAULT 0;
        DECLARE v_done_cw06 INTEGER DEFAULT 0;
        DECLARE c_cw06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw06 = 1;
        OPEN c_cw06;
        loop_cw06: LOOP
            FETCH c_cw06 INTO v_dept_cw06, v_lvl_cw06, v_head_cw06;
            IF v_done_cw06 = 1 THEN LEAVE loop_cw06; END IF;
        END LOOP;
        CLOSE c_cw06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_cw06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_cw06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [cw07]
    BEGIN
        DECLARE v_sh_cw07 INTEGER DEFAULT 0;
        DECLARE v_car_cw07 INTEGER DEFAULT 0;
        DECLARE v_qty_cw07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_cw07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cw07 INTEGER DEFAULT 0;
        DECLARE c_cw07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw07 = 1;
        OPEN c_cw07;
        loop_cw07: LOOP
            FETCH c_cw07 INTO v_sh_cw07, v_car_cw07, v_qty_cw07;
            IF v_done_cw07 = 1 THEN LEAVE loop_cw07; END IF;
            SET v_tot_cw07 = v_tot_cw07 + v_qty_cw07;
        END LOOP;
        CLOSE c_cw07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_cw07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cw08]
    BEGIN
        DECLARE v_sql_cw08 VARCHAR(1000);
        DECLARE v_n_cw08 INTEGER DEFAULT 0;
        SET v_sql_cw08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_cw08 FROM v_sql_cw08;
        EXECUTE st_cw08;
        SELECT COUNT(*) INTO v_n_cw08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cw08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cw09]
    BEGIN
        DECLARE v_key_cw09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cw09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cw09' AS VARCHAR(40)), v_key_cw09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [cw10]
    BEGIN
        DECLARE v_so_cw10 INTEGER DEFAULT 0;
        DECLARE v_cust_cw10 INTEGER DEFAULT 0;
        DECLARE v_rk_cw10 INTEGER DEFAULT 0;
        DECLARE v_run_cw10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw10 INTEGER DEFAULT 0;
        DECLARE c_cw10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw10 = 1;
        OPEN c_cw10;
        loop_cw10: LOOP
            FETCH c_cw10 INTO v_so_cw10, v_cust_cw10, v_rk_cw10, v_run_cw10;
            IF v_done_cw10 = 1 THEN LEAVE loop_cw10; END IF;
        END LOOP;
        CLOSE c_cw10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_cw10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_cw10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [cw11]
    BEGIN
        DECLARE v_hi_cw11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_cw11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_cw11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [cw12]
    BEGIN
        DECLARE v_pairs_cw12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_cw12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_cw12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [cw13]
    BEGIN
        DECLARE v_rows_cw13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_cw13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_cw13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_cw13 FROM SESSION.TMP_cw13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_cw13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [cw14]
    BEGIN
        DECLARE v_rc_cw14 INTEGER DEFAULT 0;
        DECLARE v_band_cw14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_cw14 = ROW_COUNT;
        SET v_band_cw14 = CASE
                            WHEN v_rc_cw14 = 0 THEN 'NONE'
                            WHEN v_rc_cw14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_cw14, 'COUNT', 'band=' || v_band_cw14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [cw15]
    BEGIN
        DECLARE v_i_cw15 INTEGER DEFAULT 0;
        SAVEPOINT sp_cw15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_cw15 < 4 DO
            SET v_i_cw15 = v_i_cw15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_cw15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_cw15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_cw15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [cw16]
    BEGIN
        DECLARE v_j_cw16 INTEGER DEFAULT 0;
        DECLARE v_sum_cw16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_cw16 = v_j_cw16 + 1;
        UNTIL v_j_cw16 >= 3 END REPEAT;
        FOR row_cw16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_cw16 = v_sum_cw16 + COALESCE(row_cw16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_cw16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_cw16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [cw17]
    BEGIN
        DECLARE v_n_cw17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_cw17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_cw17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [cw18]
    BEGIN
        DECLARE v_levels_cw18 INTEGER DEFAULT 0;
        DECLARE c_cw18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_cw18 = 0;
        OPEN c_cw18;
        FETCH c_cw18 INTO v_levels_cw18;
        CLOSE c_cw18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_cw18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cw19]
    BEGIN
        DECLARE v_sql_cw19 VARCHAR(1000);
        DECLARE v_n_cw19 INTEGER DEFAULT 0;
        SET v_sql_cw19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_cw19 FROM v_sql_cw19;
        EXECUTE st_cw19;
        SELECT COUNT(*) INTO v_n_cw19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cw19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cw20]
    BEGIN
        DECLARE v_key_cw20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cw20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cw20' AS VARCHAR(40)), v_key_cw20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [cw21]
    BEGIN
        DECLARE v_so_cw21 INTEGER DEFAULT 0;
        DECLARE v_cust_cw21 INTEGER DEFAULT 0;
        DECLARE v_ctry_cw21 INTEGER DEFAULT 0;
        DECLARE v_ccy_cw21 INTEGER DEFAULT 0;
        DECLARE v_sub_cw21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cw21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cw21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cw21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cw21 INTEGER DEFAULT 0;
        DECLARE v_done_cw21 INTEGER DEFAULT 0;
        DECLARE c_cw21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw21 = 1;
        OPEN c_cw21;
        loop_cw21: LOOP
            FETCH c_cw21 INTO v_so_cw21, v_cust_cw21, v_ctry_cw21, v_ccy_cw21, v_sub_cw21;
            IF v_done_cw21 = 1 THEN LEAVE loop_cw21; END IF;
            SET v_tax_cw21 = ERP_FN_TAX(v_ctry_cw21, v_sub_cw21);
            SET v_fx_cw21 = ERP_FN_FX_CONVERT(v_ccy_cw21, 1, v_sub_cw21 + v_tax_cw21);
            SET v_acc_cw21 = v_acc_cw21 + v_fx_cw21;
            SET v_cnt_cw21 = v_cnt_cw21 + 1;
        END LOOP;
        CLOSE c_cw21;
        IF v_cnt_cw21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cw21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cw21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cw22]
    BEGIN
        DECLARE v_pid_cw22 INTEGER DEFAULT 0;
        DECLARE v_oh_cw22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cw22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cw22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cw22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cw22 INTEGER DEFAULT 0;
        DECLARE c_cw22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw22 = 1;
        OPEN c_cw22;
        loop_cw22: LOOP
            FETCH c_cw22 INTO v_pid_cw22, v_oh_cw22, v_cost_cw22;
            IF v_done_cw22 = 1 THEN LEAVE loop_cw22; END IF;
            SET v_avail_cw22 = ERP_FN_INVENTORY_ONHAND(v_pid_cw22);
            SET v_val_cw22 = v_val_cw22 + CAST(COALESCE(v_oh_cw22,0) * COALESCE(v_cost_cw22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cw22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cw22;
        END LOOP;
        CLOSE c_cw22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cw22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cw23]
    BEGIN
        DECLARE v_prod_cw23 INTEGER DEFAULT 0;
        DECLARE v_rm_cw23 INTEGER DEFAULT 0;
        DECLARE v_supp_cw23 INTEGER DEFAULT 0;
        DECLARE v_qper_cw23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cw23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cw23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cw23 INTEGER DEFAULT 0;
        DECLARE c_cw23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw23 = 1;
        OPEN c_cw23;
        loop_cw23: LOOP
            FETCH c_cw23 INTO v_prod_cw23, v_rm_cw23, v_supp_cw23, v_qper_cw23, v_uc_cw23;
            IF v_done_cw23 = 1 THEN LEAVE loop_cw23; END IF;
            SET v_roll_cw23 = v_roll_cw23 + COALESCE(v_qper_cw23,0) * COALESCE(v_uc_cw23,0);
        END LOOP;
        CLOSE c_cw23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cw23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cw24]
    BEGIN
        DECLARE v_acct_cw24 INTEGER DEFAULT 0;
        DECLARE v_deb_cw24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cw24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cw24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw24 INTEGER DEFAULT 0;
        DECLARE c_cw24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw24 = 1;
        OPEN c_cw24;
        loop_cw24: LOOP
            FETCH c_cw24 INTO v_acct_cw24, v_deb_cw24, v_cred_cw24;
            IF v_done_cw24 = 1 THEN LEAVE loop_cw24; END IF;
            SET v_net_cw24 = v_net_cw24 + (v_deb_cw24 - v_cred_cw24);
        END LOOP;
        CLOSE c_cw24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cw24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cw25]
    BEGIN
        DECLARE v_pid_cw25 INTEGER DEFAULT 0;
        DECLARE v_lp_cw25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cw25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cw25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cw25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cw25 INTEGER DEFAULT 0;
        DECLARE c_cw25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw25 = 1;
        OPEN c_cw25;
        loop_cw25: LOOP
            FETCH c_cw25 INTO v_pid_cw25, v_lp_cw25, v_pp_cw25;
            IF v_done_cw25 = 1 THEN LEAVE loop_cw25; END IF;
            SET v_var_cw25 = v_var_cw25 + (COALESCE(v_lp_cw25,0) - COALESCE(v_pp_cw25,0));
            SET v_marg_cw25 = ERP_FN_MARGIN(v_pid_cw25);
        END LOOP;
        CLOSE c_cw25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cw25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cw26]
    BEGIN
        DECLARE v_inv_cw26 INTEGER DEFAULT 0;
        DECLARE v_amt_cw26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cw26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cw26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw26 INTEGER DEFAULT 0;
        DECLARE c_cw26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw26 = 1;
        OPEN c_cw26;
        loop_cw26: LOOP
            FETCH c_cw26 INTO v_inv_cw26, v_amt_cw26, v_alloc_cw26;
            IF v_done_cw26 = 1 THEN LEAVE loop_cw26; END IF;
            SET v_open_cw26 = v_open_cw26 + (v_amt_cw26 - v_alloc_cw26);
        END LOOP;
        CLOSE c_cw26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cw26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [cw27]
    BEGIN
        DECLARE v_lvl_cw27 INTEGER DEFAULT 0;
        DECLARE v_dept_cw27 INTEGER DEFAULT 0;
        DECLARE v_head_cw27 INTEGER DEFAULT 0;
        DECLARE v_done_cw27 INTEGER DEFAULT 0;
        DECLARE c_cw27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw27 = 1;
        OPEN c_cw27;
        loop_cw27: LOOP
            FETCH c_cw27 INTO v_dept_cw27, v_lvl_cw27, v_head_cw27;
            IF v_done_cw27 = 1 THEN LEAVE loop_cw27; END IF;
        END LOOP;
        CLOSE c_cw27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_cw27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_cw27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [cw28]
    BEGIN
        DECLARE v_sh_cw28 INTEGER DEFAULT 0;
        DECLARE v_car_cw28 INTEGER DEFAULT 0;
        DECLARE v_qty_cw28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_cw28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cw28 INTEGER DEFAULT 0;
        DECLARE c_cw28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw28 = 1;
        OPEN c_cw28;
        loop_cw28: LOOP
            FETCH c_cw28 INTO v_sh_cw28, v_car_cw28, v_qty_cw28;
            IF v_done_cw28 = 1 THEN LEAVE loop_cw28; END IF;
            SET v_tot_cw28 = v_tot_cw28 + v_qty_cw28;
        END LOOP;
        CLOSE c_cw28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_cw28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cw29]
    BEGIN
        DECLARE v_sql_cw29 VARCHAR(1000);
        DECLARE v_n_cw29 INTEGER DEFAULT 0;
        SET v_sql_cw29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_cw29 FROM v_sql_cw29;
        EXECUTE st_cw29;
        SELECT COUNT(*) INTO v_n_cw29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cw29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cw30]
    BEGIN
        DECLARE v_key_cw30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cw30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cw30' AS VARCHAR(40)), v_key_cw30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [cw31]
    BEGIN
        DECLARE v_so_cw31 INTEGER DEFAULT 0;
        DECLARE v_cust_cw31 INTEGER DEFAULT 0;
        DECLARE v_rk_cw31 INTEGER DEFAULT 0;
        DECLARE v_run_cw31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw31 INTEGER DEFAULT 0;
        DECLARE c_cw31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw31 = 1;
        OPEN c_cw31;
        loop_cw31: LOOP
            FETCH c_cw31 INTO v_so_cw31, v_cust_cw31, v_rk_cw31, v_run_cw31;
            IF v_done_cw31 = 1 THEN LEAVE loop_cw31; END IF;
        END LOOP;
        CLOSE c_cw31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_cw31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_cw31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [cw32]
    BEGIN
        DECLARE v_hi_cw32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_cw32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_cw32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [cw33]
    BEGIN
        DECLARE v_pairs_cw33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_cw33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_cw33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [cw34]
    BEGIN
        DECLARE v_rows_cw34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_cw34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_cw34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_cw34 FROM SESSION.TMP_cw34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_cw34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [cw35]
    BEGIN
        DECLARE v_rc_cw35 INTEGER DEFAULT 0;
        DECLARE v_band_cw35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_cw35 = ROW_COUNT;
        SET v_band_cw35 = CASE
                            WHEN v_rc_cw35 = 0 THEN 'NONE'
                            WHEN v_rc_cw35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_cw35, 'COUNT', 'band=' || v_band_cw35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [cw36]
    BEGIN
        DECLARE v_i_cw36 INTEGER DEFAULT 0;
        SAVEPOINT sp_cw36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_cw36 < 4 DO
            SET v_i_cw36 = v_i_cw36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_cw36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_cw36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_cw36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [cw37]
    BEGIN
        DECLARE v_j_cw37 INTEGER DEFAULT 0;
        DECLARE v_sum_cw37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_cw37 = v_j_cw37 + 1;
        UNTIL v_j_cw37 >= 3 END REPEAT;
        FOR row_cw37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_cw37 = v_sum_cw37 + COALESCE(row_cw37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_cw37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_cw37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [cw38]
    BEGIN
        DECLARE v_n_cw38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_cw38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_cw38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [cw39]
    BEGIN
        DECLARE v_levels_cw39 INTEGER DEFAULT 0;
        DECLARE c_cw39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_cw39 = 0;
        OPEN c_cw39;
        FETCH c_cw39 INTO v_levels_cw39;
        CLOSE c_cw39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_cw39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cw40]
    BEGIN
        DECLARE v_sql_cw40 VARCHAR(1000);
        DECLARE v_n_cw40 INTEGER DEFAULT 0;
        SET v_sql_cw40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_cw40 FROM v_sql_cw40;
        EXECUTE st_cw40;
        SELECT COUNT(*) INTO v_n_cw40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cw40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cw41]
    BEGIN
        DECLARE v_key_cw41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cw41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cw41' AS VARCHAR(40)), v_key_cw41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [cw42]
    BEGIN
        DECLARE v_so_cw42 INTEGER DEFAULT 0;
        DECLARE v_cust_cw42 INTEGER DEFAULT 0;
        DECLARE v_ctry_cw42 INTEGER DEFAULT 0;
        DECLARE v_ccy_cw42 INTEGER DEFAULT 0;
        DECLARE v_sub_cw42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cw42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cw42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cw42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cw42 INTEGER DEFAULT 0;
        DECLARE v_done_cw42 INTEGER DEFAULT 0;
        DECLARE c_cw42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw42 = 1;
        OPEN c_cw42;
        loop_cw42: LOOP
            FETCH c_cw42 INTO v_so_cw42, v_cust_cw42, v_ctry_cw42, v_ccy_cw42, v_sub_cw42;
            IF v_done_cw42 = 1 THEN LEAVE loop_cw42; END IF;
            SET v_tax_cw42 = ERP_FN_TAX(v_ctry_cw42, v_sub_cw42);
            SET v_fx_cw42 = ERP_FN_FX_CONVERT(v_ccy_cw42, 1, v_sub_cw42 + v_tax_cw42);
            SET v_acc_cw42 = v_acc_cw42 + v_fx_cw42;
            SET v_cnt_cw42 = v_cnt_cw42 + 1;
        END LOOP;
        CLOSE c_cw42;
        IF v_cnt_cw42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cw42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cw42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cw43]
    BEGIN
        DECLARE v_pid_cw43 INTEGER DEFAULT 0;
        DECLARE v_oh_cw43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cw43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cw43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cw43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cw43 INTEGER DEFAULT 0;
        DECLARE c_cw43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw43 = 1;
        OPEN c_cw43;
        loop_cw43: LOOP
            FETCH c_cw43 INTO v_pid_cw43, v_oh_cw43, v_cost_cw43;
            IF v_done_cw43 = 1 THEN LEAVE loop_cw43; END IF;
            SET v_avail_cw43 = ERP_FN_INVENTORY_ONHAND(v_pid_cw43);
            SET v_val_cw43 = v_val_cw43 + CAST(COALESCE(v_oh_cw43,0) * COALESCE(v_cost_cw43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cw43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cw43;
        END LOOP;
        CLOSE c_cw43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cw43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cw44]
    BEGIN
        DECLARE v_prod_cw44 INTEGER DEFAULT 0;
        DECLARE v_rm_cw44 INTEGER DEFAULT 0;
        DECLARE v_supp_cw44 INTEGER DEFAULT 0;
        DECLARE v_qper_cw44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cw44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cw44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cw44 INTEGER DEFAULT 0;
        DECLARE c_cw44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw44 = 1;
        OPEN c_cw44;
        loop_cw44: LOOP
            FETCH c_cw44 INTO v_prod_cw44, v_rm_cw44, v_supp_cw44, v_qper_cw44, v_uc_cw44;
            IF v_done_cw44 = 1 THEN LEAVE loop_cw44; END IF;
            SET v_roll_cw44 = v_roll_cw44 + COALESCE(v_qper_cw44,0) * COALESCE(v_uc_cw44,0);
        END LOOP;
        CLOSE c_cw44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cw44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cw45]
    BEGIN
        DECLARE v_acct_cw45 INTEGER DEFAULT 0;
        DECLARE v_deb_cw45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cw45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cw45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw45 INTEGER DEFAULT 0;
        DECLARE c_cw45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw45 = 1;
        OPEN c_cw45;
        loop_cw45: LOOP
            FETCH c_cw45 INTO v_acct_cw45, v_deb_cw45, v_cred_cw45;
            IF v_done_cw45 = 1 THEN LEAVE loop_cw45; END IF;
            SET v_net_cw45 = v_net_cw45 + (v_deb_cw45 - v_cred_cw45);
        END LOOP;
        CLOSE c_cw45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cw45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cw46]
    BEGIN
        DECLARE v_pid_cw46 INTEGER DEFAULT 0;
        DECLARE v_lp_cw46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cw46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cw46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cw46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cw46 INTEGER DEFAULT 0;
        DECLARE c_cw46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw46 = 1;
        OPEN c_cw46;
        loop_cw46: LOOP
            FETCH c_cw46 INTO v_pid_cw46, v_lp_cw46, v_pp_cw46;
            IF v_done_cw46 = 1 THEN LEAVE loop_cw46; END IF;
            SET v_var_cw46 = v_var_cw46 + (COALESCE(v_lp_cw46,0) - COALESCE(v_pp_cw46,0));
            SET v_marg_cw46 = ERP_FN_MARGIN(v_pid_cw46);
        END LOOP;
        CLOSE c_cw46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cw46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cw47]
    BEGIN
        DECLARE v_inv_cw47 INTEGER DEFAULT 0;
        DECLARE v_amt_cw47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cw47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cw47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw47 INTEGER DEFAULT 0;
        DECLARE c_cw47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw47 = 1;
        OPEN c_cw47;
        loop_cw47: LOOP
            FETCH c_cw47 INTO v_inv_cw47, v_amt_cw47, v_alloc_cw47;
            IF v_done_cw47 = 1 THEN LEAVE loop_cw47; END IF;
            SET v_open_cw47 = v_open_cw47 + (v_amt_cw47 - v_alloc_cw47);
        END LOOP;
        CLOSE c_cw47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cw47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [cw48]
    BEGIN
        DECLARE v_lvl_cw48 INTEGER DEFAULT 0;
        DECLARE v_dept_cw48 INTEGER DEFAULT 0;
        DECLARE v_head_cw48 INTEGER DEFAULT 0;
        DECLARE v_done_cw48 INTEGER DEFAULT 0;
        DECLARE c_cw48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw48 = 1;
        OPEN c_cw48;
        loop_cw48: LOOP
            FETCH c_cw48 INTO v_dept_cw48, v_lvl_cw48, v_head_cw48;
            IF v_done_cw48 = 1 THEN LEAVE loop_cw48; END IF;
        END LOOP;
        CLOSE c_cw48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_cw48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_cw48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [cw49]
    BEGIN
        DECLARE v_sh_cw49 INTEGER DEFAULT 0;
        DECLARE v_car_cw49 INTEGER DEFAULT 0;
        DECLARE v_qty_cw49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_cw49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cw49 INTEGER DEFAULT 0;
        DECLARE c_cw49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw49 = 1;
        OPEN c_cw49;
        loop_cw49: LOOP
            FETCH c_cw49 INTO v_sh_cw49, v_car_cw49, v_qty_cw49;
            IF v_done_cw49 = 1 THEN LEAVE loop_cw49; END IF;
            SET v_tot_cw49 = v_tot_cw49 + v_qty_cw49;
        END LOOP;
        CLOSE c_cw49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_cw49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cw50]
    BEGIN
        DECLARE v_sql_cw50 VARCHAR(1000);
        DECLARE v_n_cw50 INTEGER DEFAULT 0;
        SET v_sql_cw50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_cw50 FROM v_sql_cw50;
        EXECUTE st_cw50;
        SELECT COUNT(*) INTO v_n_cw50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cw50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cw51]
    BEGIN
        DECLARE v_key_cw51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cw51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cw51' AS VARCHAR(40)), v_key_cw51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [cw52]
    BEGIN
        DECLARE v_so_cw52 INTEGER DEFAULT 0;
        DECLARE v_cust_cw52 INTEGER DEFAULT 0;
        DECLARE v_rk_cw52 INTEGER DEFAULT 0;
        DECLARE v_run_cw52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cw52 INTEGER DEFAULT 0;
        DECLARE c_cw52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cw52 = 1;
        OPEN c_cw52;
        loop_cw52: LOOP
            FETCH c_cw52 INTO v_so_cw52, v_cust_cw52, v_rk_cw52, v_run_cw52;
            IF v_done_cw52 = 1 THEN LEAVE loop_cw52; END IF;
        END LOOP;
        CLOSE c_cw52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_cw52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_cw52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [cw53]
    BEGIN
        DECLARE v_hi_cw53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_cw53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_cw53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [cw54]
    BEGIN
        DECLARE v_pairs_cw54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_cw54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_cw54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [cw55]
    BEGIN
        DECLARE v_rows_cw55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_cw55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_cw55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_cw55 FROM SESSION.TMP_cw55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_cw55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [cw56]
    BEGIN
        DECLARE v_rc_cw56 INTEGER DEFAULT 0;
        DECLARE v_band_cw56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_cw56 = ROW_COUNT;
        SET v_band_cw56 = CASE
                            WHEN v_rc_cw56 = 0 THEN 'NONE'
                            WHEN v_rc_cw56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_cw56, 'COUNT', 'band=' || v_band_cw56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [cw57]
    BEGIN
        DECLARE v_i_cw57 INTEGER DEFAULT 0;
        SAVEPOINT sp_cw57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_cw57 < 4 DO
            SET v_i_cw57 = v_i_cw57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_cw57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_cw57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_cw57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_REPLENISH_STOCK(IN p_product_id INTEGER, IN p_so_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_need DECIMAL(16,4) DEFAULT 0;
    DECLARE v_manufactured SMALLINT DEFAULT 0;
    DECLARE v_target DECIMAL(16,4) DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('REPLENISH', p_product_id, 'ERROR', 'replenish failed');
    END;
    SELECT COALESCE(reorder_point,0), COALESCE(is_manufactured,0)
        INTO v_target, v_manufactured FROM ERP_PRODUCT WHERE id = p_product_id;
    SET v_need = ERP_FN_REORDER_QTY(p_product_id, v_target);
    IF v_need > 0 THEN
        CALL ERP_USP_CREATE_WORK_ORDER(p_product_id, v_need, p_so_id);
        CALL ERP_USP_PROCURE_MATERIAL(p_product_id, v_need);
    END IF;
    CALL ERP_USP_AUDIT('REPLENISH', p_product_id, 'DONE', 'replenish evaluated');
    -- order/customer/country/currency revenue scan [rp00]
    BEGIN
        DECLARE v_so_rp00 INTEGER DEFAULT 0;
        DECLARE v_cust_rp00 INTEGER DEFAULT 0;
        DECLARE v_ctry_rp00 INTEGER DEFAULT 0;
        DECLARE v_ccy_rp00 INTEGER DEFAULT 0;
        DECLARE v_sub_rp00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rp00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rp00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rp00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rp00 INTEGER DEFAULT 0;
        DECLARE v_done_rp00 INTEGER DEFAULT 0;
        DECLARE c_rp00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp00 = 1;
        OPEN c_rp00;
        loop_rp00: LOOP
            FETCH c_rp00 INTO v_so_rp00, v_cust_rp00, v_ctry_rp00, v_ccy_rp00, v_sub_rp00;
            IF v_done_rp00 = 1 THEN LEAVE loop_rp00; END IF;
            SET v_tax_rp00 = ERP_FN_TAX(v_ctry_rp00, v_sub_rp00);
            SET v_fx_rp00 = ERP_FN_FX_CONVERT(v_ccy_rp00, 1, v_sub_rp00 + v_tax_rp00);
            SET v_acc_rp00 = v_acc_rp00 + v_fx_rp00;
            SET v_cnt_rp00 = v_cnt_rp00 + 1;
        END LOOP;
        CLOSE c_rp00;
        IF v_cnt_rp00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rp00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rp00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rp01]
    BEGIN
        DECLARE v_pid_rp01 INTEGER DEFAULT 0;
        DECLARE v_oh_rp01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rp01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rp01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rp01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rp01 INTEGER DEFAULT 0;
        DECLARE c_rp01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp01 = 1;
        OPEN c_rp01;
        loop_rp01: LOOP
            FETCH c_rp01 INTO v_pid_rp01, v_oh_rp01, v_cost_rp01;
            IF v_done_rp01 = 1 THEN LEAVE loop_rp01; END IF;
            SET v_avail_rp01 = ERP_FN_INVENTORY_ONHAND(v_pid_rp01);
            SET v_val_rp01 = v_val_rp01 + CAST(COALESCE(v_oh_rp01,0) * COALESCE(v_cost_rp01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rp01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rp01;
        END LOOP;
        CLOSE c_rp01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rp01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rp02]
    BEGIN
        DECLARE v_prod_rp02 INTEGER DEFAULT 0;
        DECLARE v_rm_rp02 INTEGER DEFAULT 0;
        DECLARE v_supp_rp02 INTEGER DEFAULT 0;
        DECLARE v_qper_rp02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rp02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rp02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rp02 INTEGER DEFAULT 0;
        DECLARE c_rp02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp02 = 1;
        OPEN c_rp02;
        loop_rp02: LOOP
            FETCH c_rp02 INTO v_prod_rp02, v_rm_rp02, v_supp_rp02, v_qper_rp02, v_uc_rp02;
            IF v_done_rp02 = 1 THEN LEAVE loop_rp02; END IF;
            SET v_roll_rp02 = v_roll_rp02 + COALESCE(v_qper_rp02,0) * COALESCE(v_uc_rp02,0);
        END LOOP;
        CLOSE c_rp02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rp02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rp03]
    BEGIN
        DECLARE v_acct_rp03 INTEGER DEFAULT 0;
        DECLARE v_deb_rp03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rp03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rp03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp03 INTEGER DEFAULT 0;
        DECLARE c_rp03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp03 = 1;
        OPEN c_rp03;
        loop_rp03: LOOP
            FETCH c_rp03 INTO v_acct_rp03, v_deb_rp03, v_cred_rp03;
            IF v_done_rp03 = 1 THEN LEAVE loop_rp03; END IF;
            SET v_net_rp03 = v_net_rp03 + (v_deb_rp03 - v_cred_rp03);
        END LOOP;
        CLOSE c_rp03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rp03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rp04]
    BEGIN
        DECLARE v_pid_rp04 INTEGER DEFAULT 0;
        DECLARE v_lp_rp04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rp04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rp04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rp04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rp04 INTEGER DEFAULT 0;
        DECLARE c_rp04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp04 = 1;
        OPEN c_rp04;
        loop_rp04: LOOP
            FETCH c_rp04 INTO v_pid_rp04, v_lp_rp04, v_pp_rp04;
            IF v_done_rp04 = 1 THEN LEAVE loop_rp04; END IF;
            SET v_var_rp04 = v_var_rp04 + (COALESCE(v_lp_rp04,0) - COALESCE(v_pp_rp04,0));
            SET v_marg_rp04 = ERP_FN_MARGIN(v_pid_rp04);
        END LOOP;
        CLOSE c_rp04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rp04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rp05]
    BEGIN
        DECLARE v_inv_rp05 INTEGER DEFAULT 0;
        DECLARE v_amt_rp05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rp05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rp05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp05 INTEGER DEFAULT 0;
        DECLARE c_rp05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp05 = 1;
        OPEN c_rp05;
        loop_rp05: LOOP
            FETCH c_rp05 INTO v_inv_rp05, v_amt_rp05, v_alloc_rp05;
            IF v_done_rp05 = 1 THEN LEAVE loop_rp05; END IF;
            SET v_open_rp05 = v_open_rp05 + (v_amt_rp05 - v_alloc_rp05);
        END LOOP;
        CLOSE c_rp05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rp05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rp06]
    BEGIN
        DECLARE v_lvl_rp06 INTEGER DEFAULT 0;
        DECLARE v_dept_rp06 INTEGER DEFAULT 0;
        DECLARE v_head_rp06 INTEGER DEFAULT 0;
        DECLARE v_done_rp06 INTEGER DEFAULT 0;
        DECLARE c_rp06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp06 = 1;
        OPEN c_rp06;
        loop_rp06: LOOP
            FETCH c_rp06 INTO v_dept_rp06, v_lvl_rp06, v_head_rp06;
            IF v_done_rp06 = 1 THEN LEAVE loop_rp06; END IF;
        END LOOP;
        CLOSE c_rp06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rp06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rp06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rp07]
    BEGIN
        DECLARE v_sh_rp07 INTEGER DEFAULT 0;
        DECLARE v_car_rp07 INTEGER DEFAULT 0;
        DECLARE v_qty_rp07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rp07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rp07 INTEGER DEFAULT 0;
        DECLARE c_rp07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp07 = 1;
        OPEN c_rp07;
        loop_rp07: LOOP
            FETCH c_rp07 INTO v_sh_rp07, v_car_rp07, v_qty_rp07;
            IF v_done_rp07 = 1 THEN LEAVE loop_rp07; END IF;
            SET v_tot_rp07 = v_tot_rp07 + v_qty_rp07;
        END LOOP;
        CLOSE c_rp07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rp07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rp08]
    BEGIN
        DECLARE v_sql_rp08 VARCHAR(1000);
        DECLARE v_n_rp08 INTEGER DEFAULT 0;
        SET v_sql_rp08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rp08 FROM v_sql_rp08;
        EXECUTE st_rp08;
        SELECT COUNT(*) INTO v_n_rp08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rp08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rp09]
    BEGIN
        DECLARE v_key_rp09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rp09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rp09' AS VARCHAR(40)), v_key_rp09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rp10]
    BEGIN
        DECLARE v_so_rp10 INTEGER DEFAULT 0;
        DECLARE v_cust_rp10 INTEGER DEFAULT 0;
        DECLARE v_rk_rp10 INTEGER DEFAULT 0;
        DECLARE v_run_rp10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp10 INTEGER DEFAULT 0;
        DECLARE c_rp10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp10 = 1;
        OPEN c_rp10;
        loop_rp10: LOOP
            FETCH c_rp10 INTO v_so_rp10, v_cust_rp10, v_rk_rp10, v_run_rp10;
            IF v_done_rp10 = 1 THEN LEAVE loop_rp10; END IF;
        END LOOP;
        CLOSE c_rp10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rp10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rp10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rp11]
    BEGIN
        DECLARE v_hi_rp11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rp11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rp11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rp12]
    BEGIN
        DECLARE v_pairs_rp12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rp12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rp12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rp13]
    BEGIN
        DECLARE v_rows_rp13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rp13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rp13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rp13 FROM SESSION.TMP_rp13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rp13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rp14]
    BEGIN
        DECLARE v_rc_rp14 INTEGER DEFAULT 0;
        DECLARE v_band_rp14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rp14 = ROW_COUNT;
        SET v_band_rp14 = CASE
                            WHEN v_rc_rp14 = 0 THEN 'NONE'
                            WHEN v_rc_rp14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rp14, 'COUNT', 'band=' || v_band_rp14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rp15]
    BEGIN
        DECLARE v_i_rp15 INTEGER DEFAULT 0;
        SAVEPOINT sp_rp15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rp15 < 4 DO
            SET v_i_rp15 = v_i_rp15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rp15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rp15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rp15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rp16]
    BEGIN
        DECLARE v_j_rp16 INTEGER DEFAULT 0;
        DECLARE v_sum_rp16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rp16 = v_j_rp16 + 1;
        UNTIL v_j_rp16 >= 3 END REPEAT;
        FOR row_rp16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rp16 = v_sum_rp16 + COALESCE(row_rp16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rp16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rp16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rp17]
    BEGIN
        DECLARE v_n_rp17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rp17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rp17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rp18]
    BEGIN
        DECLARE v_levels_rp18 INTEGER DEFAULT 0;
        DECLARE c_rp18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rp18 = 0;
        OPEN c_rp18;
        FETCH c_rp18 INTO v_levels_rp18;
        CLOSE c_rp18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rp18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rp19]
    BEGIN
        DECLARE v_sql_rp19 VARCHAR(1000);
        DECLARE v_n_rp19 INTEGER DEFAULT 0;
        SET v_sql_rp19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rp19 FROM v_sql_rp19;
        EXECUTE st_rp19;
        SELECT COUNT(*) INTO v_n_rp19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rp19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rp20]
    BEGIN
        DECLARE v_key_rp20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rp20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rp20' AS VARCHAR(40)), v_key_rp20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rp21]
    BEGIN
        DECLARE v_so_rp21 INTEGER DEFAULT 0;
        DECLARE v_cust_rp21 INTEGER DEFAULT 0;
        DECLARE v_ctry_rp21 INTEGER DEFAULT 0;
        DECLARE v_ccy_rp21 INTEGER DEFAULT 0;
        DECLARE v_sub_rp21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rp21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rp21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rp21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rp21 INTEGER DEFAULT 0;
        DECLARE v_done_rp21 INTEGER DEFAULT 0;
        DECLARE c_rp21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp21 = 1;
        OPEN c_rp21;
        loop_rp21: LOOP
            FETCH c_rp21 INTO v_so_rp21, v_cust_rp21, v_ctry_rp21, v_ccy_rp21, v_sub_rp21;
            IF v_done_rp21 = 1 THEN LEAVE loop_rp21; END IF;
            SET v_tax_rp21 = ERP_FN_TAX(v_ctry_rp21, v_sub_rp21);
            SET v_fx_rp21 = ERP_FN_FX_CONVERT(v_ccy_rp21, 1, v_sub_rp21 + v_tax_rp21);
            SET v_acc_rp21 = v_acc_rp21 + v_fx_rp21;
            SET v_cnt_rp21 = v_cnt_rp21 + 1;
        END LOOP;
        CLOSE c_rp21;
        IF v_cnt_rp21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rp21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rp21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rp22]
    BEGIN
        DECLARE v_pid_rp22 INTEGER DEFAULT 0;
        DECLARE v_oh_rp22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rp22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rp22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rp22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rp22 INTEGER DEFAULT 0;
        DECLARE c_rp22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp22 = 1;
        OPEN c_rp22;
        loop_rp22: LOOP
            FETCH c_rp22 INTO v_pid_rp22, v_oh_rp22, v_cost_rp22;
            IF v_done_rp22 = 1 THEN LEAVE loop_rp22; END IF;
            SET v_avail_rp22 = ERP_FN_INVENTORY_ONHAND(v_pid_rp22);
            SET v_val_rp22 = v_val_rp22 + CAST(COALESCE(v_oh_rp22,0) * COALESCE(v_cost_rp22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rp22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rp22;
        END LOOP;
        CLOSE c_rp22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rp22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rp23]
    BEGIN
        DECLARE v_prod_rp23 INTEGER DEFAULT 0;
        DECLARE v_rm_rp23 INTEGER DEFAULT 0;
        DECLARE v_supp_rp23 INTEGER DEFAULT 0;
        DECLARE v_qper_rp23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rp23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rp23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rp23 INTEGER DEFAULT 0;
        DECLARE c_rp23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp23 = 1;
        OPEN c_rp23;
        loop_rp23: LOOP
            FETCH c_rp23 INTO v_prod_rp23, v_rm_rp23, v_supp_rp23, v_qper_rp23, v_uc_rp23;
            IF v_done_rp23 = 1 THEN LEAVE loop_rp23; END IF;
            SET v_roll_rp23 = v_roll_rp23 + COALESCE(v_qper_rp23,0) * COALESCE(v_uc_rp23,0);
        END LOOP;
        CLOSE c_rp23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rp23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rp24]
    BEGIN
        DECLARE v_acct_rp24 INTEGER DEFAULT 0;
        DECLARE v_deb_rp24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rp24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rp24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp24 INTEGER DEFAULT 0;
        DECLARE c_rp24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp24 = 1;
        OPEN c_rp24;
        loop_rp24: LOOP
            FETCH c_rp24 INTO v_acct_rp24, v_deb_rp24, v_cred_rp24;
            IF v_done_rp24 = 1 THEN LEAVE loop_rp24; END IF;
            SET v_net_rp24 = v_net_rp24 + (v_deb_rp24 - v_cred_rp24);
        END LOOP;
        CLOSE c_rp24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rp24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rp25]
    BEGIN
        DECLARE v_pid_rp25 INTEGER DEFAULT 0;
        DECLARE v_lp_rp25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rp25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rp25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rp25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rp25 INTEGER DEFAULT 0;
        DECLARE c_rp25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp25 = 1;
        OPEN c_rp25;
        loop_rp25: LOOP
            FETCH c_rp25 INTO v_pid_rp25, v_lp_rp25, v_pp_rp25;
            IF v_done_rp25 = 1 THEN LEAVE loop_rp25; END IF;
            SET v_var_rp25 = v_var_rp25 + (COALESCE(v_lp_rp25,0) - COALESCE(v_pp_rp25,0));
            SET v_marg_rp25 = ERP_FN_MARGIN(v_pid_rp25);
        END LOOP;
        CLOSE c_rp25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rp25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rp26]
    BEGIN
        DECLARE v_inv_rp26 INTEGER DEFAULT 0;
        DECLARE v_amt_rp26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rp26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rp26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp26 INTEGER DEFAULT 0;
        DECLARE c_rp26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp26 = 1;
        OPEN c_rp26;
        loop_rp26: LOOP
            FETCH c_rp26 INTO v_inv_rp26, v_amt_rp26, v_alloc_rp26;
            IF v_done_rp26 = 1 THEN LEAVE loop_rp26; END IF;
            SET v_open_rp26 = v_open_rp26 + (v_amt_rp26 - v_alloc_rp26);
        END LOOP;
        CLOSE c_rp26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rp26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rp27]
    BEGIN
        DECLARE v_lvl_rp27 INTEGER DEFAULT 0;
        DECLARE v_dept_rp27 INTEGER DEFAULT 0;
        DECLARE v_head_rp27 INTEGER DEFAULT 0;
        DECLARE v_done_rp27 INTEGER DEFAULT 0;
        DECLARE c_rp27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp27 = 1;
        OPEN c_rp27;
        loop_rp27: LOOP
            FETCH c_rp27 INTO v_dept_rp27, v_lvl_rp27, v_head_rp27;
            IF v_done_rp27 = 1 THEN LEAVE loop_rp27; END IF;
        END LOOP;
        CLOSE c_rp27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rp27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rp27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rp28]
    BEGIN
        DECLARE v_sh_rp28 INTEGER DEFAULT 0;
        DECLARE v_car_rp28 INTEGER DEFAULT 0;
        DECLARE v_qty_rp28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rp28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rp28 INTEGER DEFAULT 0;
        DECLARE c_rp28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp28 = 1;
        OPEN c_rp28;
        loop_rp28: LOOP
            FETCH c_rp28 INTO v_sh_rp28, v_car_rp28, v_qty_rp28;
            IF v_done_rp28 = 1 THEN LEAVE loop_rp28; END IF;
            SET v_tot_rp28 = v_tot_rp28 + v_qty_rp28;
        END LOOP;
        CLOSE c_rp28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rp28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rp29]
    BEGIN
        DECLARE v_sql_rp29 VARCHAR(1000);
        DECLARE v_n_rp29 INTEGER DEFAULT 0;
        SET v_sql_rp29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rp29 FROM v_sql_rp29;
        EXECUTE st_rp29;
        SELECT COUNT(*) INTO v_n_rp29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rp29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rp30]
    BEGIN
        DECLARE v_key_rp30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rp30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rp30' AS VARCHAR(40)), v_key_rp30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rp31]
    BEGIN
        DECLARE v_so_rp31 INTEGER DEFAULT 0;
        DECLARE v_cust_rp31 INTEGER DEFAULT 0;
        DECLARE v_rk_rp31 INTEGER DEFAULT 0;
        DECLARE v_run_rp31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp31 INTEGER DEFAULT 0;
        DECLARE c_rp31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp31 = 1;
        OPEN c_rp31;
        loop_rp31: LOOP
            FETCH c_rp31 INTO v_so_rp31, v_cust_rp31, v_rk_rp31, v_run_rp31;
            IF v_done_rp31 = 1 THEN LEAVE loop_rp31; END IF;
        END LOOP;
        CLOSE c_rp31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rp31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rp31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rp32]
    BEGIN
        DECLARE v_hi_rp32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rp32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rp32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rp33]
    BEGIN
        DECLARE v_pairs_rp33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rp33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rp33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rp34]
    BEGIN
        DECLARE v_rows_rp34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rp34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rp34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rp34 FROM SESSION.TMP_rp34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rp34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rp35]
    BEGIN
        DECLARE v_rc_rp35 INTEGER DEFAULT 0;
        DECLARE v_band_rp35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rp35 = ROW_COUNT;
        SET v_band_rp35 = CASE
                            WHEN v_rc_rp35 = 0 THEN 'NONE'
                            WHEN v_rc_rp35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rp35, 'COUNT', 'band=' || v_band_rp35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rp36]
    BEGIN
        DECLARE v_i_rp36 INTEGER DEFAULT 0;
        SAVEPOINT sp_rp36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rp36 < 4 DO
            SET v_i_rp36 = v_i_rp36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rp36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rp36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rp36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rp37]
    BEGIN
        DECLARE v_j_rp37 INTEGER DEFAULT 0;
        DECLARE v_sum_rp37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rp37 = v_j_rp37 + 1;
        UNTIL v_j_rp37 >= 3 END REPEAT;
        FOR row_rp37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rp37 = v_sum_rp37 + COALESCE(row_rp37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rp37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rp37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rp38]
    BEGIN
        DECLARE v_n_rp38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rp38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rp38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rp39]
    BEGIN
        DECLARE v_levels_rp39 INTEGER DEFAULT 0;
        DECLARE c_rp39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rp39 = 0;
        OPEN c_rp39;
        FETCH c_rp39 INTO v_levels_rp39;
        CLOSE c_rp39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rp39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rp40]
    BEGIN
        DECLARE v_sql_rp40 VARCHAR(1000);
        DECLARE v_n_rp40 INTEGER DEFAULT 0;
        SET v_sql_rp40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rp40 FROM v_sql_rp40;
        EXECUTE st_rp40;
        SELECT COUNT(*) INTO v_n_rp40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rp40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rp41]
    BEGIN
        DECLARE v_key_rp41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rp41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rp41' AS VARCHAR(40)), v_key_rp41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rp42]
    BEGIN
        DECLARE v_so_rp42 INTEGER DEFAULT 0;
        DECLARE v_cust_rp42 INTEGER DEFAULT 0;
        DECLARE v_ctry_rp42 INTEGER DEFAULT 0;
        DECLARE v_ccy_rp42 INTEGER DEFAULT 0;
        DECLARE v_sub_rp42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rp42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rp42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rp42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rp42 INTEGER DEFAULT 0;
        DECLARE v_done_rp42 INTEGER DEFAULT 0;
        DECLARE c_rp42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp42 = 1;
        OPEN c_rp42;
        loop_rp42: LOOP
            FETCH c_rp42 INTO v_so_rp42, v_cust_rp42, v_ctry_rp42, v_ccy_rp42, v_sub_rp42;
            IF v_done_rp42 = 1 THEN LEAVE loop_rp42; END IF;
            SET v_tax_rp42 = ERP_FN_TAX(v_ctry_rp42, v_sub_rp42);
            SET v_fx_rp42 = ERP_FN_FX_CONVERT(v_ccy_rp42, 1, v_sub_rp42 + v_tax_rp42);
            SET v_acc_rp42 = v_acc_rp42 + v_fx_rp42;
            SET v_cnt_rp42 = v_cnt_rp42 + 1;
        END LOOP;
        CLOSE c_rp42;
        IF v_cnt_rp42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rp42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rp42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rp43]
    BEGIN
        DECLARE v_pid_rp43 INTEGER DEFAULT 0;
        DECLARE v_oh_rp43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rp43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rp43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rp43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rp43 INTEGER DEFAULT 0;
        DECLARE c_rp43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp43 = 1;
        OPEN c_rp43;
        loop_rp43: LOOP
            FETCH c_rp43 INTO v_pid_rp43, v_oh_rp43, v_cost_rp43;
            IF v_done_rp43 = 1 THEN LEAVE loop_rp43; END IF;
            SET v_avail_rp43 = ERP_FN_INVENTORY_ONHAND(v_pid_rp43);
            SET v_val_rp43 = v_val_rp43 + CAST(COALESCE(v_oh_rp43,0) * COALESCE(v_cost_rp43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rp43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rp43;
        END LOOP;
        CLOSE c_rp43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rp43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rp44]
    BEGIN
        DECLARE v_prod_rp44 INTEGER DEFAULT 0;
        DECLARE v_rm_rp44 INTEGER DEFAULT 0;
        DECLARE v_supp_rp44 INTEGER DEFAULT 0;
        DECLARE v_qper_rp44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rp44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rp44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rp44 INTEGER DEFAULT 0;
        DECLARE c_rp44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp44 = 1;
        OPEN c_rp44;
        loop_rp44: LOOP
            FETCH c_rp44 INTO v_prod_rp44, v_rm_rp44, v_supp_rp44, v_qper_rp44, v_uc_rp44;
            IF v_done_rp44 = 1 THEN LEAVE loop_rp44; END IF;
            SET v_roll_rp44 = v_roll_rp44 + COALESCE(v_qper_rp44,0) * COALESCE(v_uc_rp44,0);
        END LOOP;
        CLOSE c_rp44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rp44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rp45]
    BEGIN
        DECLARE v_acct_rp45 INTEGER DEFAULT 0;
        DECLARE v_deb_rp45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rp45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rp45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp45 INTEGER DEFAULT 0;
        DECLARE c_rp45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp45 = 1;
        OPEN c_rp45;
        loop_rp45: LOOP
            FETCH c_rp45 INTO v_acct_rp45, v_deb_rp45, v_cred_rp45;
            IF v_done_rp45 = 1 THEN LEAVE loop_rp45; END IF;
            SET v_net_rp45 = v_net_rp45 + (v_deb_rp45 - v_cred_rp45);
        END LOOP;
        CLOSE c_rp45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rp45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rp46]
    BEGIN
        DECLARE v_pid_rp46 INTEGER DEFAULT 0;
        DECLARE v_lp_rp46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rp46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rp46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rp46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rp46 INTEGER DEFAULT 0;
        DECLARE c_rp46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp46 = 1;
        OPEN c_rp46;
        loop_rp46: LOOP
            FETCH c_rp46 INTO v_pid_rp46, v_lp_rp46, v_pp_rp46;
            IF v_done_rp46 = 1 THEN LEAVE loop_rp46; END IF;
            SET v_var_rp46 = v_var_rp46 + (COALESCE(v_lp_rp46,0) - COALESCE(v_pp_rp46,0));
            SET v_marg_rp46 = ERP_FN_MARGIN(v_pid_rp46);
        END LOOP;
        CLOSE c_rp46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rp46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rp47]
    BEGIN
        DECLARE v_inv_rp47 INTEGER DEFAULT 0;
        DECLARE v_amt_rp47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rp47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rp47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp47 INTEGER DEFAULT 0;
        DECLARE c_rp47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp47 = 1;
        OPEN c_rp47;
        loop_rp47: LOOP
            FETCH c_rp47 INTO v_inv_rp47, v_amt_rp47, v_alloc_rp47;
            IF v_done_rp47 = 1 THEN LEAVE loop_rp47; END IF;
            SET v_open_rp47 = v_open_rp47 + (v_amt_rp47 - v_alloc_rp47);
        END LOOP;
        CLOSE c_rp47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rp47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rp48]
    BEGIN
        DECLARE v_lvl_rp48 INTEGER DEFAULT 0;
        DECLARE v_dept_rp48 INTEGER DEFAULT 0;
        DECLARE v_head_rp48 INTEGER DEFAULT 0;
        DECLARE v_done_rp48 INTEGER DEFAULT 0;
        DECLARE c_rp48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp48 = 1;
        OPEN c_rp48;
        loop_rp48: LOOP
            FETCH c_rp48 INTO v_dept_rp48, v_lvl_rp48, v_head_rp48;
            IF v_done_rp48 = 1 THEN LEAVE loop_rp48; END IF;
        END LOOP;
        CLOSE c_rp48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rp48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rp48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rp49]
    BEGIN
        DECLARE v_sh_rp49 INTEGER DEFAULT 0;
        DECLARE v_car_rp49 INTEGER DEFAULT 0;
        DECLARE v_qty_rp49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rp49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rp49 INTEGER DEFAULT 0;
        DECLARE c_rp49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp49 = 1;
        OPEN c_rp49;
        loop_rp49: LOOP
            FETCH c_rp49 INTO v_sh_rp49, v_car_rp49, v_qty_rp49;
            IF v_done_rp49 = 1 THEN LEAVE loop_rp49; END IF;
            SET v_tot_rp49 = v_tot_rp49 + v_qty_rp49;
        END LOOP;
        CLOSE c_rp49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rp49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rp50]
    BEGIN
        DECLARE v_sql_rp50 VARCHAR(1000);
        DECLARE v_n_rp50 INTEGER DEFAULT 0;
        SET v_sql_rp50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rp50 FROM v_sql_rp50;
        EXECUTE st_rp50;
        SELECT COUNT(*) INTO v_n_rp50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rp50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rp51]
    BEGIN
        DECLARE v_key_rp51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rp51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rp51' AS VARCHAR(40)), v_key_rp51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rp52]
    BEGIN
        DECLARE v_so_rp52 INTEGER DEFAULT 0;
        DECLARE v_cust_rp52 INTEGER DEFAULT 0;
        DECLARE v_rk_rp52 INTEGER DEFAULT 0;
        DECLARE v_run_rp52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rp52 INTEGER DEFAULT 0;
        DECLARE c_rp52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rp52 = 1;
        OPEN c_rp52;
        loop_rp52: LOOP
            FETCH c_rp52 INTO v_so_rp52, v_cust_rp52, v_rk_rp52, v_run_rp52;
            IF v_done_rp52 = 1 THEN LEAVE loop_rp52; END IF;
        END LOOP;
        CLOSE c_rp52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rp52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rp52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rp53]
    BEGIN
        DECLARE v_hi_rp53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rp53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rp53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rp54]
    BEGIN
        DECLARE v_pairs_rp54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rp54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rp54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rp55]
    BEGIN
        DECLARE v_rows_rp55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rp55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rp55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rp55 FROM SESSION.TMP_rp55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rp55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rp56]
    BEGIN
        DECLARE v_rc_rp56 INTEGER DEFAULT 0;
        DECLARE v_band_rp56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rp56 = ROW_COUNT;
        SET v_band_rp56 = CASE
                            WHEN v_rc_rp56 = 0 THEN 'NONE'
                            WHEN v_rc_rp56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rp56, 'COUNT', 'band=' || v_band_rp56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rp57]
    BEGIN
        DECLARE v_i_rp57 INTEGER DEFAULT 0;
        SAVEPOINT sp_rp57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rp57 < 4 DO
            SET v_i_rp57 = v_i_rp57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rp57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rp57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rp57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_RESERVE_STOCK(IN p_product_id INTEGER, IN p_qty DECIMAL(16,4), IN p_so_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_avail DECIMAL(16,4) DEFAULT 0;
    DECLARE v_inv_id INTEGER DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('RESERVE', p_product_id, 'ERROR', 'reserve failed');
    END;
    SET v_avail = ERP_FN_INVENTORY_ONHAND(p_product_id);
    SELECT MIN(id) INTO v_inv_id FROM ERP_INVENTORY WHERE product_id = p_product_id;
    IF v_avail >= p_qty THEN
        UPDATE ERP_INVENTORY SET reserved = reserved + p_qty WHERE id = v_inv_id;
    ELSE
        CALL ERP_USP_REPLENISH_STOCK(p_product_id, p_so_id);
    END IF;
    CALL ERP_USP_AUDIT('RESERVE', p_product_id, 'DONE', 'reservation processed');
    -- order/customer/country/currency revenue scan [rs00]
    BEGIN
        DECLARE v_so_rs00 INTEGER DEFAULT 0;
        DECLARE v_cust_rs00 INTEGER DEFAULT 0;
        DECLARE v_ctry_rs00 INTEGER DEFAULT 0;
        DECLARE v_ccy_rs00 INTEGER DEFAULT 0;
        DECLARE v_sub_rs00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rs00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rs00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rs00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rs00 INTEGER DEFAULT 0;
        DECLARE v_done_rs00 INTEGER DEFAULT 0;
        DECLARE c_rs00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs00 = 1;
        OPEN c_rs00;
        loop_rs00: LOOP
            FETCH c_rs00 INTO v_so_rs00, v_cust_rs00, v_ctry_rs00, v_ccy_rs00, v_sub_rs00;
            IF v_done_rs00 = 1 THEN LEAVE loop_rs00; END IF;
            SET v_tax_rs00 = ERP_FN_TAX(v_ctry_rs00, v_sub_rs00);
            SET v_fx_rs00 = ERP_FN_FX_CONVERT(v_ccy_rs00, 1, v_sub_rs00 + v_tax_rs00);
            SET v_acc_rs00 = v_acc_rs00 + v_fx_rs00;
            SET v_cnt_rs00 = v_cnt_rs00 + 1;
        END LOOP;
        CLOSE c_rs00;
        IF v_cnt_rs00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rs00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rs00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rs01]
    BEGIN
        DECLARE v_pid_rs01 INTEGER DEFAULT 0;
        DECLARE v_oh_rs01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rs01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rs01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rs01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rs01 INTEGER DEFAULT 0;
        DECLARE c_rs01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs01 = 1;
        OPEN c_rs01;
        loop_rs01: LOOP
            FETCH c_rs01 INTO v_pid_rs01, v_oh_rs01, v_cost_rs01;
            IF v_done_rs01 = 1 THEN LEAVE loop_rs01; END IF;
            SET v_avail_rs01 = ERP_FN_INVENTORY_ONHAND(v_pid_rs01);
            SET v_val_rs01 = v_val_rs01 + CAST(COALESCE(v_oh_rs01,0) * COALESCE(v_cost_rs01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rs01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rs01;
        END LOOP;
        CLOSE c_rs01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rs01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rs02]
    BEGIN
        DECLARE v_prod_rs02 INTEGER DEFAULT 0;
        DECLARE v_rm_rs02 INTEGER DEFAULT 0;
        DECLARE v_supp_rs02 INTEGER DEFAULT 0;
        DECLARE v_qper_rs02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rs02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rs02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rs02 INTEGER DEFAULT 0;
        DECLARE c_rs02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs02 = 1;
        OPEN c_rs02;
        loop_rs02: LOOP
            FETCH c_rs02 INTO v_prod_rs02, v_rm_rs02, v_supp_rs02, v_qper_rs02, v_uc_rs02;
            IF v_done_rs02 = 1 THEN LEAVE loop_rs02; END IF;
            SET v_roll_rs02 = v_roll_rs02 + COALESCE(v_qper_rs02,0) * COALESCE(v_uc_rs02,0);
        END LOOP;
        CLOSE c_rs02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rs02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rs03]
    BEGIN
        DECLARE v_acct_rs03 INTEGER DEFAULT 0;
        DECLARE v_deb_rs03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rs03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rs03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs03 INTEGER DEFAULT 0;
        DECLARE c_rs03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs03 = 1;
        OPEN c_rs03;
        loop_rs03: LOOP
            FETCH c_rs03 INTO v_acct_rs03, v_deb_rs03, v_cred_rs03;
            IF v_done_rs03 = 1 THEN LEAVE loop_rs03; END IF;
            SET v_net_rs03 = v_net_rs03 + (v_deb_rs03 - v_cred_rs03);
        END LOOP;
        CLOSE c_rs03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rs03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rs04]
    BEGIN
        DECLARE v_pid_rs04 INTEGER DEFAULT 0;
        DECLARE v_lp_rs04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rs04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rs04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rs04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rs04 INTEGER DEFAULT 0;
        DECLARE c_rs04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs04 = 1;
        OPEN c_rs04;
        loop_rs04: LOOP
            FETCH c_rs04 INTO v_pid_rs04, v_lp_rs04, v_pp_rs04;
            IF v_done_rs04 = 1 THEN LEAVE loop_rs04; END IF;
            SET v_var_rs04 = v_var_rs04 + (COALESCE(v_lp_rs04,0) - COALESCE(v_pp_rs04,0));
            SET v_marg_rs04 = ERP_FN_MARGIN(v_pid_rs04);
        END LOOP;
        CLOSE c_rs04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rs04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rs05]
    BEGIN
        DECLARE v_inv_rs05 INTEGER DEFAULT 0;
        DECLARE v_amt_rs05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rs05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rs05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs05 INTEGER DEFAULT 0;
        DECLARE c_rs05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs05 = 1;
        OPEN c_rs05;
        loop_rs05: LOOP
            FETCH c_rs05 INTO v_inv_rs05, v_amt_rs05, v_alloc_rs05;
            IF v_done_rs05 = 1 THEN LEAVE loop_rs05; END IF;
            SET v_open_rs05 = v_open_rs05 + (v_amt_rs05 - v_alloc_rs05);
        END LOOP;
        CLOSE c_rs05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rs05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rs06]
    BEGIN
        DECLARE v_lvl_rs06 INTEGER DEFAULT 0;
        DECLARE v_dept_rs06 INTEGER DEFAULT 0;
        DECLARE v_head_rs06 INTEGER DEFAULT 0;
        DECLARE v_done_rs06 INTEGER DEFAULT 0;
        DECLARE c_rs06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs06 = 1;
        OPEN c_rs06;
        loop_rs06: LOOP
            FETCH c_rs06 INTO v_dept_rs06, v_lvl_rs06, v_head_rs06;
            IF v_done_rs06 = 1 THEN LEAVE loop_rs06; END IF;
        END LOOP;
        CLOSE c_rs06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rs06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rs06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rs07]
    BEGIN
        DECLARE v_sh_rs07 INTEGER DEFAULT 0;
        DECLARE v_car_rs07 INTEGER DEFAULT 0;
        DECLARE v_qty_rs07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rs07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rs07 INTEGER DEFAULT 0;
        DECLARE c_rs07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs07 = 1;
        OPEN c_rs07;
        loop_rs07: LOOP
            FETCH c_rs07 INTO v_sh_rs07, v_car_rs07, v_qty_rs07;
            IF v_done_rs07 = 1 THEN LEAVE loop_rs07; END IF;
            SET v_tot_rs07 = v_tot_rs07 + v_qty_rs07;
        END LOOP;
        CLOSE c_rs07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rs07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rs08]
    BEGIN
        DECLARE v_sql_rs08 VARCHAR(1000);
        DECLARE v_n_rs08 INTEGER DEFAULT 0;
        SET v_sql_rs08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rs08 FROM v_sql_rs08;
        EXECUTE st_rs08;
        SELECT COUNT(*) INTO v_n_rs08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rs08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rs09]
    BEGIN
        DECLARE v_key_rs09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rs09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rs09' AS VARCHAR(40)), v_key_rs09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rs10]
    BEGIN
        DECLARE v_so_rs10 INTEGER DEFAULT 0;
        DECLARE v_cust_rs10 INTEGER DEFAULT 0;
        DECLARE v_rk_rs10 INTEGER DEFAULT 0;
        DECLARE v_run_rs10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs10 INTEGER DEFAULT 0;
        DECLARE c_rs10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs10 = 1;
        OPEN c_rs10;
        loop_rs10: LOOP
            FETCH c_rs10 INTO v_so_rs10, v_cust_rs10, v_rk_rs10, v_run_rs10;
            IF v_done_rs10 = 1 THEN LEAVE loop_rs10; END IF;
        END LOOP;
        CLOSE c_rs10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rs10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rs10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rs11]
    BEGIN
        DECLARE v_hi_rs11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rs11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rs11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rs12]
    BEGIN
        DECLARE v_pairs_rs12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rs12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rs12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rs13]
    BEGIN
        DECLARE v_rows_rs13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rs13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rs13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rs13 FROM SESSION.TMP_rs13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rs13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rs14]
    BEGIN
        DECLARE v_rc_rs14 INTEGER DEFAULT 0;
        DECLARE v_band_rs14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rs14 = ROW_COUNT;
        SET v_band_rs14 = CASE
                            WHEN v_rc_rs14 = 0 THEN 'NONE'
                            WHEN v_rc_rs14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rs14, 'COUNT', 'band=' || v_band_rs14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rs15]
    BEGIN
        DECLARE v_i_rs15 INTEGER DEFAULT 0;
        SAVEPOINT sp_rs15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rs15 < 4 DO
            SET v_i_rs15 = v_i_rs15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rs15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rs15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rs15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rs16]
    BEGIN
        DECLARE v_j_rs16 INTEGER DEFAULT 0;
        DECLARE v_sum_rs16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rs16 = v_j_rs16 + 1;
        UNTIL v_j_rs16 >= 3 END REPEAT;
        FOR row_rs16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rs16 = v_sum_rs16 + COALESCE(row_rs16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rs16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rs16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rs17]
    BEGIN
        DECLARE v_n_rs17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rs17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rs17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rs18]
    BEGIN
        DECLARE v_levels_rs18 INTEGER DEFAULT 0;
        DECLARE c_rs18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rs18 = 0;
        OPEN c_rs18;
        FETCH c_rs18 INTO v_levels_rs18;
        CLOSE c_rs18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rs18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rs19]
    BEGIN
        DECLARE v_sql_rs19 VARCHAR(1000);
        DECLARE v_n_rs19 INTEGER DEFAULT 0;
        SET v_sql_rs19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rs19 FROM v_sql_rs19;
        EXECUTE st_rs19;
        SELECT COUNT(*) INTO v_n_rs19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rs19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rs20]
    BEGIN
        DECLARE v_key_rs20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rs20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rs20' AS VARCHAR(40)), v_key_rs20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rs21]
    BEGIN
        DECLARE v_so_rs21 INTEGER DEFAULT 0;
        DECLARE v_cust_rs21 INTEGER DEFAULT 0;
        DECLARE v_ctry_rs21 INTEGER DEFAULT 0;
        DECLARE v_ccy_rs21 INTEGER DEFAULT 0;
        DECLARE v_sub_rs21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rs21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rs21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rs21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rs21 INTEGER DEFAULT 0;
        DECLARE v_done_rs21 INTEGER DEFAULT 0;
        DECLARE c_rs21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs21 = 1;
        OPEN c_rs21;
        loop_rs21: LOOP
            FETCH c_rs21 INTO v_so_rs21, v_cust_rs21, v_ctry_rs21, v_ccy_rs21, v_sub_rs21;
            IF v_done_rs21 = 1 THEN LEAVE loop_rs21; END IF;
            SET v_tax_rs21 = ERP_FN_TAX(v_ctry_rs21, v_sub_rs21);
            SET v_fx_rs21 = ERP_FN_FX_CONVERT(v_ccy_rs21, 1, v_sub_rs21 + v_tax_rs21);
            SET v_acc_rs21 = v_acc_rs21 + v_fx_rs21;
            SET v_cnt_rs21 = v_cnt_rs21 + 1;
        END LOOP;
        CLOSE c_rs21;
        IF v_cnt_rs21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rs21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rs21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rs22]
    BEGIN
        DECLARE v_pid_rs22 INTEGER DEFAULT 0;
        DECLARE v_oh_rs22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rs22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rs22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rs22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rs22 INTEGER DEFAULT 0;
        DECLARE c_rs22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs22 = 1;
        OPEN c_rs22;
        loop_rs22: LOOP
            FETCH c_rs22 INTO v_pid_rs22, v_oh_rs22, v_cost_rs22;
            IF v_done_rs22 = 1 THEN LEAVE loop_rs22; END IF;
            SET v_avail_rs22 = ERP_FN_INVENTORY_ONHAND(v_pid_rs22);
            SET v_val_rs22 = v_val_rs22 + CAST(COALESCE(v_oh_rs22,0) * COALESCE(v_cost_rs22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rs22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rs22;
        END LOOP;
        CLOSE c_rs22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rs22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rs23]
    BEGIN
        DECLARE v_prod_rs23 INTEGER DEFAULT 0;
        DECLARE v_rm_rs23 INTEGER DEFAULT 0;
        DECLARE v_supp_rs23 INTEGER DEFAULT 0;
        DECLARE v_qper_rs23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rs23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rs23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rs23 INTEGER DEFAULT 0;
        DECLARE c_rs23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs23 = 1;
        OPEN c_rs23;
        loop_rs23: LOOP
            FETCH c_rs23 INTO v_prod_rs23, v_rm_rs23, v_supp_rs23, v_qper_rs23, v_uc_rs23;
            IF v_done_rs23 = 1 THEN LEAVE loop_rs23; END IF;
            SET v_roll_rs23 = v_roll_rs23 + COALESCE(v_qper_rs23,0) * COALESCE(v_uc_rs23,0);
        END LOOP;
        CLOSE c_rs23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rs23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rs24]
    BEGIN
        DECLARE v_acct_rs24 INTEGER DEFAULT 0;
        DECLARE v_deb_rs24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rs24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rs24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs24 INTEGER DEFAULT 0;
        DECLARE c_rs24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs24 = 1;
        OPEN c_rs24;
        loop_rs24: LOOP
            FETCH c_rs24 INTO v_acct_rs24, v_deb_rs24, v_cred_rs24;
            IF v_done_rs24 = 1 THEN LEAVE loop_rs24; END IF;
            SET v_net_rs24 = v_net_rs24 + (v_deb_rs24 - v_cred_rs24);
        END LOOP;
        CLOSE c_rs24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rs24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rs25]
    BEGIN
        DECLARE v_pid_rs25 INTEGER DEFAULT 0;
        DECLARE v_lp_rs25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rs25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rs25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rs25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rs25 INTEGER DEFAULT 0;
        DECLARE c_rs25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs25 = 1;
        OPEN c_rs25;
        loop_rs25: LOOP
            FETCH c_rs25 INTO v_pid_rs25, v_lp_rs25, v_pp_rs25;
            IF v_done_rs25 = 1 THEN LEAVE loop_rs25; END IF;
            SET v_var_rs25 = v_var_rs25 + (COALESCE(v_lp_rs25,0) - COALESCE(v_pp_rs25,0));
            SET v_marg_rs25 = ERP_FN_MARGIN(v_pid_rs25);
        END LOOP;
        CLOSE c_rs25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rs25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rs26]
    BEGIN
        DECLARE v_inv_rs26 INTEGER DEFAULT 0;
        DECLARE v_amt_rs26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rs26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rs26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs26 INTEGER DEFAULT 0;
        DECLARE c_rs26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs26 = 1;
        OPEN c_rs26;
        loop_rs26: LOOP
            FETCH c_rs26 INTO v_inv_rs26, v_amt_rs26, v_alloc_rs26;
            IF v_done_rs26 = 1 THEN LEAVE loop_rs26; END IF;
            SET v_open_rs26 = v_open_rs26 + (v_amt_rs26 - v_alloc_rs26);
        END LOOP;
        CLOSE c_rs26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rs26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rs27]
    BEGIN
        DECLARE v_lvl_rs27 INTEGER DEFAULT 0;
        DECLARE v_dept_rs27 INTEGER DEFAULT 0;
        DECLARE v_head_rs27 INTEGER DEFAULT 0;
        DECLARE v_done_rs27 INTEGER DEFAULT 0;
        DECLARE c_rs27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs27 = 1;
        OPEN c_rs27;
        loop_rs27: LOOP
            FETCH c_rs27 INTO v_dept_rs27, v_lvl_rs27, v_head_rs27;
            IF v_done_rs27 = 1 THEN LEAVE loop_rs27; END IF;
        END LOOP;
        CLOSE c_rs27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rs27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rs27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rs28]
    BEGIN
        DECLARE v_sh_rs28 INTEGER DEFAULT 0;
        DECLARE v_car_rs28 INTEGER DEFAULT 0;
        DECLARE v_qty_rs28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rs28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rs28 INTEGER DEFAULT 0;
        DECLARE c_rs28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs28 = 1;
        OPEN c_rs28;
        loop_rs28: LOOP
            FETCH c_rs28 INTO v_sh_rs28, v_car_rs28, v_qty_rs28;
            IF v_done_rs28 = 1 THEN LEAVE loop_rs28; END IF;
            SET v_tot_rs28 = v_tot_rs28 + v_qty_rs28;
        END LOOP;
        CLOSE c_rs28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rs28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rs29]
    BEGIN
        DECLARE v_sql_rs29 VARCHAR(1000);
        DECLARE v_n_rs29 INTEGER DEFAULT 0;
        SET v_sql_rs29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rs29 FROM v_sql_rs29;
        EXECUTE st_rs29;
        SELECT COUNT(*) INTO v_n_rs29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rs29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rs30]
    BEGIN
        DECLARE v_key_rs30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rs30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rs30' AS VARCHAR(40)), v_key_rs30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rs31]
    BEGIN
        DECLARE v_so_rs31 INTEGER DEFAULT 0;
        DECLARE v_cust_rs31 INTEGER DEFAULT 0;
        DECLARE v_rk_rs31 INTEGER DEFAULT 0;
        DECLARE v_run_rs31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs31 INTEGER DEFAULT 0;
        DECLARE c_rs31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs31 = 1;
        OPEN c_rs31;
        loop_rs31: LOOP
            FETCH c_rs31 INTO v_so_rs31, v_cust_rs31, v_rk_rs31, v_run_rs31;
            IF v_done_rs31 = 1 THEN LEAVE loop_rs31; END IF;
        END LOOP;
        CLOSE c_rs31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rs31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rs31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rs32]
    BEGIN
        DECLARE v_hi_rs32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rs32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rs32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rs33]
    BEGIN
        DECLARE v_pairs_rs33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rs33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rs33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rs34]
    BEGIN
        DECLARE v_rows_rs34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rs34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rs34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rs34 FROM SESSION.TMP_rs34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rs34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rs35]
    BEGIN
        DECLARE v_rc_rs35 INTEGER DEFAULT 0;
        DECLARE v_band_rs35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rs35 = ROW_COUNT;
        SET v_band_rs35 = CASE
                            WHEN v_rc_rs35 = 0 THEN 'NONE'
                            WHEN v_rc_rs35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rs35, 'COUNT', 'band=' || v_band_rs35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rs36]
    BEGIN
        DECLARE v_i_rs36 INTEGER DEFAULT 0;
        SAVEPOINT sp_rs36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rs36 < 4 DO
            SET v_i_rs36 = v_i_rs36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rs36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rs36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rs36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rs37]
    BEGIN
        DECLARE v_j_rs37 INTEGER DEFAULT 0;
        DECLARE v_sum_rs37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rs37 = v_j_rs37 + 1;
        UNTIL v_j_rs37 >= 3 END REPEAT;
        FOR row_rs37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rs37 = v_sum_rs37 + COALESCE(row_rs37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rs37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rs37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rs38]
    BEGIN
        DECLARE v_n_rs38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rs38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rs38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rs39]
    BEGIN
        DECLARE v_levels_rs39 INTEGER DEFAULT 0;
        DECLARE c_rs39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rs39 = 0;
        OPEN c_rs39;
        FETCH c_rs39 INTO v_levels_rs39;
        CLOSE c_rs39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rs39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rs40]
    BEGIN
        DECLARE v_sql_rs40 VARCHAR(1000);
        DECLARE v_n_rs40 INTEGER DEFAULT 0;
        SET v_sql_rs40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rs40 FROM v_sql_rs40;
        EXECUTE st_rs40;
        SELECT COUNT(*) INTO v_n_rs40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rs40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rs41]
    BEGIN
        DECLARE v_key_rs41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rs41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rs41' AS VARCHAR(40)), v_key_rs41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rs42]
    BEGIN
        DECLARE v_so_rs42 INTEGER DEFAULT 0;
        DECLARE v_cust_rs42 INTEGER DEFAULT 0;
        DECLARE v_ctry_rs42 INTEGER DEFAULT 0;
        DECLARE v_ccy_rs42 INTEGER DEFAULT 0;
        DECLARE v_sub_rs42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rs42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rs42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rs42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rs42 INTEGER DEFAULT 0;
        DECLARE v_done_rs42 INTEGER DEFAULT 0;
        DECLARE c_rs42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs42 = 1;
        OPEN c_rs42;
        loop_rs42: LOOP
            FETCH c_rs42 INTO v_so_rs42, v_cust_rs42, v_ctry_rs42, v_ccy_rs42, v_sub_rs42;
            IF v_done_rs42 = 1 THEN LEAVE loop_rs42; END IF;
            SET v_tax_rs42 = ERP_FN_TAX(v_ctry_rs42, v_sub_rs42);
            SET v_fx_rs42 = ERP_FN_FX_CONVERT(v_ccy_rs42, 1, v_sub_rs42 + v_tax_rs42);
            SET v_acc_rs42 = v_acc_rs42 + v_fx_rs42;
            SET v_cnt_rs42 = v_cnt_rs42 + 1;
        END LOOP;
        CLOSE c_rs42;
        IF v_cnt_rs42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rs42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rs42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rs43]
    BEGIN
        DECLARE v_pid_rs43 INTEGER DEFAULT 0;
        DECLARE v_oh_rs43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rs43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rs43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rs43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rs43 INTEGER DEFAULT 0;
        DECLARE c_rs43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs43 = 1;
        OPEN c_rs43;
        loop_rs43: LOOP
            FETCH c_rs43 INTO v_pid_rs43, v_oh_rs43, v_cost_rs43;
            IF v_done_rs43 = 1 THEN LEAVE loop_rs43; END IF;
            SET v_avail_rs43 = ERP_FN_INVENTORY_ONHAND(v_pid_rs43);
            SET v_val_rs43 = v_val_rs43 + CAST(COALESCE(v_oh_rs43,0) * COALESCE(v_cost_rs43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rs43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rs43;
        END LOOP;
        CLOSE c_rs43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rs43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rs44]
    BEGIN
        DECLARE v_prod_rs44 INTEGER DEFAULT 0;
        DECLARE v_rm_rs44 INTEGER DEFAULT 0;
        DECLARE v_supp_rs44 INTEGER DEFAULT 0;
        DECLARE v_qper_rs44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rs44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rs44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rs44 INTEGER DEFAULT 0;
        DECLARE c_rs44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs44 = 1;
        OPEN c_rs44;
        loop_rs44: LOOP
            FETCH c_rs44 INTO v_prod_rs44, v_rm_rs44, v_supp_rs44, v_qper_rs44, v_uc_rs44;
            IF v_done_rs44 = 1 THEN LEAVE loop_rs44; END IF;
            SET v_roll_rs44 = v_roll_rs44 + COALESCE(v_qper_rs44,0) * COALESCE(v_uc_rs44,0);
        END LOOP;
        CLOSE c_rs44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rs44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rs45]
    BEGIN
        DECLARE v_acct_rs45 INTEGER DEFAULT 0;
        DECLARE v_deb_rs45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rs45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rs45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs45 INTEGER DEFAULT 0;
        DECLARE c_rs45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs45 = 1;
        OPEN c_rs45;
        loop_rs45: LOOP
            FETCH c_rs45 INTO v_acct_rs45, v_deb_rs45, v_cred_rs45;
            IF v_done_rs45 = 1 THEN LEAVE loop_rs45; END IF;
            SET v_net_rs45 = v_net_rs45 + (v_deb_rs45 - v_cred_rs45);
        END LOOP;
        CLOSE c_rs45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rs45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rs46]
    BEGIN
        DECLARE v_pid_rs46 INTEGER DEFAULT 0;
        DECLARE v_lp_rs46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rs46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rs46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rs46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rs46 INTEGER DEFAULT 0;
        DECLARE c_rs46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs46 = 1;
        OPEN c_rs46;
        loop_rs46: LOOP
            FETCH c_rs46 INTO v_pid_rs46, v_lp_rs46, v_pp_rs46;
            IF v_done_rs46 = 1 THEN LEAVE loop_rs46; END IF;
            SET v_var_rs46 = v_var_rs46 + (COALESCE(v_lp_rs46,0) - COALESCE(v_pp_rs46,0));
            SET v_marg_rs46 = ERP_FN_MARGIN(v_pid_rs46);
        END LOOP;
        CLOSE c_rs46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rs46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rs47]
    BEGIN
        DECLARE v_inv_rs47 INTEGER DEFAULT 0;
        DECLARE v_amt_rs47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rs47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rs47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs47 INTEGER DEFAULT 0;
        DECLARE c_rs47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs47 = 1;
        OPEN c_rs47;
        loop_rs47: LOOP
            FETCH c_rs47 INTO v_inv_rs47, v_amt_rs47, v_alloc_rs47;
            IF v_done_rs47 = 1 THEN LEAVE loop_rs47; END IF;
            SET v_open_rs47 = v_open_rs47 + (v_amt_rs47 - v_alloc_rs47);
        END LOOP;
        CLOSE c_rs47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rs47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rs48]
    BEGIN
        DECLARE v_lvl_rs48 INTEGER DEFAULT 0;
        DECLARE v_dept_rs48 INTEGER DEFAULT 0;
        DECLARE v_head_rs48 INTEGER DEFAULT 0;
        DECLARE v_done_rs48 INTEGER DEFAULT 0;
        DECLARE c_rs48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs48 = 1;
        OPEN c_rs48;
        loop_rs48: LOOP
            FETCH c_rs48 INTO v_dept_rs48, v_lvl_rs48, v_head_rs48;
            IF v_done_rs48 = 1 THEN LEAVE loop_rs48; END IF;
        END LOOP;
        CLOSE c_rs48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rs48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rs48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rs49]
    BEGIN
        DECLARE v_sh_rs49 INTEGER DEFAULT 0;
        DECLARE v_car_rs49 INTEGER DEFAULT 0;
        DECLARE v_qty_rs49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rs49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rs49 INTEGER DEFAULT 0;
        DECLARE c_rs49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs49 = 1;
        OPEN c_rs49;
        loop_rs49: LOOP
            FETCH c_rs49 INTO v_sh_rs49, v_car_rs49, v_qty_rs49;
            IF v_done_rs49 = 1 THEN LEAVE loop_rs49; END IF;
            SET v_tot_rs49 = v_tot_rs49 + v_qty_rs49;
        END LOOP;
        CLOSE c_rs49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rs49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rs50]
    BEGIN
        DECLARE v_sql_rs50 VARCHAR(1000);
        DECLARE v_n_rs50 INTEGER DEFAULT 0;
        SET v_sql_rs50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rs50 FROM v_sql_rs50;
        EXECUTE st_rs50;
        SELECT COUNT(*) INTO v_n_rs50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rs50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rs51]
    BEGIN
        DECLARE v_key_rs51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rs51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rs51' AS VARCHAR(40)), v_key_rs51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rs52]
    BEGIN
        DECLARE v_so_rs52 INTEGER DEFAULT 0;
        DECLARE v_cust_rs52 INTEGER DEFAULT 0;
        DECLARE v_rk_rs52 INTEGER DEFAULT 0;
        DECLARE v_run_rs52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rs52 INTEGER DEFAULT 0;
        DECLARE c_rs52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rs52 = 1;
        OPEN c_rs52;
        loop_rs52: LOOP
            FETCH c_rs52 INTO v_so_rs52, v_cust_rs52, v_rk_rs52, v_run_rs52;
            IF v_done_rs52 = 1 THEN LEAVE loop_rs52; END IF;
        END LOOP;
        CLOSE c_rs52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rs52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rs52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rs53]
    BEGIN
        DECLARE v_hi_rs53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rs53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rs53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rs54]
    BEGIN
        DECLARE v_pairs_rs54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rs54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rs54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rs55]
    BEGIN
        DECLARE v_rows_rs55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rs55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rs55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rs55 FROM SESSION.TMP_rs55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rs55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rs56]
    BEGIN
        DECLARE v_rc_rs56 INTEGER DEFAULT 0;
        DECLARE v_band_rs56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rs56 = ROW_COUNT;
        SET v_band_rs56 = CASE
                            WHEN v_rc_rs56 = 0 THEN 'NONE'
                            WHEN v_rc_rs56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rs56, 'COUNT', 'band=' || v_band_rs56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rs57]
    BEGIN
        DECLARE v_i_rs57 INTEGER DEFAULT 0;
        SAVEPOINT sp_rs57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rs57 < 4 DO
            SET v_i_rs57 = v_i_rs57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rs57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rs57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rs57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_ALLOCATE_INVENTORY(IN p_so_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_pid INTEGER DEFAULT 0;
    DECLARE v_qty DECIMAL(16,4) DEFAULT 0;
    DECLARE v_done INTEGER DEFAULT 0;
    DECLARE c_lines CURSOR FOR
        SELECT sol.product_id, sol.qty FROM ERP_SALES_ORDER_LINE sol
        WHERE sol.so_id = p_so_id ORDER BY sol.id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('ALLOCATE', p_so_id, 'ERROR', 'allocate failed');
    END;
    OPEN c_lines;
    alloc_loop: LOOP
        FETCH c_lines INTO v_pid, v_qty;
        IF v_done = 1 THEN LEAVE alloc_loop; END IF;
        CALL ERP_USP_RESERVE_STOCK(v_pid, v_qty, p_so_id);
    END LOOP;
    CLOSE c_lines;
    CALL ERP_USP_AUDIT('ALLOCATE', p_so_id, 'DONE', 'inventory allocated');
    -- order/customer/country/currency revenue scan [ai00]
    BEGIN
        DECLARE v_so_ai00 INTEGER DEFAULT 0;
        DECLARE v_cust_ai00 INTEGER DEFAULT 0;
        DECLARE v_ctry_ai00 INTEGER DEFAULT 0;
        DECLARE v_ccy_ai00 INTEGER DEFAULT 0;
        DECLARE v_sub_ai00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ai00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ai00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ai00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ai00 INTEGER DEFAULT 0;
        DECLARE v_done_ai00 INTEGER DEFAULT 0;
        DECLARE c_ai00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai00 = 1;
        OPEN c_ai00;
        loop_ai00: LOOP
            FETCH c_ai00 INTO v_so_ai00, v_cust_ai00, v_ctry_ai00, v_ccy_ai00, v_sub_ai00;
            IF v_done_ai00 = 1 THEN LEAVE loop_ai00; END IF;
            SET v_tax_ai00 = ERP_FN_TAX(v_ctry_ai00, v_sub_ai00);
            SET v_fx_ai00 = ERP_FN_FX_CONVERT(v_ccy_ai00, 1, v_sub_ai00 + v_tax_ai00);
            SET v_acc_ai00 = v_acc_ai00 + v_fx_ai00;
            SET v_cnt_ai00 = v_cnt_ai00 + 1;
        END LOOP;
        CLOSE c_ai00;
        IF v_cnt_ai00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ai00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ai00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ai01]
    BEGIN
        DECLARE v_pid_ai01 INTEGER DEFAULT 0;
        DECLARE v_oh_ai01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ai01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ai01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ai01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ai01 INTEGER DEFAULT 0;
        DECLARE c_ai01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai01 = 1;
        OPEN c_ai01;
        loop_ai01: LOOP
            FETCH c_ai01 INTO v_pid_ai01, v_oh_ai01, v_cost_ai01;
            IF v_done_ai01 = 1 THEN LEAVE loop_ai01; END IF;
            SET v_avail_ai01 = ERP_FN_INVENTORY_ONHAND(v_pid_ai01);
            SET v_val_ai01 = v_val_ai01 + CAST(COALESCE(v_oh_ai01,0) * COALESCE(v_cost_ai01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ai01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ai01;
        END LOOP;
        CLOSE c_ai01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ai01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ai02]
    BEGIN
        DECLARE v_prod_ai02 INTEGER DEFAULT 0;
        DECLARE v_rm_ai02 INTEGER DEFAULT 0;
        DECLARE v_supp_ai02 INTEGER DEFAULT 0;
        DECLARE v_qper_ai02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ai02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ai02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ai02 INTEGER DEFAULT 0;
        DECLARE c_ai02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai02 = 1;
        OPEN c_ai02;
        loop_ai02: LOOP
            FETCH c_ai02 INTO v_prod_ai02, v_rm_ai02, v_supp_ai02, v_qper_ai02, v_uc_ai02;
            IF v_done_ai02 = 1 THEN LEAVE loop_ai02; END IF;
            SET v_roll_ai02 = v_roll_ai02 + COALESCE(v_qper_ai02,0) * COALESCE(v_uc_ai02,0);
        END LOOP;
        CLOSE c_ai02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ai02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ai03]
    BEGIN
        DECLARE v_acct_ai03 INTEGER DEFAULT 0;
        DECLARE v_deb_ai03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ai03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ai03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai03 INTEGER DEFAULT 0;
        DECLARE c_ai03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai03 = 1;
        OPEN c_ai03;
        loop_ai03: LOOP
            FETCH c_ai03 INTO v_acct_ai03, v_deb_ai03, v_cred_ai03;
            IF v_done_ai03 = 1 THEN LEAVE loop_ai03; END IF;
            SET v_net_ai03 = v_net_ai03 + (v_deb_ai03 - v_cred_ai03);
        END LOOP;
        CLOSE c_ai03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ai03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ai04]
    BEGIN
        DECLARE v_pid_ai04 INTEGER DEFAULT 0;
        DECLARE v_lp_ai04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ai04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ai04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ai04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ai04 INTEGER DEFAULT 0;
        DECLARE c_ai04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai04 = 1;
        OPEN c_ai04;
        loop_ai04: LOOP
            FETCH c_ai04 INTO v_pid_ai04, v_lp_ai04, v_pp_ai04;
            IF v_done_ai04 = 1 THEN LEAVE loop_ai04; END IF;
            SET v_var_ai04 = v_var_ai04 + (COALESCE(v_lp_ai04,0) - COALESCE(v_pp_ai04,0));
            SET v_marg_ai04 = ERP_FN_MARGIN(v_pid_ai04);
        END LOOP;
        CLOSE c_ai04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ai04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ai05]
    BEGIN
        DECLARE v_inv_ai05 INTEGER DEFAULT 0;
        DECLARE v_amt_ai05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ai05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ai05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai05 INTEGER DEFAULT 0;
        DECLARE c_ai05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai05 = 1;
        OPEN c_ai05;
        loop_ai05: LOOP
            FETCH c_ai05 INTO v_inv_ai05, v_amt_ai05, v_alloc_ai05;
            IF v_done_ai05 = 1 THEN LEAVE loop_ai05; END IF;
            SET v_open_ai05 = v_open_ai05 + (v_amt_ai05 - v_alloc_ai05);
        END LOOP;
        CLOSE c_ai05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ai05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ai06]
    BEGIN
        DECLARE v_lvl_ai06 INTEGER DEFAULT 0;
        DECLARE v_dept_ai06 INTEGER DEFAULT 0;
        DECLARE v_head_ai06 INTEGER DEFAULT 0;
        DECLARE v_done_ai06 INTEGER DEFAULT 0;
        DECLARE c_ai06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai06 = 1;
        OPEN c_ai06;
        loop_ai06: LOOP
            FETCH c_ai06 INTO v_dept_ai06, v_lvl_ai06, v_head_ai06;
            IF v_done_ai06 = 1 THEN LEAVE loop_ai06; END IF;
        END LOOP;
        CLOSE c_ai06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ai06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ai06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ai07]
    BEGIN
        DECLARE v_sh_ai07 INTEGER DEFAULT 0;
        DECLARE v_car_ai07 INTEGER DEFAULT 0;
        DECLARE v_qty_ai07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ai07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ai07 INTEGER DEFAULT 0;
        DECLARE c_ai07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai07 = 1;
        OPEN c_ai07;
        loop_ai07: LOOP
            FETCH c_ai07 INTO v_sh_ai07, v_car_ai07, v_qty_ai07;
            IF v_done_ai07 = 1 THEN LEAVE loop_ai07; END IF;
            SET v_tot_ai07 = v_tot_ai07 + v_qty_ai07;
        END LOOP;
        CLOSE c_ai07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ai07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ai08]
    BEGIN
        DECLARE v_sql_ai08 VARCHAR(1000);
        DECLARE v_n_ai08 INTEGER DEFAULT 0;
        SET v_sql_ai08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ai08 FROM v_sql_ai08;
        EXECUTE st_ai08;
        SELECT COUNT(*) INTO v_n_ai08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ai08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ai09]
    BEGIN
        DECLARE v_key_ai09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ai09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ai09' AS VARCHAR(40)), v_key_ai09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ai10]
    BEGIN
        DECLARE v_so_ai10 INTEGER DEFAULT 0;
        DECLARE v_cust_ai10 INTEGER DEFAULT 0;
        DECLARE v_rk_ai10 INTEGER DEFAULT 0;
        DECLARE v_run_ai10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai10 INTEGER DEFAULT 0;
        DECLARE c_ai10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai10 = 1;
        OPEN c_ai10;
        loop_ai10: LOOP
            FETCH c_ai10 INTO v_so_ai10, v_cust_ai10, v_rk_ai10, v_run_ai10;
            IF v_done_ai10 = 1 THEN LEAVE loop_ai10; END IF;
        END LOOP;
        CLOSE c_ai10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ai10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ai10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ai11]
    BEGIN
        DECLARE v_hi_ai11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ai11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ai11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ai12]
    BEGIN
        DECLARE v_pairs_ai12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ai12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ai12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ai13]
    BEGIN
        DECLARE v_rows_ai13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ai13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ai13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ai13 FROM SESSION.TMP_ai13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ai13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ai14]
    BEGIN
        DECLARE v_rc_ai14 INTEGER DEFAULT 0;
        DECLARE v_band_ai14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ai14 = ROW_COUNT;
        SET v_band_ai14 = CASE
                            WHEN v_rc_ai14 = 0 THEN 'NONE'
                            WHEN v_rc_ai14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ai14, 'COUNT', 'band=' || v_band_ai14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ai15]
    BEGIN
        DECLARE v_i_ai15 INTEGER DEFAULT 0;
        SAVEPOINT sp_ai15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ai15 < 4 DO
            SET v_i_ai15 = v_i_ai15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ai15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ai15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ai15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ai16]
    BEGIN
        DECLARE v_j_ai16 INTEGER DEFAULT 0;
        DECLARE v_sum_ai16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ai16 = v_j_ai16 + 1;
        UNTIL v_j_ai16 >= 3 END REPEAT;
        FOR row_ai16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ai16 = v_sum_ai16 + COALESCE(row_ai16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ai16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ai16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ai17]
    BEGIN
        DECLARE v_n_ai17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ai17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ai17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [ai18]
    BEGIN
        DECLARE v_levels_ai18 INTEGER DEFAULT 0;
        DECLARE c_ai18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_ai18 = 0;
        OPEN c_ai18;
        FETCH c_ai18 INTO v_levels_ai18;
        CLOSE c_ai18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_ai18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ai19]
    BEGIN
        DECLARE v_sql_ai19 VARCHAR(1000);
        DECLARE v_n_ai19 INTEGER DEFAULT 0;
        SET v_sql_ai19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_ai19 FROM v_sql_ai19;
        EXECUTE st_ai19;
        SELECT COUNT(*) INTO v_n_ai19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ai19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ai20]
    BEGIN
        DECLARE v_key_ai20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ai20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ai20' AS VARCHAR(40)), v_key_ai20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [ai21]
    BEGIN
        DECLARE v_so_ai21 INTEGER DEFAULT 0;
        DECLARE v_cust_ai21 INTEGER DEFAULT 0;
        DECLARE v_ctry_ai21 INTEGER DEFAULT 0;
        DECLARE v_ccy_ai21 INTEGER DEFAULT 0;
        DECLARE v_sub_ai21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ai21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ai21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ai21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ai21 INTEGER DEFAULT 0;
        DECLARE v_done_ai21 INTEGER DEFAULT 0;
        DECLARE c_ai21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai21 = 1;
        OPEN c_ai21;
        loop_ai21: LOOP
            FETCH c_ai21 INTO v_so_ai21, v_cust_ai21, v_ctry_ai21, v_ccy_ai21, v_sub_ai21;
            IF v_done_ai21 = 1 THEN LEAVE loop_ai21; END IF;
            SET v_tax_ai21 = ERP_FN_TAX(v_ctry_ai21, v_sub_ai21);
            SET v_fx_ai21 = ERP_FN_FX_CONVERT(v_ccy_ai21, 1, v_sub_ai21 + v_tax_ai21);
            SET v_acc_ai21 = v_acc_ai21 + v_fx_ai21;
            SET v_cnt_ai21 = v_cnt_ai21 + 1;
        END LOOP;
        CLOSE c_ai21;
        IF v_cnt_ai21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ai21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ai21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ai22]
    BEGIN
        DECLARE v_pid_ai22 INTEGER DEFAULT 0;
        DECLARE v_oh_ai22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ai22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ai22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ai22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ai22 INTEGER DEFAULT 0;
        DECLARE c_ai22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai22 = 1;
        OPEN c_ai22;
        loop_ai22: LOOP
            FETCH c_ai22 INTO v_pid_ai22, v_oh_ai22, v_cost_ai22;
            IF v_done_ai22 = 1 THEN LEAVE loop_ai22; END IF;
            SET v_avail_ai22 = ERP_FN_INVENTORY_ONHAND(v_pid_ai22);
            SET v_val_ai22 = v_val_ai22 + CAST(COALESCE(v_oh_ai22,0) * COALESCE(v_cost_ai22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ai22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ai22;
        END LOOP;
        CLOSE c_ai22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ai22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ai23]
    BEGIN
        DECLARE v_prod_ai23 INTEGER DEFAULT 0;
        DECLARE v_rm_ai23 INTEGER DEFAULT 0;
        DECLARE v_supp_ai23 INTEGER DEFAULT 0;
        DECLARE v_qper_ai23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ai23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ai23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ai23 INTEGER DEFAULT 0;
        DECLARE c_ai23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai23 = 1;
        OPEN c_ai23;
        loop_ai23: LOOP
            FETCH c_ai23 INTO v_prod_ai23, v_rm_ai23, v_supp_ai23, v_qper_ai23, v_uc_ai23;
            IF v_done_ai23 = 1 THEN LEAVE loop_ai23; END IF;
            SET v_roll_ai23 = v_roll_ai23 + COALESCE(v_qper_ai23,0) * COALESCE(v_uc_ai23,0);
        END LOOP;
        CLOSE c_ai23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ai23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ai24]
    BEGIN
        DECLARE v_acct_ai24 INTEGER DEFAULT 0;
        DECLARE v_deb_ai24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ai24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ai24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai24 INTEGER DEFAULT 0;
        DECLARE c_ai24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai24 = 1;
        OPEN c_ai24;
        loop_ai24: LOOP
            FETCH c_ai24 INTO v_acct_ai24, v_deb_ai24, v_cred_ai24;
            IF v_done_ai24 = 1 THEN LEAVE loop_ai24; END IF;
            SET v_net_ai24 = v_net_ai24 + (v_deb_ai24 - v_cred_ai24);
        END LOOP;
        CLOSE c_ai24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ai24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ai25]
    BEGIN
        DECLARE v_pid_ai25 INTEGER DEFAULT 0;
        DECLARE v_lp_ai25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ai25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ai25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ai25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ai25 INTEGER DEFAULT 0;
        DECLARE c_ai25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai25 = 1;
        OPEN c_ai25;
        loop_ai25: LOOP
            FETCH c_ai25 INTO v_pid_ai25, v_lp_ai25, v_pp_ai25;
            IF v_done_ai25 = 1 THEN LEAVE loop_ai25; END IF;
            SET v_var_ai25 = v_var_ai25 + (COALESCE(v_lp_ai25,0) - COALESCE(v_pp_ai25,0));
            SET v_marg_ai25 = ERP_FN_MARGIN(v_pid_ai25);
        END LOOP;
        CLOSE c_ai25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ai25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ai26]
    BEGIN
        DECLARE v_inv_ai26 INTEGER DEFAULT 0;
        DECLARE v_amt_ai26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ai26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ai26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai26 INTEGER DEFAULT 0;
        DECLARE c_ai26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai26 = 1;
        OPEN c_ai26;
        loop_ai26: LOOP
            FETCH c_ai26 INTO v_inv_ai26, v_amt_ai26, v_alloc_ai26;
            IF v_done_ai26 = 1 THEN LEAVE loop_ai26; END IF;
            SET v_open_ai26 = v_open_ai26 + (v_amt_ai26 - v_alloc_ai26);
        END LOOP;
        CLOSE c_ai26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ai26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ai27]
    BEGIN
        DECLARE v_lvl_ai27 INTEGER DEFAULT 0;
        DECLARE v_dept_ai27 INTEGER DEFAULT 0;
        DECLARE v_head_ai27 INTEGER DEFAULT 0;
        DECLARE v_done_ai27 INTEGER DEFAULT 0;
        DECLARE c_ai27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai27 = 1;
        OPEN c_ai27;
        loop_ai27: LOOP
            FETCH c_ai27 INTO v_dept_ai27, v_lvl_ai27, v_head_ai27;
            IF v_done_ai27 = 1 THEN LEAVE loop_ai27; END IF;
        END LOOP;
        CLOSE c_ai27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ai27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ai27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ai28]
    BEGIN
        DECLARE v_sh_ai28 INTEGER DEFAULT 0;
        DECLARE v_car_ai28 INTEGER DEFAULT 0;
        DECLARE v_qty_ai28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ai28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ai28 INTEGER DEFAULT 0;
        DECLARE c_ai28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai28 = 1;
        OPEN c_ai28;
        loop_ai28: LOOP
            FETCH c_ai28 INTO v_sh_ai28, v_car_ai28, v_qty_ai28;
            IF v_done_ai28 = 1 THEN LEAVE loop_ai28; END IF;
            SET v_tot_ai28 = v_tot_ai28 + v_qty_ai28;
        END LOOP;
        CLOSE c_ai28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ai28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ai29]
    BEGIN
        DECLARE v_sql_ai29 VARCHAR(1000);
        DECLARE v_n_ai29 INTEGER DEFAULT 0;
        SET v_sql_ai29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ai29 FROM v_sql_ai29;
        EXECUTE st_ai29;
        SELECT COUNT(*) INTO v_n_ai29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ai29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ai30]
    BEGIN
        DECLARE v_key_ai30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ai30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ai30' AS VARCHAR(40)), v_key_ai30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ai31]
    BEGIN
        DECLARE v_so_ai31 INTEGER DEFAULT 0;
        DECLARE v_cust_ai31 INTEGER DEFAULT 0;
        DECLARE v_rk_ai31 INTEGER DEFAULT 0;
        DECLARE v_run_ai31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai31 INTEGER DEFAULT 0;
        DECLARE c_ai31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai31 = 1;
        OPEN c_ai31;
        loop_ai31: LOOP
            FETCH c_ai31 INTO v_so_ai31, v_cust_ai31, v_rk_ai31, v_run_ai31;
            IF v_done_ai31 = 1 THEN LEAVE loop_ai31; END IF;
        END LOOP;
        CLOSE c_ai31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ai31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ai31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ai32]
    BEGIN
        DECLARE v_hi_ai32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ai32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ai32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ai33]
    BEGIN
        DECLARE v_pairs_ai33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ai33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ai33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ai34]
    BEGIN
        DECLARE v_rows_ai34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ai34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ai34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ai34 FROM SESSION.TMP_ai34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ai34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ai35]
    BEGIN
        DECLARE v_rc_ai35 INTEGER DEFAULT 0;
        DECLARE v_band_ai35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ai35 = ROW_COUNT;
        SET v_band_ai35 = CASE
                            WHEN v_rc_ai35 = 0 THEN 'NONE'
                            WHEN v_rc_ai35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ai35, 'COUNT', 'band=' || v_band_ai35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ai36]
    BEGIN
        DECLARE v_i_ai36 INTEGER DEFAULT 0;
        SAVEPOINT sp_ai36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ai36 < 4 DO
            SET v_i_ai36 = v_i_ai36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ai36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ai36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ai36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ai37]
    BEGIN
        DECLARE v_j_ai37 INTEGER DEFAULT 0;
        DECLARE v_sum_ai37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ai37 = v_j_ai37 + 1;
        UNTIL v_j_ai37 >= 3 END REPEAT;
        FOR row_ai37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ai37 = v_sum_ai37 + COALESCE(row_ai37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ai37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ai37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ai38]
    BEGIN
        DECLARE v_n_ai38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ai38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ai38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [ai39]
    BEGIN
        DECLARE v_levels_ai39 INTEGER DEFAULT 0;
        DECLARE c_ai39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_ai39 = 0;
        OPEN c_ai39;
        FETCH c_ai39 INTO v_levels_ai39;
        CLOSE c_ai39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_ai39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ai40]
    BEGIN
        DECLARE v_sql_ai40 VARCHAR(1000);
        DECLARE v_n_ai40 INTEGER DEFAULT 0;
        SET v_sql_ai40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_ai40 FROM v_sql_ai40;
        EXECUTE st_ai40;
        SELECT COUNT(*) INTO v_n_ai40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ai40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ai41]
    BEGIN
        DECLARE v_key_ai41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ai41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ai41' AS VARCHAR(40)), v_key_ai41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [ai42]
    BEGIN
        DECLARE v_so_ai42 INTEGER DEFAULT 0;
        DECLARE v_cust_ai42 INTEGER DEFAULT 0;
        DECLARE v_ctry_ai42 INTEGER DEFAULT 0;
        DECLARE v_ccy_ai42 INTEGER DEFAULT 0;
        DECLARE v_sub_ai42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ai42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ai42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ai42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ai42 INTEGER DEFAULT 0;
        DECLARE v_done_ai42 INTEGER DEFAULT 0;
        DECLARE c_ai42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai42 = 1;
        OPEN c_ai42;
        loop_ai42: LOOP
            FETCH c_ai42 INTO v_so_ai42, v_cust_ai42, v_ctry_ai42, v_ccy_ai42, v_sub_ai42;
            IF v_done_ai42 = 1 THEN LEAVE loop_ai42; END IF;
            SET v_tax_ai42 = ERP_FN_TAX(v_ctry_ai42, v_sub_ai42);
            SET v_fx_ai42 = ERP_FN_FX_CONVERT(v_ccy_ai42, 1, v_sub_ai42 + v_tax_ai42);
            SET v_acc_ai42 = v_acc_ai42 + v_fx_ai42;
            SET v_cnt_ai42 = v_cnt_ai42 + 1;
        END LOOP;
        CLOSE c_ai42;
        IF v_cnt_ai42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ai42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ai42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ai43]
    BEGIN
        DECLARE v_pid_ai43 INTEGER DEFAULT 0;
        DECLARE v_oh_ai43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ai43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ai43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ai43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ai43 INTEGER DEFAULT 0;
        DECLARE c_ai43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai43 = 1;
        OPEN c_ai43;
        loop_ai43: LOOP
            FETCH c_ai43 INTO v_pid_ai43, v_oh_ai43, v_cost_ai43;
            IF v_done_ai43 = 1 THEN LEAVE loop_ai43; END IF;
            SET v_avail_ai43 = ERP_FN_INVENTORY_ONHAND(v_pid_ai43);
            SET v_val_ai43 = v_val_ai43 + CAST(COALESCE(v_oh_ai43,0) * COALESCE(v_cost_ai43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ai43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ai43;
        END LOOP;
        CLOSE c_ai43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ai43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ai44]
    BEGIN
        DECLARE v_prod_ai44 INTEGER DEFAULT 0;
        DECLARE v_rm_ai44 INTEGER DEFAULT 0;
        DECLARE v_supp_ai44 INTEGER DEFAULT 0;
        DECLARE v_qper_ai44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ai44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ai44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ai44 INTEGER DEFAULT 0;
        DECLARE c_ai44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai44 = 1;
        OPEN c_ai44;
        loop_ai44: LOOP
            FETCH c_ai44 INTO v_prod_ai44, v_rm_ai44, v_supp_ai44, v_qper_ai44, v_uc_ai44;
            IF v_done_ai44 = 1 THEN LEAVE loop_ai44; END IF;
            SET v_roll_ai44 = v_roll_ai44 + COALESCE(v_qper_ai44,0) * COALESCE(v_uc_ai44,0);
        END LOOP;
        CLOSE c_ai44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ai44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ai45]
    BEGIN
        DECLARE v_acct_ai45 INTEGER DEFAULT 0;
        DECLARE v_deb_ai45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ai45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ai45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai45 INTEGER DEFAULT 0;
        DECLARE c_ai45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai45 = 1;
        OPEN c_ai45;
        loop_ai45: LOOP
            FETCH c_ai45 INTO v_acct_ai45, v_deb_ai45, v_cred_ai45;
            IF v_done_ai45 = 1 THEN LEAVE loop_ai45; END IF;
            SET v_net_ai45 = v_net_ai45 + (v_deb_ai45 - v_cred_ai45);
        END LOOP;
        CLOSE c_ai45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ai45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ai46]
    BEGIN
        DECLARE v_pid_ai46 INTEGER DEFAULT 0;
        DECLARE v_lp_ai46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ai46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ai46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ai46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ai46 INTEGER DEFAULT 0;
        DECLARE c_ai46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai46 = 1;
        OPEN c_ai46;
        loop_ai46: LOOP
            FETCH c_ai46 INTO v_pid_ai46, v_lp_ai46, v_pp_ai46;
            IF v_done_ai46 = 1 THEN LEAVE loop_ai46; END IF;
            SET v_var_ai46 = v_var_ai46 + (COALESCE(v_lp_ai46,0) - COALESCE(v_pp_ai46,0));
            SET v_marg_ai46 = ERP_FN_MARGIN(v_pid_ai46);
        END LOOP;
        CLOSE c_ai46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ai46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ai47]
    BEGIN
        DECLARE v_inv_ai47 INTEGER DEFAULT 0;
        DECLARE v_amt_ai47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ai47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ai47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai47 INTEGER DEFAULT 0;
        DECLARE c_ai47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai47 = 1;
        OPEN c_ai47;
        loop_ai47: LOOP
            FETCH c_ai47 INTO v_inv_ai47, v_amt_ai47, v_alloc_ai47;
            IF v_done_ai47 = 1 THEN LEAVE loop_ai47; END IF;
            SET v_open_ai47 = v_open_ai47 + (v_amt_ai47 - v_alloc_ai47);
        END LOOP;
        CLOSE c_ai47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ai47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ai48]
    BEGIN
        DECLARE v_lvl_ai48 INTEGER DEFAULT 0;
        DECLARE v_dept_ai48 INTEGER DEFAULT 0;
        DECLARE v_head_ai48 INTEGER DEFAULT 0;
        DECLARE v_done_ai48 INTEGER DEFAULT 0;
        DECLARE c_ai48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai48 = 1;
        OPEN c_ai48;
        loop_ai48: LOOP
            FETCH c_ai48 INTO v_dept_ai48, v_lvl_ai48, v_head_ai48;
            IF v_done_ai48 = 1 THEN LEAVE loop_ai48; END IF;
        END LOOP;
        CLOSE c_ai48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ai48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ai48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ai49]
    BEGIN
        DECLARE v_sh_ai49 INTEGER DEFAULT 0;
        DECLARE v_car_ai49 INTEGER DEFAULT 0;
        DECLARE v_qty_ai49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ai49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ai49 INTEGER DEFAULT 0;
        DECLARE c_ai49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai49 = 1;
        OPEN c_ai49;
        loop_ai49: LOOP
            FETCH c_ai49 INTO v_sh_ai49, v_car_ai49, v_qty_ai49;
            IF v_done_ai49 = 1 THEN LEAVE loop_ai49; END IF;
            SET v_tot_ai49 = v_tot_ai49 + v_qty_ai49;
        END LOOP;
        CLOSE c_ai49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ai49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ai50]
    BEGIN
        DECLARE v_sql_ai50 VARCHAR(1000);
        DECLARE v_n_ai50 INTEGER DEFAULT 0;
        SET v_sql_ai50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ai50 FROM v_sql_ai50;
        EXECUTE st_ai50;
        SELECT COUNT(*) INTO v_n_ai50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ai50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ai51]
    BEGIN
        DECLARE v_key_ai51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ai51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ai51' AS VARCHAR(40)), v_key_ai51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ai52]
    BEGIN
        DECLARE v_so_ai52 INTEGER DEFAULT 0;
        DECLARE v_cust_ai52 INTEGER DEFAULT 0;
        DECLARE v_rk_ai52 INTEGER DEFAULT 0;
        DECLARE v_run_ai52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ai52 INTEGER DEFAULT 0;
        DECLARE c_ai52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ai52 = 1;
        OPEN c_ai52;
        loop_ai52: LOOP
            FETCH c_ai52 INTO v_so_ai52, v_cust_ai52, v_rk_ai52, v_run_ai52;
            IF v_done_ai52 = 1 THEN LEAVE loop_ai52; END IF;
        END LOOP;
        CLOSE c_ai52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ai52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ai52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ai53]
    BEGIN
        DECLARE v_hi_ai53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ai53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ai53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ai54]
    BEGIN
        DECLARE v_pairs_ai54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ai54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ai54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ai55]
    BEGIN
        DECLARE v_rows_ai55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ai55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ai55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ai55 FROM SESSION.TMP_ai55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ai55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ai56]
    BEGIN
        DECLARE v_rc_ai56 INTEGER DEFAULT 0;
        DECLARE v_band_ai56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ai56 = ROW_COUNT;
        SET v_band_ai56 = CASE
                            WHEN v_rc_ai56 = 0 THEN 'NONE'
                            WHEN v_rc_ai56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ai56, 'COUNT', 'band=' || v_band_ai56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ai57]
    BEGIN
        DECLARE v_i_ai57 INTEGER DEFAULT 0;
        SAVEPOINT sp_ai57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ai57 < 4 DO
            SET v_i_ai57 = v_i_ai57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ai57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ai57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ai57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_PROCESS_ORDER(IN p_so_id INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_total DECIMAL(16,2) DEFAULT 0;
    DECLARE v_cust INTEGER DEFAULT 0;
    DECLARE v_ok SMALLINT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('ERP_SALES_ORDER', p_so_id, 'ERROR', 'process failed');
    END;
    SET v_total = ERP_FN_ORDER_SUBTOTAL(p_so_id);
    SELECT customer_id INTO v_cust FROM ERP_SALES_ORDER WHERE id = p_so_id;
    SET v_ok = ERP_FN_CREDIT_OK(v_cust, v_total);
    UPDATE ERP_SALES_ORDER SET subtotal = v_total, status = 'PROCESSED' WHERE id = p_so_id;
    IF v_ok = 1 THEN
        CALL ERP_USP_ALLOCATE_INVENTORY(p_so_id);
    ELSE
        CALL ERP_USP_AUDIT('ERP_SALES_ORDER', p_so_id, 'HOLD', 'credit hold');
    END IF;
    CALL ERP_USP_AUDIT('ERP_SALES_ORDER', p_so_id, 'PROCESS', 'order processed');
    -- order/customer/country/currency revenue scan [po00]
    BEGIN
        DECLARE v_so_po00 INTEGER DEFAULT 0;
        DECLARE v_cust_po00 INTEGER DEFAULT 0;
        DECLARE v_ctry_po00 INTEGER DEFAULT 0;
        DECLARE v_ccy_po00 INTEGER DEFAULT 0;
        DECLARE v_sub_po00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_po00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_po00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_po00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_po00 INTEGER DEFAULT 0;
        DECLARE v_done_po00 INTEGER DEFAULT 0;
        DECLARE c_po00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po00 = 1;
        OPEN c_po00;
        loop_po00: LOOP
            FETCH c_po00 INTO v_so_po00, v_cust_po00, v_ctry_po00, v_ccy_po00, v_sub_po00;
            IF v_done_po00 = 1 THEN LEAVE loop_po00; END IF;
            SET v_tax_po00 = ERP_FN_TAX(v_ctry_po00, v_sub_po00);
            SET v_fx_po00 = ERP_FN_FX_CONVERT(v_ccy_po00, 1, v_sub_po00 + v_tax_po00);
            SET v_acc_po00 = v_acc_po00 + v_fx_po00;
            SET v_cnt_po00 = v_cnt_po00 + 1;
        END LOOP;
        CLOSE c_po00;
        IF v_cnt_po00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_po00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_po00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [po01]
    BEGIN
        DECLARE v_pid_po01 INTEGER DEFAULT 0;
        DECLARE v_oh_po01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_po01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_po01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_po01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_po01 INTEGER DEFAULT 0;
        DECLARE c_po01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po01 = 1;
        OPEN c_po01;
        loop_po01: LOOP
            FETCH c_po01 INTO v_pid_po01, v_oh_po01, v_cost_po01;
            IF v_done_po01 = 1 THEN LEAVE loop_po01; END IF;
            SET v_avail_po01 = ERP_FN_INVENTORY_ONHAND(v_pid_po01);
            SET v_val_po01 = v_val_po01 + CAST(COALESCE(v_oh_po01,0) * COALESCE(v_cost_po01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_po01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_po01;
        END LOOP;
        CLOSE c_po01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_po01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [po02]
    BEGIN
        DECLARE v_prod_po02 INTEGER DEFAULT 0;
        DECLARE v_rm_po02 INTEGER DEFAULT 0;
        DECLARE v_supp_po02 INTEGER DEFAULT 0;
        DECLARE v_qper_po02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_po02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_po02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_po02 INTEGER DEFAULT 0;
        DECLARE c_po02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po02 = 1;
        OPEN c_po02;
        loop_po02: LOOP
            FETCH c_po02 INTO v_prod_po02, v_rm_po02, v_supp_po02, v_qper_po02, v_uc_po02;
            IF v_done_po02 = 1 THEN LEAVE loop_po02; END IF;
            SET v_roll_po02 = v_roll_po02 + COALESCE(v_qper_po02,0) * COALESCE(v_uc_po02,0);
        END LOOP;
        CLOSE c_po02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_po02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [po03]
    BEGIN
        DECLARE v_acct_po03 INTEGER DEFAULT 0;
        DECLARE v_deb_po03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_po03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_po03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po03 INTEGER DEFAULT 0;
        DECLARE c_po03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po03 = 1;
        OPEN c_po03;
        loop_po03: LOOP
            FETCH c_po03 INTO v_acct_po03, v_deb_po03, v_cred_po03;
            IF v_done_po03 = 1 THEN LEAVE loop_po03; END IF;
            SET v_net_po03 = v_net_po03 + (v_deb_po03 - v_cred_po03);
        END LOOP;
        CLOSE c_po03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_po03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [po04]
    BEGIN
        DECLARE v_pid_po04 INTEGER DEFAULT 0;
        DECLARE v_lp_po04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_po04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_po04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_po04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_po04 INTEGER DEFAULT 0;
        DECLARE c_po04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po04 = 1;
        OPEN c_po04;
        loop_po04: LOOP
            FETCH c_po04 INTO v_pid_po04, v_lp_po04, v_pp_po04;
            IF v_done_po04 = 1 THEN LEAVE loop_po04; END IF;
            SET v_var_po04 = v_var_po04 + (COALESCE(v_lp_po04,0) - COALESCE(v_pp_po04,0));
            SET v_marg_po04 = ERP_FN_MARGIN(v_pid_po04);
        END LOOP;
        CLOSE c_po04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_po04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [po05]
    BEGIN
        DECLARE v_inv_po05 INTEGER DEFAULT 0;
        DECLARE v_amt_po05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_po05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_po05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po05 INTEGER DEFAULT 0;
        DECLARE c_po05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po05 = 1;
        OPEN c_po05;
        loop_po05: LOOP
            FETCH c_po05 INTO v_inv_po05, v_amt_po05, v_alloc_po05;
            IF v_done_po05 = 1 THEN LEAVE loop_po05; END IF;
            SET v_open_po05 = v_open_po05 + (v_amt_po05 - v_alloc_po05);
        END LOOP;
        CLOSE c_po05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_po05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [po06]
    BEGIN
        DECLARE v_lvl_po06 INTEGER DEFAULT 0;
        DECLARE v_dept_po06 INTEGER DEFAULT 0;
        DECLARE v_head_po06 INTEGER DEFAULT 0;
        DECLARE v_done_po06 INTEGER DEFAULT 0;
        DECLARE c_po06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po06 = 1;
        OPEN c_po06;
        loop_po06: LOOP
            FETCH c_po06 INTO v_dept_po06, v_lvl_po06, v_head_po06;
            IF v_done_po06 = 1 THEN LEAVE loop_po06; END IF;
        END LOOP;
        CLOSE c_po06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_po06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_po06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [po07]
    BEGIN
        DECLARE v_sh_po07 INTEGER DEFAULT 0;
        DECLARE v_car_po07 INTEGER DEFAULT 0;
        DECLARE v_qty_po07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_po07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_po07 INTEGER DEFAULT 0;
        DECLARE c_po07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po07 = 1;
        OPEN c_po07;
        loop_po07: LOOP
            FETCH c_po07 INTO v_sh_po07, v_car_po07, v_qty_po07;
            IF v_done_po07 = 1 THEN LEAVE loop_po07; END IF;
            SET v_tot_po07 = v_tot_po07 + v_qty_po07;
        END LOOP;
        CLOSE c_po07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_po07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [po08]
    BEGIN
        DECLARE v_sql_po08 VARCHAR(1000);
        DECLARE v_n_po08 INTEGER DEFAULT 0;
        SET v_sql_po08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_po08 FROM v_sql_po08;
        EXECUTE st_po08;
        SELECT COUNT(*) INTO v_n_po08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_po08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [po09]
    BEGIN
        DECLARE v_key_po09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_po09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_po09' AS VARCHAR(40)), v_key_po09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [po10]
    BEGIN
        DECLARE v_so_po10 INTEGER DEFAULT 0;
        DECLARE v_cust_po10 INTEGER DEFAULT 0;
        DECLARE v_rk_po10 INTEGER DEFAULT 0;
        DECLARE v_run_po10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po10 INTEGER DEFAULT 0;
        DECLARE c_po10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po10 = 1;
        OPEN c_po10;
        loop_po10: LOOP
            FETCH c_po10 INTO v_so_po10, v_cust_po10, v_rk_po10, v_run_po10;
            IF v_done_po10 = 1 THEN LEAVE loop_po10; END IF;
        END LOOP;
        CLOSE c_po10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_po10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_po10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [po11]
    BEGIN
        DECLARE v_hi_po11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_po11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_po11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [po12]
    BEGIN
        DECLARE v_pairs_po12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_po12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_po12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [po13]
    BEGIN
        DECLARE v_rows_po13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_po13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_po13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_po13 FROM SESSION.TMP_po13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_po13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [po14]
    BEGIN
        DECLARE v_rc_po14 INTEGER DEFAULT 0;
        DECLARE v_band_po14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_po14 = ROW_COUNT;
        SET v_band_po14 = CASE
                            WHEN v_rc_po14 = 0 THEN 'NONE'
                            WHEN v_rc_po14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_po14, 'COUNT', 'band=' || v_band_po14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [po15]
    BEGIN
        DECLARE v_i_po15 INTEGER DEFAULT 0;
        SAVEPOINT sp_po15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_po15 < 4 DO
            SET v_i_po15 = v_i_po15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_po15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_po15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_po15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [po16]
    BEGIN
        DECLARE v_j_po16 INTEGER DEFAULT 0;
        DECLARE v_sum_po16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_po16 = v_j_po16 + 1;
        UNTIL v_j_po16 >= 3 END REPEAT;
        FOR row_po16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_po16 = v_sum_po16 + COALESCE(row_po16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_po16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_po16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [po17]
    BEGIN
        DECLARE v_n_po17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_po17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_po17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [po18]
    BEGIN
        DECLARE v_levels_po18 INTEGER DEFAULT 0;
        DECLARE c_po18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_po18 = 0;
        OPEN c_po18;
        FETCH c_po18 INTO v_levels_po18;
        CLOSE c_po18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_po18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [po19]
    BEGIN
        DECLARE v_sql_po19 VARCHAR(1000);
        DECLARE v_n_po19 INTEGER DEFAULT 0;
        SET v_sql_po19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_po19 FROM v_sql_po19;
        EXECUTE st_po19;
        SELECT COUNT(*) INTO v_n_po19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_po19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [po20]
    BEGIN
        DECLARE v_key_po20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_po20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_po20' AS VARCHAR(40)), v_key_po20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [po21]
    BEGIN
        DECLARE v_so_po21 INTEGER DEFAULT 0;
        DECLARE v_cust_po21 INTEGER DEFAULT 0;
        DECLARE v_ctry_po21 INTEGER DEFAULT 0;
        DECLARE v_ccy_po21 INTEGER DEFAULT 0;
        DECLARE v_sub_po21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_po21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_po21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_po21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_po21 INTEGER DEFAULT 0;
        DECLARE v_done_po21 INTEGER DEFAULT 0;
        DECLARE c_po21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po21 = 1;
        OPEN c_po21;
        loop_po21: LOOP
            FETCH c_po21 INTO v_so_po21, v_cust_po21, v_ctry_po21, v_ccy_po21, v_sub_po21;
            IF v_done_po21 = 1 THEN LEAVE loop_po21; END IF;
            SET v_tax_po21 = ERP_FN_TAX(v_ctry_po21, v_sub_po21);
            SET v_fx_po21 = ERP_FN_FX_CONVERT(v_ccy_po21, 1, v_sub_po21 + v_tax_po21);
            SET v_acc_po21 = v_acc_po21 + v_fx_po21;
            SET v_cnt_po21 = v_cnt_po21 + 1;
        END LOOP;
        CLOSE c_po21;
        IF v_cnt_po21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_po21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_po21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [po22]
    BEGIN
        DECLARE v_pid_po22 INTEGER DEFAULT 0;
        DECLARE v_oh_po22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_po22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_po22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_po22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_po22 INTEGER DEFAULT 0;
        DECLARE c_po22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po22 = 1;
        OPEN c_po22;
        loop_po22: LOOP
            FETCH c_po22 INTO v_pid_po22, v_oh_po22, v_cost_po22;
            IF v_done_po22 = 1 THEN LEAVE loop_po22; END IF;
            SET v_avail_po22 = ERP_FN_INVENTORY_ONHAND(v_pid_po22);
            SET v_val_po22 = v_val_po22 + CAST(COALESCE(v_oh_po22,0) * COALESCE(v_cost_po22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_po22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_po22;
        END LOOP;
        CLOSE c_po22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_po22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [po23]
    BEGIN
        DECLARE v_prod_po23 INTEGER DEFAULT 0;
        DECLARE v_rm_po23 INTEGER DEFAULT 0;
        DECLARE v_supp_po23 INTEGER DEFAULT 0;
        DECLARE v_qper_po23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_po23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_po23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_po23 INTEGER DEFAULT 0;
        DECLARE c_po23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po23 = 1;
        OPEN c_po23;
        loop_po23: LOOP
            FETCH c_po23 INTO v_prod_po23, v_rm_po23, v_supp_po23, v_qper_po23, v_uc_po23;
            IF v_done_po23 = 1 THEN LEAVE loop_po23; END IF;
            SET v_roll_po23 = v_roll_po23 + COALESCE(v_qper_po23,0) * COALESCE(v_uc_po23,0);
        END LOOP;
        CLOSE c_po23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_po23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [po24]
    BEGIN
        DECLARE v_acct_po24 INTEGER DEFAULT 0;
        DECLARE v_deb_po24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_po24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_po24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po24 INTEGER DEFAULT 0;
        DECLARE c_po24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po24 = 1;
        OPEN c_po24;
        loop_po24: LOOP
            FETCH c_po24 INTO v_acct_po24, v_deb_po24, v_cred_po24;
            IF v_done_po24 = 1 THEN LEAVE loop_po24; END IF;
            SET v_net_po24 = v_net_po24 + (v_deb_po24 - v_cred_po24);
        END LOOP;
        CLOSE c_po24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_po24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [po25]
    BEGIN
        DECLARE v_pid_po25 INTEGER DEFAULT 0;
        DECLARE v_lp_po25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_po25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_po25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_po25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_po25 INTEGER DEFAULT 0;
        DECLARE c_po25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po25 = 1;
        OPEN c_po25;
        loop_po25: LOOP
            FETCH c_po25 INTO v_pid_po25, v_lp_po25, v_pp_po25;
            IF v_done_po25 = 1 THEN LEAVE loop_po25; END IF;
            SET v_var_po25 = v_var_po25 + (COALESCE(v_lp_po25,0) - COALESCE(v_pp_po25,0));
            SET v_marg_po25 = ERP_FN_MARGIN(v_pid_po25);
        END LOOP;
        CLOSE c_po25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_po25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [po26]
    BEGIN
        DECLARE v_inv_po26 INTEGER DEFAULT 0;
        DECLARE v_amt_po26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_po26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_po26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po26 INTEGER DEFAULT 0;
        DECLARE c_po26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po26 = 1;
        OPEN c_po26;
        loop_po26: LOOP
            FETCH c_po26 INTO v_inv_po26, v_amt_po26, v_alloc_po26;
            IF v_done_po26 = 1 THEN LEAVE loop_po26; END IF;
            SET v_open_po26 = v_open_po26 + (v_amt_po26 - v_alloc_po26);
        END LOOP;
        CLOSE c_po26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_po26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [po27]
    BEGIN
        DECLARE v_lvl_po27 INTEGER DEFAULT 0;
        DECLARE v_dept_po27 INTEGER DEFAULT 0;
        DECLARE v_head_po27 INTEGER DEFAULT 0;
        DECLARE v_done_po27 INTEGER DEFAULT 0;
        DECLARE c_po27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po27 = 1;
        OPEN c_po27;
        loop_po27: LOOP
            FETCH c_po27 INTO v_dept_po27, v_lvl_po27, v_head_po27;
            IF v_done_po27 = 1 THEN LEAVE loop_po27; END IF;
        END LOOP;
        CLOSE c_po27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_po27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_po27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [po28]
    BEGIN
        DECLARE v_sh_po28 INTEGER DEFAULT 0;
        DECLARE v_car_po28 INTEGER DEFAULT 0;
        DECLARE v_qty_po28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_po28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_po28 INTEGER DEFAULT 0;
        DECLARE c_po28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po28 = 1;
        OPEN c_po28;
        loop_po28: LOOP
            FETCH c_po28 INTO v_sh_po28, v_car_po28, v_qty_po28;
            IF v_done_po28 = 1 THEN LEAVE loop_po28; END IF;
            SET v_tot_po28 = v_tot_po28 + v_qty_po28;
        END LOOP;
        CLOSE c_po28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_po28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [po29]
    BEGIN
        DECLARE v_sql_po29 VARCHAR(1000);
        DECLARE v_n_po29 INTEGER DEFAULT 0;
        SET v_sql_po29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_po29 FROM v_sql_po29;
        EXECUTE st_po29;
        SELECT COUNT(*) INTO v_n_po29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_po29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [po30]
    BEGIN
        DECLARE v_key_po30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_po30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_po30' AS VARCHAR(40)), v_key_po30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [po31]
    BEGIN
        DECLARE v_so_po31 INTEGER DEFAULT 0;
        DECLARE v_cust_po31 INTEGER DEFAULT 0;
        DECLARE v_rk_po31 INTEGER DEFAULT 0;
        DECLARE v_run_po31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po31 INTEGER DEFAULT 0;
        DECLARE c_po31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po31 = 1;
        OPEN c_po31;
        loop_po31: LOOP
            FETCH c_po31 INTO v_so_po31, v_cust_po31, v_rk_po31, v_run_po31;
            IF v_done_po31 = 1 THEN LEAVE loop_po31; END IF;
        END LOOP;
        CLOSE c_po31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_po31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_po31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [po32]
    BEGIN
        DECLARE v_hi_po32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_po32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_po32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [po33]
    BEGIN
        DECLARE v_pairs_po33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_po33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_po33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [po34]
    BEGIN
        DECLARE v_rows_po34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_po34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_po34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_po34 FROM SESSION.TMP_po34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_po34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [po35]
    BEGIN
        DECLARE v_rc_po35 INTEGER DEFAULT 0;
        DECLARE v_band_po35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_po35 = ROW_COUNT;
        SET v_band_po35 = CASE
                            WHEN v_rc_po35 = 0 THEN 'NONE'
                            WHEN v_rc_po35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_po35, 'COUNT', 'band=' || v_band_po35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [po36]
    BEGIN
        DECLARE v_i_po36 INTEGER DEFAULT 0;
        SAVEPOINT sp_po36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_po36 < 4 DO
            SET v_i_po36 = v_i_po36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_po36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_po36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_po36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [po37]
    BEGIN
        DECLARE v_j_po37 INTEGER DEFAULT 0;
        DECLARE v_sum_po37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_po37 = v_j_po37 + 1;
        UNTIL v_j_po37 >= 3 END REPEAT;
        FOR row_po37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_po37 = v_sum_po37 + COALESCE(row_po37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_po37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_po37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [po38]
    BEGIN
        DECLARE v_n_po38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_po38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_po38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [po39]
    BEGIN
        DECLARE v_levels_po39 INTEGER DEFAULT 0;
        DECLARE c_po39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_po39 = 0;
        OPEN c_po39;
        FETCH c_po39 INTO v_levels_po39;
        CLOSE c_po39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_po39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [po40]
    BEGIN
        DECLARE v_sql_po40 VARCHAR(1000);
        DECLARE v_n_po40 INTEGER DEFAULT 0;
        SET v_sql_po40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_po40 FROM v_sql_po40;
        EXECUTE st_po40;
        SELECT COUNT(*) INTO v_n_po40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_po40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [po41]
    BEGIN
        DECLARE v_key_po41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_po41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_po41' AS VARCHAR(40)), v_key_po41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [po42]
    BEGIN
        DECLARE v_so_po42 INTEGER DEFAULT 0;
        DECLARE v_cust_po42 INTEGER DEFAULT 0;
        DECLARE v_ctry_po42 INTEGER DEFAULT 0;
        DECLARE v_ccy_po42 INTEGER DEFAULT 0;
        DECLARE v_sub_po42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_po42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_po42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_po42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_po42 INTEGER DEFAULT 0;
        DECLARE v_done_po42 INTEGER DEFAULT 0;
        DECLARE c_po42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po42 = 1;
        OPEN c_po42;
        loop_po42: LOOP
            FETCH c_po42 INTO v_so_po42, v_cust_po42, v_ctry_po42, v_ccy_po42, v_sub_po42;
            IF v_done_po42 = 1 THEN LEAVE loop_po42; END IF;
            SET v_tax_po42 = ERP_FN_TAX(v_ctry_po42, v_sub_po42);
            SET v_fx_po42 = ERP_FN_FX_CONVERT(v_ccy_po42, 1, v_sub_po42 + v_tax_po42);
            SET v_acc_po42 = v_acc_po42 + v_fx_po42;
            SET v_cnt_po42 = v_cnt_po42 + 1;
        END LOOP;
        CLOSE c_po42;
        IF v_cnt_po42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_po42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_po42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [po43]
    BEGIN
        DECLARE v_pid_po43 INTEGER DEFAULT 0;
        DECLARE v_oh_po43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_po43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_po43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_po43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_po43 INTEGER DEFAULT 0;
        DECLARE c_po43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po43 = 1;
        OPEN c_po43;
        loop_po43: LOOP
            FETCH c_po43 INTO v_pid_po43, v_oh_po43, v_cost_po43;
            IF v_done_po43 = 1 THEN LEAVE loop_po43; END IF;
            SET v_avail_po43 = ERP_FN_INVENTORY_ONHAND(v_pid_po43);
            SET v_val_po43 = v_val_po43 + CAST(COALESCE(v_oh_po43,0) * COALESCE(v_cost_po43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_po43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_po43;
        END LOOP;
        CLOSE c_po43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_po43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [po44]
    BEGIN
        DECLARE v_prod_po44 INTEGER DEFAULT 0;
        DECLARE v_rm_po44 INTEGER DEFAULT 0;
        DECLARE v_supp_po44 INTEGER DEFAULT 0;
        DECLARE v_qper_po44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_po44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_po44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_po44 INTEGER DEFAULT 0;
        DECLARE c_po44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po44 = 1;
        OPEN c_po44;
        loop_po44: LOOP
            FETCH c_po44 INTO v_prod_po44, v_rm_po44, v_supp_po44, v_qper_po44, v_uc_po44;
            IF v_done_po44 = 1 THEN LEAVE loop_po44; END IF;
            SET v_roll_po44 = v_roll_po44 + COALESCE(v_qper_po44,0) * COALESCE(v_uc_po44,0);
        END LOOP;
        CLOSE c_po44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_po44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [po45]
    BEGIN
        DECLARE v_acct_po45 INTEGER DEFAULT 0;
        DECLARE v_deb_po45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_po45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_po45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po45 INTEGER DEFAULT 0;
        DECLARE c_po45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po45 = 1;
        OPEN c_po45;
        loop_po45: LOOP
            FETCH c_po45 INTO v_acct_po45, v_deb_po45, v_cred_po45;
            IF v_done_po45 = 1 THEN LEAVE loop_po45; END IF;
            SET v_net_po45 = v_net_po45 + (v_deb_po45 - v_cred_po45);
        END LOOP;
        CLOSE c_po45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_po45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [po46]
    BEGIN
        DECLARE v_pid_po46 INTEGER DEFAULT 0;
        DECLARE v_lp_po46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_po46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_po46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_po46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_po46 INTEGER DEFAULT 0;
        DECLARE c_po46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po46 = 1;
        OPEN c_po46;
        loop_po46: LOOP
            FETCH c_po46 INTO v_pid_po46, v_lp_po46, v_pp_po46;
            IF v_done_po46 = 1 THEN LEAVE loop_po46; END IF;
            SET v_var_po46 = v_var_po46 + (COALESCE(v_lp_po46,0) - COALESCE(v_pp_po46,0));
            SET v_marg_po46 = ERP_FN_MARGIN(v_pid_po46);
        END LOOP;
        CLOSE c_po46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_po46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [po47]
    BEGIN
        DECLARE v_inv_po47 INTEGER DEFAULT 0;
        DECLARE v_amt_po47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_po47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_po47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po47 INTEGER DEFAULT 0;
        DECLARE c_po47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po47 = 1;
        OPEN c_po47;
        loop_po47: LOOP
            FETCH c_po47 INTO v_inv_po47, v_amt_po47, v_alloc_po47;
            IF v_done_po47 = 1 THEN LEAVE loop_po47; END IF;
            SET v_open_po47 = v_open_po47 + (v_amt_po47 - v_alloc_po47);
        END LOOP;
        CLOSE c_po47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_po47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [po48]
    BEGIN
        DECLARE v_lvl_po48 INTEGER DEFAULT 0;
        DECLARE v_dept_po48 INTEGER DEFAULT 0;
        DECLARE v_head_po48 INTEGER DEFAULT 0;
        DECLARE v_done_po48 INTEGER DEFAULT 0;
        DECLARE c_po48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po48 = 1;
        OPEN c_po48;
        loop_po48: LOOP
            FETCH c_po48 INTO v_dept_po48, v_lvl_po48, v_head_po48;
            IF v_done_po48 = 1 THEN LEAVE loop_po48; END IF;
        END LOOP;
        CLOSE c_po48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_po48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_po48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [po49]
    BEGIN
        DECLARE v_sh_po49 INTEGER DEFAULT 0;
        DECLARE v_car_po49 INTEGER DEFAULT 0;
        DECLARE v_qty_po49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_po49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_po49 INTEGER DEFAULT 0;
        DECLARE c_po49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po49 = 1;
        OPEN c_po49;
        loop_po49: LOOP
            FETCH c_po49 INTO v_sh_po49, v_car_po49, v_qty_po49;
            IF v_done_po49 = 1 THEN LEAVE loop_po49; END IF;
            SET v_tot_po49 = v_tot_po49 + v_qty_po49;
        END LOOP;
        CLOSE c_po49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_po49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [po50]
    BEGIN
        DECLARE v_sql_po50 VARCHAR(1000);
        DECLARE v_n_po50 INTEGER DEFAULT 0;
        SET v_sql_po50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_po50 FROM v_sql_po50;
        EXECUTE st_po50;
        SELECT COUNT(*) INTO v_n_po50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_po50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [po51]
    BEGIN
        DECLARE v_key_po51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_po51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_po51' AS VARCHAR(40)), v_key_po51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [po52]
    BEGIN
        DECLARE v_so_po52 INTEGER DEFAULT 0;
        DECLARE v_cust_po52 INTEGER DEFAULT 0;
        DECLARE v_rk_po52 INTEGER DEFAULT 0;
        DECLARE v_run_po52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_po52 INTEGER DEFAULT 0;
        DECLARE c_po52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_po52 = 1;
        OPEN c_po52;
        loop_po52: LOOP
            FETCH c_po52 INTO v_so_po52, v_cust_po52, v_rk_po52, v_run_po52;
            IF v_done_po52 = 1 THEN LEAVE loop_po52; END IF;
        END LOOP;
        CLOSE c_po52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_po52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_po52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [po53]
    BEGIN
        DECLARE v_hi_po53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_po53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_po53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [po54]
    BEGIN
        DECLARE v_pairs_po54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_po54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_po54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [po55]
    BEGIN
        DECLARE v_rows_po55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_po55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_po55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_po55 FROM SESSION.TMP_po55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_po55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [po56]
    BEGIN
        DECLARE v_rc_po56 INTEGER DEFAULT 0;
        DECLARE v_band_po56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_po56 = ROW_COUNT;
        SET v_band_po56 = CASE
                            WHEN v_rc_po56 = 0 THEN 'NONE'
                            WHEN v_rc_po56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_po56, 'COUNT', 'band=' || v_band_po56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [po57]
    BEGIN
        DECLARE v_i_po57 INTEGER DEFAULT 0;
        SAVEPOINT sp_po57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_po57 < 4 DO
            SET v_i_po57 = v_i_po57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_po57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_po57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_po57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_PROCESS_ORDERS()
LANGUAGE SQL
BEGIN
    DECLARE v_id INTEGER DEFAULT 0;
    DECLARE v_done INTEGER DEFAULT 0;
    DECLARE c_orders CURSOR FOR
        SELECT id FROM ERP_SALES_ORDER WHERE status = 'NEW' ORDER BY id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
    CALL ERP_USP_AUDIT('ORDERS', 0, 'START', 'processing new orders');
    OPEN c_orders;
    ord_loop: LOOP
        FETCH c_orders INTO v_id;
        IF v_done = 1 THEN LEAVE ord_loop; END IF;
        CALL ERP_USP_PROCESS_ORDER(v_id);
    END LOOP;
    CLOSE c_orders;
    CALL ERP_USP_AUDIT('ORDERS', 0, 'END', 'orders processed');
    -- order/customer/country/currency revenue scan [ps00]
    BEGIN
        DECLARE v_so_ps00 INTEGER DEFAULT 0;
        DECLARE v_cust_ps00 INTEGER DEFAULT 0;
        DECLARE v_ctry_ps00 INTEGER DEFAULT 0;
        DECLARE v_ccy_ps00 INTEGER DEFAULT 0;
        DECLARE v_sub_ps00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ps00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ps00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ps00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ps00 INTEGER DEFAULT 0;
        DECLARE v_done_ps00 INTEGER DEFAULT 0;
        DECLARE c_ps00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps00 = 1;
        OPEN c_ps00;
        loop_ps00: LOOP
            FETCH c_ps00 INTO v_so_ps00, v_cust_ps00, v_ctry_ps00, v_ccy_ps00, v_sub_ps00;
            IF v_done_ps00 = 1 THEN LEAVE loop_ps00; END IF;
            SET v_tax_ps00 = ERP_FN_TAX(v_ctry_ps00, v_sub_ps00);
            SET v_fx_ps00 = ERP_FN_FX_CONVERT(v_ccy_ps00, 1, v_sub_ps00 + v_tax_ps00);
            SET v_acc_ps00 = v_acc_ps00 + v_fx_ps00;
            SET v_cnt_ps00 = v_cnt_ps00 + 1;
        END LOOP;
        CLOSE c_ps00;
        IF v_cnt_ps00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ps00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ps00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ps01]
    BEGIN
        DECLARE v_pid_ps01 INTEGER DEFAULT 0;
        DECLARE v_oh_ps01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ps01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ps01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ps01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ps01 INTEGER DEFAULT 0;
        DECLARE c_ps01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps01 = 1;
        OPEN c_ps01;
        loop_ps01: LOOP
            FETCH c_ps01 INTO v_pid_ps01, v_oh_ps01, v_cost_ps01;
            IF v_done_ps01 = 1 THEN LEAVE loop_ps01; END IF;
            SET v_avail_ps01 = ERP_FN_INVENTORY_ONHAND(v_pid_ps01);
            SET v_val_ps01 = v_val_ps01 + CAST(COALESCE(v_oh_ps01,0) * COALESCE(v_cost_ps01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ps01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ps01;
        END LOOP;
        CLOSE c_ps01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ps01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ps02]
    BEGIN
        DECLARE v_prod_ps02 INTEGER DEFAULT 0;
        DECLARE v_rm_ps02 INTEGER DEFAULT 0;
        DECLARE v_supp_ps02 INTEGER DEFAULT 0;
        DECLARE v_qper_ps02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ps02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ps02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ps02 INTEGER DEFAULT 0;
        DECLARE c_ps02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps02 = 1;
        OPEN c_ps02;
        loop_ps02: LOOP
            FETCH c_ps02 INTO v_prod_ps02, v_rm_ps02, v_supp_ps02, v_qper_ps02, v_uc_ps02;
            IF v_done_ps02 = 1 THEN LEAVE loop_ps02; END IF;
            SET v_roll_ps02 = v_roll_ps02 + COALESCE(v_qper_ps02,0) * COALESCE(v_uc_ps02,0);
        END LOOP;
        CLOSE c_ps02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ps02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ps03]
    BEGIN
        DECLARE v_acct_ps03 INTEGER DEFAULT 0;
        DECLARE v_deb_ps03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ps03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ps03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps03 INTEGER DEFAULT 0;
        DECLARE c_ps03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps03 = 1;
        OPEN c_ps03;
        loop_ps03: LOOP
            FETCH c_ps03 INTO v_acct_ps03, v_deb_ps03, v_cred_ps03;
            IF v_done_ps03 = 1 THEN LEAVE loop_ps03; END IF;
            SET v_net_ps03 = v_net_ps03 + (v_deb_ps03 - v_cred_ps03);
        END LOOP;
        CLOSE c_ps03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ps03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ps04]
    BEGIN
        DECLARE v_pid_ps04 INTEGER DEFAULT 0;
        DECLARE v_lp_ps04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ps04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ps04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ps04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ps04 INTEGER DEFAULT 0;
        DECLARE c_ps04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps04 = 1;
        OPEN c_ps04;
        loop_ps04: LOOP
            FETCH c_ps04 INTO v_pid_ps04, v_lp_ps04, v_pp_ps04;
            IF v_done_ps04 = 1 THEN LEAVE loop_ps04; END IF;
            SET v_var_ps04 = v_var_ps04 + (COALESCE(v_lp_ps04,0) - COALESCE(v_pp_ps04,0));
            SET v_marg_ps04 = ERP_FN_MARGIN(v_pid_ps04);
        END LOOP;
        CLOSE c_ps04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ps04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ps05]
    BEGIN
        DECLARE v_inv_ps05 INTEGER DEFAULT 0;
        DECLARE v_amt_ps05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ps05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ps05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps05 INTEGER DEFAULT 0;
        DECLARE c_ps05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps05 = 1;
        OPEN c_ps05;
        loop_ps05: LOOP
            FETCH c_ps05 INTO v_inv_ps05, v_amt_ps05, v_alloc_ps05;
            IF v_done_ps05 = 1 THEN LEAVE loop_ps05; END IF;
            SET v_open_ps05 = v_open_ps05 + (v_amt_ps05 - v_alloc_ps05);
        END LOOP;
        CLOSE c_ps05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ps05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ps06]
    BEGIN
        DECLARE v_lvl_ps06 INTEGER DEFAULT 0;
        DECLARE v_dept_ps06 INTEGER DEFAULT 0;
        DECLARE v_head_ps06 INTEGER DEFAULT 0;
        DECLARE v_done_ps06 INTEGER DEFAULT 0;
        DECLARE c_ps06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps06 = 1;
        OPEN c_ps06;
        loop_ps06: LOOP
            FETCH c_ps06 INTO v_dept_ps06, v_lvl_ps06, v_head_ps06;
            IF v_done_ps06 = 1 THEN LEAVE loop_ps06; END IF;
        END LOOP;
        CLOSE c_ps06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ps06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ps06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ps07]
    BEGIN
        DECLARE v_sh_ps07 INTEGER DEFAULT 0;
        DECLARE v_car_ps07 INTEGER DEFAULT 0;
        DECLARE v_qty_ps07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ps07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ps07 INTEGER DEFAULT 0;
        DECLARE c_ps07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps07 = 1;
        OPEN c_ps07;
        loop_ps07: LOOP
            FETCH c_ps07 INTO v_sh_ps07, v_car_ps07, v_qty_ps07;
            IF v_done_ps07 = 1 THEN LEAVE loop_ps07; END IF;
            SET v_tot_ps07 = v_tot_ps07 + v_qty_ps07;
        END LOOP;
        CLOSE c_ps07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ps07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ps08]
    BEGIN
        DECLARE v_sql_ps08 VARCHAR(1000);
        DECLARE v_n_ps08 INTEGER DEFAULT 0;
        SET v_sql_ps08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ps08 FROM v_sql_ps08;
        EXECUTE st_ps08;
        SELECT COUNT(*) INTO v_n_ps08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ps08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ps09]
    BEGIN
        DECLARE v_key_ps09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ps09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ps09' AS VARCHAR(40)), v_key_ps09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ps10]
    BEGIN
        DECLARE v_so_ps10 INTEGER DEFAULT 0;
        DECLARE v_cust_ps10 INTEGER DEFAULT 0;
        DECLARE v_rk_ps10 INTEGER DEFAULT 0;
        DECLARE v_run_ps10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps10 INTEGER DEFAULT 0;
        DECLARE c_ps10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps10 = 1;
        OPEN c_ps10;
        loop_ps10: LOOP
            FETCH c_ps10 INTO v_so_ps10, v_cust_ps10, v_rk_ps10, v_run_ps10;
            IF v_done_ps10 = 1 THEN LEAVE loop_ps10; END IF;
        END LOOP;
        CLOSE c_ps10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ps10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ps10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ps11]
    BEGIN
        DECLARE v_hi_ps11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ps11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ps11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ps12]
    BEGIN
        DECLARE v_pairs_ps12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ps12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ps12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ps13]
    BEGIN
        DECLARE v_rows_ps13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ps13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ps13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ps13 FROM SESSION.TMP_ps13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ps13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ps14]
    BEGIN
        DECLARE v_rc_ps14 INTEGER DEFAULT 0;
        DECLARE v_band_ps14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ps14 = ROW_COUNT;
        SET v_band_ps14 = CASE
                            WHEN v_rc_ps14 = 0 THEN 'NONE'
                            WHEN v_rc_ps14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ps14, 'COUNT', 'band=' || v_band_ps14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ps15]
    BEGIN
        DECLARE v_i_ps15 INTEGER DEFAULT 0;
        SAVEPOINT sp_ps15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ps15 < 4 DO
            SET v_i_ps15 = v_i_ps15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ps15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ps15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ps15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ps16]
    BEGIN
        DECLARE v_j_ps16 INTEGER DEFAULT 0;
        DECLARE v_sum_ps16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ps16 = v_j_ps16 + 1;
        UNTIL v_j_ps16 >= 3 END REPEAT;
        FOR row_ps16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ps16 = v_sum_ps16 + COALESCE(row_ps16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ps16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ps16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ps17]
    BEGIN
        DECLARE v_n_ps17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ps17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ps17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [ps18]
    BEGIN
        DECLARE v_levels_ps18 INTEGER DEFAULT 0;
        DECLARE c_ps18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_ps18 = 0;
        OPEN c_ps18;
        FETCH c_ps18 INTO v_levels_ps18;
        CLOSE c_ps18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_ps18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ps19]
    BEGIN
        DECLARE v_sql_ps19 VARCHAR(1000);
        DECLARE v_n_ps19 INTEGER DEFAULT 0;
        SET v_sql_ps19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_ps19 FROM v_sql_ps19;
        EXECUTE st_ps19;
        SELECT COUNT(*) INTO v_n_ps19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ps19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ps20]
    BEGIN
        DECLARE v_key_ps20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ps20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ps20' AS VARCHAR(40)), v_key_ps20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [ps21]
    BEGIN
        DECLARE v_so_ps21 INTEGER DEFAULT 0;
        DECLARE v_cust_ps21 INTEGER DEFAULT 0;
        DECLARE v_ctry_ps21 INTEGER DEFAULT 0;
        DECLARE v_ccy_ps21 INTEGER DEFAULT 0;
        DECLARE v_sub_ps21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ps21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ps21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ps21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ps21 INTEGER DEFAULT 0;
        DECLARE v_done_ps21 INTEGER DEFAULT 0;
        DECLARE c_ps21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps21 = 1;
        OPEN c_ps21;
        loop_ps21: LOOP
            FETCH c_ps21 INTO v_so_ps21, v_cust_ps21, v_ctry_ps21, v_ccy_ps21, v_sub_ps21;
            IF v_done_ps21 = 1 THEN LEAVE loop_ps21; END IF;
            SET v_tax_ps21 = ERP_FN_TAX(v_ctry_ps21, v_sub_ps21);
            SET v_fx_ps21 = ERP_FN_FX_CONVERT(v_ccy_ps21, 1, v_sub_ps21 + v_tax_ps21);
            SET v_acc_ps21 = v_acc_ps21 + v_fx_ps21;
            SET v_cnt_ps21 = v_cnt_ps21 + 1;
        END LOOP;
        CLOSE c_ps21;
        IF v_cnt_ps21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ps21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ps21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ps22]
    BEGIN
        DECLARE v_pid_ps22 INTEGER DEFAULT 0;
        DECLARE v_oh_ps22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ps22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ps22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ps22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ps22 INTEGER DEFAULT 0;
        DECLARE c_ps22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps22 = 1;
        OPEN c_ps22;
        loop_ps22: LOOP
            FETCH c_ps22 INTO v_pid_ps22, v_oh_ps22, v_cost_ps22;
            IF v_done_ps22 = 1 THEN LEAVE loop_ps22; END IF;
            SET v_avail_ps22 = ERP_FN_INVENTORY_ONHAND(v_pid_ps22);
            SET v_val_ps22 = v_val_ps22 + CAST(COALESCE(v_oh_ps22,0) * COALESCE(v_cost_ps22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ps22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ps22;
        END LOOP;
        CLOSE c_ps22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ps22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ps23]
    BEGIN
        DECLARE v_prod_ps23 INTEGER DEFAULT 0;
        DECLARE v_rm_ps23 INTEGER DEFAULT 0;
        DECLARE v_supp_ps23 INTEGER DEFAULT 0;
        DECLARE v_qper_ps23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ps23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ps23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ps23 INTEGER DEFAULT 0;
        DECLARE c_ps23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps23 = 1;
        OPEN c_ps23;
        loop_ps23: LOOP
            FETCH c_ps23 INTO v_prod_ps23, v_rm_ps23, v_supp_ps23, v_qper_ps23, v_uc_ps23;
            IF v_done_ps23 = 1 THEN LEAVE loop_ps23; END IF;
            SET v_roll_ps23 = v_roll_ps23 + COALESCE(v_qper_ps23,0) * COALESCE(v_uc_ps23,0);
        END LOOP;
        CLOSE c_ps23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ps23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ps24]
    BEGIN
        DECLARE v_acct_ps24 INTEGER DEFAULT 0;
        DECLARE v_deb_ps24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ps24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ps24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps24 INTEGER DEFAULT 0;
        DECLARE c_ps24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps24 = 1;
        OPEN c_ps24;
        loop_ps24: LOOP
            FETCH c_ps24 INTO v_acct_ps24, v_deb_ps24, v_cred_ps24;
            IF v_done_ps24 = 1 THEN LEAVE loop_ps24; END IF;
            SET v_net_ps24 = v_net_ps24 + (v_deb_ps24 - v_cred_ps24);
        END LOOP;
        CLOSE c_ps24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ps24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ps25]
    BEGIN
        DECLARE v_pid_ps25 INTEGER DEFAULT 0;
        DECLARE v_lp_ps25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ps25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ps25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ps25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ps25 INTEGER DEFAULT 0;
        DECLARE c_ps25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps25 = 1;
        OPEN c_ps25;
        loop_ps25: LOOP
            FETCH c_ps25 INTO v_pid_ps25, v_lp_ps25, v_pp_ps25;
            IF v_done_ps25 = 1 THEN LEAVE loop_ps25; END IF;
            SET v_var_ps25 = v_var_ps25 + (COALESCE(v_lp_ps25,0) - COALESCE(v_pp_ps25,0));
            SET v_marg_ps25 = ERP_FN_MARGIN(v_pid_ps25);
        END LOOP;
        CLOSE c_ps25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ps25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ps26]
    BEGIN
        DECLARE v_inv_ps26 INTEGER DEFAULT 0;
        DECLARE v_amt_ps26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ps26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ps26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps26 INTEGER DEFAULT 0;
        DECLARE c_ps26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps26 = 1;
        OPEN c_ps26;
        loop_ps26: LOOP
            FETCH c_ps26 INTO v_inv_ps26, v_amt_ps26, v_alloc_ps26;
            IF v_done_ps26 = 1 THEN LEAVE loop_ps26; END IF;
            SET v_open_ps26 = v_open_ps26 + (v_amt_ps26 - v_alloc_ps26);
        END LOOP;
        CLOSE c_ps26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ps26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ps27]
    BEGIN
        DECLARE v_lvl_ps27 INTEGER DEFAULT 0;
        DECLARE v_dept_ps27 INTEGER DEFAULT 0;
        DECLARE v_head_ps27 INTEGER DEFAULT 0;
        DECLARE v_done_ps27 INTEGER DEFAULT 0;
        DECLARE c_ps27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps27 = 1;
        OPEN c_ps27;
        loop_ps27: LOOP
            FETCH c_ps27 INTO v_dept_ps27, v_lvl_ps27, v_head_ps27;
            IF v_done_ps27 = 1 THEN LEAVE loop_ps27; END IF;
        END LOOP;
        CLOSE c_ps27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ps27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ps27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ps28]
    BEGIN
        DECLARE v_sh_ps28 INTEGER DEFAULT 0;
        DECLARE v_car_ps28 INTEGER DEFAULT 0;
        DECLARE v_qty_ps28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ps28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ps28 INTEGER DEFAULT 0;
        DECLARE c_ps28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps28 = 1;
        OPEN c_ps28;
        loop_ps28: LOOP
            FETCH c_ps28 INTO v_sh_ps28, v_car_ps28, v_qty_ps28;
            IF v_done_ps28 = 1 THEN LEAVE loop_ps28; END IF;
            SET v_tot_ps28 = v_tot_ps28 + v_qty_ps28;
        END LOOP;
        CLOSE c_ps28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ps28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ps29]
    BEGIN
        DECLARE v_sql_ps29 VARCHAR(1000);
        DECLARE v_n_ps29 INTEGER DEFAULT 0;
        SET v_sql_ps29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ps29 FROM v_sql_ps29;
        EXECUTE st_ps29;
        SELECT COUNT(*) INTO v_n_ps29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ps29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ps30]
    BEGIN
        DECLARE v_key_ps30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ps30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ps30' AS VARCHAR(40)), v_key_ps30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ps31]
    BEGIN
        DECLARE v_so_ps31 INTEGER DEFAULT 0;
        DECLARE v_cust_ps31 INTEGER DEFAULT 0;
        DECLARE v_rk_ps31 INTEGER DEFAULT 0;
        DECLARE v_run_ps31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps31 INTEGER DEFAULT 0;
        DECLARE c_ps31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps31 = 1;
        OPEN c_ps31;
        loop_ps31: LOOP
            FETCH c_ps31 INTO v_so_ps31, v_cust_ps31, v_rk_ps31, v_run_ps31;
            IF v_done_ps31 = 1 THEN LEAVE loop_ps31; END IF;
        END LOOP;
        CLOSE c_ps31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ps31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ps31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ps32]
    BEGIN
        DECLARE v_hi_ps32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ps32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ps32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ps33]
    BEGIN
        DECLARE v_pairs_ps33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ps33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ps33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ps34]
    BEGIN
        DECLARE v_rows_ps34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ps34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ps34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ps34 FROM SESSION.TMP_ps34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ps34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ps35]
    BEGIN
        DECLARE v_rc_ps35 INTEGER DEFAULT 0;
        DECLARE v_band_ps35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ps35 = ROW_COUNT;
        SET v_band_ps35 = CASE
                            WHEN v_rc_ps35 = 0 THEN 'NONE'
                            WHEN v_rc_ps35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ps35, 'COUNT', 'band=' || v_band_ps35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ps36]
    BEGIN
        DECLARE v_i_ps36 INTEGER DEFAULT 0;
        SAVEPOINT sp_ps36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ps36 < 4 DO
            SET v_i_ps36 = v_i_ps36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ps36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ps36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ps36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [ps37]
    BEGIN
        DECLARE v_j_ps37 INTEGER DEFAULT 0;
        DECLARE v_sum_ps37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_ps37 = v_j_ps37 + 1;
        UNTIL v_j_ps37 >= 3 END REPEAT;
        FOR row_ps37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_ps37 = v_sum_ps37 + COALESCE(row_ps37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_ps37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_ps37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [ps38]
    BEGIN
        DECLARE v_n_ps38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_ps38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_ps38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [ps39]
    BEGIN
        DECLARE v_levels_ps39 INTEGER DEFAULT 0;
        DECLARE c_ps39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_ps39 = 0;
        OPEN c_ps39;
        FETCH c_ps39 INTO v_levels_ps39;
        CLOSE c_ps39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_ps39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ps40]
    BEGIN
        DECLARE v_sql_ps40 VARCHAR(1000);
        DECLARE v_n_ps40 INTEGER DEFAULT 0;
        SET v_sql_ps40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_ps40 FROM v_sql_ps40;
        EXECUTE st_ps40;
        SELECT COUNT(*) INTO v_n_ps40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ps40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ps41]
    BEGIN
        DECLARE v_key_ps41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ps41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ps41' AS VARCHAR(40)), v_key_ps41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [ps42]
    BEGIN
        DECLARE v_so_ps42 INTEGER DEFAULT 0;
        DECLARE v_cust_ps42 INTEGER DEFAULT 0;
        DECLARE v_ctry_ps42 INTEGER DEFAULT 0;
        DECLARE v_ccy_ps42 INTEGER DEFAULT 0;
        DECLARE v_sub_ps42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_ps42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_ps42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_ps42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_ps42 INTEGER DEFAULT 0;
        DECLARE v_done_ps42 INTEGER DEFAULT 0;
        DECLARE c_ps42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps42 = 1;
        OPEN c_ps42;
        loop_ps42: LOOP
            FETCH c_ps42 INTO v_so_ps42, v_cust_ps42, v_ctry_ps42, v_ccy_ps42, v_sub_ps42;
            IF v_done_ps42 = 1 THEN LEAVE loop_ps42; END IF;
            SET v_tax_ps42 = ERP_FN_TAX(v_ctry_ps42, v_sub_ps42);
            SET v_fx_ps42 = ERP_FN_FX_CONVERT(v_ccy_ps42, 1, v_sub_ps42 + v_tax_ps42);
            SET v_acc_ps42 = v_acc_ps42 + v_fx_ps42;
            SET v_cnt_ps42 = v_cnt_ps42 + 1;
        END LOOP;
        CLOSE c_ps42;
        IF v_cnt_ps42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_ps42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_ps42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [ps43]
    BEGIN
        DECLARE v_pid_ps43 INTEGER DEFAULT 0;
        DECLARE v_oh_ps43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_ps43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_ps43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_ps43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ps43 INTEGER DEFAULT 0;
        DECLARE c_ps43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps43 = 1;
        OPEN c_ps43;
        loop_ps43: LOOP
            FETCH c_ps43 INTO v_pid_ps43, v_oh_ps43, v_cost_ps43;
            IF v_done_ps43 = 1 THEN LEAVE loop_ps43; END IF;
            SET v_avail_ps43 = ERP_FN_INVENTORY_ONHAND(v_pid_ps43);
            SET v_val_ps43 = v_val_ps43 + CAST(COALESCE(v_oh_ps43,0) * COALESCE(v_cost_ps43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_ps43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_ps43;
        END LOOP;
        CLOSE c_ps43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_ps43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [ps44]
    BEGIN
        DECLARE v_prod_ps44 INTEGER DEFAULT 0;
        DECLARE v_rm_ps44 INTEGER DEFAULT 0;
        DECLARE v_supp_ps44 INTEGER DEFAULT 0;
        DECLARE v_qper_ps44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_ps44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_ps44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ps44 INTEGER DEFAULT 0;
        DECLARE c_ps44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps44 = 1;
        OPEN c_ps44;
        loop_ps44: LOOP
            FETCH c_ps44 INTO v_prod_ps44, v_rm_ps44, v_supp_ps44, v_qper_ps44, v_uc_ps44;
            IF v_done_ps44 = 1 THEN LEAVE loop_ps44; END IF;
            SET v_roll_ps44 = v_roll_ps44 + COALESCE(v_qper_ps44,0) * COALESCE(v_uc_ps44,0);
        END LOOP;
        CLOSE c_ps44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_ps44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [ps45]
    BEGIN
        DECLARE v_acct_ps45 INTEGER DEFAULT 0;
        DECLARE v_deb_ps45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_ps45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_ps45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps45 INTEGER DEFAULT 0;
        DECLARE c_ps45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps45 = 1;
        OPEN c_ps45;
        loop_ps45: LOOP
            FETCH c_ps45 INTO v_acct_ps45, v_deb_ps45, v_cred_ps45;
            IF v_done_ps45 = 1 THEN LEAVE loop_ps45; END IF;
            SET v_net_ps45 = v_net_ps45 + (v_deb_ps45 - v_cred_ps45);
        END LOOP;
        CLOSE c_ps45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_ps45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [ps46]
    BEGIN
        DECLARE v_pid_ps46 INTEGER DEFAULT 0;
        DECLARE v_lp_ps46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_ps46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_ps46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_ps46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_ps46 INTEGER DEFAULT 0;
        DECLARE c_ps46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps46 = 1;
        OPEN c_ps46;
        loop_ps46: LOOP
            FETCH c_ps46 INTO v_pid_ps46, v_lp_ps46, v_pp_ps46;
            IF v_done_ps46 = 1 THEN LEAVE loop_ps46; END IF;
            SET v_var_ps46 = v_var_ps46 + (COALESCE(v_lp_ps46,0) - COALESCE(v_pp_ps46,0));
            SET v_marg_ps46 = ERP_FN_MARGIN(v_pid_ps46);
        END LOOP;
        CLOSE c_ps46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_ps46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [ps47]
    BEGIN
        DECLARE v_inv_ps47 INTEGER DEFAULT 0;
        DECLARE v_amt_ps47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_ps47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_ps47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps47 INTEGER DEFAULT 0;
        DECLARE c_ps47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps47 = 1;
        OPEN c_ps47;
        loop_ps47: LOOP
            FETCH c_ps47 INTO v_inv_ps47, v_amt_ps47, v_alloc_ps47;
            IF v_done_ps47 = 1 THEN LEAVE loop_ps47; END IF;
            SET v_open_ps47 = v_open_ps47 + (v_amt_ps47 - v_alloc_ps47);
        END LOOP;
        CLOSE c_ps47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_ps47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [ps48]
    BEGIN
        DECLARE v_lvl_ps48 INTEGER DEFAULT 0;
        DECLARE v_dept_ps48 INTEGER DEFAULT 0;
        DECLARE v_head_ps48 INTEGER DEFAULT 0;
        DECLARE v_done_ps48 INTEGER DEFAULT 0;
        DECLARE c_ps48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps48 = 1;
        OPEN c_ps48;
        loop_ps48: LOOP
            FETCH c_ps48 INTO v_dept_ps48, v_lvl_ps48, v_head_ps48;
            IF v_done_ps48 = 1 THEN LEAVE loop_ps48; END IF;
        END LOOP;
        CLOSE c_ps48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_ps48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_ps48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [ps49]
    BEGIN
        DECLARE v_sh_ps49 INTEGER DEFAULT 0;
        DECLARE v_car_ps49 INTEGER DEFAULT 0;
        DECLARE v_qty_ps49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_ps49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_ps49 INTEGER DEFAULT 0;
        DECLARE c_ps49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps49 = 1;
        OPEN c_ps49;
        loop_ps49: LOOP
            FETCH c_ps49 INTO v_sh_ps49, v_car_ps49, v_qty_ps49;
            IF v_done_ps49 = 1 THEN LEAVE loop_ps49; END IF;
            SET v_tot_ps49 = v_tot_ps49 + v_qty_ps49;
        END LOOP;
        CLOSE c_ps49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_ps49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [ps50]
    BEGIN
        DECLARE v_sql_ps50 VARCHAR(1000);
        DECLARE v_n_ps50 INTEGER DEFAULT 0;
        SET v_sql_ps50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_ps50 FROM v_sql_ps50;
        EXECUTE st_ps50;
        SELECT COUNT(*) INTO v_n_ps50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_ps50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [ps51]
    BEGIN
        DECLARE v_key_ps51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_ps51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_ps51' AS VARCHAR(40)), v_key_ps51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [ps52]
    BEGIN
        DECLARE v_so_ps52 INTEGER DEFAULT 0;
        DECLARE v_cust_ps52 INTEGER DEFAULT 0;
        DECLARE v_rk_ps52 INTEGER DEFAULT 0;
        DECLARE v_run_ps52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_ps52 INTEGER DEFAULT 0;
        DECLARE c_ps52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_ps52 = 1;
        OPEN c_ps52;
        loop_ps52: LOOP
            FETCH c_ps52 INTO v_so_ps52, v_cust_ps52, v_rk_ps52, v_run_ps52;
            IF v_done_ps52 = 1 THEN LEAVE loop_ps52; END IF;
        END LOOP;
        CLOSE c_ps52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_ps52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_ps52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [ps53]
    BEGIN
        DECLARE v_hi_ps53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_ps53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_ps53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [ps54]
    BEGIN
        DECLARE v_pairs_ps54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_ps54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_ps54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [ps55]
    BEGIN
        DECLARE v_rows_ps55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_ps55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_ps55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_ps55 FROM SESSION.TMP_ps55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_ps55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [ps56]
    BEGIN
        DECLARE v_rc_ps56 INTEGER DEFAULT 0;
        DECLARE v_band_ps56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_ps56 = ROW_COUNT;
        SET v_band_ps56 = CASE
                            WHEN v_rc_ps56 = 0 THEN 'NONE'
                            WHEN v_rc_ps56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_ps56, 'COUNT', 'band=' || v_band_ps56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [ps57]
    BEGIN
        DECLARE v_i_ps57 INTEGER DEFAULT 0;
        SAVEPOINT sp_ps57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_ps57 < 4 DO
            SET v_i_ps57 = v_i_ps57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_ps57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_ps57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_ps57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_RECONCILE_GL(IN p_period INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_net DECIMAL(18,2) DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('RECON', p_period, 'ERROR', 'reconcile failed');
    END;
    SELECT COALESCE(SUM(debit - credit),0) INTO v_net FROM ERP_GL_ENTRY;
    CALL ERP_USP_AUDIT('RECON', p_period, 'DONE', 'net=' || RTRIM(CHAR(CAST(v_net AS INTEGER))));
    -- order/customer/country/currency revenue scan [rg00]
    BEGIN
        DECLARE v_so_rg00 INTEGER DEFAULT 0;
        DECLARE v_cust_rg00 INTEGER DEFAULT 0;
        DECLARE v_ctry_rg00 INTEGER DEFAULT 0;
        DECLARE v_ccy_rg00 INTEGER DEFAULT 0;
        DECLARE v_sub_rg00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rg00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rg00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rg00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rg00 INTEGER DEFAULT 0;
        DECLARE v_done_rg00 INTEGER DEFAULT 0;
        DECLARE c_rg00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg00 = 1;
        OPEN c_rg00;
        loop_rg00: LOOP
            FETCH c_rg00 INTO v_so_rg00, v_cust_rg00, v_ctry_rg00, v_ccy_rg00, v_sub_rg00;
            IF v_done_rg00 = 1 THEN LEAVE loop_rg00; END IF;
            SET v_tax_rg00 = ERP_FN_TAX(v_ctry_rg00, v_sub_rg00);
            SET v_fx_rg00 = ERP_FN_FX_CONVERT(v_ccy_rg00, 1, v_sub_rg00 + v_tax_rg00);
            SET v_acc_rg00 = v_acc_rg00 + v_fx_rg00;
            SET v_cnt_rg00 = v_cnt_rg00 + 1;
        END LOOP;
        CLOSE c_rg00;
        IF v_cnt_rg00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rg00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rg00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rg01]
    BEGIN
        DECLARE v_pid_rg01 INTEGER DEFAULT 0;
        DECLARE v_oh_rg01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rg01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rg01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rg01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rg01 INTEGER DEFAULT 0;
        DECLARE c_rg01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg01 = 1;
        OPEN c_rg01;
        loop_rg01: LOOP
            FETCH c_rg01 INTO v_pid_rg01, v_oh_rg01, v_cost_rg01;
            IF v_done_rg01 = 1 THEN LEAVE loop_rg01; END IF;
            SET v_avail_rg01 = ERP_FN_INVENTORY_ONHAND(v_pid_rg01);
            SET v_val_rg01 = v_val_rg01 + CAST(COALESCE(v_oh_rg01,0) * COALESCE(v_cost_rg01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rg01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rg01;
        END LOOP;
        CLOSE c_rg01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rg01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rg02]
    BEGIN
        DECLARE v_prod_rg02 INTEGER DEFAULT 0;
        DECLARE v_rm_rg02 INTEGER DEFAULT 0;
        DECLARE v_supp_rg02 INTEGER DEFAULT 0;
        DECLARE v_qper_rg02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rg02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rg02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rg02 INTEGER DEFAULT 0;
        DECLARE c_rg02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg02 = 1;
        OPEN c_rg02;
        loop_rg02: LOOP
            FETCH c_rg02 INTO v_prod_rg02, v_rm_rg02, v_supp_rg02, v_qper_rg02, v_uc_rg02;
            IF v_done_rg02 = 1 THEN LEAVE loop_rg02; END IF;
            SET v_roll_rg02 = v_roll_rg02 + COALESCE(v_qper_rg02,0) * COALESCE(v_uc_rg02,0);
        END LOOP;
        CLOSE c_rg02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rg02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rg03]
    BEGIN
        DECLARE v_acct_rg03 INTEGER DEFAULT 0;
        DECLARE v_deb_rg03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rg03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rg03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg03 INTEGER DEFAULT 0;
        DECLARE c_rg03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg03 = 1;
        OPEN c_rg03;
        loop_rg03: LOOP
            FETCH c_rg03 INTO v_acct_rg03, v_deb_rg03, v_cred_rg03;
            IF v_done_rg03 = 1 THEN LEAVE loop_rg03; END IF;
            SET v_net_rg03 = v_net_rg03 + (v_deb_rg03 - v_cred_rg03);
        END LOOP;
        CLOSE c_rg03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rg03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rg04]
    BEGIN
        DECLARE v_pid_rg04 INTEGER DEFAULT 0;
        DECLARE v_lp_rg04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rg04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rg04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rg04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rg04 INTEGER DEFAULT 0;
        DECLARE c_rg04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg04 = 1;
        OPEN c_rg04;
        loop_rg04: LOOP
            FETCH c_rg04 INTO v_pid_rg04, v_lp_rg04, v_pp_rg04;
            IF v_done_rg04 = 1 THEN LEAVE loop_rg04; END IF;
            SET v_var_rg04 = v_var_rg04 + (COALESCE(v_lp_rg04,0) - COALESCE(v_pp_rg04,0));
            SET v_marg_rg04 = ERP_FN_MARGIN(v_pid_rg04);
        END LOOP;
        CLOSE c_rg04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rg04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rg05]
    BEGIN
        DECLARE v_inv_rg05 INTEGER DEFAULT 0;
        DECLARE v_amt_rg05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rg05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rg05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg05 INTEGER DEFAULT 0;
        DECLARE c_rg05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg05 = 1;
        OPEN c_rg05;
        loop_rg05: LOOP
            FETCH c_rg05 INTO v_inv_rg05, v_amt_rg05, v_alloc_rg05;
            IF v_done_rg05 = 1 THEN LEAVE loop_rg05; END IF;
            SET v_open_rg05 = v_open_rg05 + (v_amt_rg05 - v_alloc_rg05);
        END LOOP;
        CLOSE c_rg05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rg05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rg06]
    BEGIN
        DECLARE v_lvl_rg06 INTEGER DEFAULT 0;
        DECLARE v_dept_rg06 INTEGER DEFAULT 0;
        DECLARE v_head_rg06 INTEGER DEFAULT 0;
        DECLARE v_done_rg06 INTEGER DEFAULT 0;
        DECLARE c_rg06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg06 = 1;
        OPEN c_rg06;
        loop_rg06: LOOP
            FETCH c_rg06 INTO v_dept_rg06, v_lvl_rg06, v_head_rg06;
            IF v_done_rg06 = 1 THEN LEAVE loop_rg06; END IF;
        END LOOP;
        CLOSE c_rg06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rg06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rg06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rg07]
    BEGIN
        DECLARE v_sh_rg07 INTEGER DEFAULT 0;
        DECLARE v_car_rg07 INTEGER DEFAULT 0;
        DECLARE v_qty_rg07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rg07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rg07 INTEGER DEFAULT 0;
        DECLARE c_rg07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg07 = 1;
        OPEN c_rg07;
        loop_rg07: LOOP
            FETCH c_rg07 INTO v_sh_rg07, v_car_rg07, v_qty_rg07;
            IF v_done_rg07 = 1 THEN LEAVE loop_rg07; END IF;
            SET v_tot_rg07 = v_tot_rg07 + v_qty_rg07;
        END LOOP;
        CLOSE c_rg07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rg07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rg08]
    BEGIN
        DECLARE v_sql_rg08 VARCHAR(1000);
        DECLARE v_n_rg08 INTEGER DEFAULT 0;
        SET v_sql_rg08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rg08 FROM v_sql_rg08;
        EXECUTE st_rg08;
        SELECT COUNT(*) INTO v_n_rg08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rg08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rg09]
    BEGIN
        DECLARE v_key_rg09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rg09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rg09' AS VARCHAR(40)), v_key_rg09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rg10]
    BEGIN
        DECLARE v_so_rg10 INTEGER DEFAULT 0;
        DECLARE v_cust_rg10 INTEGER DEFAULT 0;
        DECLARE v_rk_rg10 INTEGER DEFAULT 0;
        DECLARE v_run_rg10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg10 INTEGER DEFAULT 0;
        DECLARE c_rg10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg10 = 1;
        OPEN c_rg10;
        loop_rg10: LOOP
            FETCH c_rg10 INTO v_so_rg10, v_cust_rg10, v_rk_rg10, v_run_rg10;
            IF v_done_rg10 = 1 THEN LEAVE loop_rg10; END IF;
        END LOOP;
        CLOSE c_rg10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rg10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rg10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rg11]
    BEGIN
        DECLARE v_hi_rg11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rg11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rg11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rg12]
    BEGIN
        DECLARE v_pairs_rg12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rg12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rg12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rg13]
    BEGIN
        DECLARE v_rows_rg13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rg13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rg13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rg13 FROM SESSION.TMP_rg13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rg13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rg14]
    BEGIN
        DECLARE v_rc_rg14 INTEGER DEFAULT 0;
        DECLARE v_band_rg14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rg14 = ROW_COUNT;
        SET v_band_rg14 = CASE
                            WHEN v_rc_rg14 = 0 THEN 'NONE'
                            WHEN v_rc_rg14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rg14, 'COUNT', 'band=' || v_band_rg14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rg15]
    BEGIN
        DECLARE v_i_rg15 INTEGER DEFAULT 0;
        SAVEPOINT sp_rg15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rg15 < 4 DO
            SET v_i_rg15 = v_i_rg15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rg15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rg15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rg15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rg16]
    BEGIN
        DECLARE v_j_rg16 INTEGER DEFAULT 0;
        DECLARE v_sum_rg16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rg16 = v_j_rg16 + 1;
        UNTIL v_j_rg16 >= 3 END REPEAT;
        FOR row_rg16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rg16 = v_sum_rg16 + COALESCE(row_rg16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rg16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rg16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rg17]
    BEGIN
        DECLARE v_n_rg17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rg17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rg17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rg18]
    BEGIN
        DECLARE v_levels_rg18 INTEGER DEFAULT 0;
        DECLARE c_rg18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rg18 = 0;
        OPEN c_rg18;
        FETCH c_rg18 INTO v_levels_rg18;
        CLOSE c_rg18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rg18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rg19]
    BEGIN
        DECLARE v_sql_rg19 VARCHAR(1000);
        DECLARE v_n_rg19 INTEGER DEFAULT 0;
        SET v_sql_rg19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rg19 FROM v_sql_rg19;
        EXECUTE st_rg19;
        SELECT COUNT(*) INTO v_n_rg19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rg19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rg20]
    BEGIN
        DECLARE v_key_rg20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rg20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rg20' AS VARCHAR(40)), v_key_rg20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rg21]
    BEGIN
        DECLARE v_so_rg21 INTEGER DEFAULT 0;
        DECLARE v_cust_rg21 INTEGER DEFAULT 0;
        DECLARE v_ctry_rg21 INTEGER DEFAULT 0;
        DECLARE v_ccy_rg21 INTEGER DEFAULT 0;
        DECLARE v_sub_rg21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rg21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rg21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rg21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rg21 INTEGER DEFAULT 0;
        DECLARE v_done_rg21 INTEGER DEFAULT 0;
        DECLARE c_rg21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg21 = 1;
        OPEN c_rg21;
        loop_rg21: LOOP
            FETCH c_rg21 INTO v_so_rg21, v_cust_rg21, v_ctry_rg21, v_ccy_rg21, v_sub_rg21;
            IF v_done_rg21 = 1 THEN LEAVE loop_rg21; END IF;
            SET v_tax_rg21 = ERP_FN_TAX(v_ctry_rg21, v_sub_rg21);
            SET v_fx_rg21 = ERP_FN_FX_CONVERT(v_ccy_rg21, 1, v_sub_rg21 + v_tax_rg21);
            SET v_acc_rg21 = v_acc_rg21 + v_fx_rg21;
            SET v_cnt_rg21 = v_cnt_rg21 + 1;
        END LOOP;
        CLOSE c_rg21;
        IF v_cnt_rg21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rg21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rg21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rg22]
    BEGIN
        DECLARE v_pid_rg22 INTEGER DEFAULT 0;
        DECLARE v_oh_rg22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rg22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rg22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rg22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rg22 INTEGER DEFAULT 0;
        DECLARE c_rg22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg22 = 1;
        OPEN c_rg22;
        loop_rg22: LOOP
            FETCH c_rg22 INTO v_pid_rg22, v_oh_rg22, v_cost_rg22;
            IF v_done_rg22 = 1 THEN LEAVE loop_rg22; END IF;
            SET v_avail_rg22 = ERP_FN_INVENTORY_ONHAND(v_pid_rg22);
            SET v_val_rg22 = v_val_rg22 + CAST(COALESCE(v_oh_rg22,0) * COALESCE(v_cost_rg22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rg22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rg22;
        END LOOP;
        CLOSE c_rg22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rg22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rg23]
    BEGIN
        DECLARE v_prod_rg23 INTEGER DEFAULT 0;
        DECLARE v_rm_rg23 INTEGER DEFAULT 0;
        DECLARE v_supp_rg23 INTEGER DEFAULT 0;
        DECLARE v_qper_rg23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rg23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rg23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rg23 INTEGER DEFAULT 0;
        DECLARE c_rg23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg23 = 1;
        OPEN c_rg23;
        loop_rg23: LOOP
            FETCH c_rg23 INTO v_prod_rg23, v_rm_rg23, v_supp_rg23, v_qper_rg23, v_uc_rg23;
            IF v_done_rg23 = 1 THEN LEAVE loop_rg23; END IF;
            SET v_roll_rg23 = v_roll_rg23 + COALESCE(v_qper_rg23,0) * COALESCE(v_uc_rg23,0);
        END LOOP;
        CLOSE c_rg23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rg23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rg24]
    BEGIN
        DECLARE v_acct_rg24 INTEGER DEFAULT 0;
        DECLARE v_deb_rg24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rg24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rg24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg24 INTEGER DEFAULT 0;
        DECLARE c_rg24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg24 = 1;
        OPEN c_rg24;
        loop_rg24: LOOP
            FETCH c_rg24 INTO v_acct_rg24, v_deb_rg24, v_cred_rg24;
            IF v_done_rg24 = 1 THEN LEAVE loop_rg24; END IF;
            SET v_net_rg24 = v_net_rg24 + (v_deb_rg24 - v_cred_rg24);
        END LOOP;
        CLOSE c_rg24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rg24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rg25]
    BEGIN
        DECLARE v_pid_rg25 INTEGER DEFAULT 0;
        DECLARE v_lp_rg25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rg25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rg25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rg25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rg25 INTEGER DEFAULT 0;
        DECLARE c_rg25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg25 = 1;
        OPEN c_rg25;
        loop_rg25: LOOP
            FETCH c_rg25 INTO v_pid_rg25, v_lp_rg25, v_pp_rg25;
            IF v_done_rg25 = 1 THEN LEAVE loop_rg25; END IF;
            SET v_var_rg25 = v_var_rg25 + (COALESCE(v_lp_rg25,0) - COALESCE(v_pp_rg25,0));
            SET v_marg_rg25 = ERP_FN_MARGIN(v_pid_rg25);
        END LOOP;
        CLOSE c_rg25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rg25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rg26]
    BEGIN
        DECLARE v_inv_rg26 INTEGER DEFAULT 0;
        DECLARE v_amt_rg26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rg26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rg26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg26 INTEGER DEFAULT 0;
        DECLARE c_rg26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg26 = 1;
        OPEN c_rg26;
        loop_rg26: LOOP
            FETCH c_rg26 INTO v_inv_rg26, v_amt_rg26, v_alloc_rg26;
            IF v_done_rg26 = 1 THEN LEAVE loop_rg26; END IF;
            SET v_open_rg26 = v_open_rg26 + (v_amt_rg26 - v_alloc_rg26);
        END LOOP;
        CLOSE c_rg26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rg26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rg27]
    BEGIN
        DECLARE v_lvl_rg27 INTEGER DEFAULT 0;
        DECLARE v_dept_rg27 INTEGER DEFAULT 0;
        DECLARE v_head_rg27 INTEGER DEFAULT 0;
        DECLARE v_done_rg27 INTEGER DEFAULT 0;
        DECLARE c_rg27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg27 = 1;
        OPEN c_rg27;
        loop_rg27: LOOP
            FETCH c_rg27 INTO v_dept_rg27, v_lvl_rg27, v_head_rg27;
            IF v_done_rg27 = 1 THEN LEAVE loop_rg27; END IF;
        END LOOP;
        CLOSE c_rg27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rg27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rg27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rg28]
    BEGIN
        DECLARE v_sh_rg28 INTEGER DEFAULT 0;
        DECLARE v_car_rg28 INTEGER DEFAULT 0;
        DECLARE v_qty_rg28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rg28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rg28 INTEGER DEFAULT 0;
        DECLARE c_rg28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg28 = 1;
        OPEN c_rg28;
        loop_rg28: LOOP
            FETCH c_rg28 INTO v_sh_rg28, v_car_rg28, v_qty_rg28;
            IF v_done_rg28 = 1 THEN LEAVE loop_rg28; END IF;
            SET v_tot_rg28 = v_tot_rg28 + v_qty_rg28;
        END LOOP;
        CLOSE c_rg28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rg28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rg29]
    BEGIN
        DECLARE v_sql_rg29 VARCHAR(1000);
        DECLARE v_n_rg29 INTEGER DEFAULT 0;
        SET v_sql_rg29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rg29 FROM v_sql_rg29;
        EXECUTE st_rg29;
        SELECT COUNT(*) INTO v_n_rg29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rg29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rg30]
    BEGIN
        DECLARE v_key_rg30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rg30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rg30' AS VARCHAR(40)), v_key_rg30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rg31]
    BEGIN
        DECLARE v_so_rg31 INTEGER DEFAULT 0;
        DECLARE v_cust_rg31 INTEGER DEFAULT 0;
        DECLARE v_rk_rg31 INTEGER DEFAULT 0;
        DECLARE v_run_rg31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg31 INTEGER DEFAULT 0;
        DECLARE c_rg31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg31 = 1;
        OPEN c_rg31;
        loop_rg31: LOOP
            FETCH c_rg31 INTO v_so_rg31, v_cust_rg31, v_rk_rg31, v_run_rg31;
            IF v_done_rg31 = 1 THEN LEAVE loop_rg31; END IF;
        END LOOP;
        CLOSE c_rg31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rg31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rg31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rg32]
    BEGIN
        DECLARE v_hi_rg32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rg32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rg32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rg33]
    BEGIN
        DECLARE v_pairs_rg33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rg33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rg33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rg34]
    BEGIN
        DECLARE v_rows_rg34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rg34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rg34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rg34 FROM SESSION.TMP_rg34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rg34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rg35]
    BEGIN
        DECLARE v_rc_rg35 INTEGER DEFAULT 0;
        DECLARE v_band_rg35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rg35 = ROW_COUNT;
        SET v_band_rg35 = CASE
                            WHEN v_rc_rg35 = 0 THEN 'NONE'
                            WHEN v_rc_rg35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rg35, 'COUNT', 'band=' || v_band_rg35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rg36]
    BEGIN
        DECLARE v_i_rg36 INTEGER DEFAULT 0;
        SAVEPOINT sp_rg36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rg36 < 4 DO
            SET v_i_rg36 = v_i_rg36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rg36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rg36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rg36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rg37]
    BEGIN
        DECLARE v_j_rg37 INTEGER DEFAULT 0;
        DECLARE v_sum_rg37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rg37 = v_j_rg37 + 1;
        UNTIL v_j_rg37 >= 3 END REPEAT;
        FOR row_rg37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rg37 = v_sum_rg37 + COALESCE(row_rg37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rg37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rg37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rg38]
    BEGIN
        DECLARE v_n_rg38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rg38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rg38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rg39]
    BEGIN
        DECLARE v_levels_rg39 INTEGER DEFAULT 0;
        DECLARE c_rg39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rg39 = 0;
        OPEN c_rg39;
        FETCH c_rg39 INTO v_levels_rg39;
        CLOSE c_rg39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rg39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rg40]
    BEGIN
        DECLARE v_sql_rg40 VARCHAR(1000);
        DECLARE v_n_rg40 INTEGER DEFAULT 0;
        SET v_sql_rg40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rg40 FROM v_sql_rg40;
        EXECUTE st_rg40;
        SELECT COUNT(*) INTO v_n_rg40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rg40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rg41]
    BEGIN
        DECLARE v_key_rg41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rg41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rg41' AS VARCHAR(40)), v_key_rg41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rg42]
    BEGIN
        DECLARE v_so_rg42 INTEGER DEFAULT 0;
        DECLARE v_cust_rg42 INTEGER DEFAULT 0;
        DECLARE v_ctry_rg42 INTEGER DEFAULT 0;
        DECLARE v_ccy_rg42 INTEGER DEFAULT 0;
        DECLARE v_sub_rg42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rg42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rg42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rg42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rg42 INTEGER DEFAULT 0;
        DECLARE v_done_rg42 INTEGER DEFAULT 0;
        DECLARE c_rg42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg42 = 1;
        OPEN c_rg42;
        loop_rg42: LOOP
            FETCH c_rg42 INTO v_so_rg42, v_cust_rg42, v_ctry_rg42, v_ccy_rg42, v_sub_rg42;
            IF v_done_rg42 = 1 THEN LEAVE loop_rg42; END IF;
            SET v_tax_rg42 = ERP_FN_TAX(v_ctry_rg42, v_sub_rg42);
            SET v_fx_rg42 = ERP_FN_FX_CONVERT(v_ccy_rg42, 1, v_sub_rg42 + v_tax_rg42);
            SET v_acc_rg42 = v_acc_rg42 + v_fx_rg42;
            SET v_cnt_rg42 = v_cnt_rg42 + 1;
        END LOOP;
        CLOSE c_rg42;
        IF v_cnt_rg42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rg42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rg42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rg43]
    BEGIN
        DECLARE v_pid_rg43 INTEGER DEFAULT 0;
        DECLARE v_oh_rg43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rg43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rg43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rg43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rg43 INTEGER DEFAULT 0;
        DECLARE c_rg43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg43 = 1;
        OPEN c_rg43;
        loop_rg43: LOOP
            FETCH c_rg43 INTO v_pid_rg43, v_oh_rg43, v_cost_rg43;
            IF v_done_rg43 = 1 THEN LEAVE loop_rg43; END IF;
            SET v_avail_rg43 = ERP_FN_INVENTORY_ONHAND(v_pid_rg43);
            SET v_val_rg43 = v_val_rg43 + CAST(COALESCE(v_oh_rg43,0) * COALESCE(v_cost_rg43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rg43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rg43;
        END LOOP;
        CLOSE c_rg43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rg43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rg44]
    BEGIN
        DECLARE v_prod_rg44 INTEGER DEFAULT 0;
        DECLARE v_rm_rg44 INTEGER DEFAULT 0;
        DECLARE v_supp_rg44 INTEGER DEFAULT 0;
        DECLARE v_qper_rg44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rg44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rg44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rg44 INTEGER DEFAULT 0;
        DECLARE c_rg44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg44 = 1;
        OPEN c_rg44;
        loop_rg44: LOOP
            FETCH c_rg44 INTO v_prod_rg44, v_rm_rg44, v_supp_rg44, v_qper_rg44, v_uc_rg44;
            IF v_done_rg44 = 1 THEN LEAVE loop_rg44; END IF;
            SET v_roll_rg44 = v_roll_rg44 + COALESCE(v_qper_rg44,0) * COALESCE(v_uc_rg44,0);
        END LOOP;
        CLOSE c_rg44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rg44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rg45]
    BEGIN
        DECLARE v_acct_rg45 INTEGER DEFAULT 0;
        DECLARE v_deb_rg45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rg45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rg45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg45 INTEGER DEFAULT 0;
        DECLARE c_rg45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg45 = 1;
        OPEN c_rg45;
        loop_rg45: LOOP
            FETCH c_rg45 INTO v_acct_rg45, v_deb_rg45, v_cred_rg45;
            IF v_done_rg45 = 1 THEN LEAVE loop_rg45; END IF;
            SET v_net_rg45 = v_net_rg45 + (v_deb_rg45 - v_cred_rg45);
        END LOOP;
        CLOSE c_rg45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rg45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rg46]
    BEGIN
        DECLARE v_pid_rg46 INTEGER DEFAULT 0;
        DECLARE v_lp_rg46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rg46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rg46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rg46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rg46 INTEGER DEFAULT 0;
        DECLARE c_rg46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg46 = 1;
        OPEN c_rg46;
        loop_rg46: LOOP
            FETCH c_rg46 INTO v_pid_rg46, v_lp_rg46, v_pp_rg46;
            IF v_done_rg46 = 1 THEN LEAVE loop_rg46; END IF;
            SET v_var_rg46 = v_var_rg46 + (COALESCE(v_lp_rg46,0) - COALESCE(v_pp_rg46,0));
            SET v_marg_rg46 = ERP_FN_MARGIN(v_pid_rg46);
        END LOOP;
        CLOSE c_rg46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rg46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rg47]
    BEGIN
        DECLARE v_inv_rg47 INTEGER DEFAULT 0;
        DECLARE v_amt_rg47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rg47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rg47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg47 INTEGER DEFAULT 0;
        DECLARE c_rg47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg47 = 1;
        OPEN c_rg47;
        loop_rg47: LOOP
            FETCH c_rg47 INTO v_inv_rg47, v_amt_rg47, v_alloc_rg47;
            IF v_done_rg47 = 1 THEN LEAVE loop_rg47; END IF;
            SET v_open_rg47 = v_open_rg47 + (v_amt_rg47 - v_alloc_rg47);
        END LOOP;
        CLOSE c_rg47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rg47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rg48]
    BEGIN
        DECLARE v_lvl_rg48 INTEGER DEFAULT 0;
        DECLARE v_dept_rg48 INTEGER DEFAULT 0;
        DECLARE v_head_rg48 INTEGER DEFAULT 0;
        DECLARE v_done_rg48 INTEGER DEFAULT 0;
        DECLARE c_rg48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg48 = 1;
        OPEN c_rg48;
        loop_rg48: LOOP
            FETCH c_rg48 INTO v_dept_rg48, v_lvl_rg48, v_head_rg48;
            IF v_done_rg48 = 1 THEN LEAVE loop_rg48; END IF;
        END LOOP;
        CLOSE c_rg48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rg48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rg48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rg49]
    BEGIN
        DECLARE v_sh_rg49 INTEGER DEFAULT 0;
        DECLARE v_car_rg49 INTEGER DEFAULT 0;
        DECLARE v_qty_rg49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rg49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rg49 INTEGER DEFAULT 0;
        DECLARE c_rg49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg49 = 1;
        OPEN c_rg49;
        loop_rg49: LOOP
            FETCH c_rg49 INTO v_sh_rg49, v_car_rg49, v_qty_rg49;
            IF v_done_rg49 = 1 THEN LEAVE loop_rg49; END IF;
            SET v_tot_rg49 = v_tot_rg49 + v_qty_rg49;
        END LOOP;
        CLOSE c_rg49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rg49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rg50]
    BEGIN
        DECLARE v_sql_rg50 VARCHAR(1000);
        DECLARE v_n_rg50 INTEGER DEFAULT 0;
        SET v_sql_rg50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rg50 FROM v_sql_rg50;
        EXECUTE st_rg50;
        SELECT COUNT(*) INTO v_n_rg50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rg50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rg51]
    BEGIN
        DECLARE v_key_rg51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rg51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rg51' AS VARCHAR(40)), v_key_rg51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rg52]
    BEGIN
        DECLARE v_so_rg52 INTEGER DEFAULT 0;
        DECLARE v_cust_rg52 INTEGER DEFAULT 0;
        DECLARE v_rk_rg52 INTEGER DEFAULT 0;
        DECLARE v_run_rg52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rg52 INTEGER DEFAULT 0;
        DECLARE c_rg52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rg52 = 1;
        OPEN c_rg52;
        loop_rg52: LOOP
            FETCH c_rg52 INTO v_so_rg52, v_cust_rg52, v_rk_rg52, v_run_rg52;
            IF v_done_rg52 = 1 THEN LEAVE loop_rg52; END IF;
        END LOOP;
        CLOSE c_rg52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rg52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rg52)), CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_PROCESS_DAY(IN p_run_date DATE)
LANGUAGE SQL
BEGIN
    DECLARE v_count INTEGER DEFAULT 0;
    DECLARE v_period INTEGER DEFAULT 0;
    SET v_period = ERP_FN_FISCAL_PERIOD(p_run_date);
    SELECT COUNT(*) INTO v_count FROM ERP_SALES_ORDER WHERE status = 'NEW';
    CALL ERP_USP_AUDIT('CYCLE', v_period, 'START', 'Processing ' || RTRIM(CHAR(v_count)) || ' orders');
    CALL ERP_USP_PROCESS_ORDERS();
    -- order/customer/country/currency revenue scan [pd00]
    BEGIN
        DECLARE v_so_pd00 INTEGER DEFAULT 0;
        DECLARE v_cust_pd00 INTEGER DEFAULT 0;
        DECLARE v_ctry_pd00 INTEGER DEFAULT 0;
        DECLARE v_ccy_pd00 INTEGER DEFAULT 0;
        DECLARE v_sub_pd00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pd00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pd00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pd00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pd00 INTEGER DEFAULT 0;
        DECLARE v_done_pd00 INTEGER DEFAULT 0;
        DECLARE c_pd00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd00 = 1;
        OPEN c_pd00;
        loop_pd00: LOOP
            FETCH c_pd00 INTO v_so_pd00, v_cust_pd00, v_ctry_pd00, v_ccy_pd00, v_sub_pd00;
            IF v_done_pd00 = 1 THEN LEAVE loop_pd00; END IF;
            SET v_tax_pd00 = ERP_FN_TAX(v_ctry_pd00, v_sub_pd00);
            SET v_fx_pd00 = ERP_FN_FX_CONVERT(v_ccy_pd00, 1, v_sub_pd00 + v_tax_pd00);
            SET v_acc_pd00 = v_acc_pd00 + v_fx_pd00;
            SET v_cnt_pd00 = v_cnt_pd00 + 1;
        END LOOP;
        CLOSE c_pd00;
        IF v_cnt_pd00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pd00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pd00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pd01]
    BEGIN
        DECLARE v_pid_pd01 INTEGER DEFAULT 0;
        DECLARE v_oh_pd01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pd01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pd01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pd01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pd01 INTEGER DEFAULT 0;
        DECLARE c_pd01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd01 = 1;
        OPEN c_pd01;
        loop_pd01: LOOP
            FETCH c_pd01 INTO v_pid_pd01, v_oh_pd01, v_cost_pd01;
            IF v_done_pd01 = 1 THEN LEAVE loop_pd01; END IF;
            SET v_avail_pd01 = ERP_FN_INVENTORY_ONHAND(v_pid_pd01);
            SET v_val_pd01 = v_val_pd01 + CAST(COALESCE(v_oh_pd01,0) * COALESCE(v_cost_pd01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pd01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pd01;
        END LOOP;
        CLOSE c_pd01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pd01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pd02]
    BEGIN
        DECLARE v_prod_pd02 INTEGER DEFAULT 0;
        DECLARE v_rm_pd02 INTEGER DEFAULT 0;
        DECLARE v_supp_pd02 INTEGER DEFAULT 0;
        DECLARE v_qper_pd02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pd02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pd02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pd02 INTEGER DEFAULT 0;
        DECLARE c_pd02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd02 = 1;
        OPEN c_pd02;
        loop_pd02: LOOP
            FETCH c_pd02 INTO v_prod_pd02, v_rm_pd02, v_supp_pd02, v_qper_pd02, v_uc_pd02;
            IF v_done_pd02 = 1 THEN LEAVE loop_pd02; END IF;
            SET v_roll_pd02 = v_roll_pd02 + COALESCE(v_qper_pd02,0) * COALESCE(v_uc_pd02,0);
        END LOOP;
        CLOSE c_pd02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pd02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pd03]
    BEGIN
        DECLARE v_acct_pd03 INTEGER DEFAULT 0;
        DECLARE v_deb_pd03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pd03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pd03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd03 INTEGER DEFAULT 0;
        DECLARE c_pd03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd03 = 1;
        OPEN c_pd03;
        loop_pd03: LOOP
            FETCH c_pd03 INTO v_acct_pd03, v_deb_pd03, v_cred_pd03;
            IF v_done_pd03 = 1 THEN LEAVE loop_pd03; END IF;
            SET v_net_pd03 = v_net_pd03 + (v_deb_pd03 - v_cred_pd03);
        END LOOP;
        CLOSE c_pd03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pd03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pd04]
    BEGIN
        DECLARE v_pid_pd04 INTEGER DEFAULT 0;
        DECLARE v_lp_pd04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pd04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pd04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pd04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pd04 INTEGER DEFAULT 0;
        DECLARE c_pd04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd04 = 1;
        OPEN c_pd04;
        loop_pd04: LOOP
            FETCH c_pd04 INTO v_pid_pd04, v_lp_pd04, v_pp_pd04;
            IF v_done_pd04 = 1 THEN LEAVE loop_pd04; END IF;
            SET v_var_pd04 = v_var_pd04 + (COALESCE(v_lp_pd04,0) - COALESCE(v_pp_pd04,0));
            SET v_marg_pd04 = ERP_FN_MARGIN(v_pid_pd04);
        END LOOP;
        CLOSE c_pd04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pd04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pd05]
    BEGIN
        DECLARE v_inv_pd05 INTEGER DEFAULT 0;
        DECLARE v_amt_pd05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pd05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pd05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd05 INTEGER DEFAULT 0;
        DECLARE c_pd05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd05 = 1;
        OPEN c_pd05;
        loop_pd05: LOOP
            FETCH c_pd05 INTO v_inv_pd05, v_amt_pd05, v_alloc_pd05;
            IF v_done_pd05 = 1 THEN LEAVE loop_pd05; END IF;
            SET v_open_pd05 = v_open_pd05 + (v_amt_pd05 - v_alloc_pd05);
        END LOOP;
        CLOSE c_pd05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pd05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pd06]
    BEGIN
        DECLARE v_lvl_pd06 INTEGER DEFAULT 0;
        DECLARE v_dept_pd06 INTEGER DEFAULT 0;
        DECLARE v_head_pd06 INTEGER DEFAULT 0;
        DECLARE v_done_pd06 INTEGER DEFAULT 0;
        DECLARE c_pd06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd06 = 1;
        OPEN c_pd06;
        loop_pd06: LOOP
            FETCH c_pd06 INTO v_dept_pd06, v_lvl_pd06, v_head_pd06;
            IF v_done_pd06 = 1 THEN LEAVE loop_pd06; END IF;
        END LOOP;
        CLOSE c_pd06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pd06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pd06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pd07]
    BEGIN
        DECLARE v_sh_pd07 INTEGER DEFAULT 0;
        DECLARE v_car_pd07 INTEGER DEFAULT 0;
        DECLARE v_qty_pd07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pd07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pd07 INTEGER DEFAULT 0;
        DECLARE c_pd07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd07 = 1;
        OPEN c_pd07;
        loop_pd07: LOOP
            FETCH c_pd07 INTO v_sh_pd07, v_car_pd07, v_qty_pd07;
            IF v_done_pd07 = 1 THEN LEAVE loop_pd07; END IF;
            SET v_tot_pd07 = v_tot_pd07 + v_qty_pd07;
        END LOOP;
        CLOSE c_pd07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pd07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pd08]
    BEGIN
        DECLARE v_sql_pd08 VARCHAR(1000);
        DECLARE v_n_pd08 INTEGER DEFAULT 0;
        SET v_sql_pd08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pd08 FROM v_sql_pd08;
        EXECUTE st_pd08;
        SELECT COUNT(*) INTO v_n_pd08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pd08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pd09]
    BEGIN
        DECLARE v_key_pd09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pd09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pd09' AS VARCHAR(40)), v_key_pd09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pd10]
    BEGIN
        DECLARE v_so_pd10 INTEGER DEFAULT 0;
        DECLARE v_cust_pd10 INTEGER DEFAULT 0;
        DECLARE v_rk_pd10 INTEGER DEFAULT 0;
        DECLARE v_run_pd10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd10 INTEGER DEFAULT 0;
        DECLARE c_pd10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd10 = 1;
        OPEN c_pd10;
        loop_pd10: LOOP
            FETCH c_pd10 INTO v_so_pd10, v_cust_pd10, v_rk_pd10, v_run_pd10;
            IF v_done_pd10 = 1 THEN LEAVE loop_pd10; END IF;
        END LOOP;
        CLOSE c_pd10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pd10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pd10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [pd11]
    BEGIN
        DECLARE v_hi_pd11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_pd11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_pd11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [pd12]
    BEGIN
        DECLARE v_pairs_pd12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_pd12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_pd12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [pd13]
    BEGIN
        DECLARE v_rows_pd13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_pd13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_pd13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_pd13 FROM SESSION.TMP_pd13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_pd13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [pd14]
    BEGIN
        DECLARE v_rc_pd14 INTEGER DEFAULT 0;
        DECLARE v_band_pd14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_pd14 = ROW_COUNT;
        SET v_band_pd14 = CASE
                            WHEN v_rc_pd14 = 0 THEN 'NONE'
                            WHEN v_rc_pd14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_pd14, 'COUNT', 'band=' || v_band_pd14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [pd15]
    BEGIN
        DECLARE v_i_pd15 INTEGER DEFAULT 0;
        SAVEPOINT sp_pd15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_pd15 < 4 DO
            SET v_i_pd15 = v_i_pd15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_pd15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_pd15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_pd15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [pd16]
    BEGIN
        DECLARE v_j_pd16 INTEGER DEFAULT 0;
        DECLARE v_sum_pd16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_pd16 = v_j_pd16 + 1;
        UNTIL v_j_pd16 >= 3 END REPEAT;
        FOR row_pd16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_pd16 = v_sum_pd16 + COALESCE(row_pd16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_pd16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_pd16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [pd17]
    BEGIN
        DECLARE v_n_pd17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_pd17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_pd17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [pd18]
    BEGIN
        DECLARE v_levels_pd18 INTEGER DEFAULT 0;
        DECLARE c_pd18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_pd18 = 0;
        OPEN c_pd18;
        FETCH c_pd18 INTO v_levels_pd18;
        CLOSE c_pd18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_pd18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pd19]
    BEGIN
        DECLARE v_sql_pd19 VARCHAR(1000);
        DECLARE v_n_pd19 INTEGER DEFAULT 0;
        SET v_sql_pd19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_pd19 FROM v_sql_pd19;
        EXECUTE st_pd19;
        SELECT COUNT(*) INTO v_n_pd19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pd19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pd20]
    BEGIN
        DECLARE v_key_pd20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pd20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pd20' AS VARCHAR(40)), v_key_pd20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [pd21]
    BEGIN
        DECLARE v_so_pd21 INTEGER DEFAULT 0;
        DECLARE v_cust_pd21 INTEGER DEFAULT 0;
        DECLARE v_ctry_pd21 INTEGER DEFAULT 0;
        DECLARE v_ccy_pd21 INTEGER DEFAULT 0;
        DECLARE v_sub_pd21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pd21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pd21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pd21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pd21 INTEGER DEFAULT 0;
        DECLARE v_done_pd21 INTEGER DEFAULT 0;
        DECLARE c_pd21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd21 = 1;
        OPEN c_pd21;
        loop_pd21: LOOP
            FETCH c_pd21 INTO v_so_pd21, v_cust_pd21, v_ctry_pd21, v_ccy_pd21, v_sub_pd21;
            IF v_done_pd21 = 1 THEN LEAVE loop_pd21; END IF;
            SET v_tax_pd21 = ERP_FN_TAX(v_ctry_pd21, v_sub_pd21);
            SET v_fx_pd21 = ERP_FN_FX_CONVERT(v_ccy_pd21, 1, v_sub_pd21 + v_tax_pd21);
            SET v_acc_pd21 = v_acc_pd21 + v_fx_pd21;
            SET v_cnt_pd21 = v_cnt_pd21 + 1;
        END LOOP;
        CLOSE c_pd21;
        IF v_cnt_pd21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pd21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pd21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pd22]
    BEGIN
        DECLARE v_pid_pd22 INTEGER DEFAULT 0;
        DECLARE v_oh_pd22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pd22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pd22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pd22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pd22 INTEGER DEFAULT 0;
        DECLARE c_pd22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd22 = 1;
        OPEN c_pd22;
        loop_pd22: LOOP
            FETCH c_pd22 INTO v_pid_pd22, v_oh_pd22, v_cost_pd22;
            IF v_done_pd22 = 1 THEN LEAVE loop_pd22; END IF;
            SET v_avail_pd22 = ERP_FN_INVENTORY_ONHAND(v_pid_pd22);
            SET v_val_pd22 = v_val_pd22 + CAST(COALESCE(v_oh_pd22,0) * COALESCE(v_cost_pd22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pd22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pd22;
        END LOOP;
        CLOSE c_pd22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pd22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pd23]
    BEGIN
        DECLARE v_prod_pd23 INTEGER DEFAULT 0;
        DECLARE v_rm_pd23 INTEGER DEFAULT 0;
        DECLARE v_supp_pd23 INTEGER DEFAULT 0;
        DECLARE v_qper_pd23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pd23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pd23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pd23 INTEGER DEFAULT 0;
        DECLARE c_pd23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd23 = 1;
        OPEN c_pd23;
        loop_pd23: LOOP
            FETCH c_pd23 INTO v_prod_pd23, v_rm_pd23, v_supp_pd23, v_qper_pd23, v_uc_pd23;
            IF v_done_pd23 = 1 THEN LEAVE loop_pd23; END IF;
            SET v_roll_pd23 = v_roll_pd23 + COALESCE(v_qper_pd23,0) * COALESCE(v_uc_pd23,0);
        END LOOP;
        CLOSE c_pd23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pd23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pd24]
    BEGIN
        DECLARE v_acct_pd24 INTEGER DEFAULT 0;
        DECLARE v_deb_pd24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pd24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pd24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd24 INTEGER DEFAULT 0;
        DECLARE c_pd24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd24 = 1;
        OPEN c_pd24;
        loop_pd24: LOOP
            FETCH c_pd24 INTO v_acct_pd24, v_deb_pd24, v_cred_pd24;
            IF v_done_pd24 = 1 THEN LEAVE loop_pd24; END IF;
            SET v_net_pd24 = v_net_pd24 + (v_deb_pd24 - v_cred_pd24);
        END LOOP;
        CLOSE c_pd24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pd24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pd25]
    BEGIN
        DECLARE v_pid_pd25 INTEGER DEFAULT 0;
        DECLARE v_lp_pd25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pd25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pd25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pd25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pd25 INTEGER DEFAULT 0;
        DECLARE c_pd25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd25 = 1;
        OPEN c_pd25;
        loop_pd25: LOOP
            FETCH c_pd25 INTO v_pid_pd25, v_lp_pd25, v_pp_pd25;
            IF v_done_pd25 = 1 THEN LEAVE loop_pd25; END IF;
            SET v_var_pd25 = v_var_pd25 + (COALESCE(v_lp_pd25,0) - COALESCE(v_pp_pd25,0));
            SET v_marg_pd25 = ERP_FN_MARGIN(v_pid_pd25);
        END LOOP;
        CLOSE c_pd25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pd25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pd26]
    BEGIN
        DECLARE v_inv_pd26 INTEGER DEFAULT 0;
        DECLARE v_amt_pd26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pd26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pd26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd26 INTEGER DEFAULT 0;
        DECLARE c_pd26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd26 = 1;
        OPEN c_pd26;
        loop_pd26: LOOP
            FETCH c_pd26 INTO v_inv_pd26, v_amt_pd26, v_alloc_pd26;
            IF v_done_pd26 = 1 THEN LEAVE loop_pd26; END IF;
            SET v_open_pd26 = v_open_pd26 + (v_amt_pd26 - v_alloc_pd26);
        END LOOP;
        CLOSE c_pd26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pd26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pd27]
    BEGIN
        DECLARE v_lvl_pd27 INTEGER DEFAULT 0;
        DECLARE v_dept_pd27 INTEGER DEFAULT 0;
        DECLARE v_head_pd27 INTEGER DEFAULT 0;
        DECLARE v_done_pd27 INTEGER DEFAULT 0;
        DECLARE c_pd27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd27 = 1;
        OPEN c_pd27;
        loop_pd27: LOOP
            FETCH c_pd27 INTO v_dept_pd27, v_lvl_pd27, v_head_pd27;
            IF v_done_pd27 = 1 THEN LEAVE loop_pd27; END IF;
        END LOOP;
        CLOSE c_pd27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pd27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pd27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pd28]
    BEGIN
        DECLARE v_sh_pd28 INTEGER DEFAULT 0;
        DECLARE v_car_pd28 INTEGER DEFAULT 0;
        DECLARE v_qty_pd28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pd28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pd28 INTEGER DEFAULT 0;
        DECLARE c_pd28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd28 = 1;
        OPEN c_pd28;
        loop_pd28: LOOP
            FETCH c_pd28 INTO v_sh_pd28, v_car_pd28, v_qty_pd28;
            IF v_done_pd28 = 1 THEN LEAVE loop_pd28; END IF;
            SET v_tot_pd28 = v_tot_pd28 + v_qty_pd28;
        END LOOP;
        CLOSE c_pd28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pd28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pd29]
    BEGIN
        DECLARE v_sql_pd29 VARCHAR(1000);
        DECLARE v_n_pd29 INTEGER DEFAULT 0;
        SET v_sql_pd29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pd29 FROM v_sql_pd29;
        EXECUTE st_pd29;
        SELECT COUNT(*) INTO v_n_pd29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pd29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pd30]
    BEGIN
        DECLARE v_key_pd30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pd30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pd30' AS VARCHAR(40)), v_key_pd30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pd31]
    BEGIN
        DECLARE v_so_pd31 INTEGER DEFAULT 0;
        DECLARE v_cust_pd31 INTEGER DEFAULT 0;
        DECLARE v_rk_pd31 INTEGER DEFAULT 0;
        DECLARE v_run_pd31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd31 INTEGER DEFAULT 0;
        DECLARE c_pd31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd31 = 1;
        OPEN c_pd31;
        loop_pd31: LOOP
            FETCH c_pd31 INTO v_so_pd31, v_cust_pd31, v_rk_pd31, v_run_pd31;
            IF v_done_pd31 = 1 THEN LEAVE loop_pd31; END IF;
        END LOOP;
        CLOSE c_pd31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pd31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pd31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [pd32]
    BEGIN
        DECLARE v_hi_pd32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_pd32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_pd32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [pd33]
    BEGIN
        DECLARE v_pairs_pd33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_pd33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_pd33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [pd34]
    BEGIN
        DECLARE v_rows_pd34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_pd34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_pd34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_pd34 FROM SESSION.TMP_pd34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_pd34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [pd35]
    BEGIN
        DECLARE v_rc_pd35 INTEGER DEFAULT 0;
        DECLARE v_band_pd35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_pd35 = ROW_COUNT;
        SET v_band_pd35 = CASE
                            WHEN v_rc_pd35 = 0 THEN 'NONE'
                            WHEN v_rc_pd35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_pd35, 'COUNT', 'band=' || v_band_pd35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [pd36]
    BEGIN
        DECLARE v_i_pd36 INTEGER DEFAULT 0;
        SAVEPOINT sp_pd36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_pd36 < 4 DO
            SET v_i_pd36 = v_i_pd36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_pd36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_pd36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_pd36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [pd37]
    BEGIN
        DECLARE v_j_pd37 INTEGER DEFAULT 0;
        DECLARE v_sum_pd37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_pd37 = v_j_pd37 + 1;
        UNTIL v_j_pd37 >= 3 END REPEAT;
        FOR row_pd37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_pd37 = v_sum_pd37 + COALESCE(row_pd37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_pd37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_pd37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [pd38]
    BEGIN
        DECLARE v_n_pd38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_pd38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_pd38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [pd39]
    BEGIN
        DECLARE v_levels_pd39 INTEGER DEFAULT 0;
        DECLARE c_pd39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_pd39 = 0;
        OPEN c_pd39;
        FETCH c_pd39 INTO v_levels_pd39;
        CLOSE c_pd39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_pd39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pd40]
    BEGIN
        DECLARE v_sql_pd40 VARCHAR(1000);
        DECLARE v_n_pd40 INTEGER DEFAULT 0;
        SET v_sql_pd40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_pd40 FROM v_sql_pd40;
        EXECUTE st_pd40;
        SELECT COUNT(*) INTO v_n_pd40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pd40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pd41]
    BEGIN
        DECLARE v_key_pd41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pd41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pd41' AS VARCHAR(40)), v_key_pd41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [pd42]
    BEGIN
        DECLARE v_so_pd42 INTEGER DEFAULT 0;
        DECLARE v_cust_pd42 INTEGER DEFAULT 0;
        DECLARE v_ctry_pd42 INTEGER DEFAULT 0;
        DECLARE v_ccy_pd42 INTEGER DEFAULT 0;
        DECLARE v_sub_pd42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_pd42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_pd42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_pd42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_pd42 INTEGER DEFAULT 0;
        DECLARE v_done_pd42 INTEGER DEFAULT 0;
        DECLARE c_pd42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd42 = 1;
        OPEN c_pd42;
        loop_pd42: LOOP
            FETCH c_pd42 INTO v_so_pd42, v_cust_pd42, v_ctry_pd42, v_ccy_pd42, v_sub_pd42;
            IF v_done_pd42 = 1 THEN LEAVE loop_pd42; END IF;
            SET v_tax_pd42 = ERP_FN_TAX(v_ctry_pd42, v_sub_pd42);
            SET v_fx_pd42 = ERP_FN_FX_CONVERT(v_ccy_pd42, 1, v_sub_pd42 + v_tax_pd42);
            SET v_acc_pd42 = v_acc_pd42 + v_fx_pd42;
            SET v_cnt_pd42 = v_cnt_pd42 + 1;
        END LOOP;
        CLOSE c_pd42;
        IF v_cnt_pd42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_pd42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_pd42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [pd43]
    BEGIN
        DECLARE v_pid_pd43 INTEGER DEFAULT 0;
        DECLARE v_oh_pd43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_pd43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_pd43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_pd43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pd43 INTEGER DEFAULT 0;
        DECLARE c_pd43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd43 = 1;
        OPEN c_pd43;
        loop_pd43: LOOP
            FETCH c_pd43 INTO v_pid_pd43, v_oh_pd43, v_cost_pd43;
            IF v_done_pd43 = 1 THEN LEAVE loop_pd43; END IF;
            SET v_avail_pd43 = ERP_FN_INVENTORY_ONHAND(v_pid_pd43);
            SET v_val_pd43 = v_val_pd43 + CAST(COALESCE(v_oh_pd43,0) * COALESCE(v_cost_pd43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_pd43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_pd43;
        END LOOP;
        CLOSE c_pd43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_pd43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [pd44]
    BEGIN
        DECLARE v_prod_pd44 INTEGER DEFAULT 0;
        DECLARE v_rm_pd44 INTEGER DEFAULT 0;
        DECLARE v_supp_pd44 INTEGER DEFAULT 0;
        DECLARE v_qper_pd44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_pd44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_pd44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pd44 INTEGER DEFAULT 0;
        DECLARE c_pd44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd44 = 1;
        OPEN c_pd44;
        loop_pd44: LOOP
            FETCH c_pd44 INTO v_prod_pd44, v_rm_pd44, v_supp_pd44, v_qper_pd44, v_uc_pd44;
            IF v_done_pd44 = 1 THEN LEAVE loop_pd44; END IF;
            SET v_roll_pd44 = v_roll_pd44 + COALESCE(v_qper_pd44,0) * COALESCE(v_uc_pd44,0);
        END LOOP;
        CLOSE c_pd44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_pd44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [pd45]
    BEGIN
        DECLARE v_acct_pd45 INTEGER DEFAULT 0;
        DECLARE v_deb_pd45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_pd45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_pd45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd45 INTEGER DEFAULT 0;
        DECLARE c_pd45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd45 = 1;
        OPEN c_pd45;
        loop_pd45: LOOP
            FETCH c_pd45 INTO v_acct_pd45, v_deb_pd45, v_cred_pd45;
            IF v_done_pd45 = 1 THEN LEAVE loop_pd45; END IF;
            SET v_net_pd45 = v_net_pd45 + (v_deb_pd45 - v_cred_pd45);
        END LOOP;
        CLOSE c_pd45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_pd45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [pd46]
    BEGIN
        DECLARE v_pid_pd46 INTEGER DEFAULT 0;
        DECLARE v_lp_pd46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_pd46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_pd46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_pd46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_pd46 INTEGER DEFAULT 0;
        DECLARE c_pd46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd46 = 1;
        OPEN c_pd46;
        loop_pd46: LOOP
            FETCH c_pd46 INTO v_pid_pd46, v_lp_pd46, v_pp_pd46;
            IF v_done_pd46 = 1 THEN LEAVE loop_pd46; END IF;
            SET v_var_pd46 = v_var_pd46 + (COALESCE(v_lp_pd46,0) - COALESCE(v_pp_pd46,0));
            SET v_marg_pd46 = ERP_FN_MARGIN(v_pid_pd46);
        END LOOP;
        CLOSE c_pd46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_pd46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [pd47]
    BEGIN
        DECLARE v_inv_pd47 INTEGER DEFAULT 0;
        DECLARE v_amt_pd47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_pd47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_pd47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd47 INTEGER DEFAULT 0;
        DECLARE c_pd47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd47 = 1;
        OPEN c_pd47;
        loop_pd47: LOOP
            FETCH c_pd47 INTO v_inv_pd47, v_amt_pd47, v_alloc_pd47;
            IF v_done_pd47 = 1 THEN LEAVE loop_pd47; END IF;
            SET v_open_pd47 = v_open_pd47 + (v_amt_pd47 - v_alloc_pd47);
        END LOOP;
        CLOSE c_pd47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_pd47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [pd48]
    BEGIN
        DECLARE v_lvl_pd48 INTEGER DEFAULT 0;
        DECLARE v_dept_pd48 INTEGER DEFAULT 0;
        DECLARE v_head_pd48 INTEGER DEFAULT 0;
        DECLARE v_done_pd48 INTEGER DEFAULT 0;
        DECLARE c_pd48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd48 = 1;
        OPEN c_pd48;
        loop_pd48: LOOP
            FETCH c_pd48 INTO v_dept_pd48, v_lvl_pd48, v_head_pd48;
            IF v_done_pd48 = 1 THEN LEAVE loop_pd48; END IF;
        END LOOP;
        CLOSE c_pd48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_pd48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_pd48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [pd49]
    BEGIN
        DECLARE v_sh_pd49 INTEGER DEFAULT 0;
        DECLARE v_car_pd49 INTEGER DEFAULT 0;
        DECLARE v_qty_pd49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_pd49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_pd49 INTEGER DEFAULT 0;
        DECLARE c_pd49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd49 = 1;
        OPEN c_pd49;
        loop_pd49: LOOP
            FETCH c_pd49 INTO v_sh_pd49, v_car_pd49, v_qty_pd49;
            IF v_done_pd49 = 1 THEN LEAVE loop_pd49; END IF;
            SET v_tot_pd49 = v_tot_pd49 + v_qty_pd49;
        END LOOP;
        CLOSE c_pd49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_pd49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pd50]
    BEGIN
        DECLARE v_sql_pd50 VARCHAR(1000);
        DECLARE v_n_pd50 INTEGER DEFAULT 0;
        SET v_sql_pd50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_pd50 FROM v_sql_pd50;
        EXECUTE st_pd50;
        SELECT COUNT(*) INTO v_n_pd50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pd50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [pd51]
    BEGIN
        DECLARE v_key_pd51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_pd51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_pd51' AS VARCHAR(40)), v_key_pd51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [pd52]
    BEGIN
        DECLARE v_so_pd52 INTEGER DEFAULT 0;
        DECLARE v_cust_pd52 INTEGER DEFAULT 0;
        DECLARE v_rk_pd52 INTEGER DEFAULT 0;
        DECLARE v_run_pd52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_pd52 INTEGER DEFAULT 0;
        DECLARE c_pd52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_pd52 = 1;
        OPEN c_pd52;
        loop_pd52: LOOP
            FETCH c_pd52 INTO v_so_pd52, v_cust_pd52, v_rk_pd52, v_run_pd52;
            IF v_done_pd52 = 1 THEN LEAVE loop_pd52; END IF;
        END LOOP;
        CLOSE c_pd52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_pd52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_pd52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [pd53]
    BEGIN
        DECLARE v_hi_pd53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_pd53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_pd53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [pd54]
    BEGIN
        DECLARE v_pairs_pd54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_pd54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_pd54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [pd55]
    BEGIN
        DECLARE v_rows_pd55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_pd55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_pd55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_pd55 FROM SESSION.TMP_pd55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_pd55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [pd56]
    BEGIN
        DECLARE v_rc_pd56 INTEGER DEFAULT 0;
        DECLARE v_band_pd56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_pd56 = ROW_COUNT;
        SET v_band_pd56 = CASE
                            WHEN v_rc_pd56 = 0 THEN 'NONE'
                            WHEN v_rc_pd56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_pd56, 'COUNT', 'band=' || v_band_pd56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [pd57]
    BEGIN
        DECLARE v_i_pd57 INTEGER DEFAULT 0;
        SAVEPOINT sp_pd57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_pd57 < 4 DO
            SET v_i_pd57 = v_i_pd57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_pd57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_pd57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_pd57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [pd58]
    BEGIN
        DECLARE v_j_pd58 INTEGER DEFAULT 0;
        DECLARE v_sum_pd58 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_pd58 = v_j_pd58 + 1;
        UNTIL v_j_pd58 >= 3 END REPEAT;
        FOR row_pd58 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_pd58 = v_sum_pd58 + COALESCE(row_pd58.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_pd58, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_pd58 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [pd59]
    BEGIN
        DECLARE v_n_pd59 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_pd59
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_pd59, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [pd60]
    BEGIN
        DECLARE v_levels_pd60 INTEGER DEFAULT 0;
        DECLARE c_pd60 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_pd60 = 0;
        OPEN c_pd60;
        FETCH c_pd60 INTO v_levels_pd60;
        CLOSE c_pd60;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_pd60,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [pd61]
    BEGIN
        DECLARE v_sql_pd61 VARCHAR(1000);
        DECLARE v_n_pd61 INTEGER DEFAULT 0;
        SET v_sql_pd61 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_pd61 FROM v_sql_pd61;
        EXECUTE st_pd61;
        SELECT COUNT(*) INTO v_n_pd61 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_pd61, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    CALL ERP_USP_RECONCILE_GL(v_period);
    CALL ERP_USP_AUDIT('CYCLE', v_period, 'END', 'day processed');
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_REBUILD_MQT()
LANGUAGE SQL
BEGIN
    DECLARE v_sql VARCHAR(2000);
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
        CALL ERP_USP_AUDIT('MQT', 0, 'WARN', 'refresh skipped');
    SET v_sql = 'REFRESH TABLE ERP_MQT_CUSTOMER_REV';
    PREPARE rstmt1 FROM v_sql;
    EXECUTE rstmt1;
    SET v_sql = 'REFRESH TABLE ERP_MQT_PRODUCT_MARGIN';
    PREPARE rstmt2 FROM v_sql;
    EXECUTE rstmt2;
    EXECUTE IMMEDIATE 'UPDATE ERP_PRODUCT SET reorder_point = reorder_point WHERE reorder_point >= 0';
    CALL ERP_USP_AUDIT('MQT', 0, 'REBUILD', 'materialized query tables refreshed');
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_CLOSE_PERIOD(IN p_period INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_open INTEGER DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        CALL ERP_USP_AUDIT('CLOSE', p_period, 'ERROR', 'close failed');
    END;
    SELECT COUNT(*) INTO v_open FROM ERP_INVOICE WHERE status = 'OPEN';
    CALL ERP_USP_REBUILD_MQT();
    CALL ERP_USP_AUDIT('CLOSE', p_period, 'DONE', 'open_invoices=' || RTRIM(CHAR(v_open)));
    -- order/customer/country/currency revenue scan [cp00]
    BEGIN
        DECLARE v_so_cp00 INTEGER DEFAULT 0;
        DECLARE v_cust_cp00 INTEGER DEFAULT 0;
        DECLARE v_ctry_cp00 INTEGER DEFAULT 0;
        DECLARE v_ccy_cp00 INTEGER DEFAULT 0;
        DECLARE v_sub_cp00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cp00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cp00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cp00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cp00 INTEGER DEFAULT 0;
        DECLARE v_done_cp00 INTEGER DEFAULT 0;
        DECLARE c_cp00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp00 = 1;
        OPEN c_cp00;
        loop_cp00: LOOP
            FETCH c_cp00 INTO v_so_cp00, v_cust_cp00, v_ctry_cp00, v_ccy_cp00, v_sub_cp00;
            IF v_done_cp00 = 1 THEN LEAVE loop_cp00; END IF;
            SET v_tax_cp00 = ERP_FN_TAX(v_ctry_cp00, v_sub_cp00);
            SET v_fx_cp00 = ERP_FN_FX_CONVERT(v_ccy_cp00, 1, v_sub_cp00 + v_tax_cp00);
            SET v_acc_cp00 = v_acc_cp00 + v_fx_cp00;
            SET v_cnt_cp00 = v_cnt_cp00 + 1;
        END LOOP;
        CLOSE c_cp00;
        IF v_cnt_cp00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cp00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cp00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cp01]
    BEGIN
        DECLARE v_pid_cp01 INTEGER DEFAULT 0;
        DECLARE v_oh_cp01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cp01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cp01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cp01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cp01 INTEGER DEFAULT 0;
        DECLARE c_cp01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp01 = 1;
        OPEN c_cp01;
        loop_cp01: LOOP
            FETCH c_cp01 INTO v_pid_cp01, v_oh_cp01, v_cost_cp01;
            IF v_done_cp01 = 1 THEN LEAVE loop_cp01; END IF;
            SET v_avail_cp01 = ERP_FN_INVENTORY_ONHAND(v_pid_cp01);
            SET v_val_cp01 = v_val_cp01 + CAST(COALESCE(v_oh_cp01,0) * COALESCE(v_cost_cp01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cp01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cp01;
        END LOOP;
        CLOSE c_cp01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cp01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cp02]
    BEGIN
        DECLARE v_prod_cp02 INTEGER DEFAULT 0;
        DECLARE v_rm_cp02 INTEGER DEFAULT 0;
        DECLARE v_supp_cp02 INTEGER DEFAULT 0;
        DECLARE v_qper_cp02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cp02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cp02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cp02 INTEGER DEFAULT 0;
        DECLARE c_cp02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp02 = 1;
        OPEN c_cp02;
        loop_cp02: LOOP
            FETCH c_cp02 INTO v_prod_cp02, v_rm_cp02, v_supp_cp02, v_qper_cp02, v_uc_cp02;
            IF v_done_cp02 = 1 THEN LEAVE loop_cp02; END IF;
            SET v_roll_cp02 = v_roll_cp02 + COALESCE(v_qper_cp02,0) * COALESCE(v_uc_cp02,0);
        END LOOP;
        CLOSE c_cp02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cp02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cp03]
    BEGIN
        DECLARE v_acct_cp03 INTEGER DEFAULT 0;
        DECLARE v_deb_cp03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cp03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cp03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cp03 INTEGER DEFAULT 0;
        DECLARE c_cp03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp03 = 1;
        OPEN c_cp03;
        loop_cp03: LOOP
            FETCH c_cp03 INTO v_acct_cp03, v_deb_cp03, v_cred_cp03;
            IF v_done_cp03 = 1 THEN LEAVE loop_cp03; END IF;
            SET v_net_cp03 = v_net_cp03 + (v_deb_cp03 - v_cred_cp03);
        END LOOP;
        CLOSE c_cp03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cp03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cp04]
    BEGIN
        DECLARE v_pid_cp04 INTEGER DEFAULT 0;
        DECLARE v_lp_cp04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cp04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cp04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cp04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cp04 INTEGER DEFAULT 0;
        DECLARE c_cp04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp04 = 1;
        OPEN c_cp04;
        loop_cp04: LOOP
            FETCH c_cp04 INTO v_pid_cp04, v_lp_cp04, v_pp_cp04;
            IF v_done_cp04 = 1 THEN LEAVE loop_cp04; END IF;
            SET v_var_cp04 = v_var_cp04 + (COALESCE(v_lp_cp04,0) - COALESCE(v_pp_cp04,0));
            SET v_marg_cp04 = ERP_FN_MARGIN(v_pid_cp04);
        END LOOP;
        CLOSE c_cp04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cp04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cp05]
    BEGIN
        DECLARE v_inv_cp05 INTEGER DEFAULT 0;
        DECLARE v_amt_cp05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cp05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cp05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cp05 INTEGER DEFAULT 0;
        DECLARE c_cp05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp05 = 1;
        OPEN c_cp05;
        loop_cp05: LOOP
            FETCH c_cp05 INTO v_inv_cp05, v_amt_cp05, v_alloc_cp05;
            IF v_done_cp05 = 1 THEN LEAVE loop_cp05; END IF;
            SET v_open_cp05 = v_open_cp05 + (v_amt_cp05 - v_alloc_cp05);
        END LOOP;
        CLOSE c_cp05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cp05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [cp06]
    BEGIN
        DECLARE v_lvl_cp06 INTEGER DEFAULT 0;
        DECLARE v_dept_cp06 INTEGER DEFAULT 0;
        DECLARE v_head_cp06 INTEGER DEFAULT 0;
        DECLARE v_done_cp06 INTEGER DEFAULT 0;
        DECLARE c_cp06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp06 = 1;
        OPEN c_cp06;
        loop_cp06: LOOP
            FETCH c_cp06 INTO v_dept_cp06, v_lvl_cp06, v_head_cp06;
            IF v_done_cp06 = 1 THEN LEAVE loop_cp06; END IF;
        END LOOP;
        CLOSE c_cp06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_cp06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_cp06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [cp07]
    BEGIN
        DECLARE v_sh_cp07 INTEGER DEFAULT 0;
        DECLARE v_car_cp07 INTEGER DEFAULT 0;
        DECLARE v_qty_cp07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_cp07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cp07 INTEGER DEFAULT 0;
        DECLARE c_cp07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp07 = 1;
        OPEN c_cp07;
        loop_cp07: LOOP
            FETCH c_cp07 INTO v_sh_cp07, v_car_cp07, v_qty_cp07;
            IF v_done_cp07 = 1 THEN LEAVE loop_cp07; END IF;
            SET v_tot_cp07 = v_tot_cp07 + v_qty_cp07;
        END LOOP;
        CLOSE c_cp07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_cp07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cp08]
    BEGIN
        DECLARE v_sql_cp08 VARCHAR(1000);
        DECLARE v_n_cp08 INTEGER DEFAULT 0;
        SET v_sql_cp08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_cp08 FROM v_sql_cp08;
        EXECUTE st_cp08;
        SELECT COUNT(*) INTO v_n_cp08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cp08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cp09]
    BEGIN
        DECLARE v_key_cp09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cp09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cp09' AS VARCHAR(40)), v_key_cp09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [cp10]
    BEGIN
        DECLARE v_so_cp10 INTEGER DEFAULT 0;
        DECLARE v_cust_cp10 INTEGER DEFAULT 0;
        DECLARE v_rk_cp10 INTEGER DEFAULT 0;
        DECLARE v_run_cp10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cp10 INTEGER DEFAULT 0;
        DECLARE c_cp10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp10 = 1;
        OPEN c_cp10;
        loop_cp10: LOOP
            FETCH c_cp10 INTO v_so_cp10, v_cust_cp10, v_rk_cp10, v_run_cp10;
            IF v_done_cp10 = 1 THEN LEAVE loop_cp10; END IF;
        END LOOP;
        CLOSE c_cp10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_cp10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_cp10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [cp11]
    BEGIN
        DECLARE v_hi_cp11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_cp11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_cp11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [cp12]
    BEGIN
        DECLARE v_pairs_cp12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_cp12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_cp12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [cp13]
    BEGIN
        DECLARE v_rows_cp13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_cp13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_cp13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_cp13 FROM SESSION.TMP_cp13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_cp13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [cp14]
    BEGIN
        DECLARE v_rc_cp14 INTEGER DEFAULT 0;
        DECLARE v_band_cp14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_cp14 = ROW_COUNT;
        SET v_band_cp14 = CASE
                            WHEN v_rc_cp14 = 0 THEN 'NONE'
                            WHEN v_rc_cp14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_cp14, 'COUNT', 'band=' || v_band_cp14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [cp15]
    BEGIN
        DECLARE v_i_cp15 INTEGER DEFAULT 0;
        SAVEPOINT sp_cp15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_cp15 < 4 DO
            SET v_i_cp15 = v_i_cp15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_cp15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_cp15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_cp15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [cp16]
    BEGIN
        DECLARE v_j_cp16 INTEGER DEFAULT 0;
        DECLARE v_sum_cp16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_cp16 = v_j_cp16 + 1;
        UNTIL v_j_cp16 >= 3 END REPEAT;
        FOR row_cp16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_cp16 = v_sum_cp16 + COALESCE(row_cp16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_cp16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_cp16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [cp17]
    BEGIN
        DECLARE v_n_cp17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_cp17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_cp17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [cp18]
    BEGIN
        DECLARE v_levels_cp18 INTEGER DEFAULT 0;
        DECLARE c_cp18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_cp18 = 0;
        OPEN c_cp18;
        FETCH c_cp18 INTO v_levels_cp18;
        CLOSE c_cp18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_cp18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cp19]
    BEGIN
        DECLARE v_sql_cp19 VARCHAR(1000);
        DECLARE v_n_cp19 INTEGER DEFAULT 0;
        SET v_sql_cp19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_cp19 FROM v_sql_cp19;
        EXECUTE st_cp19;
        SELECT COUNT(*) INTO v_n_cp19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cp19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cp20]
    BEGIN
        DECLARE v_key_cp20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cp20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cp20' AS VARCHAR(40)), v_key_cp20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [cp21]
    BEGIN
        DECLARE v_so_cp21 INTEGER DEFAULT 0;
        DECLARE v_cust_cp21 INTEGER DEFAULT 0;
        DECLARE v_ctry_cp21 INTEGER DEFAULT 0;
        DECLARE v_ccy_cp21 INTEGER DEFAULT 0;
        DECLARE v_sub_cp21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cp21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cp21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cp21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cp21 INTEGER DEFAULT 0;
        DECLARE v_done_cp21 INTEGER DEFAULT 0;
        DECLARE c_cp21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp21 = 1;
        OPEN c_cp21;
        loop_cp21: LOOP
            FETCH c_cp21 INTO v_so_cp21, v_cust_cp21, v_ctry_cp21, v_ccy_cp21, v_sub_cp21;
            IF v_done_cp21 = 1 THEN LEAVE loop_cp21; END IF;
            SET v_tax_cp21 = ERP_FN_TAX(v_ctry_cp21, v_sub_cp21);
            SET v_fx_cp21 = ERP_FN_FX_CONVERT(v_ccy_cp21, 1, v_sub_cp21 + v_tax_cp21);
            SET v_acc_cp21 = v_acc_cp21 + v_fx_cp21;
            SET v_cnt_cp21 = v_cnt_cp21 + 1;
        END LOOP;
        CLOSE c_cp21;
        IF v_cnt_cp21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cp21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cp21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cp22]
    BEGIN
        DECLARE v_pid_cp22 INTEGER DEFAULT 0;
        DECLARE v_oh_cp22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cp22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cp22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cp22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cp22 INTEGER DEFAULT 0;
        DECLARE c_cp22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp22 = 1;
        OPEN c_cp22;
        loop_cp22: LOOP
            FETCH c_cp22 INTO v_pid_cp22, v_oh_cp22, v_cost_cp22;
            IF v_done_cp22 = 1 THEN LEAVE loop_cp22; END IF;
            SET v_avail_cp22 = ERP_FN_INVENTORY_ONHAND(v_pid_cp22);
            SET v_val_cp22 = v_val_cp22 + CAST(COALESCE(v_oh_cp22,0) * COALESCE(v_cost_cp22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cp22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cp22;
        END LOOP;
        CLOSE c_cp22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cp22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cp23]
    BEGIN
        DECLARE v_prod_cp23 INTEGER DEFAULT 0;
        DECLARE v_rm_cp23 INTEGER DEFAULT 0;
        DECLARE v_supp_cp23 INTEGER DEFAULT 0;
        DECLARE v_qper_cp23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cp23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cp23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cp23 INTEGER DEFAULT 0;
        DECLARE c_cp23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp23 = 1;
        OPEN c_cp23;
        loop_cp23: LOOP
            FETCH c_cp23 INTO v_prod_cp23, v_rm_cp23, v_supp_cp23, v_qper_cp23, v_uc_cp23;
            IF v_done_cp23 = 1 THEN LEAVE loop_cp23; END IF;
            SET v_roll_cp23 = v_roll_cp23 + COALESCE(v_qper_cp23,0) * COALESCE(v_uc_cp23,0);
        END LOOP;
        CLOSE c_cp23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cp23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cp24]
    BEGIN
        DECLARE v_acct_cp24 INTEGER DEFAULT 0;
        DECLARE v_deb_cp24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cp24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cp24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cp24 INTEGER DEFAULT 0;
        DECLARE c_cp24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp24 = 1;
        OPEN c_cp24;
        loop_cp24: LOOP
            FETCH c_cp24 INTO v_acct_cp24, v_deb_cp24, v_cred_cp24;
            IF v_done_cp24 = 1 THEN LEAVE loop_cp24; END IF;
            SET v_net_cp24 = v_net_cp24 + (v_deb_cp24 - v_cred_cp24);
        END LOOP;
        CLOSE c_cp24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cp24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cp25]
    BEGIN
        DECLARE v_pid_cp25 INTEGER DEFAULT 0;
        DECLARE v_lp_cp25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cp25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cp25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cp25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cp25 INTEGER DEFAULT 0;
        DECLARE c_cp25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp25 = 1;
        OPEN c_cp25;
        loop_cp25: LOOP
            FETCH c_cp25 INTO v_pid_cp25, v_lp_cp25, v_pp_cp25;
            IF v_done_cp25 = 1 THEN LEAVE loop_cp25; END IF;
            SET v_var_cp25 = v_var_cp25 + (COALESCE(v_lp_cp25,0) - COALESCE(v_pp_cp25,0));
            SET v_marg_cp25 = ERP_FN_MARGIN(v_pid_cp25);
        END LOOP;
        CLOSE c_cp25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cp25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cp26]
    BEGIN
        DECLARE v_inv_cp26 INTEGER DEFAULT 0;
        DECLARE v_amt_cp26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cp26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cp26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cp26 INTEGER DEFAULT 0;
        DECLARE c_cp26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp26 = 1;
        OPEN c_cp26;
        loop_cp26: LOOP
            FETCH c_cp26 INTO v_inv_cp26, v_amt_cp26, v_alloc_cp26;
            IF v_done_cp26 = 1 THEN LEAVE loop_cp26; END IF;
            SET v_open_cp26 = v_open_cp26 + (v_amt_cp26 - v_alloc_cp26);
        END LOOP;
        CLOSE c_cp26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cp26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [cp27]
    BEGIN
        DECLARE v_lvl_cp27 INTEGER DEFAULT 0;
        DECLARE v_dept_cp27 INTEGER DEFAULT 0;
        DECLARE v_head_cp27 INTEGER DEFAULT 0;
        DECLARE v_done_cp27 INTEGER DEFAULT 0;
        DECLARE c_cp27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp27 = 1;
        OPEN c_cp27;
        loop_cp27: LOOP
            FETCH c_cp27 INTO v_dept_cp27, v_lvl_cp27, v_head_cp27;
            IF v_done_cp27 = 1 THEN LEAVE loop_cp27; END IF;
        END LOOP;
        CLOSE c_cp27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_cp27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_cp27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [cp28]
    BEGIN
        DECLARE v_sh_cp28 INTEGER DEFAULT 0;
        DECLARE v_car_cp28 INTEGER DEFAULT 0;
        DECLARE v_qty_cp28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_cp28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cp28 INTEGER DEFAULT 0;
        DECLARE c_cp28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp28 = 1;
        OPEN c_cp28;
        loop_cp28: LOOP
            FETCH c_cp28 INTO v_sh_cp28, v_car_cp28, v_qty_cp28;
            IF v_done_cp28 = 1 THEN LEAVE loop_cp28; END IF;
            SET v_tot_cp28 = v_tot_cp28 + v_qty_cp28;
        END LOOP;
        CLOSE c_cp28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_cp28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cp29]
    BEGIN
        DECLARE v_sql_cp29 VARCHAR(1000);
        DECLARE v_n_cp29 INTEGER DEFAULT 0;
        SET v_sql_cp29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_cp29 FROM v_sql_cp29;
        EXECUTE st_cp29;
        SELECT COUNT(*) INTO v_n_cp29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cp29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cp30]
    BEGIN
        DECLARE v_key_cp30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cp30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cp30' AS VARCHAR(40)), v_key_cp30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [cp31]
    BEGIN
        DECLARE v_so_cp31 INTEGER DEFAULT 0;
        DECLARE v_cust_cp31 INTEGER DEFAULT 0;
        DECLARE v_rk_cp31 INTEGER DEFAULT 0;
        DECLARE v_run_cp31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cp31 INTEGER DEFAULT 0;
        DECLARE c_cp31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp31 = 1;
        OPEN c_cp31;
        loop_cp31: LOOP
            FETCH c_cp31 INTO v_so_cp31, v_cust_cp31, v_rk_cp31, v_run_cp31;
            IF v_done_cp31 = 1 THEN LEAVE loop_cp31; END IF;
        END LOOP;
        CLOSE c_cp31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_cp31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_cp31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [cp32]
    BEGIN
        DECLARE v_hi_cp32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_cp32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_cp32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [cp33]
    BEGIN
        DECLARE v_pairs_cp33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_cp33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_cp33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [cp34]
    BEGIN
        DECLARE v_rows_cp34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_cp34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_cp34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_cp34 FROM SESSION.TMP_cp34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_cp34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [cp35]
    BEGIN
        DECLARE v_rc_cp35 INTEGER DEFAULT 0;
        DECLARE v_band_cp35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_cp35 = ROW_COUNT;
        SET v_band_cp35 = CASE
                            WHEN v_rc_cp35 = 0 THEN 'NONE'
                            WHEN v_rc_cp35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_cp35, 'COUNT', 'band=' || v_band_cp35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [cp36]
    BEGIN
        DECLARE v_i_cp36 INTEGER DEFAULT 0;
        SAVEPOINT sp_cp36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_cp36 < 4 DO
            SET v_i_cp36 = v_i_cp36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_cp36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_cp36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_cp36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [cp37]
    BEGIN
        DECLARE v_j_cp37 INTEGER DEFAULT 0;
        DECLARE v_sum_cp37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_cp37 = v_j_cp37 + 1;
        UNTIL v_j_cp37 >= 3 END REPEAT;
        FOR row_cp37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_cp37 = v_sum_cp37 + COALESCE(row_cp37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_cp37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_cp37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [cp38]
    BEGIN
        DECLARE v_n_cp38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_cp38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_cp38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [cp39]
    BEGIN
        DECLARE v_levels_cp39 INTEGER DEFAULT 0;
        DECLARE c_cp39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_cp39 = 0;
        OPEN c_cp39;
        FETCH c_cp39 INTO v_levels_cp39;
        CLOSE c_cp39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_cp39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [cp40]
    BEGIN
        DECLARE v_sql_cp40 VARCHAR(1000);
        DECLARE v_n_cp40 INTEGER DEFAULT 0;
        SET v_sql_cp40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_cp40 FROM v_sql_cp40;
        EXECUTE st_cp40;
        SELECT COUNT(*) INTO v_n_cp40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_cp40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [cp41]
    BEGIN
        DECLARE v_key_cp41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_cp41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_cp41' AS VARCHAR(40)), v_key_cp41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [cp42]
    BEGIN
        DECLARE v_so_cp42 INTEGER DEFAULT 0;
        DECLARE v_cust_cp42 INTEGER DEFAULT 0;
        DECLARE v_ctry_cp42 INTEGER DEFAULT 0;
        DECLARE v_ccy_cp42 INTEGER DEFAULT 0;
        DECLARE v_sub_cp42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_cp42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_cp42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_cp42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_cp42 INTEGER DEFAULT 0;
        DECLARE v_done_cp42 INTEGER DEFAULT 0;
        DECLARE c_cp42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp42 = 1;
        OPEN c_cp42;
        loop_cp42: LOOP
            FETCH c_cp42 INTO v_so_cp42, v_cust_cp42, v_ctry_cp42, v_ccy_cp42, v_sub_cp42;
            IF v_done_cp42 = 1 THEN LEAVE loop_cp42; END IF;
            SET v_tax_cp42 = ERP_FN_TAX(v_ctry_cp42, v_sub_cp42);
            SET v_fx_cp42 = ERP_FN_FX_CONVERT(v_ccy_cp42, 1, v_sub_cp42 + v_tax_cp42);
            SET v_acc_cp42 = v_acc_cp42 + v_fx_cp42;
            SET v_cnt_cp42 = v_cnt_cp42 + 1;
        END LOOP;
        CLOSE c_cp42;
        IF v_cnt_cp42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_cp42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_cp42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [cp43]
    BEGIN
        DECLARE v_pid_cp43 INTEGER DEFAULT 0;
        DECLARE v_oh_cp43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_cp43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_cp43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_cp43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cp43 INTEGER DEFAULT 0;
        DECLARE c_cp43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp43 = 1;
        OPEN c_cp43;
        loop_cp43: LOOP
            FETCH c_cp43 INTO v_pid_cp43, v_oh_cp43, v_cost_cp43;
            IF v_done_cp43 = 1 THEN LEAVE loop_cp43; END IF;
            SET v_avail_cp43 = ERP_FN_INVENTORY_ONHAND(v_pid_cp43);
            SET v_val_cp43 = v_val_cp43 + CAST(COALESCE(v_oh_cp43,0) * COALESCE(v_cost_cp43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_cp43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_cp43;
        END LOOP;
        CLOSE c_cp43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_cp43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [cp44]
    BEGIN
        DECLARE v_prod_cp44 INTEGER DEFAULT 0;
        DECLARE v_rm_cp44 INTEGER DEFAULT 0;
        DECLARE v_supp_cp44 INTEGER DEFAULT 0;
        DECLARE v_qper_cp44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_cp44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_cp44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_cp44 INTEGER DEFAULT 0;
        DECLARE c_cp44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp44 = 1;
        OPEN c_cp44;
        loop_cp44: LOOP
            FETCH c_cp44 INTO v_prod_cp44, v_rm_cp44, v_supp_cp44, v_qper_cp44, v_uc_cp44;
            IF v_done_cp44 = 1 THEN LEAVE loop_cp44; END IF;
            SET v_roll_cp44 = v_roll_cp44 + COALESCE(v_qper_cp44,0) * COALESCE(v_uc_cp44,0);
        END LOOP;
        CLOSE c_cp44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_cp44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [cp45]
    BEGIN
        DECLARE v_acct_cp45 INTEGER DEFAULT 0;
        DECLARE v_deb_cp45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_cp45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_cp45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cp45 INTEGER DEFAULT 0;
        DECLARE c_cp45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp45 = 1;
        OPEN c_cp45;
        loop_cp45: LOOP
            FETCH c_cp45 INTO v_acct_cp45, v_deb_cp45, v_cred_cp45;
            IF v_done_cp45 = 1 THEN LEAVE loop_cp45; END IF;
            SET v_net_cp45 = v_net_cp45 + (v_deb_cp45 - v_cred_cp45);
        END LOOP;
        CLOSE c_cp45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_cp45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [cp46]
    BEGIN
        DECLARE v_pid_cp46 INTEGER DEFAULT 0;
        DECLARE v_lp_cp46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_cp46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_cp46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_cp46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_cp46 INTEGER DEFAULT 0;
        DECLARE c_cp46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp46 = 1;
        OPEN c_cp46;
        loop_cp46: LOOP
            FETCH c_cp46 INTO v_pid_cp46, v_lp_cp46, v_pp_cp46;
            IF v_done_cp46 = 1 THEN LEAVE loop_cp46; END IF;
            SET v_var_cp46 = v_var_cp46 + (COALESCE(v_lp_cp46,0) - COALESCE(v_pp_cp46,0));
            SET v_marg_cp46 = ERP_FN_MARGIN(v_pid_cp46);
        END LOOP;
        CLOSE c_cp46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_cp46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [cp47]
    BEGIN
        DECLARE v_inv_cp47 INTEGER DEFAULT 0;
        DECLARE v_amt_cp47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_cp47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_cp47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_cp47 INTEGER DEFAULT 0;
        DECLARE c_cp47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_cp47 = 1;
        OPEN c_cp47;
        loop_cp47: LOOP
            FETCH c_cp47 INTO v_inv_cp47, v_amt_cp47, v_alloc_cp47;
            IF v_done_cp47 = 1 THEN LEAVE loop_cp47; END IF;
            SET v_open_cp47 = v_open_cp47 + (v_amt_cp47 - v_alloc_cp47);
        END LOOP;
        CLOSE c_cp47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_cp47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_ARCHIVE_AUDIT(IN p_keep_days INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_n INTEGER DEFAULT 0;
    DECLARE v_sql VARCHAR(500);
    SET v_sql = 'DELETE FROM ERP_AUDIT_LOG WHERE logged_ts < (CURRENT TIMESTAMP - ? DAYS)';
    PREPARE dstmt FROM v_sql;
    EXECUTE dstmt USING p_keep_days;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    CALL ERP_USP_AUDIT('ARCHIVE', v_n, 'PURGE', 'old audit rows removed');
    -- order/customer/country/currency revenue scan [aa00]
    BEGIN
        DECLARE v_so_aa00 INTEGER DEFAULT 0;
        DECLARE v_cust_aa00 INTEGER DEFAULT 0;
        DECLARE v_ctry_aa00 INTEGER DEFAULT 0;
        DECLARE v_ccy_aa00 INTEGER DEFAULT 0;
        DECLARE v_sub_aa00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_aa00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_aa00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_aa00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_aa00 INTEGER DEFAULT 0;
        DECLARE v_done_aa00 INTEGER DEFAULT 0;
        DECLARE c_aa00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa00 = 1;
        OPEN c_aa00;
        loop_aa00: LOOP
            FETCH c_aa00 INTO v_so_aa00, v_cust_aa00, v_ctry_aa00, v_ccy_aa00, v_sub_aa00;
            IF v_done_aa00 = 1 THEN LEAVE loop_aa00; END IF;
            SET v_tax_aa00 = ERP_FN_TAX(v_ctry_aa00, v_sub_aa00);
            SET v_fx_aa00 = ERP_FN_FX_CONVERT(v_ccy_aa00, 1, v_sub_aa00 + v_tax_aa00);
            SET v_acc_aa00 = v_acc_aa00 + v_fx_aa00;
            SET v_cnt_aa00 = v_cnt_aa00 + 1;
        END LOOP;
        CLOSE c_aa00;
        IF v_cnt_aa00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_aa00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_aa00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [aa01]
    BEGIN
        DECLARE v_pid_aa01 INTEGER DEFAULT 0;
        DECLARE v_oh_aa01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_aa01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_aa01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_aa01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_aa01 INTEGER DEFAULT 0;
        DECLARE c_aa01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa01 = 1;
        OPEN c_aa01;
        loop_aa01: LOOP
            FETCH c_aa01 INTO v_pid_aa01, v_oh_aa01, v_cost_aa01;
            IF v_done_aa01 = 1 THEN LEAVE loop_aa01; END IF;
            SET v_avail_aa01 = ERP_FN_INVENTORY_ONHAND(v_pid_aa01);
            SET v_val_aa01 = v_val_aa01 + CAST(COALESCE(v_oh_aa01,0) * COALESCE(v_cost_aa01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_aa01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_aa01;
        END LOOP;
        CLOSE c_aa01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_aa01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [aa02]
    BEGIN
        DECLARE v_prod_aa02 INTEGER DEFAULT 0;
        DECLARE v_rm_aa02 INTEGER DEFAULT 0;
        DECLARE v_supp_aa02 INTEGER DEFAULT 0;
        DECLARE v_qper_aa02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_aa02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_aa02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_aa02 INTEGER DEFAULT 0;
        DECLARE c_aa02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa02 = 1;
        OPEN c_aa02;
        loop_aa02: LOOP
            FETCH c_aa02 INTO v_prod_aa02, v_rm_aa02, v_supp_aa02, v_qper_aa02, v_uc_aa02;
            IF v_done_aa02 = 1 THEN LEAVE loop_aa02; END IF;
            SET v_roll_aa02 = v_roll_aa02 + COALESCE(v_qper_aa02,0) * COALESCE(v_uc_aa02,0);
        END LOOP;
        CLOSE c_aa02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_aa02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [aa03]
    BEGIN
        DECLARE v_acct_aa03 INTEGER DEFAULT 0;
        DECLARE v_deb_aa03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_aa03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_aa03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_aa03 INTEGER DEFAULT 0;
        DECLARE c_aa03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa03 = 1;
        OPEN c_aa03;
        loop_aa03: LOOP
            FETCH c_aa03 INTO v_acct_aa03, v_deb_aa03, v_cred_aa03;
            IF v_done_aa03 = 1 THEN LEAVE loop_aa03; END IF;
            SET v_net_aa03 = v_net_aa03 + (v_deb_aa03 - v_cred_aa03);
        END LOOP;
        CLOSE c_aa03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_aa03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [aa04]
    BEGIN
        DECLARE v_pid_aa04 INTEGER DEFAULT 0;
        DECLARE v_lp_aa04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_aa04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_aa04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_aa04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_aa04 INTEGER DEFAULT 0;
        DECLARE c_aa04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa04 = 1;
        OPEN c_aa04;
        loop_aa04: LOOP
            FETCH c_aa04 INTO v_pid_aa04, v_lp_aa04, v_pp_aa04;
            IF v_done_aa04 = 1 THEN LEAVE loop_aa04; END IF;
            SET v_var_aa04 = v_var_aa04 + (COALESCE(v_lp_aa04,0) - COALESCE(v_pp_aa04,0));
            SET v_marg_aa04 = ERP_FN_MARGIN(v_pid_aa04);
        END LOOP;
        CLOSE c_aa04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_aa04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [aa05]
    BEGIN
        DECLARE v_inv_aa05 INTEGER DEFAULT 0;
        DECLARE v_amt_aa05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_aa05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_aa05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_aa05 INTEGER DEFAULT 0;
        DECLARE c_aa05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa05 = 1;
        OPEN c_aa05;
        loop_aa05: LOOP
            FETCH c_aa05 INTO v_inv_aa05, v_amt_aa05, v_alloc_aa05;
            IF v_done_aa05 = 1 THEN LEAVE loop_aa05; END IF;
            SET v_open_aa05 = v_open_aa05 + (v_amt_aa05 - v_alloc_aa05);
        END LOOP;
        CLOSE c_aa05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_aa05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [aa06]
    BEGIN
        DECLARE v_lvl_aa06 INTEGER DEFAULT 0;
        DECLARE v_dept_aa06 INTEGER DEFAULT 0;
        DECLARE v_head_aa06 INTEGER DEFAULT 0;
        DECLARE v_done_aa06 INTEGER DEFAULT 0;
        DECLARE c_aa06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa06 = 1;
        OPEN c_aa06;
        loop_aa06: LOOP
            FETCH c_aa06 INTO v_dept_aa06, v_lvl_aa06, v_head_aa06;
            IF v_done_aa06 = 1 THEN LEAVE loop_aa06; END IF;
        END LOOP;
        CLOSE c_aa06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_aa06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_aa06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [aa07]
    BEGIN
        DECLARE v_sh_aa07 INTEGER DEFAULT 0;
        DECLARE v_car_aa07 INTEGER DEFAULT 0;
        DECLARE v_qty_aa07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_aa07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_aa07 INTEGER DEFAULT 0;
        DECLARE c_aa07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa07 = 1;
        OPEN c_aa07;
        loop_aa07: LOOP
            FETCH c_aa07 INTO v_sh_aa07, v_car_aa07, v_qty_aa07;
            IF v_done_aa07 = 1 THEN LEAVE loop_aa07; END IF;
            SET v_tot_aa07 = v_tot_aa07 + v_qty_aa07;
        END LOOP;
        CLOSE c_aa07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_aa07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [aa08]
    BEGIN
        DECLARE v_sql_aa08 VARCHAR(1000);
        DECLARE v_n_aa08 INTEGER DEFAULT 0;
        SET v_sql_aa08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_aa08 FROM v_sql_aa08;
        EXECUTE st_aa08;
        SELECT COUNT(*) INTO v_n_aa08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_aa08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [aa09]
    BEGIN
        DECLARE v_key_aa09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_aa09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_aa09' AS VARCHAR(40)), v_key_aa09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [aa10]
    BEGIN
        DECLARE v_so_aa10 INTEGER DEFAULT 0;
        DECLARE v_cust_aa10 INTEGER DEFAULT 0;
        DECLARE v_rk_aa10 INTEGER DEFAULT 0;
        DECLARE v_run_aa10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_aa10 INTEGER DEFAULT 0;
        DECLARE c_aa10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa10 = 1;
        OPEN c_aa10;
        loop_aa10: LOOP
            FETCH c_aa10 INTO v_so_aa10, v_cust_aa10, v_rk_aa10, v_run_aa10;
            IF v_done_aa10 = 1 THEN LEAVE loop_aa10; END IF;
        END LOOP;
        CLOSE c_aa10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_aa10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_aa10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [aa11]
    BEGIN
        DECLARE v_hi_aa11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_aa11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_aa11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [aa12]
    BEGIN
        DECLARE v_pairs_aa12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_aa12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_aa12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [aa13]
    BEGIN
        DECLARE v_rows_aa13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_aa13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_aa13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_aa13 FROM SESSION.TMP_aa13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_aa13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [aa14]
    BEGIN
        DECLARE v_rc_aa14 INTEGER DEFAULT 0;
        DECLARE v_band_aa14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_aa14 = ROW_COUNT;
        SET v_band_aa14 = CASE
                            WHEN v_rc_aa14 = 0 THEN 'NONE'
                            WHEN v_rc_aa14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_aa14, 'COUNT', 'band=' || v_band_aa14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [aa15]
    BEGIN
        DECLARE v_i_aa15 INTEGER DEFAULT 0;
        SAVEPOINT sp_aa15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_aa15 < 4 DO
            SET v_i_aa15 = v_i_aa15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_aa15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_aa15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_aa15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [aa16]
    BEGIN
        DECLARE v_j_aa16 INTEGER DEFAULT 0;
        DECLARE v_sum_aa16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_aa16 = v_j_aa16 + 1;
        UNTIL v_j_aa16 >= 3 END REPEAT;
        FOR row_aa16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_aa16 = v_sum_aa16 + COALESCE(row_aa16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_aa16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_aa16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [aa17]
    BEGIN
        DECLARE v_n_aa17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_aa17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_aa17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [aa18]
    BEGIN
        DECLARE v_levels_aa18 INTEGER DEFAULT 0;
        DECLARE c_aa18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_aa18 = 0;
        OPEN c_aa18;
        FETCH c_aa18 INTO v_levels_aa18;
        CLOSE c_aa18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_aa18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [aa19]
    BEGIN
        DECLARE v_sql_aa19 VARCHAR(1000);
        DECLARE v_n_aa19 INTEGER DEFAULT 0;
        SET v_sql_aa19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_aa19 FROM v_sql_aa19;
        EXECUTE st_aa19;
        SELECT COUNT(*) INTO v_n_aa19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_aa19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [aa20]
    BEGIN
        DECLARE v_key_aa20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_aa20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_aa20' AS VARCHAR(40)), v_key_aa20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [aa21]
    BEGIN
        DECLARE v_so_aa21 INTEGER DEFAULT 0;
        DECLARE v_cust_aa21 INTEGER DEFAULT 0;
        DECLARE v_ctry_aa21 INTEGER DEFAULT 0;
        DECLARE v_ccy_aa21 INTEGER DEFAULT 0;
        DECLARE v_sub_aa21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_aa21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_aa21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_aa21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_aa21 INTEGER DEFAULT 0;
        DECLARE v_done_aa21 INTEGER DEFAULT 0;
        DECLARE c_aa21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa21 = 1;
        OPEN c_aa21;
        loop_aa21: LOOP
            FETCH c_aa21 INTO v_so_aa21, v_cust_aa21, v_ctry_aa21, v_ccy_aa21, v_sub_aa21;
            IF v_done_aa21 = 1 THEN LEAVE loop_aa21; END IF;
            SET v_tax_aa21 = ERP_FN_TAX(v_ctry_aa21, v_sub_aa21);
            SET v_fx_aa21 = ERP_FN_FX_CONVERT(v_ccy_aa21, 1, v_sub_aa21 + v_tax_aa21);
            SET v_acc_aa21 = v_acc_aa21 + v_fx_aa21;
            SET v_cnt_aa21 = v_cnt_aa21 + 1;
        END LOOP;
        CLOSE c_aa21;
        IF v_cnt_aa21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_aa21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_aa21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [aa22]
    BEGIN
        DECLARE v_pid_aa22 INTEGER DEFAULT 0;
        DECLARE v_oh_aa22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_aa22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_aa22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_aa22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_aa22 INTEGER DEFAULT 0;
        DECLARE c_aa22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa22 = 1;
        OPEN c_aa22;
        loop_aa22: LOOP
            FETCH c_aa22 INTO v_pid_aa22, v_oh_aa22, v_cost_aa22;
            IF v_done_aa22 = 1 THEN LEAVE loop_aa22; END IF;
            SET v_avail_aa22 = ERP_FN_INVENTORY_ONHAND(v_pid_aa22);
            SET v_val_aa22 = v_val_aa22 + CAST(COALESCE(v_oh_aa22,0) * COALESCE(v_cost_aa22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_aa22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_aa22;
        END LOOP;
        CLOSE c_aa22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_aa22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [aa23]
    BEGIN
        DECLARE v_prod_aa23 INTEGER DEFAULT 0;
        DECLARE v_rm_aa23 INTEGER DEFAULT 0;
        DECLARE v_supp_aa23 INTEGER DEFAULT 0;
        DECLARE v_qper_aa23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_aa23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_aa23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_aa23 INTEGER DEFAULT 0;
        DECLARE c_aa23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa23 = 1;
        OPEN c_aa23;
        loop_aa23: LOOP
            FETCH c_aa23 INTO v_prod_aa23, v_rm_aa23, v_supp_aa23, v_qper_aa23, v_uc_aa23;
            IF v_done_aa23 = 1 THEN LEAVE loop_aa23; END IF;
            SET v_roll_aa23 = v_roll_aa23 + COALESCE(v_qper_aa23,0) * COALESCE(v_uc_aa23,0);
        END LOOP;
        CLOSE c_aa23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_aa23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [aa24]
    BEGIN
        DECLARE v_acct_aa24 INTEGER DEFAULT 0;
        DECLARE v_deb_aa24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_aa24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_aa24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_aa24 INTEGER DEFAULT 0;
        DECLARE c_aa24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa24 = 1;
        OPEN c_aa24;
        loop_aa24: LOOP
            FETCH c_aa24 INTO v_acct_aa24, v_deb_aa24, v_cred_aa24;
            IF v_done_aa24 = 1 THEN LEAVE loop_aa24; END IF;
            SET v_net_aa24 = v_net_aa24 + (v_deb_aa24 - v_cred_aa24);
        END LOOP;
        CLOSE c_aa24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_aa24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [aa25]
    BEGIN
        DECLARE v_pid_aa25 INTEGER DEFAULT 0;
        DECLARE v_lp_aa25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_aa25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_aa25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_aa25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_aa25 INTEGER DEFAULT 0;
        DECLARE c_aa25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa25 = 1;
        OPEN c_aa25;
        loop_aa25: LOOP
            FETCH c_aa25 INTO v_pid_aa25, v_lp_aa25, v_pp_aa25;
            IF v_done_aa25 = 1 THEN LEAVE loop_aa25; END IF;
            SET v_var_aa25 = v_var_aa25 + (COALESCE(v_lp_aa25,0) - COALESCE(v_pp_aa25,0));
            SET v_marg_aa25 = ERP_FN_MARGIN(v_pid_aa25);
        END LOOP;
        CLOSE c_aa25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_aa25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [aa26]
    BEGIN
        DECLARE v_inv_aa26 INTEGER DEFAULT 0;
        DECLARE v_amt_aa26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_aa26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_aa26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_aa26 INTEGER DEFAULT 0;
        DECLARE c_aa26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa26 = 1;
        OPEN c_aa26;
        loop_aa26: LOOP
            FETCH c_aa26 INTO v_inv_aa26, v_amt_aa26, v_alloc_aa26;
            IF v_done_aa26 = 1 THEN LEAVE loop_aa26; END IF;
            SET v_open_aa26 = v_open_aa26 + (v_amt_aa26 - v_alloc_aa26);
        END LOOP;
        CLOSE c_aa26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_aa26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [aa27]
    BEGIN
        DECLARE v_lvl_aa27 INTEGER DEFAULT 0;
        DECLARE v_dept_aa27 INTEGER DEFAULT 0;
        DECLARE v_head_aa27 INTEGER DEFAULT 0;
        DECLARE v_done_aa27 INTEGER DEFAULT 0;
        DECLARE c_aa27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa27 = 1;
        OPEN c_aa27;
        loop_aa27: LOOP
            FETCH c_aa27 INTO v_dept_aa27, v_lvl_aa27, v_head_aa27;
            IF v_done_aa27 = 1 THEN LEAVE loop_aa27; END IF;
        END LOOP;
        CLOSE c_aa27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_aa27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_aa27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [aa28]
    BEGIN
        DECLARE v_sh_aa28 INTEGER DEFAULT 0;
        DECLARE v_car_aa28 INTEGER DEFAULT 0;
        DECLARE v_qty_aa28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_aa28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_aa28 INTEGER DEFAULT 0;
        DECLARE c_aa28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa28 = 1;
        OPEN c_aa28;
        loop_aa28: LOOP
            FETCH c_aa28 INTO v_sh_aa28, v_car_aa28, v_qty_aa28;
            IF v_done_aa28 = 1 THEN LEAVE loop_aa28; END IF;
            SET v_tot_aa28 = v_tot_aa28 + v_qty_aa28;
        END LOOP;
        CLOSE c_aa28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_aa28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [aa29]
    BEGIN
        DECLARE v_sql_aa29 VARCHAR(1000);
        DECLARE v_n_aa29 INTEGER DEFAULT 0;
        SET v_sql_aa29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_aa29 FROM v_sql_aa29;
        EXECUTE st_aa29;
        SELECT COUNT(*) INTO v_n_aa29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_aa29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [aa30]
    BEGIN
        DECLARE v_key_aa30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_aa30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_aa30' AS VARCHAR(40)), v_key_aa30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [aa31]
    BEGIN
        DECLARE v_so_aa31 INTEGER DEFAULT 0;
        DECLARE v_cust_aa31 INTEGER DEFAULT 0;
        DECLARE v_rk_aa31 INTEGER DEFAULT 0;
        DECLARE v_run_aa31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_aa31 INTEGER DEFAULT 0;
        DECLARE c_aa31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa31 = 1;
        OPEN c_aa31;
        loop_aa31: LOOP
            FETCH c_aa31 INTO v_so_aa31, v_cust_aa31, v_rk_aa31, v_run_aa31;
            IF v_done_aa31 = 1 THEN LEAVE loop_aa31; END IF;
        END LOOP;
        CLOSE c_aa31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_aa31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_aa31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [aa32]
    BEGIN
        DECLARE v_hi_aa32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_aa32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_aa32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [aa33]
    BEGIN
        DECLARE v_pairs_aa33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_aa33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_aa33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [aa34]
    BEGIN
        DECLARE v_rows_aa34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_aa34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_aa34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_aa34 FROM SESSION.TMP_aa34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_aa34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [aa35]
    BEGIN
        DECLARE v_rc_aa35 INTEGER DEFAULT 0;
        DECLARE v_band_aa35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_aa35 = ROW_COUNT;
        SET v_band_aa35 = CASE
                            WHEN v_rc_aa35 = 0 THEN 'NONE'
                            WHEN v_rc_aa35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_aa35, 'COUNT', 'band=' || v_band_aa35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [aa36]
    BEGIN
        DECLARE v_i_aa36 INTEGER DEFAULT 0;
        SAVEPOINT sp_aa36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_aa36 < 4 DO
            SET v_i_aa36 = v_i_aa36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_aa36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_aa36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_aa36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [aa37]
    BEGIN
        DECLARE v_j_aa37 INTEGER DEFAULT 0;
        DECLARE v_sum_aa37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_aa37 = v_j_aa37 + 1;
        UNTIL v_j_aa37 >= 3 END REPEAT;
        FOR row_aa37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_aa37 = v_sum_aa37 + COALESCE(row_aa37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_aa37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_aa37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [aa38]
    BEGIN
        DECLARE v_n_aa38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_aa38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_aa38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [aa39]
    BEGIN
        DECLARE v_levels_aa39 INTEGER DEFAULT 0;
        DECLARE c_aa39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_aa39 = 0;
        OPEN c_aa39;
        FETCH c_aa39 INTO v_levels_aa39;
        CLOSE c_aa39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_aa39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [aa40]
    BEGIN
        DECLARE v_sql_aa40 VARCHAR(1000);
        DECLARE v_n_aa40 INTEGER DEFAULT 0;
        SET v_sql_aa40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_aa40 FROM v_sql_aa40;
        EXECUTE st_aa40;
        SELECT COUNT(*) INTO v_n_aa40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_aa40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [aa41]
    BEGIN
        DECLARE v_key_aa41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_aa41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_aa41' AS VARCHAR(40)), v_key_aa41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [aa42]
    BEGIN
        DECLARE v_so_aa42 INTEGER DEFAULT 0;
        DECLARE v_cust_aa42 INTEGER DEFAULT 0;
        DECLARE v_ctry_aa42 INTEGER DEFAULT 0;
        DECLARE v_ccy_aa42 INTEGER DEFAULT 0;
        DECLARE v_sub_aa42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_aa42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_aa42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_aa42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_aa42 INTEGER DEFAULT 0;
        DECLARE v_done_aa42 INTEGER DEFAULT 0;
        DECLARE c_aa42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_aa42 = 1;
        OPEN c_aa42;
        loop_aa42: LOOP
            FETCH c_aa42 INTO v_so_aa42, v_cust_aa42, v_ctry_aa42, v_ccy_aa42, v_sub_aa42;
            IF v_done_aa42 = 1 THEN LEAVE loop_aa42; END IF;
            SET v_tax_aa42 = ERP_FN_TAX(v_ctry_aa42, v_sub_aa42);
            SET v_fx_aa42 = ERP_FN_FX_CONVERT(v_ccy_aa42, 1, v_sub_aa42 + v_tax_aa42);
            SET v_acc_aa42 = v_acc_aa42 + v_fx_aa42;
            SET v_cnt_aa42 = v_cnt_aa42 + 1;
        END LOOP;
        CLOSE c_aa42;
        IF v_cnt_aa42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_aa42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_aa42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    COMMIT;
END @

CREATE PROCEDURE ERP_USP_EDGE_OPS()
LANGUAGE SQL
BEGIN
    DECLARE v_i INTEGER DEFAULT 0;
    DECLARE v_band VARCHAR(10);
    DECLARE v_cnt INTEGER DEFAULT 0;
    DECLARE CONTINUE HANDLER FOR SQLWARNING
        SET v_cnt = v_cnt;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('EDGE', 0, 'ERROR', 'edge_ops failed', CURRENT TIMESTAMP);
    END;

    SAVEPOINT sp_edge ON ROLLBACK RETAIN CURSORS;

    WHILE v_i < 6 DO
        SET v_i = v_i + 1;
        SET v_band = CASE
                        WHEN v_i <= 2 THEN 'LOW'
                        WHEN v_i <= 4 THEN 'MID'
                        ELSE 'HIGH'
                     END;
        IF v_band = 'LOW' THEN
            SET v_cnt = v_cnt + 1;
        ELSEIF v_band = 'MID' THEN
            SET v_cnt = v_cnt + 2;
        ELSE
            SET v_cnt = v_cnt + 3;
        END IF;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('EDGE', v_i, 'ITER', 'band=' || v_band, CURRENT TIMESTAMP);
    END WHILE;

    -- discard the per-iteration rows, keep the summary
    ROLLBACK TO SAVEPOINT sp_edge;

    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('EDGE', v_cnt, 'DONE', 'score=' || RTRIM(CHAR(v_cnt)), CURRENT TIMESTAMP);
    COMMIT;
END @

-- ---------------------------------------------------------------------------
-- RECURSIVE CALL PATTERNS (direct self-recursion + mutual/circular recursion)
-- ---------------------------------------------------------------------------
CREATE PROCEDURE ERP_USP_EXPLODE_BOM(IN p_material_id INTEGER, IN p_depth INTEGER)
LANGUAGE SQL
BEGIN
    -- STUB body (replaced below via CREATE OR REPLACE so the self-CALL resolves)
    DECLARE v_noop INTEGER DEFAULT 0;
    SET v_noop = p_depth;
END @

CREATE OR REPLACE PROCEDURE ERP_USP_EXPLODE_BOM(IN p_material_id INTEGER, IN p_depth INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_child INTEGER DEFAULT 0;
    DECLARE v_done INTEGER DEFAULT 0;
    DECLARE c_child CURSOR FOR
        SELECT b.raw_material_id
        FROM ERP_BOM b
        WHERE b.parent_bom_id = p_material_id
        ORDER BY b.id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
    -- base case / depth guard: stop descending past 8 levels
    IF p_depth > 8 THEN
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_EXPLODE', p_material_id, 'MAXDEPTH',
                'depth guard hit at ' || RTRIM(CHAR(p_depth)), CURRENT TIMESTAMP);
        RETURN;
    END IF;
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('BOM_EXPLODE', p_material_id, 'VISIT',
            'level=' || RTRIM(CHAR(p_depth)), CURRENT TIMESTAMP);
    OPEN c_child;
    child_loop: LOOP
        FETCH c_child INTO v_child;
        IF v_done = 1 THEN LEAVE child_loop; END IF;
        -- DIRECT self-recursive CALL (guarded by p_depth + 1)
        CALL ERP_USP_EXPLODE_BOM(v_child, p_depth + 1);
    END LOOP;
    CLOSE c_child;
END @

CREATE PROCEDURE ERP_USP_WALK_DOWN(IN p_dept_id INTEGER, IN p_depth INTEGER)
LANGUAGE SQL
BEGIN
    -- STUB body (replaced below via CREATE OR REPLACE once WALK_UP exists)
    DECLARE v_noop INTEGER DEFAULT 0;
    SET v_noop = p_depth;
END @

CREATE PROCEDURE ERP_USP_WALK_UP(IN p_dept_id INTEGER, IN p_depth INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_parent INTEGER DEFAULT 0;
    DECLARE v_has_parent INTEGER DEFAULT 0;
    -- depth guard terminates the mutual-recursion cycle
    IF p_depth > 8 THEN
        RETURN;
    END IF;
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('WALK_UP', p_dept_id, 'VISIT', 'depth=' || RTRIM(CHAR(p_depth)), CURRENT TIMESTAMP);
    SELECT COALESCE(parent_id, -1) INTO v_parent FROM ERP_DEPARTMENT WHERE id = p_dept_id;
    IF v_parent >= 0 THEN
        -- MUTUAL recursion: WALK_UP -> WALK_DOWN (back-edge closes the cycle)
        CALL ERP_USP_WALK_DOWN(v_parent, p_depth + 1);
    END IF;
END @

CREATE OR REPLACE PROCEDURE ERP_USP_WALK_DOWN(IN p_dept_id INTEGER, IN p_depth INTEGER)
LANGUAGE SQL
BEGIN
    DECLARE v_child INTEGER DEFAULT 0;
    DECLARE v_done INTEGER DEFAULT 0;
    DECLARE c_kids CURSOR FOR
        SELECT d.id FROM ERP_DEPARTMENT d WHERE d.parent_id = p_dept_id ORDER BY d.id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
    -- depth guard terminates the mutual-recursion cycle
    IF p_depth > 8 THEN
        RETURN;
    END IF;
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('WALK_DOWN', p_dept_id, 'VISIT', 'depth=' || RTRIM(CHAR(p_depth)), CURRENT TIMESTAMP);
    OPEN c_kids;
    down_loop: LOOP
        FETCH c_kids INTO v_child;
        IF v_done = 1 THEN LEAVE down_loop; END IF;
        -- MUTUAL recursion: WALK_DOWN -> WALK_UP
        CALL ERP_USP_WALK_UP(v_child, p_depth + 1);
    END LOOP;
    CLOSE c_kids;
END @

CREATE PROCEDURE ERP_USP_REPORT_AR()
LANGUAGE SQL
DYNAMIC RESULT SETS 1
BEGIN
    -- WITH RETURN cursor: hand the open result set back to the caller
    DECLARE c_ar CURSOR WITH RETURN TO CALLER FOR
        SELECT customer_id, SUM(invoiced - allocated) AS open_ar
        FROM ERP_VW_OPEN_AR
        GROUP BY customer_id
        ORDER BY customer_id;
    CALL ERP_USP_AUDIT('REPORT', 0, 'AR', 'open AR result set opened');
    OPEN c_ar;
END @

-- ===========================================================================
-- ENTRY PROCEDURE (analysis root)
-- ===========================================================================
-- ===========================================================================
-- Deep linear stage chain (ERP_USP_STAGE_01 .. ERP_USP_STAGE_16)
-- Rooted by CALL ERP_USP_STAGE_01 inside ERP_USP_RUN_CYCLE.
-- Defined in reverse order so each callee precedes its caller.
-- Each stage does real DML/loops/cursors and references existing ERP_FN_* funcs.
-- ===========================================================================

CREATE PROCEDURE ERP_USP_STAGE_16(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_16', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s16b00]
    BEGIN
        DECLARE v_so_s16b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s16b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s16b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s16b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s16b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s16b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s16b00 INTEGER DEFAULT 0;
        DECLARE v_done_s16b00 INTEGER DEFAULT 0;
        DECLARE c_s16b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s16b00 = 1;
        OPEN c_s16b00;
        loop_s16b00: LOOP
            FETCH c_s16b00 INTO v_so_s16b00, v_ctry_s16b00, v_ccy_s16b00, v_sub_s16b00;
            IF v_done_s16b00 = 1 THEN LEAVE loop_s16b00; END IF;
            SET v_tax_s16b00 = ERP_FN_TAX(v_ctry_s16b00, v_sub_s16b00);
            SET v_acc_s16b00 = v_acc_s16b00 + ERP_FN_FX_CONVERT(v_ccy_s16b00, 1, v_sub_s16b00 + v_tax_s16b00);
            SET v_cnt_s16b00 = v_cnt_s16b00 + 1;
        END LOOP;
        CLOSE c_s16b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s16b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s16b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s16b01]
    BEGIN
        DECLARE v_pid_s16b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s16b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s16b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s16b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s16b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s16b01 INTEGER DEFAULT 0;
        DECLARE c_s16b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s16b01 = 1;
        OPEN c_s16b01;
        loop_s16b01: LOOP
            FETCH c_s16b01 INTO v_pid_s16b01, v_oh_s16b01;
            IF v_done_s16b01 = 1 THEN LEAVE loop_s16b01; END IF;
            SET v_avail_s16b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s16b01);
            SET v_ro_s16b01 = ERP_FN_REORDER_QTY(v_pid_s16b01, 100);
            SET v_val_s16b01 = v_val_s16b01 + v_avail_s16b01 + v_ro_s16b01;
        END LOOP;
        CLOSE c_s16b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s16b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s16b02]
    BEGIN
        DECLARE v_pid_s16b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s16b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s16b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s16b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s16b02 INTEGER DEFAULT 0;
        DECLARE c_s16b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s16b02 = 1;
        OPEN c_s16b02;
        loop_s16b02: LOOP
            FETCH c_s16b02 INTO v_pid_s16b02;
            IF v_done_s16b02 = 1 THEN LEAVE loop_s16b02; END IF;
            SET v_mrg_s16b02 = ERP_FN_MARGIN(v_pid_s16b02);
            SET v_bc_s16b02 = ERP_FN_BOM_COST(v_pid_s16b02);
            IF v_mrg_s16b02 > 0 THEN
                SET v_tot_s16b02 = v_tot_s16b02 + v_bc_s16b02;
            ELSE
                SET v_tot_s16b02 = v_tot_s16b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s16b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s16b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s16b03]
    BEGIN
        DECLARE v_st_s16b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s16b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s16b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s16b03 = 0;
        FOR row_s16b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s16b03 = ERP_FN_ORDER_SUBTOTAL(row_s16b03.soid);
            SET v_lt_s16b03 = ERP_FN_LINE_TOTAL(1, v_st_s16b03, 0);
            SET v_grand_s16b03 = v_grand_s16b03 + v_st_s16b03 + (v_lt_s16b03 - v_lt_s16b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s16b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s16b04]
    BEGIN
        DECLARE v_cid_s16b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s16b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s16b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s16b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s16b04 INTEGER DEFAULT 0;
        DECLARE v_done_s16b04 INTEGER DEFAULT 0;
        DECLARE c_s16b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s16b04 = 1;
        OPEN c_s16b04;
        loop_s16b04: LOOP
            FETCH c_s16b04 INTO v_cid_s16b04;
            IF v_done_s16b04 = 1 THEN LEAVE loop_s16b04; END IF;
            SET v_bal_s16b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s16b04);
            SET v_disc_s16b04 = ERP_FN_DISCOUNT_PCT(v_cid_s16b04, 25);
            SET v_ok_s16b04 = ERP_FN_CREDIT_OK(v_cid_s16b04, v_bal_s16b04 + v_disc_s16b04);
            IF v_ok_s16b04 = 0 THEN SET v_bad_s16b04 = v_bad_s16b04 + 1; END IF;
        END LOOP;
        CLOSE c_s16b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s16b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s16b05]
    BEGIN
        DECLARE v_per_s16b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s16b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s16b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s16b05 INTEGER DEFAULT 0;
        DECLARE v_done_s16b05 INTEGER DEFAULT 0;
        DECLARE c_s16b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s16b05 = 1;
        SET v_per_s16b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s16b05;
        loop_s16b05: LOOP
            FETCH c_s16b05 INTO v_pid_s16b05;
            IF v_done_s16b05 = 1 THEN LEAVE loop_s16b05; END IF;
            SET v_dep_s16b05 = ERP_FN_BOM_DEPTH(v_pid_s16b05);
            IF v_dep_s16b05 > v_maxdep_s16b05 THEN SET v_maxdep_s16b05 = v_dep_s16b05; END IF;
        END LOOP;
        CLOSE c_s16b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s16b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s16b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s16b06]
    BEGIN
        DECLARE v_net_s16b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s16b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s16b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s16b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s16b06 INTEGER DEFAULT 0;
        DECLARE c_s16b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s16b06 = 1;
        OPEN c_s16b06;
        loop_s16b06: LOOP
            FETCH c_s16b06 INTO v_acct_s16b06, v_deb_s16b06, v_cred_s16b06;
            IF v_done_s16b06 = 1 THEN LEAVE loop_s16b06; END IF;
            SET v_net_s16b06 = v_net_s16b06 + (v_deb_s16b06 - v_cred_s16b06);
        END LOOP;
        CLOSE c_s16b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s16b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s16b07]
    BEGIN
        DECLARE v_sql_s16b07 VARCHAR(1000);
        DECLARE v_n_s16b07 INTEGER DEFAULT 0;
        SET v_sql_s16b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s16b07 FROM v_sql_s16b07;
        EXECUTE st_s16b07;
        SELECT COUNT(*) INTO v_n_s16b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s16b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s16b08]
    BEGIN
        DECLARE v_key_s16b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s16b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s16b08' AS VARCHAR(40)), v_key_s16b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s16b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s16b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s16b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s16b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s16b09 FROM SESSION.TMP_s16b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s16b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s16b09 INTEGER DEFAULT 0;
            DECLARE c_s16b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s16b09 = 0;
            OPEN c_s16b09;
            FETCH c_s16b09 INTO v_lvl_s16b09;
            CLOSE c_s16b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s16b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s16b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s16b09 INTEGER DEFAULT 0;
            DECLARE v_band_s16b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s16b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s16b09 = ROW_COUNT;
            SET v_band_s16b09 = CASE WHEN v_rc_s16b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s16b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s16b09, 'STAGE', 'band=' || v_band_s16b09, CURRENT TIMESTAMP);
        END;
    END;
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_16', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_15(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_15', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s15b00]
    BEGIN
        DECLARE v_so_s15b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s15b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s15b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s15b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s15b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s15b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s15b00 INTEGER DEFAULT 0;
        DECLARE v_done_s15b00 INTEGER DEFAULT 0;
        DECLARE c_s15b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s15b00 = 1;
        OPEN c_s15b00;
        loop_s15b00: LOOP
            FETCH c_s15b00 INTO v_so_s15b00, v_ctry_s15b00, v_ccy_s15b00, v_sub_s15b00;
            IF v_done_s15b00 = 1 THEN LEAVE loop_s15b00; END IF;
            SET v_tax_s15b00 = ERP_FN_TAX(v_ctry_s15b00, v_sub_s15b00);
            SET v_acc_s15b00 = v_acc_s15b00 + ERP_FN_FX_CONVERT(v_ccy_s15b00, 1, v_sub_s15b00 + v_tax_s15b00);
            SET v_cnt_s15b00 = v_cnt_s15b00 + 1;
        END LOOP;
        CLOSE c_s15b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s15b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s15b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s15b01]
    BEGIN
        DECLARE v_pid_s15b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s15b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s15b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s15b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s15b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s15b01 INTEGER DEFAULT 0;
        DECLARE c_s15b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s15b01 = 1;
        OPEN c_s15b01;
        loop_s15b01: LOOP
            FETCH c_s15b01 INTO v_pid_s15b01, v_oh_s15b01;
            IF v_done_s15b01 = 1 THEN LEAVE loop_s15b01; END IF;
            SET v_avail_s15b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s15b01);
            SET v_ro_s15b01 = ERP_FN_REORDER_QTY(v_pid_s15b01, 100);
            SET v_val_s15b01 = v_val_s15b01 + v_avail_s15b01 + v_ro_s15b01;
        END LOOP;
        CLOSE c_s15b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s15b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s15b02]
    BEGIN
        DECLARE v_pid_s15b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s15b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s15b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s15b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s15b02 INTEGER DEFAULT 0;
        DECLARE c_s15b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s15b02 = 1;
        OPEN c_s15b02;
        loop_s15b02: LOOP
            FETCH c_s15b02 INTO v_pid_s15b02;
            IF v_done_s15b02 = 1 THEN LEAVE loop_s15b02; END IF;
            SET v_mrg_s15b02 = ERP_FN_MARGIN(v_pid_s15b02);
            SET v_bc_s15b02 = ERP_FN_BOM_COST(v_pid_s15b02);
            IF v_mrg_s15b02 > 0 THEN
                SET v_tot_s15b02 = v_tot_s15b02 + v_bc_s15b02;
            ELSE
                SET v_tot_s15b02 = v_tot_s15b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s15b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s15b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s15b03]
    BEGIN
        DECLARE v_st_s15b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s15b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s15b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s15b03 = 0;
        FOR row_s15b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s15b03 = ERP_FN_ORDER_SUBTOTAL(row_s15b03.soid);
            SET v_lt_s15b03 = ERP_FN_LINE_TOTAL(1, v_st_s15b03, 0);
            SET v_grand_s15b03 = v_grand_s15b03 + v_st_s15b03 + (v_lt_s15b03 - v_lt_s15b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s15b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s15b04]
    BEGIN
        DECLARE v_cid_s15b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s15b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s15b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s15b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s15b04 INTEGER DEFAULT 0;
        DECLARE v_done_s15b04 INTEGER DEFAULT 0;
        DECLARE c_s15b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s15b04 = 1;
        OPEN c_s15b04;
        loop_s15b04: LOOP
            FETCH c_s15b04 INTO v_cid_s15b04;
            IF v_done_s15b04 = 1 THEN LEAVE loop_s15b04; END IF;
            SET v_bal_s15b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s15b04);
            SET v_disc_s15b04 = ERP_FN_DISCOUNT_PCT(v_cid_s15b04, 25);
            SET v_ok_s15b04 = ERP_FN_CREDIT_OK(v_cid_s15b04, v_bal_s15b04 + v_disc_s15b04);
            IF v_ok_s15b04 = 0 THEN SET v_bad_s15b04 = v_bad_s15b04 + 1; END IF;
        END LOOP;
        CLOSE c_s15b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s15b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s15b05]
    BEGIN
        DECLARE v_per_s15b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s15b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s15b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s15b05 INTEGER DEFAULT 0;
        DECLARE v_done_s15b05 INTEGER DEFAULT 0;
        DECLARE c_s15b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s15b05 = 1;
        SET v_per_s15b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s15b05;
        loop_s15b05: LOOP
            FETCH c_s15b05 INTO v_pid_s15b05;
            IF v_done_s15b05 = 1 THEN LEAVE loop_s15b05; END IF;
            SET v_dep_s15b05 = ERP_FN_BOM_DEPTH(v_pid_s15b05);
            IF v_dep_s15b05 > v_maxdep_s15b05 THEN SET v_maxdep_s15b05 = v_dep_s15b05; END IF;
        END LOOP;
        CLOSE c_s15b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s15b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s15b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s15b06]
    BEGIN
        DECLARE v_net_s15b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s15b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s15b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s15b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s15b06 INTEGER DEFAULT 0;
        DECLARE c_s15b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s15b06 = 1;
        OPEN c_s15b06;
        loop_s15b06: LOOP
            FETCH c_s15b06 INTO v_acct_s15b06, v_deb_s15b06, v_cred_s15b06;
            IF v_done_s15b06 = 1 THEN LEAVE loop_s15b06; END IF;
            SET v_net_s15b06 = v_net_s15b06 + (v_deb_s15b06 - v_cred_s15b06);
        END LOOP;
        CLOSE c_s15b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s15b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s15b07]
    BEGIN
        DECLARE v_sql_s15b07 VARCHAR(1000);
        DECLARE v_n_s15b07 INTEGER DEFAULT 0;
        SET v_sql_s15b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s15b07 FROM v_sql_s15b07;
        EXECUTE st_s15b07;
        SELECT COUNT(*) INTO v_n_s15b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s15b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s15b08]
    BEGIN
        DECLARE v_key_s15b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s15b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s15b08' AS VARCHAR(40)), v_key_s15b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s15b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s15b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s15b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s15b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s15b09 FROM SESSION.TMP_s15b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s15b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s15b09 INTEGER DEFAULT 0;
            DECLARE c_s15b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s15b09 = 0;
            OPEN c_s15b09;
            FETCH c_s15b09 INTO v_lvl_s15b09;
            CLOSE c_s15b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s15b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s15b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s15b09 INTEGER DEFAULT 0;
            DECLARE v_band_s15b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s15b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s15b09 = ROW_COUNT;
            SET v_band_s15b09 = CASE WHEN v_rc_s15b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s15b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s15b09, 'STAGE', 'band=' || v_band_s15b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_16(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_15', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_14(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_14', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s14b00]
    BEGIN
        DECLARE v_so_s14b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s14b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s14b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s14b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s14b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s14b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s14b00 INTEGER DEFAULT 0;
        DECLARE v_done_s14b00 INTEGER DEFAULT 0;
        DECLARE c_s14b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s14b00 = 1;
        OPEN c_s14b00;
        loop_s14b00: LOOP
            FETCH c_s14b00 INTO v_so_s14b00, v_ctry_s14b00, v_ccy_s14b00, v_sub_s14b00;
            IF v_done_s14b00 = 1 THEN LEAVE loop_s14b00; END IF;
            SET v_tax_s14b00 = ERP_FN_TAX(v_ctry_s14b00, v_sub_s14b00);
            SET v_acc_s14b00 = v_acc_s14b00 + ERP_FN_FX_CONVERT(v_ccy_s14b00, 1, v_sub_s14b00 + v_tax_s14b00);
            SET v_cnt_s14b00 = v_cnt_s14b00 + 1;
        END LOOP;
        CLOSE c_s14b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s14b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s14b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s14b01]
    BEGIN
        DECLARE v_pid_s14b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s14b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s14b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s14b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s14b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s14b01 INTEGER DEFAULT 0;
        DECLARE c_s14b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s14b01 = 1;
        OPEN c_s14b01;
        loop_s14b01: LOOP
            FETCH c_s14b01 INTO v_pid_s14b01, v_oh_s14b01;
            IF v_done_s14b01 = 1 THEN LEAVE loop_s14b01; END IF;
            SET v_avail_s14b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s14b01);
            SET v_ro_s14b01 = ERP_FN_REORDER_QTY(v_pid_s14b01, 100);
            SET v_val_s14b01 = v_val_s14b01 + v_avail_s14b01 + v_ro_s14b01;
        END LOOP;
        CLOSE c_s14b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s14b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s14b02]
    BEGIN
        DECLARE v_pid_s14b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s14b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s14b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s14b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s14b02 INTEGER DEFAULT 0;
        DECLARE c_s14b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s14b02 = 1;
        OPEN c_s14b02;
        loop_s14b02: LOOP
            FETCH c_s14b02 INTO v_pid_s14b02;
            IF v_done_s14b02 = 1 THEN LEAVE loop_s14b02; END IF;
            SET v_mrg_s14b02 = ERP_FN_MARGIN(v_pid_s14b02);
            SET v_bc_s14b02 = ERP_FN_BOM_COST(v_pid_s14b02);
            IF v_mrg_s14b02 > 0 THEN
                SET v_tot_s14b02 = v_tot_s14b02 + v_bc_s14b02;
            ELSE
                SET v_tot_s14b02 = v_tot_s14b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s14b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s14b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s14b03]
    BEGIN
        DECLARE v_st_s14b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s14b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s14b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s14b03 = 0;
        FOR row_s14b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s14b03 = ERP_FN_ORDER_SUBTOTAL(row_s14b03.soid);
            SET v_lt_s14b03 = ERP_FN_LINE_TOTAL(1, v_st_s14b03, 0);
            SET v_grand_s14b03 = v_grand_s14b03 + v_st_s14b03 + (v_lt_s14b03 - v_lt_s14b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s14b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s14b04]
    BEGIN
        DECLARE v_cid_s14b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s14b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s14b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s14b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s14b04 INTEGER DEFAULT 0;
        DECLARE v_done_s14b04 INTEGER DEFAULT 0;
        DECLARE c_s14b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s14b04 = 1;
        OPEN c_s14b04;
        loop_s14b04: LOOP
            FETCH c_s14b04 INTO v_cid_s14b04;
            IF v_done_s14b04 = 1 THEN LEAVE loop_s14b04; END IF;
            SET v_bal_s14b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s14b04);
            SET v_disc_s14b04 = ERP_FN_DISCOUNT_PCT(v_cid_s14b04, 25);
            SET v_ok_s14b04 = ERP_FN_CREDIT_OK(v_cid_s14b04, v_bal_s14b04 + v_disc_s14b04);
            IF v_ok_s14b04 = 0 THEN SET v_bad_s14b04 = v_bad_s14b04 + 1; END IF;
        END LOOP;
        CLOSE c_s14b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s14b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s14b05]
    BEGIN
        DECLARE v_per_s14b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s14b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s14b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s14b05 INTEGER DEFAULT 0;
        DECLARE v_done_s14b05 INTEGER DEFAULT 0;
        DECLARE c_s14b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s14b05 = 1;
        SET v_per_s14b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s14b05;
        loop_s14b05: LOOP
            FETCH c_s14b05 INTO v_pid_s14b05;
            IF v_done_s14b05 = 1 THEN LEAVE loop_s14b05; END IF;
            SET v_dep_s14b05 = ERP_FN_BOM_DEPTH(v_pid_s14b05);
            IF v_dep_s14b05 > v_maxdep_s14b05 THEN SET v_maxdep_s14b05 = v_dep_s14b05; END IF;
        END LOOP;
        CLOSE c_s14b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s14b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s14b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s14b06]
    BEGIN
        DECLARE v_net_s14b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s14b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s14b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s14b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s14b06 INTEGER DEFAULT 0;
        DECLARE c_s14b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s14b06 = 1;
        OPEN c_s14b06;
        loop_s14b06: LOOP
            FETCH c_s14b06 INTO v_acct_s14b06, v_deb_s14b06, v_cred_s14b06;
            IF v_done_s14b06 = 1 THEN LEAVE loop_s14b06; END IF;
            SET v_net_s14b06 = v_net_s14b06 + (v_deb_s14b06 - v_cred_s14b06);
        END LOOP;
        CLOSE c_s14b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s14b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s14b07]
    BEGIN
        DECLARE v_sql_s14b07 VARCHAR(1000);
        DECLARE v_n_s14b07 INTEGER DEFAULT 0;
        SET v_sql_s14b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s14b07 FROM v_sql_s14b07;
        EXECUTE st_s14b07;
        SELECT COUNT(*) INTO v_n_s14b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s14b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s14b08]
    BEGIN
        DECLARE v_key_s14b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s14b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s14b08' AS VARCHAR(40)), v_key_s14b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s14b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s14b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s14b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s14b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s14b09 FROM SESSION.TMP_s14b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s14b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s14b09 INTEGER DEFAULT 0;
            DECLARE c_s14b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s14b09 = 0;
            OPEN c_s14b09;
            FETCH c_s14b09 INTO v_lvl_s14b09;
            CLOSE c_s14b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s14b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s14b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s14b09 INTEGER DEFAULT 0;
            DECLARE v_band_s14b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s14b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s14b09 = ROW_COUNT;
            SET v_band_s14b09 = CASE WHEN v_rc_s14b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s14b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s14b09, 'STAGE', 'band=' || v_band_s14b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_15(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_14', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_13(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_13', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s13b00]
    BEGIN
        DECLARE v_so_s13b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s13b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s13b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s13b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s13b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s13b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s13b00 INTEGER DEFAULT 0;
        DECLARE v_done_s13b00 INTEGER DEFAULT 0;
        DECLARE c_s13b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s13b00 = 1;
        OPEN c_s13b00;
        loop_s13b00: LOOP
            FETCH c_s13b00 INTO v_so_s13b00, v_ctry_s13b00, v_ccy_s13b00, v_sub_s13b00;
            IF v_done_s13b00 = 1 THEN LEAVE loop_s13b00; END IF;
            SET v_tax_s13b00 = ERP_FN_TAX(v_ctry_s13b00, v_sub_s13b00);
            SET v_acc_s13b00 = v_acc_s13b00 + ERP_FN_FX_CONVERT(v_ccy_s13b00, 1, v_sub_s13b00 + v_tax_s13b00);
            SET v_cnt_s13b00 = v_cnt_s13b00 + 1;
        END LOOP;
        CLOSE c_s13b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s13b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s13b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s13b01]
    BEGIN
        DECLARE v_pid_s13b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s13b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s13b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s13b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s13b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s13b01 INTEGER DEFAULT 0;
        DECLARE c_s13b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s13b01 = 1;
        OPEN c_s13b01;
        loop_s13b01: LOOP
            FETCH c_s13b01 INTO v_pid_s13b01, v_oh_s13b01;
            IF v_done_s13b01 = 1 THEN LEAVE loop_s13b01; END IF;
            SET v_avail_s13b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s13b01);
            SET v_ro_s13b01 = ERP_FN_REORDER_QTY(v_pid_s13b01, 100);
            SET v_val_s13b01 = v_val_s13b01 + v_avail_s13b01 + v_ro_s13b01;
        END LOOP;
        CLOSE c_s13b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s13b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s13b02]
    BEGIN
        DECLARE v_pid_s13b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s13b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s13b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s13b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s13b02 INTEGER DEFAULT 0;
        DECLARE c_s13b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s13b02 = 1;
        OPEN c_s13b02;
        loop_s13b02: LOOP
            FETCH c_s13b02 INTO v_pid_s13b02;
            IF v_done_s13b02 = 1 THEN LEAVE loop_s13b02; END IF;
            SET v_mrg_s13b02 = ERP_FN_MARGIN(v_pid_s13b02);
            SET v_bc_s13b02 = ERP_FN_BOM_COST(v_pid_s13b02);
            IF v_mrg_s13b02 > 0 THEN
                SET v_tot_s13b02 = v_tot_s13b02 + v_bc_s13b02;
            ELSE
                SET v_tot_s13b02 = v_tot_s13b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s13b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s13b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s13b03]
    BEGIN
        DECLARE v_st_s13b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s13b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s13b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s13b03 = 0;
        FOR row_s13b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s13b03 = ERP_FN_ORDER_SUBTOTAL(row_s13b03.soid);
            SET v_lt_s13b03 = ERP_FN_LINE_TOTAL(1, v_st_s13b03, 0);
            SET v_grand_s13b03 = v_grand_s13b03 + v_st_s13b03 + (v_lt_s13b03 - v_lt_s13b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s13b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s13b04]
    BEGIN
        DECLARE v_cid_s13b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s13b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s13b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s13b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s13b04 INTEGER DEFAULT 0;
        DECLARE v_done_s13b04 INTEGER DEFAULT 0;
        DECLARE c_s13b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s13b04 = 1;
        OPEN c_s13b04;
        loop_s13b04: LOOP
            FETCH c_s13b04 INTO v_cid_s13b04;
            IF v_done_s13b04 = 1 THEN LEAVE loop_s13b04; END IF;
            SET v_bal_s13b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s13b04);
            SET v_disc_s13b04 = ERP_FN_DISCOUNT_PCT(v_cid_s13b04, 25);
            SET v_ok_s13b04 = ERP_FN_CREDIT_OK(v_cid_s13b04, v_bal_s13b04 + v_disc_s13b04);
            IF v_ok_s13b04 = 0 THEN SET v_bad_s13b04 = v_bad_s13b04 + 1; END IF;
        END LOOP;
        CLOSE c_s13b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s13b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s13b05]
    BEGIN
        DECLARE v_per_s13b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s13b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s13b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s13b05 INTEGER DEFAULT 0;
        DECLARE v_done_s13b05 INTEGER DEFAULT 0;
        DECLARE c_s13b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s13b05 = 1;
        SET v_per_s13b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s13b05;
        loop_s13b05: LOOP
            FETCH c_s13b05 INTO v_pid_s13b05;
            IF v_done_s13b05 = 1 THEN LEAVE loop_s13b05; END IF;
            SET v_dep_s13b05 = ERP_FN_BOM_DEPTH(v_pid_s13b05);
            IF v_dep_s13b05 > v_maxdep_s13b05 THEN SET v_maxdep_s13b05 = v_dep_s13b05; END IF;
        END LOOP;
        CLOSE c_s13b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s13b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s13b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s13b06]
    BEGIN
        DECLARE v_net_s13b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s13b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s13b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s13b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s13b06 INTEGER DEFAULT 0;
        DECLARE c_s13b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s13b06 = 1;
        OPEN c_s13b06;
        loop_s13b06: LOOP
            FETCH c_s13b06 INTO v_acct_s13b06, v_deb_s13b06, v_cred_s13b06;
            IF v_done_s13b06 = 1 THEN LEAVE loop_s13b06; END IF;
            SET v_net_s13b06 = v_net_s13b06 + (v_deb_s13b06 - v_cred_s13b06);
        END LOOP;
        CLOSE c_s13b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s13b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s13b07]
    BEGIN
        DECLARE v_sql_s13b07 VARCHAR(1000);
        DECLARE v_n_s13b07 INTEGER DEFAULT 0;
        SET v_sql_s13b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s13b07 FROM v_sql_s13b07;
        EXECUTE st_s13b07;
        SELECT COUNT(*) INTO v_n_s13b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s13b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s13b08]
    BEGIN
        DECLARE v_key_s13b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s13b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s13b08' AS VARCHAR(40)), v_key_s13b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s13b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s13b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s13b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s13b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s13b09 FROM SESSION.TMP_s13b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s13b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s13b09 INTEGER DEFAULT 0;
            DECLARE c_s13b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s13b09 = 0;
            OPEN c_s13b09;
            FETCH c_s13b09 INTO v_lvl_s13b09;
            CLOSE c_s13b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s13b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s13b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s13b09 INTEGER DEFAULT 0;
            DECLARE v_band_s13b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s13b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s13b09 = ROW_COUNT;
            SET v_band_s13b09 = CASE WHEN v_rc_s13b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s13b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s13b09, 'STAGE', 'band=' || v_band_s13b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_14(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_13', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_12(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_12', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s12b00]
    BEGIN
        DECLARE v_so_s12b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s12b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s12b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s12b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s12b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s12b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s12b00 INTEGER DEFAULT 0;
        DECLARE v_done_s12b00 INTEGER DEFAULT 0;
        DECLARE c_s12b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s12b00 = 1;
        OPEN c_s12b00;
        loop_s12b00: LOOP
            FETCH c_s12b00 INTO v_so_s12b00, v_ctry_s12b00, v_ccy_s12b00, v_sub_s12b00;
            IF v_done_s12b00 = 1 THEN LEAVE loop_s12b00; END IF;
            SET v_tax_s12b00 = ERP_FN_TAX(v_ctry_s12b00, v_sub_s12b00);
            SET v_acc_s12b00 = v_acc_s12b00 + ERP_FN_FX_CONVERT(v_ccy_s12b00, 1, v_sub_s12b00 + v_tax_s12b00);
            SET v_cnt_s12b00 = v_cnt_s12b00 + 1;
        END LOOP;
        CLOSE c_s12b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s12b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s12b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s12b01]
    BEGIN
        DECLARE v_pid_s12b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s12b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s12b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s12b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s12b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s12b01 INTEGER DEFAULT 0;
        DECLARE c_s12b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s12b01 = 1;
        OPEN c_s12b01;
        loop_s12b01: LOOP
            FETCH c_s12b01 INTO v_pid_s12b01, v_oh_s12b01;
            IF v_done_s12b01 = 1 THEN LEAVE loop_s12b01; END IF;
            SET v_avail_s12b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s12b01);
            SET v_ro_s12b01 = ERP_FN_REORDER_QTY(v_pid_s12b01, 100);
            SET v_val_s12b01 = v_val_s12b01 + v_avail_s12b01 + v_ro_s12b01;
        END LOOP;
        CLOSE c_s12b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s12b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s12b02]
    BEGIN
        DECLARE v_pid_s12b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s12b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s12b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s12b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s12b02 INTEGER DEFAULT 0;
        DECLARE c_s12b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s12b02 = 1;
        OPEN c_s12b02;
        loop_s12b02: LOOP
            FETCH c_s12b02 INTO v_pid_s12b02;
            IF v_done_s12b02 = 1 THEN LEAVE loop_s12b02; END IF;
            SET v_mrg_s12b02 = ERP_FN_MARGIN(v_pid_s12b02);
            SET v_bc_s12b02 = ERP_FN_BOM_COST(v_pid_s12b02);
            IF v_mrg_s12b02 > 0 THEN
                SET v_tot_s12b02 = v_tot_s12b02 + v_bc_s12b02;
            ELSE
                SET v_tot_s12b02 = v_tot_s12b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s12b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s12b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s12b03]
    BEGIN
        DECLARE v_st_s12b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s12b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s12b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s12b03 = 0;
        FOR row_s12b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s12b03 = ERP_FN_ORDER_SUBTOTAL(row_s12b03.soid);
            SET v_lt_s12b03 = ERP_FN_LINE_TOTAL(1, v_st_s12b03, 0);
            SET v_grand_s12b03 = v_grand_s12b03 + v_st_s12b03 + (v_lt_s12b03 - v_lt_s12b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s12b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s12b04]
    BEGIN
        DECLARE v_cid_s12b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s12b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s12b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s12b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s12b04 INTEGER DEFAULT 0;
        DECLARE v_done_s12b04 INTEGER DEFAULT 0;
        DECLARE c_s12b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s12b04 = 1;
        OPEN c_s12b04;
        loop_s12b04: LOOP
            FETCH c_s12b04 INTO v_cid_s12b04;
            IF v_done_s12b04 = 1 THEN LEAVE loop_s12b04; END IF;
            SET v_bal_s12b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s12b04);
            SET v_disc_s12b04 = ERP_FN_DISCOUNT_PCT(v_cid_s12b04, 25);
            SET v_ok_s12b04 = ERP_FN_CREDIT_OK(v_cid_s12b04, v_bal_s12b04 + v_disc_s12b04);
            IF v_ok_s12b04 = 0 THEN SET v_bad_s12b04 = v_bad_s12b04 + 1; END IF;
        END LOOP;
        CLOSE c_s12b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s12b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s12b05]
    BEGIN
        DECLARE v_per_s12b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s12b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s12b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s12b05 INTEGER DEFAULT 0;
        DECLARE v_done_s12b05 INTEGER DEFAULT 0;
        DECLARE c_s12b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s12b05 = 1;
        SET v_per_s12b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s12b05;
        loop_s12b05: LOOP
            FETCH c_s12b05 INTO v_pid_s12b05;
            IF v_done_s12b05 = 1 THEN LEAVE loop_s12b05; END IF;
            SET v_dep_s12b05 = ERP_FN_BOM_DEPTH(v_pid_s12b05);
            IF v_dep_s12b05 > v_maxdep_s12b05 THEN SET v_maxdep_s12b05 = v_dep_s12b05; END IF;
        END LOOP;
        CLOSE c_s12b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s12b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s12b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s12b06]
    BEGIN
        DECLARE v_net_s12b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s12b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s12b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s12b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s12b06 INTEGER DEFAULT 0;
        DECLARE c_s12b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s12b06 = 1;
        OPEN c_s12b06;
        loop_s12b06: LOOP
            FETCH c_s12b06 INTO v_acct_s12b06, v_deb_s12b06, v_cred_s12b06;
            IF v_done_s12b06 = 1 THEN LEAVE loop_s12b06; END IF;
            SET v_net_s12b06 = v_net_s12b06 + (v_deb_s12b06 - v_cred_s12b06);
        END LOOP;
        CLOSE c_s12b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s12b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s12b07]
    BEGIN
        DECLARE v_sql_s12b07 VARCHAR(1000);
        DECLARE v_n_s12b07 INTEGER DEFAULT 0;
        SET v_sql_s12b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s12b07 FROM v_sql_s12b07;
        EXECUTE st_s12b07;
        SELECT COUNT(*) INTO v_n_s12b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s12b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s12b08]
    BEGIN
        DECLARE v_key_s12b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s12b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s12b08' AS VARCHAR(40)), v_key_s12b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s12b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s12b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s12b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s12b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s12b09 FROM SESSION.TMP_s12b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s12b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s12b09 INTEGER DEFAULT 0;
            DECLARE c_s12b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s12b09 = 0;
            OPEN c_s12b09;
            FETCH c_s12b09 INTO v_lvl_s12b09;
            CLOSE c_s12b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s12b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s12b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s12b09 INTEGER DEFAULT 0;
            DECLARE v_band_s12b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s12b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s12b09 = ROW_COUNT;
            SET v_band_s12b09 = CASE WHEN v_rc_s12b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s12b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s12b09, 'STAGE', 'band=' || v_band_s12b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_13(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_12', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_11(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_11', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s11b00]
    BEGIN
        DECLARE v_so_s11b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s11b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s11b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s11b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s11b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s11b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s11b00 INTEGER DEFAULT 0;
        DECLARE v_done_s11b00 INTEGER DEFAULT 0;
        DECLARE c_s11b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s11b00 = 1;
        OPEN c_s11b00;
        loop_s11b00: LOOP
            FETCH c_s11b00 INTO v_so_s11b00, v_ctry_s11b00, v_ccy_s11b00, v_sub_s11b00;
            IF v_done_s11b00 = 1 THEN LEAVE loop_s11b00; END IF;
            SET v_tax_s11b00 = ERP_FN_TAX(v_ctry_s11b00, v_sub_s11b00);
            SET v_acc_s11b00 = v_acc_s11b00 + ERP_FN_FX_CONVERT(v_ccy_s11b00, 1, v_sub_s11b00 + v_tax_s11b00);
            SET v_cnt_s11b00 = v_cnt_s11b00 + 1;
        END LOOP;
        CLOSE c_s11b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s11b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s11b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s11b01]
    BEGIN
        DECLARE v_pid_s11b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s11b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s11b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s11b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s11b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s11b01 INTEGER DEFAULT 0;
        DECLARE c_s11b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s11b01 = 1;
        OPEN c_s11b01;
        loop_s11b01: LOOP
            FETCH c_s11b01 INTO v_pid_s11b01, v_oh_s11b01;
            IF v_done_s11b01 = 1 THEN LEAVE loop_s11b01; END IF;
            SET v_avail_s11b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s11b01);
            SET v_ro_s11b01 = ERP_FN_REORDER_QTY(v_pid_s11b01, 100);
            SET v_val_s11b01 = v_val_s11b01 + v_avail_s11b01 + v_ro_s11b01;
        END LOOP;
        CLOSE c_s11b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s11b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s11b02]
    BEGIN
        DECLARE v_pid_s11b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s11b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s11b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s11b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s11b02 INTEGER DEFAULT 0;
        DECLARE c_s11b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s11b02 = 1;
        OPEN c_s11b02;
        loop_s11b02: LOOP
            FETCH c_s11b02 INTO v_pid_s11b02;
            IF v_done_s11b02 = 1 THEN LEAVE loop_s11b02; END IF;
            SET v_mrg_s11b02 = ERP_FN_MARGIN(v_pid_s11b02);
            SET v_bc_s11b02 = ERP_FN_BOM_COST(v_pid_s11b02);
            IF v_mrg_s11b02 > 0 THEN
                SET v_tot_s11b02 = v_tot_s11b02 + v_bc_s11b02;
            ELSE
                SET v_tot_s11b02 = v_tot_s11b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s11b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s11b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s11b03]
    BEGIN
        DECLARE v_st_s11b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s11b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s11b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s11b03 = 0;
        FOR row_s11b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s11b03 = ERP_FN_ORDER_SUBTOTAL(row_s11b03.soid);
            SET v_lt_s11b03 = ERP_FN_LINE_TOTAL(1, v_st_s11b03, 0);
            SET v_grand_s11b03 = v_grand_s11b03 + v_st_s11b03 + (v_lt_s11b03 - v_lt_s11b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s11b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s11b04]
    BEGIN
        DECLARE v_cid_s11b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s11b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s11b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s11b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s11b04 INTEGER DEFAULT 0;
        DECLARE v_done_s11b04 INTEGER DEFAULT 0;
        DECLARE c_s11b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s11b04 = 1;
        OPEN c_s11b04;
        loop_s11b04: LOOP
            FETCH c_s11b04 INTO v_cid_s11b04;
            IF v_done_s11b04 = 1 THEN LEAVE loop_s11b04; END IF;
            SET v_bal_s11b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s11b04);
            SET v_disc_s11b04 = ERP_FN_DISCOUNT_PCT(v_cid_s11b04, 25);
            SET v_ok_s11b04 = ERP_FN_CREDIT_OK(v_cid_s11b04, v_bal_s11b04 + v_disc_s11b04);
            IF v_ok_s11b04 = 0 THEN SET v_bad_s11b04 = v_bad_s11b04 + 1; END IF;
        END LOOP;
        CLOSE c_s11b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s11b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s11b05]
    BEGIN
        DECLARE v_per_s11b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s11b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s11b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s11b05 INTEGER DEFAULT 0;
        DECLARE v_done_s11b05 INTEGER DEFAULT 0;
        DECLARE c_s11b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s11b05 = 1;
        SET v_per_s11b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s11b05;
        loop_s11b05: LOOP
            FETCH c_s11b05 INTO v_pid_s11b05;
            IF v_done_s11b05 = 1 THEN LEAVE loop_s11b05; END IF;
            SET v_dep_s11b05 = ERP_FN_BOM_DEPTH(v_pid_s11b05);
            IF v_dep_s11b05 > v_maxdep_s11b05 THEN SET v_maxdep_s11b05 = v_dep_s11b05; END IF;
        END LOOP;
        CLOSE c_s11b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s11b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s11b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s11b06]
    BEGIN
        DECLARE v_net_s11b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s11b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s11b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s11b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s11b06 INTEGER DEFAULT 0;
        DECLARE c_s11b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s11b06 = 1;
        OPEN c_s11b06;
        loop_s11b06: LOOP
            FETCH c_s11b06 INTO v_acct_s11b06, v_deb_s11b06, v_cred_s11b06;
            IF v_done_s11b06 = 1 THEN LEAVE loop_s11b06; END IF;
            SET v_net_s11b06 = v_net_s11b06 + (v_deb_s11b06 - v_cred_s11b06);
        END LOOP;
        CLOSE c_s11b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s11b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s11b07]
    BEGIN
        DECLARE v_sql_s11b07 VARCHAR(1000);
        DECLARE v_n_s11b07 INTEGER DEFAULT 0;
        SET v_sql_s11b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s11b07 FROM v_sql_s11b07;
        EXECUTE st_s11b07;
        SELECT COUNT(*) INTO v_n_s11b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s11b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s11b08]
    BEGIN
        DECLARE v_key_s11b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s11b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s11b08' AS VARCHAR(40)), v_key_s11b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s11b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s11b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s11b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s11b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s11b09 FROM SESSION.TMP_s11b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s11b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s11b09 INTEGER DEFAULT 0;
            DECLARE c_s11b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s11b09 = 0;
            OPEN c_s11b09;
            FETCH c_s11b09 INTO v_lvl_s11b09;
            CLOSE c_s11b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s11b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s11b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s11b09 INTEGER DEFAULT 0;
            DECLARE v_band_s11b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s11b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s11b09 = ROW_COUNT;
            SET v_band_s11b09 = CASE WHEN v_rc_s11b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s11b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s11b09, 'STAGE', 'band=' || v_band_s11b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_12(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_11', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_10(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_10', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s10b00]
    BEGIN
        DECLARE v_so_s10b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s10b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s10b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s10b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s10b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s10b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s10b00 INTEGER DEFAULT 0;
        DECLARE v_done_s10b00 INTEGER DEFAULT 0;
        DECLARE c_s10b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s10b00 = 1;
        OPEN c_s10b00;
        loop_s10b00: LOOP
            FETCH c_s10b00 INTO v_so_s10b00, v_ctry_s10b00, v_ccy_s10b00, v_sub_s10b00;
            IF v_done_s10b00 = 1 THEN LEAVE loop_s10b00; END IF;
            SET v_tax_s10b00 = ERP_FN_TAX(v_ctry_s10b00, v_sub_s10b00);
            SET v_acc_s10b00 = v_acc_s10b00 + ERP_FN_FX_CONVERT(v_ccy_s10b00, 1, v_sub_s10b00 + v_tax_s10b00);
            SET v_cnt_s10b00 = v_cnt_s10b00 + 1;
        END LOOP;
        CLOSE c_s10b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s10b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s10b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s10b01]
    BEGIN
        DECLARE v_pid_s10b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s10b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s10b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s10b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s10b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s10b01 INTEGER DEFAULT 0;
        DECLARE c_s10b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s10b01 = 1;
        OPEN c_s10b01;
        loop_s10b01: LOOP
            FETCH c_s10b01 INTO v_pid_s10b01, v_oh_s10b01;
            IF v_done_s10b01 = 1 THEN LEAVE loop_s10b01; END IF;
            SET v_avail_s10b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s10b01);
            SET v_ro_s10b01 = ERP_FN_REORDER_QTY(v_pid_s10b01, 100);
            SET v_val_s10b01 = v_val_s10b01 + v_avail_s10b01 + v_ro_s10b01;
        END LOOP;
        CLOSE c_s10b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s10b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s10b02]
    BEGIN
        DECLARE v_pid_s10b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s10b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s10b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s10b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s10b02 INTEGER DEFAULT 0;
        DECLARE c_s10b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s10b02 = 1;
        OPEN c_s10b02;
        loop_s10b02: LOOP
            FETCH c_s10b02 INTO v_pid_s10b02;
            IF v_done_s10b02 = 1 THEN LEAVE loop_s10b02; END IF;
            SET v_mrg_s10b02 = ERP_FN_MARGIN(v_pid_s10b02);
            SET v_bc_s10b02 = ERP_FN_BOM_COST(v_pid_s10b02);
            IF v_mrg_s10b02 > 0 THEN
                SET v_tot_s10b02 = v_tot_s10b02 + v_bc_s10b02;
            ELSE
                SET v_tot_s10b02 = v_tot_s10b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s10b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s10b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s10b03]
    BEGIN
        DECLARE v_st_s10b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s10b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s10b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s10b03 = 0;
        FOR row_s10b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s10b03 = ERP_FN_ORDER_SUBTOTAL(row_s10b03.soid);
            SET v_lt_s10b03 = ERP_FN_LINE_TOTAL(1, v_st_s10b03, 0);
            SET v_grand_s10b03 = v_grand_s10b03 + v_st_s10b03 + (v_lt_s10b03 - v_lt_s10b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s10b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s10b04]
    BEGIN
        DECLARE v_cid_s10b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s10b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s10b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s10b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s10b04 INTEGER DEFAULT 0;
        DECLARE v_done_s10b04 INTEGER DEFAULT 0;
        DECLARE c_s10b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s10b04 = 1;
        OPEN c_s10b04;
        loop_s10b04: LOOP
            FETCH c_s10b04 INTO v_cid_s10b04;
            IF v_done_s10b04 = 1 THEN LEAVE loop_s10b04; END IF;
            SET v_bal_s10b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s10b04);
            SET v_disc_s10b04 = ERP_FN_DISCOUNT_PCT(v_cid_s10b04, 25);
            SET v_ok_s10b04 = ERP_FN_CREDIT_OK(v_cid_s10b04, v_bal_s10b04 + v_disc_s10b04);
            IF v_ok_s10b04 = 0 THEN SET v_bad_s10b04 = v_bad_s10b04 + 1; END IF;
        END LOOP;
        CLOSE c_s10b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s10b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s10b05]
    BEGIN
        DECLARE v_per_s10b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s10b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s10b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s10b05 INTEGER DEFAULT 0;
        DECLARE v_done_s10b05 INTEGER DEFAULT 0;
        DECLARE c_s10b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s10b05 = 1;
        SET v_per_s10b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s10b05;
        loop_s10b05: LOOP
            FETCH c_s10b05 INTO v_pid_s10b05;
            IF v_done_s10b05 = 1 THEN LEAVE loop_s10b05; END IF;
            SET v_dep_s10b05 = ERP_FN_BOM_DEPTH(v_pid_s10b05);
            IF v_dep_s10b05 > v_maxdep_s10b05 THEN SET v_maxdep_s10b05 = v_dep_s10b05; END IF;
        END LOOP;
        CLOSE c_s10b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s10b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s10b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s10b06]
    BEGIN
        DECLARE v_net_s10b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s10b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s10b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s10b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s10b06 INTEGER DEFAULT 0;
        DECLARE c_s10b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s10b06 = 1;
        OPEN c_s10b06;
        loop_s10b06: LOOP
            FETCH c_s10b06 INTO v_acct_s10b06, v_deb_s10b06, v_cred_s10b06;
            IF v_done_s10b06 = 1 THEN LEAVE loop_s10b06; END IF;
            SET v_net_s10b06 = v_net_s10b06 + (v_deb_s10b06 - v_cred_s10b06);
        END LOOP;
        CLOSE c_s10b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s10b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s10b07]
    BEGIN
        DECLARE v_sql_s10b07 VARCHAR(1000);
        DECLARE v_n_s10b07 INTEGER DEFAULT 0;
        SET v_sql_s10b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s10b07 FROM v_sql_s10b07;
        EXECUTE st_s10b07;
        SELECT COUNT(*) INTO v_n_s10b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s10b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s10b08]
    BEGIN
        DECLARE v_key_s10b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s10b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s10b08' AS VARCHAR(40)), v_key_s10b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s10b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s10b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s10b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s10b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s10b09 FROM SESSION.TMP_s10b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s10b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s10b09 INTEGER DEFAULT 0;
            DECLARE c_s10b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s10b09 = 0;
            OPEN c_s10b09;
            FETCH c_s10b09 INTO v_lvl_s10b09;
            CLOSE c_s10b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s10b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s10b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s10b09 INTEGER DEFAULT 0;
            DECLARE v_band_s10b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s10b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s10b09 = ROW_COUNT;
            SET v_band_s10b09 = CASE WHEN v_rc_s10b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s10b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s10b09, 'STAGE', 'band=' || v_band_s10b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_11(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_10', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_09(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_09', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s09b00]
    BEGIN
        DECLARE v_so_s09b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s09b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s09b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s09b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s09b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s09b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s09b00 INTEGER DEFAULT 0;
        DECLARE v_done_s09b00 INTEGER DEFAULT 0;
        DECLARE c_s09b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s09b00 = 1;
        OPEN c_s09b00;
        loop_s09b00: LOOP
            FETCH c_s09b00 INTO v_so_s09b00, v_ctry_s09b00, v_ccy_s09b00, v_sub_s09b00;
            IF v_done_s09b00 = 1 THEN LEAVE loop_s09b00; END IF;
            SET v_tax_s09b00 = ERP_FN_TAX(v_ctry_s09b00, v_sub_s09b00);
            SET v_acc_s09b00 = v_acc_s09b00 + ERP_FN_FX_CONVERT(v_ccy_s09b00, 1, v_sub_s09b00 + v_tax_s09b00);
            SET v_cnt_s09b00 = v_cnt_s09b00 + 1;
        END LOOP;
        CLOSE c_s09b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s09b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s09b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s09b01]
    BEGIN
        DECLARE v_pid_s09b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s09b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s09b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s09b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s09b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s09b01 INTEGER DEFAULT 0;
        DECLARE c_s09b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s09b01 = 1;
        OPEN c_s09b01;
        loop_s09b01: LOOP
            FETCH c_s09b01 INTO v_pid_s09b01, v_oh_s09b01;
            IF v_done_s09b01 = 1 THEN LEAVE loop_s09b01; END IF;
            SET v_avail_s09b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s09b01);
            SET v_ro_s09b01 = ERP_FN_REORDER_QTY(v_pid_s09b01, 100);
            SET v_val_s09b01 = v_val_s09b01 + v_avail_s09b01 + v_ro_s09b01;
        END LOOP;
        CLOSE c_s09b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s09b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s09b02]
    BEGIN
        DECLARE v_pid_s09b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s09b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s09b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s09b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s09b02 INTEGER DEFAULT 0;
        DECLARE c_s09b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s09b02 = 1;
        OPEN c_s09b02;
        loop_s09b02: LOOP
            FETCH c_s09b02 INTO v_pid_s09b02;
            IF v_done_s09b02 = 1 THEN LEAVE loop_s09b02; END IF;
            SET v_mrg_s09b02 = ERP_FN_MARGIN(v_pid_s09b02);
            SET v_bc_s09b02 = ERP_FN_BOM_COST(v_pid_s09b02);
            IF v_mrg_s09b02 > 0 THEN
                SET v_tot_s09b02 = v_tot_s09b02 + v_bc_s09b02;
            ELSE
                SET v_tot_s09b02 = v_tot_s09b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s09b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s09b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s09b03]
    BEGIN
        DECLARE v_st_s09b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s09b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s09b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s09b03 = 0;
        FOR row_s09b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s09b03 = ERP_FN_ORDER_SUBTOTAL(row_s09b03.soid);
            SET v_lt_s09b03 = ERP_FN_LINE_TOTAL(1, v_st_s09b03, 0);
            SET v_grand_s09b03 = v_grand_s09b03 + v_st_s09b03 + (v_lt_s09b03 - v_lt_s09b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s09b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s09b04]
    BEGIN
        DECLARE v_cid_s09b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s09b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s09b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s09b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s09b04 INTEGER DEFAULT 0;
        DECLARE v_done_s09b04 INTEGER DEFAULT 0;
        DECLARE c_s09b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s09b04 = 1;
        OPEN c_s09b04;
        loop_s09b04: LOOP
            FETCH c_s09b04 INTO v_cid_s09b04;
            IF v_done_s09b04 = 1 THEN LEAVE loop_s09b04; END IF;
            SET v_bal_s09b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s09b04);
            SET v_disc_s09b04 = ERP_FN_DISCOUNT_PCT(v_cid_s09b04, 25);
            SET v_ok_s09b04 = ERP_FN_CREDIT_OK(v_cid_s09b04, v_bal_s09b04 + v_disc_s09b04);
            IF v_ok_s09b04 = 0 THEN SET v_bad_s09b04 = v_bad_s09b04 + 1; END IF;
        END LOOP;
        CLOSE c_s09b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s09b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s09b05]
    BEGIN
        DECLARE v_per_s09b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s09b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s09b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s09b05 INTEGER DEFAULT 0;
        DECLARE v_done_s09b05 INTEGER DEFAULT 0;
        DECLARE c_s09b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s09b05 = 1;
        SET v_per_s09b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s09b05;
        loop_s09b05: LOOP
            FETCH c_s09b05 INTO v_pid_s09b05;
            IF v_done_s09b05 = 1 THEN LEAVE loop_s09b05; END IF;
            SET v_dep_s09b05 = ERP_FN_BOM_DEPTH(v_pid_s09b05);
            IF v_dep_s09b05 > v_maxdep_s09b05 THEN SET v_maxdep_s09b05 = v_dep_s09b05; END IF;
        END LOOP;
        CLOSE c_s09b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s09b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s09b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s09b06]
    BEGIN
        DECLARE v_net_s09b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s09b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s09b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s09b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s09b06 INTEGER DEFAULT 0;
        DECLARE c_s09b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s09b06 = 1;
        OPEN c_s09b06;
        loop_s09b06: LOOP
            FETCH c_s09b06 INTO v_acct_s09b06, v_deb_s09b06, v_cred_s09b06;
            IF v_done_s09b06 = 1 THEN LEAVE loop_s09b06; END IF;
            SET v_net_s09b06 = v_net_s09b06 + (v_deb_s09b06 - v_cred_s09b06);
        END LOOP;
        CLOSE c_s09b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s09b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s09b07]
    BEGIN
        DECLARE v_sql_s09b07 VARCHAR(1000);
        DECLARE v_n_s09b07 INTEGER DEFAULT 0;
        SET v_sql_s09b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s09b07 FROM v_sql_s09b07;
        EXECUTE st_s09b07;
        SELECT COUNT(*) INTO v_n_s09b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s09b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s09b08]
    BEGIN
        DECLARE v_key_s09b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s09b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s09b08' AS VARCHAR(40)), v_key_s09b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s09b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s09b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s09b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s09b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s09b09 FROM SESSION.TMP_s09b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s09b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s09b09 INTEGER DEFAULT 0;
            DECLARE c_s09b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s09b09 = 0;
            OPEN c_s09b09;
            FETCH c_s09b09 INTO v_lvl_s09b09;
            CLOSE c_s09b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s09b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s09b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s09b09 INTEGER DEFAULT 0;
            DECLARE v_band_s09b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s09b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s09b09 = ROW_COUNT;
            SET v_band_s09b09 = CASE WHEN v_rc_s09b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s09b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s09b09, 'STAGE', 'band=' || v_band_s09b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_10(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_09', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_08(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_08', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s08b00]
    BEGIN
        DECLARE v_so_s08b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s08b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s08b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s08b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s08b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s08b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s08b00 INTEGER DEFAULT 0;
        DECLARE v_done_s08b00 INTEGER DEFAULT 0;
        DECLARE c_s08b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s08b00 = 1;
        OPEN c_s08b00;
        loop_s08b00: LOOP
            FETCH c_s08b00 INTO v_so_s08b00, v_ctry_s08b00, v_ccy_s08b00, v_sub_s08b00;
            IF v_done_s08b00 = 1 THEN LEAVE loop_s08b00; END IF;
            SET v_tax_s08b00 = ERP_FN_TAX(v_ctry_s08b00, v_sub_s08b00);
            SET v_acc_s08b00 = v_acc_s08b00 + ERP_FN_FX_CONVERT(v_ccy_s08b00, 1, v_sub_s08b00 + v_tax_s08b00);
            SET v_cnt_s08b00 = v_cnt_s08b00 + 1;
        END LOOP;
        CLOSE c_s08b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s08b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s08b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s08b01]
    BEGIN
        DECLARE v_pid_s08b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s08b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s08b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s08b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s08b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s08b01 INTEGER DEFAULT 0;
        DECLARE c_s08b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s08b01 = 1;
        OPEN c_s08b01;
        loop_s08b01: LOOP
            FETCH c_s08b01 INTO v_pid_s08b01, v_oh_s08b01;
            IF v_done_s08b01 = 1 THEN LEAVE loop_s08b01; END IF;
            SET v_avail_s08b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s08b01);
            SET v_ro_s08b01 = ERP_FN_REORDER_QTY(v_pid_s08b01, 100);
            SET v_val_s08b01 = v_val_s08b01 + v_avail_s08b01 + v_ro_s08b01;
        END LOOP;
        CLOSE c_s08b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s08b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s08b02]
    BEGIN
        DECLARE v_pid_s08b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s08b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s08b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s08b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s08b02 INTEGER DEFAULT 0;
        DECLARE c_s08b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s08b02 = 1;
        OPEN c_s08b02;
        loop_s08b02: LOOP
            FETCH c_s08b02 INTO v_pid_s08b02;
            IF v_done_s08b02 = 1 THEN LEAVE loop_s08b02; END IF;
            SET v_mrg_s08b02 = ERP_FN_MARGIN(v_pid_s08b02);
            SET v_bc_s08b02 = ERP_FN_BOM_COST(v_pid_s08b02);
            IF v_mrg_s08b02 > 0 THEN
                SET v_tot_s08b02 = v_tot_s08b02 + v_bc_s08b02;
            ELSE
                SET v_tot_s08b02 = v_tot_s08b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s08b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s08b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s08b03]
    BEGIN
        DECLARE v_st_s08b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s08b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s08b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s08b03 = 0;
        FOR row_s08b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s08b03 = ERP_FN_ORDER_SUBTOTAL(row_s08b03.soid);
            SET v_lt_s08b03 = ERP_FN_LINE_TOTAL(1, v_st_s08b03, 0);
            SET v_grand_s08b03 = v_grand_s08b03 + v_st_s08b03 + (v_lt_s08b03 - v_lt_s08b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s08b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s08b04]
    BEGIN
        DECLARE v_cid_s08b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s08b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s08b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s08b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s08b04 INTEGER DEFAULT 0;
        DECLARE v_done_s08b04 INTEGER DEFAULT 0;
        DECLARE c_s08b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s08b04 = 1;
        OPEN c_s08b04;
        loop_s08b04: LOOP
            FETCH c_s08b04 INTO v_cid_s08b04;
            IF v_done_s08b04 = 1 THEN LEAVE loop_s08b04; END IF;
            SET v_bal_s08b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s08b04);
            SET v_disc_s08b04 = ERP_FN_DISCOUNT_PCT(v_cid_s08b04, 25);
            SET v_ok_s08b04 = ERP_FN_CREDIT_OK(v_cid_s08b04, v_bal_s08b04 + v_disc_s08b04);
            IF v_ok_s08b04 = 0 THEN SET v_bad_s08b04 = v_bad_s08b04 + 1; END IF;
        END LOOP;
        CLOSE c_s08b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s08b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s08b05]
    BEGIN
        DECLARE v_per_s08b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s08b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s08b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s08b05 INTEGER DEFAULT 0;
        DECLARE v_done_s08b05 INTEGER DEFAULT 0;
        DECLARE c_s08b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s08b05 = 1;
        SET v_per_s08b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s08b05;
        loop_s08b05: LOOP
            FETCH c_s08b05 INTO v_pid_s08b05;
            IF v_done_s08b05 = 1 THEN LEAVE loop_s08b05; END IF;
            SET v_dep_s08b05 = ERP_FN_BOM_DEPTH(v_pid_s08b05);
            IF v_dep_s08b05 > v_maxdep_s08b05 THEN SET v_maxdep_s08b05 = v_dep_s08b05; END IF;
        END LOOP;
        CLOSE c_s08b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s08b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s08b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s08b06]
    BEGIN
        DECLARE v_net_s08b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s08b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s08b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s08b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s08b06 INTEGER DEFAULT 0;
        DECLARE c_s08b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s08b06 = 1;
        OPEN c_s08b06;
        loop_s08b06: LOOP
            FETCH c_s08b06 INTO v_acct_s08b06, v_deb_s08b06, v_cred_s08b06;
            IF v_done_s08b06 = 1 THEN LEAVE loop_s08b06; END IF;
            SET v_net_s08b06 = v_net_s08b06 + (v_deb_s08b06 - v_cred_s08b06);
        END LOOP;
        CLOSE c_s08b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s08b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s08b07]
    BEGIN
        DECLARE v_sql_s08b07 VARCHAR(1000);
        DECLARE v_n_s08b07 INTEGER DEFAULT 0;
        SET v_sql_s08b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s08b07 FROM v_sql_s08b07;
        EXECUTE st_s08b07;
        SELECT COUNT(*) INTO v_n_s08b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s08b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s08b08]
    BEGIN
        DECLARE v_key_s08b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s08b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s08b08' AS VARCHAR(40)), v_key_s08b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s08b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s08b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s08b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s08b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s08b09 FROM SESSION.TMP_s08b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s08b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s08b09 INTEGER DEFAULT 0;
            DECLARE c_s08b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s08b09 = 0;
            OPEN c_s08b09;
            FETCH c_s08b09 INTO v_lvl_s08b09;
            CLOSE c_s08b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s08b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s08b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s08b09 INTEGER DEFAULT 0;
            DECLARE v_band_s08b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s08b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s08b09 = ROW_COUNT;
            SET v_band_s08b09 = CASE WHEN v_rc_s08b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s08b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s08b09, 'STAGE', 'band=' || v_band_s08b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_09(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_08', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_07(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_07', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s07b00]
    BEGIN
        DECLARE v_so_s07b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s07b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s07b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s07b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s07b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s07b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s07b00 INTEGER DEFAULT 0;
        DECLARE v_done_s07b00 INTEGER DEFAULT 0;
        DECLARE c_s07b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s07b00 = 1;
        OPEN c_s07b00;
        loop_s07b00: LOOP
            FETCH c_s07b00 INTO v_so_s07b00, v_ctry_s07b00, v_ccy_s07b00, v_sub_s07b00;
            IF v_done_s07b00 = 1 THEN LEAVE loop_s07b00; END IF;
            SET v_tax_s07b00 = ERP_FN_TAX(v_ctry_s07b00, v_sub_s07b00);
            SET v_acc_s07b00 = v_acc_s07b00 + ERP_FN_FX_CONVERT(v_ccy_s07b00, 1, v_sub_s07b00 + v_tax_s07b00);
            SET v_cnt_s07b00 = v_cnt_s07b00 + 1;
        END LOOP;
        CLOSE c_s07b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s07b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s07b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s07b01]
    BEGIN
        DECLARE v_pid_s07b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s07b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s07b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s07b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s07b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s07b01 INTEGER DEFAULT 0;
        DECLARE c_s07b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s07b01 = 1;
        OPEN c_s07b01;
        loop_s07b01: LOOP
            FETCH c_s07b01 INTO v_pid_s07b01, v_oh_s07b01;
            IF v_done_s07b01 = 1 THEN LEAVE loop_s07b01; END IF;
            SET v_avail_s07b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s07b01);
            SET v_ro_s07b01 = ERP_FN_REORDER_QTY(v_pid_s07b01, 100);
            SET v_val_s07b01 = v_val_s07b01 + v_avail_s07b01 + v_ro_s07b01;
        END LOOP;
        CLOSE c_s07b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s07b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s07b02]
    BEGIN
        DECLARE v_pid_s07b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s07b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s07b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s07b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s07b02 INTEGER DEFAULT 0;
        DECLARE c_s07b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s07b02 = 1;
        OPEN c_s07b02;
        loop_s07b02: LOOP
            FETCH c_s07b02 INTO v_pid_s07b02;
            IF v_done_s07b02 = 1 THEN LEAVE loop_s07b02; END IF;
            SET v_mrg_s07b02 = ERP_FN_MARGIN(v_pid_s07b02);
            SET v_bc_s07b02 = ERP_FN_BOM_COST(v_pid_s07b02);
            IF v_mrg_s07b02 > 0 THEN
                SET v_tot_s07b02 = v_tot_s07b02 + v_bc_s07b02;
            ELSE
                SET v_tot_s07b02 = v_tot_s07b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s07b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s07b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s07b03]
    BEGIN
        DECLARE v_st_s07b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s07b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s07b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s07b03 = 0;
        FOR row_s07b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s07b03 = ERP_FN_ORDER_SUBTOTAL(row_s07b03.soid);
            SET v_lt_s07b03 = ERP_FN_LINE_TOTAL(1, v_st_s07b03, 0);
            SET v_grand_s07b03 = v_grand_s07b03 + v_st_s07b03 + (v_lt_s07b03 - v_lt_s07b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s07b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s07b04]
    BEGIN
        DECLARE v_cid_s07b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s07b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s07b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s07b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s07b04 INTEGER DEFAULT 0;
        DECLARE v_done_s07b04 INTEGER DEFAULT 0;
        DECLARE c_s07b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s07b04 = 1;
        OPEN c_s07b04;
        loop_s07b04: LOOP
            FETCH c_s07b04 INTO v_cid_s07b04;
            IF v_done_s07b04 = 1 THEN LEAVE loop_s07b04; END IF;
            SET v_bal_s07b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s07b04);
            SET v_disc_s07b04 = ERP_FN_DISCOUNT_PCT(v_cid_s07b04, 25);
            SET v_ok_s07b04 = ERP_FN_CREDIT_OK(v_cid_s07b04, v_bal_s07b04 + v_disc_s07b04);
            IF v_ok_s07b04 = 0 THEN SET v_bad_s07b04 = v_bad_s07b04 + 1; END IF;
        END LOOP;
        CLOSE c_s07b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s07b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s07b05]
    BEGIN
        DECLARE v_per_s07b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s07b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s07b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s07b05 INTEGER DEFAULT 0;
        DECLARE v_done_s07b05 INTEGER DEFAULT 0;
        DECLARE c_s07b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s07b05 = 1;
        SET v_per_s07b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s07b05;
        loop_s07b05: LOOP
            FETCH c_s07b05 INTO v_pid_s07b05;
            IF v_done_s07b05 = 1 THEN LEAVE loop_s07b05; END IF;
            SET v_dep_s07b05 = ERP_FN_BOM_DEPTH(v_pid_s07b05);
            IF v_dep_s07b05 > v_maxdep_s07b05 THEN SET v_maxdep_s07b05 = v_dep_s07b05; END IF;
        END LOOP;
        CLOSE c_s07b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s07b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s07b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s07b06]
    BEGIN
        DECLARE v_net_s07b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s07b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s07b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s07b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s07b06 INTEGER DEFAULT 0;
        DECLARE c_s07b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s07b06 = 1;
        OPEN c_s07b06;
        loop_s07b06: LOOP
            FETCH c_s07b06 INTO v_acct_s07b06, v_deb_s07b06, v_cred_s07b06;
            IF v_done_s07b06 = 1 THEN LEAVE loop_s07b06; END IF;
            SET v_net_s07b06 = v_net_s07b06 + (v_deb_s07b06 - v_cred_s07b06);
        END LOOP;
        CLOSE c_s07b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s07b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s07b07]
    BEGIN
        DECLARE v_sql_s07b07 VARCHAR(1000);
        DECLARE v_n_s07b07 INTEGER DEFAULT 0;
        SET v_sql_s07b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s07b07 FROM v_sql_s07b07;
        EXECUTE st_s07b07;
        SELECT COUNT(*) INTO v_n_s07b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s07b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s07b08]
    BEGIN
        DECLARE v_key_s07b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s07b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s07b08' AS VARCHAR(40)), v_key_s07b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s07b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s07b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s07b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s07b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s07b09 FROM SESSION.TMP_s07b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s07b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s07b09 INTEGER DEFAULT 0;
            DECLARE c_s07b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s07b09 = 0;
            OPEN c_s07b09;
            FETCH c_s07b09 INTO v_lvl_s07b09;
            CLOSE c_s07b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s07b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s07b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s07b09 INTEGER DEFAULT 0;
            DECLARE v_band_s07b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s07b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s07b09 = ROW_COUNT;
            SET v_band_s07b09 = CASE WHEN v_rc_s07b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s07b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s07b09, 'STAGE', 'band=' || v_band_s07b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_08(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_07', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_06(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_06', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s06b00]
    BEGIN
        DECLARE v_so_s06b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s06b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s06b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s06b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s06b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s06b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s06b00 INTEGER DEFAULT 0;
        DECLARE v_done_s06b00 INTEGER DEFAULT 0;
        DECLARE c_s06b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s06b00 = 1;
        OPEN c_s06b00;
        loop_s06b00: LOOP
            FETCH c_s06b00 INTO v_so_s06b00, v_ctry_s06b00, v_ccy_s06b00, v_sub_s06b00;
            IF v_done_s06b00 = 1 THEN LEAVE loop_s06b00; END IF;
            SET v_tax_s06b00 = ERP_FN_TAX(v_ctry_s06b00, v_sub_s06b00);
            SET v_acc_s06b00 = v_acc_s06b00 + ERP_FN_FX_CONVERT(v_ccy_s06b00, 1, v_sub_s06b00 + v_tax_s06b00);
            SET v_cnt_s06b00 = v_cnt_s06b00 + 1;
        END LOOP;
        CLOSE c_s06b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s06b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s06b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s06b01]
    BEGIN
        DECLARE v_pid_s06b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s06b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s06b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s06b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s06b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s06b01 INTEGER DEFAULT 0;
        DECLARE c_s06b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s06b01 = 1;
        OPEN c_s06b01;
        loop_s06b01: LOOP
            FETCH c_s06b01 INTO v_pid_s06b01, v_oh_s06b01;
            IF v_done_s06b01 = 1 THEN LEAVE loop_s06b01; END IF;
            SET v_avail_s06b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s06b01);
            SET v_ro_s06b01 = ERP_FN_REORDER_QTY(v_pid_s06b01, 100);
            SET v_val_s06b01 = v_val_s06b01 + v_avail_s06b01 + v_ro_s06b01;
        END LOOP;
        CLOSE c_s06b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s06b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s06b02]
    BEGIN
        DECLARE v_pid_s06b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s06b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s06b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s06b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s06b02 INTEGER DEFAULT 0;
        DECLARE c_s06b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s06b02 = 1;
        OPEN c_s06b02;
        loop_s06b02: LOOP
            FETCH c_s06b02 INTO v_pid_s06b02;
            IF v_done_s06b02 = 1 THEN LEAVE loop_s06b02; END IF;
            SET v_mrg_s06b02 = ERP_FN_MARGIN(v_pid_s06b02);
            SET v_bc_s06b02 = ERP_FN_BOM_COST(v_pid_s06b02);
            IF v_mrg_s06b02 > 0 THEN
                SET v_tot_s06b02 = v_tot_s06b02 + v_bc_s06b02;
            ELSE
                SET v_tot_s06b02 = v_tot_s06b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s06b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s06b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s06b03]
    BEGIN
        DECLARE v_st_s06b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s06b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s06b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s06b03 = 0;
        FOR row_s06b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s06b03 = ERP_FN_ORDER_SUBTOTAL(row_s06b03.soid);
            SET v_lt_s06b03 = ERP_FN_LINE_TOTAL(1, v_st_s06b03, 0);
            SET v_grand_s06b03 = v_grand_s06b03 + v_st_s06b03 + (v_lt_s06b03 - v_lt_s06b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s06b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s06b04]
    BEGIN
        DECLARE v_cid_s06b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s06b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s06b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s06b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s06b04 INTEGER DEFAULT 0;
        DECLARE v_done_s06b04 INTEGER DEFAULT 0;
        DECLARE c_s06b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s06b04 = 1;
        OPEN c_s06b04;
        loop_s06b04: LOOP
            FETCH c_s06b04 INTO v_cid_s06b04;
            IF v_done_s06b04 = 1 THEN LEAVE loop_s06b04; END IF;
            SET v_bal_s06b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s06b04);
            SET v_disc_s06b04 = ERP_FN_DISCOUNT_PCT(v_cid_s06b04, 25);
            SET v_ok_s06b04 = ERP_FN_CREDIT_OK(v_cid_s06b04, v_bal_s06b04 + v_disc_s06b04);
            IF v_ok_s06b04 = 0 THEN SET v_bad_s06b04 = v_bad_s06b04 + 1; END IF;
        END LOOP;
        CLOSE c_s06b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s06b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s06b05]
    BEGIN
        DECLARE v_per_s06b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s06b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s06b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s06b05 INTEGER DEFAULT 0;
        DECLARE v_done_s06b05 INTEGER DEFAULT 0;
        DECLARE c_s06b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s06b05 = 1;
        SET v_per_s06b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s06b05;
        loop_s06b05: LOOP
            FETCH c_s06b05 INTO v_pid_s06b05;
            IF v_done_s06b05 = 1 THEN LEAVE loop_s06b05; END IF;
            SET v_dep_s06b05 = ERP_FN_BOM_DEPTH(v_pid_s06b05);
            IF v_dep_s06b05 > v_maxdep_s06b05 THEN SET v_maxdep_s06b05 = v_dep_s06b05; END IF;
        END LOOP;
        CLOSE c_s06b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s06b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s06b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s06b06]
    BEGIN
        DECLARE v_net_s06b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s06b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s06b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s06b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s06b06 INTEGER DEFAULT 0;
        DECLARE c_s06b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s06b06 = 1;
        OPEN c_s06b06;
        loop_s06b06: LOOP
            FETCH c_s06b06 INTO v_acct_s06b06, v_deb_s06b06, v_cred_s06b06;
            IF v_done_s06b06 = 1 THEN LEAVE loop_s06b06; END IF;
            SET v_net_s06b06 = v_net_s06b06 + (v_deb_s06b06 - v_cred_s06b06);
        END LOOP;
        CLOSE c_s06b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s06b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s06b07]
    BEGIN
        DECLARE v_sql_s06b07 VARCHAR(1000);
        DECLARE v_n_s06b07 INTEGER DEFAULT 0;
        SET v_sql_s06b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s06b07 FROM v_sql_s06b07;
        EXECUTE st_s06b07;
        SELECT COUNT(*) INTO v_n_s06b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s06b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s06b08]
    BEGIN
        DECLARE v_key_s06b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s06b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s06b08' AS VARCHAR(40)), v_key_s06b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s06b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s06b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s06b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s06b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s06b09 FROM SESSION.TMP_s06b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s06b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s06b09 INTEGER DEFAULT 0;
            DECLARE c_s06b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s06b09 = 0;
            OPEN c_s06b09;
            FETCH c_s06b09 INTO v_lvl_s06b09;
            CLOSE c_s06b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s06b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s06b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s06b09 INTEGER DEFAULT 0;
            DECLARE v_band_s06b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s06b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s06b09 = ROW_COUNT;
            SET v_band_s06b09 = CASE WHEN v_rc_s06b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s06b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s06b09, 'STAGE', 'band=' || v_band_s06b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_07(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_06', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_05(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_05', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s05b00]
    BEGIN
        DECLARE v_so_s05b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s05b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s05b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s05b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s05b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s05b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s05b00 INTEGER DEFAULT 0;
        DECLARE v_done_s05b00 INTEGER DEFAULT 0;
        DECLARE c_s05b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s05b00 = 1;
        OPEN c_s05b00;
        loop_s05b00: LOOP
            FETCH c_s05b00 INTO v_so_s05b00, v_ctry_s05b00, v_ccy_s05b00, v_sub_s05b00;
            IF v_done_s05b00 = 1 THEN LEAVE loop_s05b00; END IF;
            SET v_tax_s05b00 = ERP_FN_TAX(v_ctry_s05b00, v_sub_s05b00);
            SET v_acc_s05b00 = v_acc_s05b00 + ERP_FN_FX_CONVERT(v_ccy_s05b00, 1, v_sub_s05b00 + v_tax_s05b00);
            SET v_cnt_s05b00 = v_cnt_s05b00 + 1;
        END LOOP;
        CLOSE c_s05b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s05b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s05b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s05b01]
    BEGIN
        DECLARE v_pid_s05b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s05b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s05b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s05b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s05b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s05b01 INTEGER DEFAULT 0;
        DECLARE c_s05b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s05b01 = 1;
        OPEN c_s05b01;
        loop_s05b01: LOOP
            FETCH c_s05b01 INTO v_pid_s05b01, v_oh_s05b01;
            IF v_done_s05b01 = 1 THEN LEAVE loop_s05b01; END IF;
            SET v_avail_s05b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s05b01);
            SET v_ro_s05b01 = ERP_FN_REORDER_QTY(v_pid_s05b01, 100);
            SET v_val_s05b01 = v_val_s05b01 + v_avail_s05b01 + v_ro_s05b01;
        END LOOP;
        CLOSE c_s05b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s05b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s05b02]
    BEGIN
        DECLARE v_pid_s05b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s05b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s05b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s05b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s05b02 INTEGER DEFAULT 0;
        DECLARE c_s05b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s05b02 = 1;
        OPEN c_s05b02;
        loop_s05b02: LOOP
            FETCH c_s05b02 INTO v_pid_s05b02;
            IF v_done_s05b02 = 1 THEN LEAVE loop_s05b02; END IF;
            SET v_mrg_s05b02 = ERP_FN_MARGIN(v_pid_s05b02);
            SET v_bc_s05b02 = ERP_FN_BOM_COST(v_pid_s05b02);
            IF v_mrg_s05b02 > 0 THEN
                SET v_tot_s05b02 = v_tot_s05b02 + v_bc_s05b02;
            ELSE
                SET v_tot_s05b02 = v_tot_s05b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s05b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s05b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s05b03]
    BEGIN
        DECLARE v_st_s05b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s05b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s05b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s05b03 = 0;
        FOR row_s05b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s05b03 = ERP_FN_ORDER_SUBTOTAL(row_s05b03.soid);
            SET v_lt_s05b03 = ERP_FN_LINE_TOTAL(1, v_st_s05b03, 0);
            SET v_grand_s05b03 = v_grand_s05b03 + v_st_s05b03 + (v_lt_s05b03 - v_lt_s05b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s05b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s05b04]
    BEGIN
        DECLARE v_cid_s05b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s05b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s05b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s05b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s05b04 INTEGER DEFAULT 0;
        DECLARE v_done_s05b04 INTEGER DEFAULT 0;
        DECLARE c_s05b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s05b04 = 1;
        OPEN c_s05b04;
        loop_s05b04: LOOP
            FETCH c_s05b04 INTO v_cid_s05b04;
            IF v_done_s05b04 = 1 THEN LEAVE loop_s05b04; END IF;
            SET v_bal_s05b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s05b04);
            SET v_disc_s05b04 = ERP_FN_DISCOUNT_PCT(v_cid_s05b04, 25);
            SET v_ok_s05b04 = ERP_FN_CREDIT_OK(v_cid_s05b04, v_bal_s05b04 + v_disc_s05b04);
            IF v_ok_s05b04 = 0 THEN SET v_bad_s05b04 = v_bad_s05b04 + 1; END IF;
        END LOOP;
        CLOSE c_s05b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s05b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s05b05]
    BEGIN
        DECLARE v_per_s05b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s05b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s05b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s05b05 INTEGER DEFAULT 0;
        DECLARE v_done_s05b05 INTEGER DEFAULT 0;
        DECLARE c_s05b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s05b05 = 1;
        SET v_per_s05b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s05b05;
        loop_s05b05: LOOP
            FETCH c_s05b05 INTO v_pid_s05b05;
            IF v_done_s05b05 = 1 THEN LEAVE loop_s05b05; END IF;
            SET v_dep_s05b05 = ERP_FN_BOM_DEPTH(v_pid_s05b05);
            IF v_dep_s05b05 > v_maxdep_s05b05 THEN SET v_maxdep_s05b05 = v_dep_s05b05; END IF;
        END LOOP;
        CLOSE c_s05b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s05b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s05b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s05b06]
    BEGIN
        DECLARE v_net_s05b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s05b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s05b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s05b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s05b06 INTEGER DEFAULT 0;
        DECLARE c_s05b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s05b06 = 1;
        OPEN c_s05b06;
        loop_s05b06: LOOP
            FETCH c_s05b06 INTO v_acct_s05b06, v_deb_s05b06, v_cred_s05b06;
            IF v_done_s05b06 = 1 THEN LEAVE loop_s05b06; END IF;
            SET v_net_s05b06 = v_net_s05b06 + (v_deb_s05b06 - v_cred_s05b06);
        END LOOP;
        CLOSE c_s05b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s05b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s05b07]
    BEGIN
        DECLARE v_sql_s05b07 VARCHAR(1000);
        DECLARE v_n_s05b07 INTEGER DEFAULT 0;
        SET v_sql_s05b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s05b07 FROM v_sql_s05b07;
        EXECUTE st_s05b07;
        SELECT COUNT(*) INTO v_n_s05b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s05b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s05b08]
    BEGIN
        DECLARE v_key_s05b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s05b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s05b08' AS VARCHAR(40)), v_key_s05b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s05b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s05b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s05b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s05b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s05b09 FROM SESSION.TMP_s05b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s05b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s05b09 INTEGER DEFAULT 0;
            DECLARE c_s05b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s05b09 = 0;
            OPEN c_s05b09;
            FETCH c_s05b09 INTO v_lvl_s05b09;
            CLOSE c_s05b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s05b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s05b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s05b09 INTEGER DEFAULT 0;
            DECLARE v_band_s05b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s05b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s05b09 = ROW_COUNT;
            SET v_band_s05b09 = CASE WHEN v_rc_s05b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s05b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s05b09, 'STAGE', 'band=' || v_band_s05b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_06(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_05', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_04(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_04', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s04b00]
    BEGIN
        DECLARE v_so_s04b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s04b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s04b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s04b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s04b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s04b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s04b00 INTEGER DEFAULT 0;
        DECLARE v_done_s04b00 INTEGER DEFAULT 0;
        DECLARE c_s04b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s04b00 = 1;
        OPEN c_s04b00;
        loop_s04b00: LOOP
            FETCH c_s04b00 INTO v_so_s04b00, v_ctry_s04b00, v_ccy_s04b00, v_sub_s04b00;
            IF v_done_s04b00 = 1 THEN LEAVE loop_s04b00; END IF;
            SET v_tax_s04b00 = ERP_FN_TAX(v_ctry_s04b00, v_sub_s04b00);
            SET v_acc_s04b00 = v_acc_s04b00 + ERP_FN_FX_CONVERT(v_ccy_s04b00, 1, v_sub_s04b00 + v_tax_s04b00);
            SET v_cnt_s04b00 = v_cnt_s04b00 + 1;
        END LOOP;
        CLOSE c_s04b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s04b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s04b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s04b01]
    BEGIN
        DECLARE v_pid_s04b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s04b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s04b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s04b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s04b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s04b01 INTEGER DEFAULT 0;
        DECLARE c_s04b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s04b01 = 1;
        OPEN c_s04b01;
        loop_s04b01: LOOP
            FETCH c_s04b01 INTO v_pid_s04b01, v_oh_s04b01;
            IF v_done_s04b01 = 1 THEN LEAVE loop_s04b01; END IF;
            SET v_avail_s04b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s04b01);
            SET v_ro_s04b01 = ERP_FN_REORDER_QTY(v_pid_s04b01, 100);
            SET v_val_s04b01 = v_val_s04b01 + v_avail_s04b01 + v_ro_s04b01;
        END LOOP;
        CLOSE c_s04b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s04b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s04b02]
    BEGIN
        DECLARE v_pid_s04b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s04b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s04b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s04b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s04b02 INTEGER DEFAULT 0;
        DECLARE c_s04b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s04b02 = 1;
        OPEN c_s04b02;
        loop_s04b02: LOOP
            FETCH c_s04b02 INTO v_pid_s04b02;
            IF v_done_s04b02 = 1 THEN LEAVE loop_s04b02; END IF;
            SET v_mrg_s04b02 = ERP_FN_MARGIN(v_pid_s04b02);
            SET v_bc_s04b02 = ERP_FN_BOM_COST(v_pid_s04b02);
            IF v_mrg_s04b02 > 0 THEN
                SET v_tot_s04b02 = v_tot_s04b02 + v_bc_s04b02;
            ELSE
                SET v_tot_s04b02 = v_tot_s04b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s04b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s04b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s04b03]
    BEGIN
        DECLARE v_st_s04b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s04b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s04b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s04b03 = 0;
        FOR row_s04b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s04b03 = ERP_FN_ORDER_SUBTOTAL(row_s04b03.soid);
            SET v_lt_s04b03 = ERP_FN_LINE_TOTAL(1, v_st_s04b03, 0);
            SET v_grand_s04b03 = v_grand_s04b03 + v_st_s04b03 + (v_lt_s04b03 - v_lt_s04b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s04b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s04b04]
    BEGIN
        DECLARE v_cid_s04b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s04b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s04b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s04b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s04b04 INTEGER DEFAULT 0;
        DECLARE v_done_s04b04 INTEGER DEFAULT 0;
        DECLARE c_s04b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s04b04 = 1;
        OPEN c_s04b04;
        loop_s04b04: LOOP
            FETCH c_s04b04 INTO v_cid_s04b04;
            IF v_done_s04b04 = 1 THEN LEAVE loop_s04b04; END IF;
            SET v_bal_s04b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s04b04);
            SET v_disc_s04b04 = ERP_FN_DISCOUNT_PCT(v_cid_s04b04, 25);
            SET v_ok_s04b04 = ERP_FN_CREDIT_OK(v_cid_s04b04, v_bal_s04b04 + v_disc_s04b04);
            IF v_ok_s04b04 = 0 THEN SET v_bad_s04b04 = v_bad_s04b04 + 1; END IF;
        END LOOP;
        CLOSE c_s04b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s04b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s04b05]
    BEGIN
        DECLARE v_per_s04b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s04b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s04b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s04b05 INTEGER DEFAULT 0;
        DECLARE v_done_s04b05 INTEGER DEFAULT 0;
        DECLARE c_s04b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s04b05 = 1;
        SET v_per_s04b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s04b05;
        loop_s04b05: LOOP
            FETCH c_s04b05 INTO v_pid_s04b05;
            IF v_done_s04b05 = 1 THEN LEAVE loop_s04b05; END IF;
            SET v_dep_s04b05 = ERP_FN_BOM_DEPTH(v_pid_s04b05);
            IF v_dep_s04b05 > v_maxdep_s04b05 THEN SET v_maxdep_s04b05 = v_dep_s04b05; END IF;
        END LOOP;
        CLOSE c_s04b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s04b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s04b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s04b06]
    BEGIN
        DECLARE v_net_s04b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s04b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s04b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s04b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s04b06 INTEGER DEFAULT 0;
        DECLARE c_s04b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s04b06 = 1;
        OPEN c_s04b06;
        loop_s04b06: LOOP
            FETCH c_s04b06 INTO v_acct_s04b06, v_deb_s04b06, v_cred_s04b06;
            IF v_done_s04b06 = 1 THEN LEAVE loop_s04b06; END IF;
            SET v_net_s04b06 = v_net_s04b06 + (v_deb_s04b06 - v_cred_s04b06);
        END LOOP;
        CLOSE c_s04b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s04b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s04b07]
    BEGIN
        DECLARE v_sql_s04b07 VARCHAR(1000);
        DECLARE v_n_s04b07 INTEGER DEFAULT 0;
        SET v_sql_s04b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s04b07 FROM v_sql_s04b07;
        EXECUTE st_s04b07;
        SELECT COUNT(*) INTO v_n_s04b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s04b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s04b08]
    BEGIN
        DECLARE v_key_s04b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s04b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s04b08' AS VARCHAR(40)), v_key_s04b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s04b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s04b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s04b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s04b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s04b09 FROM SESSION.TMP_s04b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s04b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s04b09 INTEGER DEFAULT 0;
            DECLARE c_s04b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s04b09 = 0;
            OPEN c_s04b09;
            FETCH c_s04b09 INTO v_lvl_s04b09;
            CLOSE c_s04b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s04b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s04b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s04b09 INTEGER DEFAULT 0;
            DECLARE v_band_s04b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s04b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s04b09 = ROW_COUNT;
            SET v_band_s04b09 = CASE WHEN v_rc_s04b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s04b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s04b09, 'STAGE', 'band=' || v_band_s04b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_05(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_04', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_03(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_03', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s03b00]
    BEGIN
        DECLARE v_so_s03b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s03b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s03b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s03b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s03b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s03b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s03b00 INTEGER DEFAULT 0;
        DECLARE v_done_s03b00 INTEGER DEFAULT 0;
        DECLARE c_s03b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s03b00 = 1;
        OPEN c_s03b00;
        loop_s03b00: LOOP
            FETCH c_s03b00 INTO v_so_s03b00, v_ctry_s03b00, v_ccy_s03b00, v_sub_s03b00;
            IF v_done_s03b00 = 1 THEN LEAVE loop_s03b00; END IF;
            SET v_tax_s03b00 = ERP_FN_TAX(v_ctry_s03b00, v_sub_s03b00);
            SET v_acc_s03b00 = v_acc_s03b00 + ERP_FN_FX_CONVERT(v_ccy_s03b00, 1, v_sub_s03b00 + v_tax_s03b00);
            SET v_cnt_s03b00 = v_cnt_s03b00 + 1;
        END LOOP;
        CLOSE c_s03b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s03b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s03b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s03b01]
    BEGIN
        DECLARE v_pid_s03b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s03b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s03b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s03b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s03b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s03b01 INTEGER DEFAULT 0;
        DECLARE c_s03b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s03b01 = 1;
        OPEN c_s03b01;
        loop_s03b01: LOOP
            FETCH c_s03b01 INTO v_pid_s03b01, v_oh_s03b01;
            IF v_done_s03b01 = 1 THEN LEAVE loop_s03b01; END IF;
            SET v_avail_s03b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s03b01);
            SET v_ro_s03b01 = ERP_FN_REORDER_QTY(v_pid_s03b01, 100);
            SET v_val_s03b01 = v_val_s03b01 + v_avail_s03b01 + v_ro_s03b01;
        END LOOP;
        CLOSE c_s03b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s03b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s03b02]
    BEGIN
        DECLARE v_pid_s03b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s03b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s03b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s03b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s03b02 INTEGER DEFAULT 0;
        DECLARE c_s03b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s03b02 = 1;
        OPEN c_s03b02;
        loop_s03b02: LOOP
            FETCH c_s03b02 INTO v_pid_s03b02;
            IF v_done_s03b02 = 1 THEN LEAVE loop_s03b02; END IF;
            SET v_mrg_s03b02 = ERP_FN_MARGIN(v_pid_s03b02);
            SET v_bc_s03b02 = ERP_FN_BOM_COST(v_pid_s03b02);
            IF v_mrg_s03b02 > 0 THEN
                SET v_tot_s03b02 = v_tot_s03b02 + v_bc_s03b02;
            ELSE
                SET v_tot_s03b02 = v_tot_s03b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s03b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s03b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s03b03]
    BEGIN
        DECLARE v_st_s03b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s03b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s03b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s03b03 = 0;
        FOR row_s03b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s03b03 = ERP_FN_ORDER_SUBTOTAL(row_s03b03.soid);
            SET v_lt_s03b03 = ERP_FN_LINE_TOTAL(1, v_st_s03b03, 0);
            SET v_grand_s03b03 = v_grand_s03b03 + v_st_s03b03 + (v_lt_s03b03 - v_lt_s03b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s03b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s03b04]
    BEGIN
        DECLARE v_cid_s03b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s03b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s03b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s03b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s03b04 INTEGER DEFAULT 0;
        DECLARE v_done_s03b04 INTEGER DEFAULT 0;
        DECLARE c_s03b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s03b04 = 1;
        OPEN c_s03b04;
        loop_s03b04: LOOP
            FETCH c_s03b04 INTO v_cid_s03b04;
            IF v_done_s03b04 = 1 THEN LEAVE loop_s03b04; END IF;
            SET v_bal_s03b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s03b04);
            SET v_disc_s03b04 = ERP_FN_DISCOUNT_PCT(v_cid_s03b04, 25);
            SET v_ok_s03b04 = ERP_FN_CREDIT_OK(v_cid_s03b04, v_bal_s03b04 + v_disc_s03b04);
            IF v_ok_s03b04 = 0 THEN SET v_bad_s03b04 = v_bad_s03b04 + 1; END IF;
        END LOOP;
        CLOSE c_s03b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s03b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s03b05]
    BEGIN
        DECLARE v_per_s03b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s03b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s03b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s03b05 INTEGER DEFAULT 0;
        DECLARE v_done_s03b05 INTEGER DEFAULT 0;
        DECLARE c_s03b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s03b05 = 1;
        SET v_per_s03b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s03b05;
        loop_s03b05: LOOP
            FETCH c_s03b05 INTO v_pid_s03b05;
            IF v_done_s03b05 = 1 THEN LEAVE loop_s03b05; END IF;
            SET v_dep_s03b05 = ERP_FN_BOM_DEPTH(v_pid_s03b05);
            IF v_dep_s03b05 > v_maxdep_s03b05 THEN SET v_maxdep_s03b05 = v_dep_s03b05; END IF;
        END LOOP;
        CLOSE c_s03b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s03b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s03b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s03b06]
    BEGIN
        DECLARE v_net_s03b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s03b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s03b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s03b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s03b06 INTEGER DEFAULT 0;
        DECLARE c_s03b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s03b06 = 1;
        OPEN c_s03b06;
        loop_s03b06: LOOP
            FETCH c_s03b06 INTO v_acct_s03b06, v_deb_s03b06, v_cred_s03b06;
            IF v_done_s03b06 = 1 THEN LEAVE loop_s03b06; END IF;
            SET v_net_s03b06 = v_net_s03b06 + (v_deb_s03b06 - v_cred_s03b06);
        END LOOP;
        CLOSE c_s03b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s03b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s03b07]
    BEGIN
        DECLARE v_sql_s03b07 VARCHAR(1000);
        DECLARE v_n_s03b07 INTEGER DEFAULT 0;
        SET v_sql_s03b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s03b07 FROM v_sql_s03b07;
        EXECUTE st_s03b07;
        SELECT COUNT(*) INTO v_n_s03b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s03b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s03b08]
    BEGIN
        DECLARE v_key_s03b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s03b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s03b08' AS VARCHAR(40)), v_key_s03b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s03b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s03b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s03b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s03b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s03b09 FROM SESSION.TMP_s03b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s03b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s03b09 INTEGER DEFAULT 0;
            DECLARE c_s03b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s03b09 = 0;
            OPEN c_s03b09;
            FETCH c_s03b09 INTO v_lvl_s03b09;
            CLOSE c_s03b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s03b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s03b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s03b09 INTEGER DEFAULT 0;
            DECLARE v_band_s03b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s03b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s03b09 = ROW_COUNT;
            SET v_band_s03b09 = CASE WHEN v_rc_s03b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s03b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s03b09, 'STAGE', 'band=' || v_band_s03b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_04(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_03', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_02(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_02', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s02b00]
    BEGIN
        DECLARE v_so_s02b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s02b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s02b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s02b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s02b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s02b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s02b00 INTEGER DEFAULT 0;
        DECLARE v_done_s02b00 INTEGER DEFAULT 0;
        DECLARE c_s02b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s02b00 = 1;
        OPEN c_s02b00;
        loop_s02b00: LOOP
            FETCH c_s02b00 INTO v_so_s02b00, v_ctry_s02b00, v_ccy_s02b00, v_sub_s02b00;
            IF v_done_s02b00 = 1 THEN LEAVE loop_s02b00; END IF;
            SET v_tax_s02b00 = ERP_FN_TAX(v_ctry_s02b00, v_sub_s02b00);
            SET v_acc_s02b00 = v_acc_s02b00 + ERP_FN_FX_CONVERT(v_ccy_s02b00, 1, v_sub_s02b00 + v_tax_s02b00);
            SET v_cnt_s02b00 = v_cnt_s02b00 + 1;
        END LOOP;
        CLOSE c_s02b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s02b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s02b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s02b01]
    BEGIN
        DECLARE v_pid_s02b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s02b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s02b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s02b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s02b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s02b01 INTEGER DEFAULT 0;
        DECLARE c_s02b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s02b01 = 1;
        OPEN c_s02b01;
        loop_s02b01: LOOP
            FETCH c_s02b01 INTO v_pid_s02b01, v_oh_s02b01;
            IF v_done_s02b01 = 1 THEN LEAVE loop_s02b01; END IF;
            SET v_avail_s02b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s02b01);
            SET v_ro_s02b01 = ERP_FN_REORDER_QTY(v_pid_s02b01, 100);
            SET v_val_s02b01 = v_val_s02b01 + v_avail_s02b01 + v_ro_s02b01;
        END LOOP;
        CLOSE c_s02b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s02b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s02b02]
    BEGIN
        DECLARE v_pid_s02b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s02b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s02b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s02b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s02b02 INTEGER DEFAULT 0;
        DECLARE c_s02b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s02b02 = 1;
        OPEN c_s02b02;
        loop_s02b02: LOOP
            FETCH c_s02b02 INTO v_pid_s02b02;
            IF v_done_s02b02 = 1 THEN LEAVE loop_s02b02; END IF;
            SET v_mrg_s02b02 = ERP_FN_MARGIN(v_pid_s02b02);
            SET v_bc_s02b02 = ERP_FN_BOM_COST(v_pid_s02b02);
            IF v_mrg_s02b02 > 0 THEN
                SET v_tot_s02b02 = v_tot_s02b02 + v_bc_s02b02;
            ELSE
                SET v_tot_s02b02 = v_tot_s02b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s02b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s02b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s02b03]
    BEGIN
        DECLARE v_st_s02b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s02b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s02b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s02b03 = 0;
        FOR row_s02b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s02b03 = ERP_FN_ORDER_SUBTOTAL(row_s02b03.soid);
            SET v_lt_s02b03 = ERP_FN_LINE_TOTAL(1, v_st_s02b03, 0);
            SET v_grand_s02b03 = v_grand_s02b03 + v_st_s02b03 + (v_lt_s02b03 - v_lt_s02b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s02b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s02b04]
    BEGIN
        DECLARE v_cid_s02b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s02b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s02b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s02b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s02b04 INTEGER DEFAULT 0;
        DECLARE v_done_s02b04 INTEGER DEFAULT 0;
        DECLARE c_s02b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s02b04 = 1;
        OPEN c_s02b04;
        loop_s02b04: LOOP
            FETCH c_s02b04 INTO v_cid_s02b04;
            IF v_done_s02b04 = 1 THEN LEAVE loop_s02b04; END IF;
            SET v_bal_s02b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s02b04);
            SET v_disc_s02b04 = ERP_FN_DISCOUNT_PCT(v_cid_s02b04, 25);
            SET v_ok_s02b04 = ERP_FN_CREDIT_OK(v_cid_s02b04, v_bal_s02b04 + v_disc_s02b04);
            IF v_ok_s02b04 = 0 THEN SET v_bad_s02b04 = v_bad_s02b04 + 1; END IF;
        END LOOP;
        CLOSE c_s02b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s02b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s02b05]
    BEGIN
        DECLARE v_per_s02b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s02b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s02b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s02b05 INTEGER DEFAULT 0;
        DECLARE v_done_s02b05 INTEGER DEFAULT 0;
        DECLARE c_s02b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s02b05 = 1;
        SET v_per_s02b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s02b05;
        loop_s02b05: LOOP
            FETCH c_s02b05 INTO v_pid_s02b05;
            IF v_done_s02b05 = 1 THEN LEAVE loop_s02b05; END IF;
            SET v_dep_s02b05 = ERP_FN_BOM_DEPTH(v_pid_s02b05);
            IF v_dep_s02b05 > v_maxdep_s02b05 THEN SET v_maxdep_s02b05 = v_dep_s02b05; END IF;
        END LOOP;
        CLOSE c_s02b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s02b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s02b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s02b06]
    BEGIN
        DECLARE v_net_s02b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s02b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s02b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s02b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s02b06 INTEGER DEFAULT 0;
        DECLARE c_s02b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s02b06 = 1;
        OPEN c_s02b06;
        loop_s02b06: LOOP
            FETCH c_s02b06 INTO v_acct_s02b06, v_deb_s02b06, v_cred_s02b06;
            IF v_done_s02b06 = 1 THEN LEAVE loop_s02b06; END IF;
            SET v_net_s02b06 = v_net_s02b06 + (v_deb_s02b06 - v_cred_s02b06);
        END LOOP;
        CLOSE c_s02b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s02b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s02b07]
    BEGIN
        DECLARE v_sql_s02b07 VARCHAR(1000);
        DECLARE v_n_s02b07 INTEGER DEFAULT 0;
        SET v_sql_s02b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s02b07 FROM v_sql_s02b07;
        EXECUTE st_s02b07;
        SELECT COUNT(*) INTO v_n_s02b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s02b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s02b08]
    BEGIN
        DECLARE v_key_s02b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s02b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s02b08' AS VARCHAR(40)), v_key_s02b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s02b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s02b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s02b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s02b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s02b09 FROM SESSION.TMP_s02b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s02b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s02b09 INTEGER DEFAULT 0;
            DECLARE c_s02b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s02b09 = 0;
            OPEN c_s02b09;
            FETCH c_s02b09 INTO v_lvl_s02b09;
            CLOSE c_s02b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s02b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s02b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s02b09 INTEGER DEFAULT 0;
            DECLARE v_band_s02b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s02b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s02b09 = ROW_COUNT;
            SET v_band_s02b09 = CASE WHEN v_rc_s02b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s02b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s02b09, 'STAGE', 'band=' || v_band_s02b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_03(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_02', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_STAGE_01(IN p_run INTEGER)
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'ENTER', 'ERP_USP_STAGE_01', CURRENT TIMESTAMP);
    -- revenue scan (tax + fx) [s01b00]
    BEGIN
        DECLARE v_so_s01b00 INTEGER DEFAULT 0;
        DECLARE v_ctry_s01b00 INTEGER DEFAULT 0;
        DECLARE v_ccy_s01b00 INTEGER DEFAULT 0;
        DECLARE v_sub_s01b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_s01b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_s01b00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_s01b00 INTEGER DEFAULT 0;
        DECLARE v_done_s01b00 INTEGER DEFAULT 0;
        DECLARE c_s01b00 CURSOR FOR
            SELECT so.id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s01b00 = 1;
        OPEN c_s01b00;
        loop_s01b00: LOOP
            FETCH c_s01b00 INTO v_so_s01b00, v_ctry_s01b00, v_ccy_s01b00, v_sub_s01b00;
            IF v_done_s01b00 = 1 THEN LEAVE loop_s01b00; END IF;
            SET v_tax_s01b00 = ERP_FN_TAX(v_ctry_s01b00, v_sub_s01b00);
            SET v_acc_s01b00 = v_acc_s01b00 + ERP_FN_FX_CONVERT(v_ccy_s01b00, 1, v_sub_s01b00 + v_tax_s01b00);
            SET v_cnt_s01b00 = v_cnt_s01b00 + 1;
        END LOOP;
        CLOSE c_s01b00;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_REV', v_cnt_s01b00, 'SCAN', 'usd=' || RTRIM(CHAR(CAST(v_acc_s01b00 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- inventory valuation (onhand + reorder) [s01b01]
    BEGIN
        DECLARE v_pid_s01b01 INTEGER DEFAULT 0;
        DECLARE v_oh_s01b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_avail_s01b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_ro_s01b01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_val_s01b01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s01b01 INTEGER DEFAULT 0;
        DECLARE c_s01b01 CURSOR FOR
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p
            LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            LEFT JOIN ERP_LOCATION l ON l.id = i.location_id
            LEFT JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s01b01 = 1;
        OPEN c_s01b01;
        loop_s01b01: LOOP
            FETCH c_s01b01 INTO v_pid_s01b01, v_oh_s01b01;
            IF v_done_s01b01 = 1 THEN LEAVE loop_s01b01; END IF;
            SET v_avail_s01b01 = ERP_FN_INVENTORY_ONHAND(v_pid_s01b01);
            SET v_ro_s01b01 = ERP_FN_REORDER_QTY(v_pid_s01b01, 100);
            SET v_val_s01b01 = v_val_s01b01 + v_avail_s01b01 + v_ro_s01b01;
        END LOOP;
        CLOSE c_s01b01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_INV', 0, 'VALUE', 'v=' || RTRIM(CHAR(CAST(v_val_s01b01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- product margin + bom cost roll [s01b02]
    BEGIN
        DECLARE v_pid_s01b02 INTEGER DEFAULT 0;
        DECLARE v_mrg_s01b02 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_bc_s01b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_tot_s01b02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_s01b02 INTEGER DEFAULT 0;
        DECLARE c_s01b02 CURSOR FOR
            SELECT p.id FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s01b02 = 1;
        OPEN c_s01b02;
        loop_s01b02: LOOP
            FETCH c_s01b02 INTO v_pid_s01b02;
            IF v_done_s01b02 = 1 THEN LEAVE loop_s01b02; END IF;
            SET v_mrg_s01b02 = ERP_FN_MARGIN(v_pid_s01b02);
            SET v_bc_s01b02 = ERP_FN_BOM_COST(v_pid_s01b02);
            IF v_mrg_s01b02 > 0 THEN
                SET v_tot_s01b02 = v_tot_s01b02 + v_bc_s01b02;
            ELSE
                SET v_tot_s01b02 = v_tot_s01b02 + 0;
            END IF;
        END LOOP;
        CLOSE c_s01b02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_MRG', 0, 'ROLLUP', 'c=' || RTRIM(CHAR(CAST(v_tot_s01b02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- order subtotal / line total recompute [s01b03]
    BEGIN
        DECLARE v_st_s01b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_lt_s01b03 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_grand_s01b03 DECIMAL(18,2) DEFAULT 0;
        SET v_grand_s01b03 = 0;
        FOR row_s01b03 AS
            SELECT so.id AS soid FROM ERP_SALES_ORDER so WHERE so.subtotal >= 0 ORDER BY so.id
        DO
            SET v_st_s01b03 = ERP_FN_ORDER_SUBTOTAL(row_s01b03.soid);
            SET v_lt_s01b03 = ERP_FN_LINE_TOTAL(1, v_st_s01b03, 0);
            SET v_grand_s01b03 = v_grand_s01b03 + v_st_s01b03 + (v_lt_s01b03 - v_lt_s01b03);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_SUB', 0, 'SCAN', 'g=' || RTRIM(CHAR(CAST(v_grand_s01b03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- customer balance / credit / discount [s01b04]
    BEGIN
        DECLARE v_cid_s01b04 INTEGER DEFAULT 0;
        DECLARE v_bal_s01b04 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_ok_s01b04 SMALLINT DEFAULT 0;
        DECLARE v_disc_s01b04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_bad_s01b04 INTEGER DEFAULT 0;
        DECLARE v_done_s01b04 INTEGER DEFAULT 0;
        DECLARE c_s01b04 CURSOR FOR
            SELECT c.id FROM ERP_CUSTOMER c ORDER BY c.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s01b04 = 1;
        OPEN c_s01b04;
        loop_s01b04: LOOP
            FETCH c_s01b04 INTO v_cid_s01b04;
            IF v_done_s01b04 = 1 THEN LEAVE loop_s01b04; END IF;
            SET v_bal_s01b04 = ERP_FN_CUSTOMER_BALANCE(v_cid_s01b04);
            SET v_disc_s01b04 = ERP_FN_DISCOUNT_PCT(v_cid_s01b04, 25);
            SET v_ok_s01b04 = ERP_FN_CREDIT_OK(v_cid_s01b04, v_bal_s01b04 + v_disc_s01b04);
            IF v_ok_s01b04 = 0 THEN SET v_bad_s01b04 = v_bad_s01b04 + 1; END IF;
        END LOOP;
        CLOSE c_s01b04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_CR', v_bad_s01b04, 'SCAN', 'over_limit', CURRENT TIMESTAMP);
    END;
    -- fiscal period + bom depth [s01b05]
    BEGIN
        DECLARE v_per_s01b05 INTEGER DEFAULT 0;
        DECLARE v_pid_s01b05 INTEGER DEFAULT 0;
        DECLARE v_dep_s01b05 INTEGER DEFAULT 0;
        DECLARE v_maxdep_s01b05 INTEGER DEFAULT 0;
        DECLARE v_done_s01b05 INTEGER DEFAULT 0;
        DECLARE c_s01b05 CURSOR FOR SELECT p.id FROM ERP_PRODUCT p ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s01b05 = 1;
        SET v_per_s01b05 = ERP_FN_FISCAL_PERIOD(CURRENT DATE);
        OPEN c_s01b05;
        loop_s01b05: LOOP
            FETCH c_s01b05 INTO v_pid_s01b05;
            IF v_done_s01b05 = 1 THEN LEAVE loop_s01b05; END IF;
            SET v_dep_s01b05 = ERP_FN_BOM_DEPTH(v_pid_s01b05);
            IF v_dep_s01b05 > v_maxdep_s01b05 THEN SET v_maxdep_s01b05 = v_dep_s01b05; END IF;
        END LOOP;
        CLOSE c_s01b05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_FP', v_per_s01b05, 'SCAN', 'maxdepth=' || RTRIM(CHAR(v_maxdep_s01b05)), CURRENT TIMESTAMP);
    END;
    -- GL reconciliation (left join + group by) [s01b06]
    BEGIN
        DECLARE v_net_s01b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_acct_s01b06 INTEGER DEFAULT 0;
        DECLARE v_deb_s01b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_s01b06 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_s01b06 INTEGER DEFAULT 0;
        DECLARE c_s01b06 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_s01b06 = 1;
        OPEN c_s01b06;
        loop_s01b06: LOOP
            FETCH c_s01b06 INTO v_acct_s01b06, v_deb_s01b06, v_cred_s01b06;
            IF v_done_s01b06 = 1 THEN LEAVE loop_s01b06; END IF;
            SET v_net_s01b06 = v_net_s01b06 + (v_deb_s01b06 - v_cred_s01b06);
        END LOOP;
        CLOSE c_s01b06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_GL', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_s01b06 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance (prepare/execute) [s01b07]
    BEGIN
        DECLARE v_sql_s01b07 VARCHAR(1000);
        DECLARE v_n_s01b07 INTEGER DEFAULT 0;
        SET v_sql_s01b07 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_s01b07 FROM v_sql_s01b07;
        EXECUTE st_s01b07;
        SELECT COUNT(*) INTO v_n_s01b07 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('STG_DYN', v_n_s01b07, 'MAINT', 'so', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of stats [s01b08]
    BEGIN
        DECLARE v_key_s01b08 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_s01b08 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STG_s01b08' AS VARCHAR(40)), v_key_s01b08)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'sol rows', CURRENT TIMESTAMP);
    END;
    -- GTT stage + recursive CTE + subquery + diagnostics [s01b09]
    BEGIN
        BEGIN
            DECLARE v_rows_s01b09 INTEGER DEFAULT 0;
            DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_s01b09 (
                product_id INTEGER, on_hand DECIMAL(16,4)
            ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
            INSERT INTO SESSION.TMP_s01b09(product_id, on_hand)
            SELECT p.id, COALESCE(SUM(i.on_hand),0)
            FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
            GROUP BY p.id;
            SELECT COUNT(*) INTO v_rows_s01b09 FROM SESSION.TMP_s01b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_GTT', v_rows_s01b09, 'STAGE', 'temp rows', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_lvl_s01b09 INTEGER DEFAULT 0;
            DECLARE c_s01b09 CURSOR FOR
                WITH dh (dept_id, parent_id, lvl) AS (
                    SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                    FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                    UNION ALL
                    SELECT d2.id, d2.parent_id, dh.lvl + 1
                    FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                    WHERE dh.lvl < 10
                )
                SELECT COALESCE(MAX(lvl),0) FROM dh;
            DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_lvl_s01b09 = 0;
            OPEN c_s01b09;
            FETCH c_s01b09 INTO v_lvl_s01b09;
            CLOSE c_s01b09;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_CTE', COALESCE(v_lvl_s01b09,0), 'SCAN', 'dept_depth', CURRENT TIMESTAMP);
        END;
        BEGIN
            DECLARE v_hi_s01b09 INTEGER DEFAULT 0;
            DECLARE v_rc_s01b09 INTEGER DEFAULT 0;
            DECLARE v_band_s01b09 VARCHAR(10);
            SELECT COUNT(*) INTO v_hi_s01b09
            FROM ERP_CUSTOMER c
            WHERE c.id IN (SELECT so.customer_id FROM ERP_SALES_ORDER so
                           WHERE so.subtotal > (SELECT COALESCE(AVG(so2.subtotal),0)
                                                FROM ERP_SALES_ORDER so2
                                                WHERE so2.customer_id = so.customer_id));
            UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
            GET DIAGNOSTICS v_rc_s01b09 = ROW_COUNT;
            SET v_band_s01b09 = CASE WHEN v_rc_s01b09 = 0 THEN 'NONE'
                                    WHEN v_rc_s01b09 < 5 THEN 'FEW' ELSE 'MANY' END;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('STG_MIX', v_hi_s01b09, 'STAGE', 'band=' || v_band_s01b09, CURRENT TIMESTAMP);
        END;
    END;
    CALL ERP_USP_STAGE_02(p_run + 1);
    INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
    VALUES ('STAGE', p_run, 'EXIT', 'ERP_USP_STAGE_01', CURRENT TIMESTAMP);
END @

CREATE PROCEDURE ERP_USP_TOUCH_VIEWS()
LANGUAGE SQL
BEGIN
    DECLARE v_n INTEGER DEFAULT 0;
    SELECT COUNT(*) INTO v_n FROM ERP_VW_ORDER_SUMMARY;
    CALL ERP_USP_AUDIT('TOUCH_VIEW', v_n, 'READ', 'ERP_VW_ORDER_SUMMARY');
    SELECT COUNT(*) INTO v_n FROM ERP_VW_OPEN_AR;
    CALL ERP_USP_AUDIT('TOUCH_VIEW', v_n, 'READ', 'ERP_VW_OPEN_AR');
    SELECT COUNT(*) INTO v_n FROM ERP_VW_INVENTORY_STATUS;
    CALL ERP_USP_AUDIT('TOUCH_VIEW', v_n, 'READ', 'ERP_VW_INVENTORY_STATUS');
    SELECT COUNT(*) INTO v_n FROM ERP_MQT_CUSTOMER_REV;
    CALL ERP_USP_AUDIT('TOUCH_VIEW', v_n, 'READ', 'ERP_MQT_CUSTOMER_REV');
    SELECT COUNT(*) INTO v_n FROM ERP_MQT_PRODUCT_MARGIN;
    CALL ERP_USP_AUDIT('TOUCH_VIEW', v_n, 'READ', 'ERP_MQT_PRODUCT_MARGIN');
END @

-- ---------------------------------------------------------------------------
-- CROSS-SCHEMA test case: second schema ERP_REF referenced from DB2INST1
-- ---------------------------------------------------------------------------
CREATE SCHEMA ERP_REF @

CREATE TABLE ERP_REF.REF_AUDIT (
    id          INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    source      VARCHAR(60),
    detail      VARCHAR(400),
    logged_ts   TIMESTAMP
) @

CREATE TABLE ERP_REF.REF_REGION (
    region_id   INTEGER NOT NULL PRIMARY KEY,
    region_name VARCHAR(60),
    active      SMALLINT DEFAULT 1
) @

INSERT INTO ERP_REF.REF_REGION (region_id, region_name, active) VALUES (1, 'AMER', 1) @
INSERT INTO ERP_REF.REF_REGION (region_id, region_name, active) VALUES (2, 'EMEA', 1) @
INSERT INTO ERP_REF.REF_REGION (region_id, region_name, active) VALUES (3, 'APAC', 1) @
INSERT INTO ERP_REF.REF_REGION (region_id, region_name, active) VALUES (4, 'LATAM', 0) @

CREATE VIEW ERP_REF.VW_REGION AS
    SELECT region_id, region_name, active
    FROM ERP_REF.REF_REGION
    WHERE active = 1 @

CREATE FUNCTION ERP_REF.FN_REGION_NAME(p_region_id INTEGER)
RETURNS VARCHAR(60)
LANGUAGE SQL
BEGIN ATOMIC
    DECLARE v_name VARCHAR(60) DEFAULT NULL;
    SET v_name = (SELECT region_name FROM ERP_REF.REF_REGION WHERE region_id = p_region_id);
    RETURN v_name;
END @

CREATE PROCEDURE ERP_REF.USP_REF_LOG(IN p_source VARCHAR(60), IN p_detail VARCHAR(400))
LANGUAGE SQL
BEGIN
    INSERT INTO ERP_REF.REF_AUDIT(source, detail, logged_ts)
    VALUES (p_source, p_detail, CURRENT TIMESTAMP);
END @

CREATE TRIGGER ERP_REF.TRG_REF_REGION
    AFTER INSERT ON ERP_REF.REF_REGION
    REFERENCING NEW AS n
    FOR EACH ROW
    INSERT INTO ERP_REF.REF_AUDIT(source, detail, logged_ts)
    VALUES ('REF_REGION', 'inserted region ' || COALESCE(n.region_name, '?'), CURRENT TIMESTAMP) @

CREATE PROCEDURE DB2INST1.ERP_USP_XSCHEMA_TOUCH()
LANGUAGE SQL
BEGIN
    DECLARE v_cnt INTEGER DEFAULT 0;
    DECLARE v_vw_cnt INTEGER DEFAULT 0;
    DECLARE v_name VARCHAR(60) DEFAULT NULL;
    DECLARE v_max INTEGER DEFAULT 0;
    -- (a) cross-schema CALL
    CALL ERP_REF.USP_REF_LOG('XSCHEMA', 'touch invoked from DB2INST1');
    -- (b) cross-schema reads: base table, view, and scalar function
    SET v_cnt = (SELECT COUNT(*) FROM ERP_REF.REF_REGION);
    SET v_vw_cnt = (SELECT COUNT(*) FROM ERP_REF.VW_REGION);
    SET v_name = ERP_REF.FN_REGION_NAME(1);
    -- (c) cross-schema INSERT (fires ERP_REF.TRG_REF_REGION)
    SET v_max = (SELECT COALESCE(MAX(region_id),0) FROM ERP_REF.REF_REGION);
    INSERT INTO ERP_REF.REF_REGION (region_id, region_name, active)
    VALUES (v_max + 1, 'RGN_' || RTRIM(CHAR(v_max + 1)), 1);
    CALL ERP_USP_AUDIT('XSCHEMA', v_cnt, 'TOUCH',
        'regions=' || RTRIM(CHAR(v_cnt)) || ' view=' || RTRIM(CHAR(v_vw_cnt)) ||
        ' first=' || COALESCE(v_name, '?'));
END @

CREATE PROCEDURE ERP_USP_RUN_CYCLE()
LANGUAGE SQL
BEGIN
    SET ERP_GV_RUN_ID = NEXTVAL FOR ERP_SEQ_ORDER;
    CALL ERP_USP_AUDIT('CYCLE', ERP_GV_RUN_ID, 'RUN', 'Cycle invoked for tenant ' || ERP_GV_TENANT);
    -- order/customer/country/currency revenue scan [rc00]
    BEGIN
        DECLARE v_so_rc00 INTEGER DEFAULT 0;
        DECLARE v_cust_rc00 INTEGER DEFAULT 0;
        DECLARE v_ctry_rc00 INTEGER DEFAULT 0;
        DECLARE v_ccy_rc00 INTEGER DEFAULT 0;
        DECLARE v_sub_rc00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rc00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rc00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rc00 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rc00 INTEGER DEFAULT 0;
        DECLARE v_done_rc00 INTEGER DEFAULT 0;
        DECLARE c_rc00 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc00 = 1;
        OPEN c_rc00;
        loop_rc00: LOOP
            FETCH c_rc00 INTO v_so_rc00, v_cust_rc00, v_ctry_rc00, v_ccy_rc00, v_sub_rc00;
            IF v_done_rc00 = 1 THEN LEAVE loop_rc00; END IF;
            SET v_tax_rc00 = ERP_FN_TAX(v_ctry_rc00, v_sub_rc00);
            SET v_fx_rc00 = ERP_FN_FX_CONVERT(v_ccy_rc00, 1, v_sub_rc00 + v_tax_rc00);
            SET v_acc_rc00 = v_acc_rc00 + v_fx_rc00;
            SET v_cnt_rc00 = v_cnt_rc00 + 1;
        END LOOP;
        CLOSE c_rc00;
        IF v_cnt_rc00 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rc00, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rc00 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rc01]
    BEGIN
        DECLARE v_pid_rc01 INTEGER DEFAULT 0;
        DECLARE v_oh_rc01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rc01 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rc01 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rc01 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rc01 INTEGER DEFAULT 0;
        DECLARE c_rc01 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc01 = 1;
        OPEN c_rc01;
        loop_rc01: LOOP
            FETCH c_rc01 INTO v_pid_rc01, v_oh_rc01, v_cost_rc01;
            IF v_done_rc01 = 1 THEN LEAVE loop_rc01; END IF;
            SET v_avail_rc01 = ERP_FN_INVENTORY_ONHAND(v_pid_rc01);
            SET v_val_rc01 = v_val_rc01 + CAST(COALESCE(v_oh_rc01,0) * COALESCE(v_cost_rc01,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rc01, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rc01;
        END LOOP;
        CLOSE c_rc01;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rc01 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rc02]
    BEGIN
        DECLARE v_prod_rc02 INTEGER DEFAULT 0;
        DECLARE v_rm_rc02 INTEGER DEFAULT 0;
        DECLARE v_supp_rc02 INTEGER DEFAULT 0;
        DECLARE v_qper_rc02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rc02 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rc02 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rc02 INTEGER DEFAULT 0;
        DECLARE c_rc02 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc02 = 1;
        OPEN c_rc02;
        loop_rc02: LOOP
            FETCH c_rc02 INTO v_prod_rc02, v_rm_rc02, v_supp_rc02, v_qper_rc02, v_uc_rc02;
            IF v_done_rc02 = 1 THEN LEAVE loop_rc02; END IF;
            SET v_roll_rc02 = v_roll_rc02 + COALESCE(v_qper_rc02,0) * COALESCE(v_uc_rc02,0);
        END LOOP;
        CLOSE c_rc02;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rc02 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rc03]
    BEGIN
        DECLARE v_acct_rc03 INTEGER DEFAULT 0;
        DECLARE v_deb_rc03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rc03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rc03 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc03 INTEGER DEFAULT 0;
        DECLARE c_rc03 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc03 = 1;
        OPEN c_rc03;
        loop_rc03: LOOP
            FETCH c_rc03 INTO v_acct_rc03, v_deb_rc03, v_cred_rc03;
            IF v_done_rc03 = 1 THEN LEAVE loop_rc03; END IF;
            SET v_net_rc03 = v_net_rc03 + (v_deb_rc03 - v_cred_rc03);
        END LOOP;
        CLOSE c_rc03;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rc03 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rc04]
    BEGIN
        DECLARE v_pid_rc04 INTEGER DEFAULT 0;
        DECLARE v_lp_rc04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rc04 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rc04 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rc04 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rc04 INTEGER DEFAULT 0;
        DECLARE c_rc04 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc04 = 1;
        OPEN c_rc04;
        loop_rc04: LOOP
            FETCH c_rc04 INTO v_pid_rc04, v_lp_rc04, v_pp_rc04;
            IF v_done_rc04 = 1 THEN LEAVE loop_rc04; END IF;
            SET v_var_rc04 = v_var_rc04 + (COALESCE(v_lp_rc04,0) - COALESCE(v_pp_rc04,0));
            SET v_marg_rc04 = ERP_FN_MARGIN(v_pid_rc04);
        END LOOP;
        CLOSE c_rc04;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rc04 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rc05]
    BEGIN
        DECLARE v_inv_rc05 INTEGER DEFAULT 0;
        DECLARE v_amt_rc05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rc05 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rc05 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc05 INTEGER DEFAULT 0;
        DECLARE c_rc05 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc05 = 1;
        OPEN c_rc05;
        loop_rc05: LOOP
            FETCH c_rc05 INTO v_inv_rc05, v_amt_rc05, v_alloc_rc05;
            IF v_done_rc05 = 1 THEN LEAVE loop_rc05; END IF;
            SET v_open_rc05 = v_open_rc05 + (v_amt_rc05 - v_alloc_rc05);
        END LOOP;
        CLOSE c_rc05;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rc05 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rc06]
    BEGIN
        DECLARE v_lvl_rc06 INTEGER DEFAULT 0;
        DECLARE v_dept_rc06 INTEGER DEFAULT 0;
        DECLARE v_head_rc06 INTEGER DEFAULT 0;
        DECLARE v_done_rc06 INTEGER DEFAULT 0;
        DECLARE c_rc06 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc06 = 1;
        OPEN c_rc06;
        loop_rc06: LOOP
            FETCH c_rc06 INTO v_dept_rc06, v_lvl_rc06, v_head_rc06;
            IF v_done_rc06 = 1 THEN LEAVE loop_rc06; END IF;
        END LOOP;
        CLOSE c_rc06;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rc06, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rc06)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rc07]
    BEGIN
        DECLARE v_sh_rc07 INTEGER DEFAULT 0;
        DECLARE v_car_rc07 INTEGER DEFAULT 0;
        DECLARE v_qty_rc07 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rc07 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rc07 INTEGER DEFAULT 0;
        DECLARE c_rc07 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc07 = 1;
        OPEN c_rc07;
        loop_rc07: LOOP
            FETCH c_rc07 INTO v_sh_rc07, v_car_rc07, v_qty_rc07;
            IF v_done_rc07 = 1 THEN LEAVE loop_rc07; END IF;
            SET v_tot_rc07 = v_tot_rc07 + v_qty_rc07;
        END LOOP;
        CLOSE c_rc07;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rc07 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rc08]
    BEGIN
        DECLARE v_sql_rc08 VARCHAR(1000);
        DECLARE v_n_rc08 INTEGER DEFAULT 0;
        SET v_sql_rc08 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rc08 FROM v_sql_rc08;
        EXECUTE st_rc08;
        SELECT COUNT(*) INTO v_n_rc08 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rc08, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rc09]
    BEGIN
        DECLARE v_key_rc09 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rc09 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rc09' AS VARCHAR(40)), v_key_rc09)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rc10]
    BEGIN
        DECLARE v_so_rc10 INTEGER DEFAULT 0;
        DECLARE v_cust_rc10 INTEGER DEFAULT 0;
        DECLARE v_rk_rc10 INTEGER DEFAULT 0;
        DECLARE v_run_rc10 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc10 INTEGER DEFAULT 0;
        DECLARE c_rc10 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc10 = 1;
        OPEN c_rc10;
        loop_rc10: LOOP
            FETCH c_rc10 INTO v_so_rc10, v_cust_rc10, v_rk_rc10, v_run_rc10;
            IF v_done_rc10 = 1 THEN LEAVE loop_rc10; END IF;
        END LOOP;
        CLOSE c_rc10;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rc10, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rc10)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rc11]
    BEGIN
        DECLARE v_hi_rc11 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rc11
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rc11, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rc12]
    BEGIN
        DECLARE v_pairs_rc12 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rc12
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rc12, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rc13]
    BEGIN
        DECLARE v_rows_rc13 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rc13 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rc13(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rc13 FROM SESSION.TMP_rc13;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rc13, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rc14]
    BEGIN
        DECLARE v_rc_rc14 INTEGER DEFAULT 0;
        DECLARE v_band_rc14 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rc14 = ROW_COUNT;
        SET v_band_rc14 = CASE
                            WHEN v_rc_rc14 = 0 THEN 'NONE'
                            WHEN v_rc_rc14 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rc14, 'COUNT', 'band=' || v_band_rc14, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rc15]
    BEGIN
        DECLARE v_i_rc15 INTEGER DEFAULT 0;
        SAVEPOINT sp_rc15 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rc15 < 4 DO
            SET v_i_rc15 = v_i_rc15 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rc15, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rc15;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rc15, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rc16]
    BEGIN
        DECLARE v_j_rc16 INTEGER DEFAULT 0;
        DECLARE v_sum_rc16 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rc16 = v_j_rc16 + 1;
        UNTIL v_j_rc16 >= 3 END REPEAT;
        FOR row_rc16 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rc16 = v_sum_rc16 + COALESCE(row_rc16.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rc16, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rc16 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rc17]
    BEGIN
        DECLARE v_n_rc17 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rc17
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rc17, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rc18]
    BEGIN
        DECLARE v_levels_rc18 INTEGER DEFAULT 0;
        DECLARE c_rc18 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rc18 = 0;
        OPEN c_rc18;
        FETCH c_rc18 INTO v_levels_rc18;
        CLOSE c_rc18;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rc18,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rc19]
    BEGIN
        DECLARE v_sql_rc19 VARCHAR(1000);
        DECLARE v_n_rc19 INTEGER DEFAULT 0;
        SET v_sql_rc19 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rc19 FROM v_sql_rc19;
        EXECUTE st_rc19;
        SELECT COUNT(*) INTO v_n_rc19 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rc19, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rc20]
    BEGIN
        DECLARE v_key_rc20 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rc20 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rc20' AS VARCHAR(40)), v_key_rc20)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rc21]
    BEGIN
        DECLARE v_so_rc21 INTEGER DEFAULT 0;
        DECLARE v_cust_rc21 INTEGER DEFAULT 0;
        DECLARE v_ctry_rc21 INTEGER DEFAULT 0;
        DECLARE v_ccy_rc21 INTEGER DEFAULT 0;
        DECLARE v_sub_rc21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rc21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rc21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rc21 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rc21 INTEGER DEFAULT 0;
        DECLARE v_done_rc21 INTEGER DEFAULT 0;
        DECLARE c_rc21 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc21 = 1;
        OPEN c_rc21;
        loop_rc21: LOOP
            FETCH c_rc21 INTO v_so_rc21, v_cust_rc21, v_ctry_rc21, v_ccy_rc21, v_sub_rc21;
            IF v_done_rc21 = 1 THEN LEAVE loop_rc21; END IF;
            SET v_tax_rc21 = ERP_FN_TAX(v_ctry_rc21, v_sub_rc21);
            SET v_fx_rc21 = ERP_FN_FX_CONVERT(v_ccy_rc21, 1, v_sub_rc21 + v_tax_rc21);
            SET v_acc_rc21 = v_acc_rc21 + v_fx_rc21;
            SET v_cnt_rc21 = v_cnt_rc21 + 1;
        END LOOP;
        CLOSE c_rc21;
        IF v_cnt_rc21 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rc21, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rc21 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rc22]
    BEGIN
        DECLARE v_pid_rc22 INTEGER DEFAULT 0;
        DECLARE v_oh_rc22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rc22 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rc22 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rc22 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rc22 INTEGER DEFAULT 0;
        DECLARE c_rc22 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc22 = 1;
        OPEN c_rc22;
        loop_rc22: LOOP
            FETCH c_rc22 INTO v_pid_rc22, v_oh_rc22, v_cost_rc22;
            IF v_done_rc22 = 1 THEN LEAVE loop_rc22; END IF;
            SET v_avail_rc22 = ERP_FN_INVENTORY_ONHAND(v_pid_rc22);
            SET v_val_rc22 = v_val_rc22 + CAST(COALESCE(v_oh_rc22,0) * COALESCE(v_cost_rc22,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rc22, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rc22;
        END LOOP;
        CLOSE c_rc22;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rc22 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rc23]
    BEGIN
        DECLARE v_prod_rc23 INTEGER DEFAULT 0;
        DECLARE v_rm_rc23 INTEGER DEFAULT 0;
        DECLARE v_supp_rc23 INTEGER DEFAULT 0;
        DECLARE v_qper_rc23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rc23 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rc23 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rc23 INTEGER DEFAULT 0;
        DECLARE c_rc23 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc23 = 1;
        OPEN c_rc23;
        loop_rc23: LOOP
            FETCH c_rc23 INTO v_prod_rc23, v_rm_rc23, v_supp_rc23, v_qper_rc23, v_uc_rc23;
            IF v_done_rc23 = 1 THEN LEAVE loop_rc23; END IF;
            SET v_roll_rc23 = v_roll_rc23 + COALESCE(v_qper_rc23,0) * COALESCE(v_uc_rc23,0);
        END LOOP;
        CLOSE c_rc23;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rc23 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rc24]
    BEGIN
        DECLARE v_acct_rc24 INTEGER DEFAULT 0;
        DECLARE v_deb_rc24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rc24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rc24 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc24 INTEGER DEFAULT 0;
        DECLARE c_rc24 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc24 = 1;
        OPEN c_rc24;
        loop_rc24: LOOP
            FETCH c_rc24 INTO v_acct_rc24, v_deb_rc24, v_cred_rc24;
            IF v_done_rc24 = 1 THEN LEAVE loop_rc24; END IF;
            SET v_net_rc24 = v_net_rc24 + (v_deb_rc24 - v_cred_rc24);
        END LOOP;
        CLOSE c_rc24;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rc24 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rc25]
    BEGIN
        DECLARE v_pid_rc25 INTEGER DEFAULT 0;
        DECLARE v_lp_rc25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rc25 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rc25 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rc25 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rc25 INTEGER DEFAULT 0;
        DECLARE c_rc25 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc25 = 1;
        OPEN c_rc25;
        loop_rc25: LOOP
            FETCH c_rc25 INTO v_pid_rc25, v_lp_rc25, v_pp_rc25;
            IF v_done_rc25 = 1 THEN LEAVE loop_rc25; END IF;
            SET v_var_rc25 = v_var_rc25 + (COALESCE(v_lp_rc25,0) - COALESCE(v_pp_rc25,0));
            SET v_marg_rc25 = ERP_FN_MARGIN(v_pid_rc25);
        END LOOP;
        CLOSE c_rc25;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rc25 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rc26]
    BEGIN
        DECLARE v_inv_rc26 INTEGER DEFAULT 0;
        DECLARE v_amt_rc26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rc26 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rc26 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc26 INTEGER DEFAULT 0;
        DECLARE c_rc26 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc26 = 1;
        OPEN c_rc26;
        loop_rc26: LOOP
            FETCH c_rc26 INTO v_inv_rc26, v_amt_rc26, v_alloc_rc26;
            IF v_done_rc26 = 1 THEN LEAVE loop_rc26; END IF;
            SET v_open_rc26 = v_open_rc26 + (v_amt_rc26 - v_alloc_rc26);
        END LOOP;
        CLOSE c_rc26;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rc26 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rc27]
    BEGIN
        DECLARE v_lvl_rc27 INTEGER DEFAULT 0;
        DECLARE v_dept_rc27 INTEGER DEFAULT 0;
        DECLARE v_head_rc27 INTEGER DEFAULT 0;
        DECLARE v_done_rc27 INTEGER DEFAULT 0;
        DECLARE c_rc27 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc27 = 1;
        OPEN c_rc27;
        loop_rc27: LOOP
            FETCH c_rc27 INTO v_dept_rc27, v_lvl_rc27, v_head_rc27;
            IF v_done_rc27 = 1 THEN LEAVE loop_rc27; END IF;
        END LOOP;
        CLOSE c_rc27;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rc27, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rc27)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rc28]
    BEGIN
        DECLARE v_sh_rc28 INTEGER DEFAULT 0;
        DECLARE v_car_rc28 INTEGER DEFAULT 0;
        DECLARE v_qty_rc28 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rc28 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rc28 INTEGER DEFAULT 0;
        DECLARE c_rc28 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc28 = 1;
        OPEN c_rc28;
        loop_rc28: LOOP
            FETCH c_rc28 INTO v_sh_rc28, v_car_rc28, v_qty_rc28;
            IF v_done_rc28 = 1 THEN LEAVE loop_rc28; END IF;
            SET v_tot_rc28 = v_tot_rc28 + v_qty_rc28;
        END LOOP;
        CLOSE c_rc28;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rc28 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rc29]
    BEGIN
        DECLARE v_sql_rc29 VARCHAR(1000);
        DECLARE v_n_rc29 INTEGER DEFAULT 0;
        SET v_sql_rc29 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rc29 FROM v_sql_rc29;
        EXECUTE st_rc29;
        SELECT COUNT(*) INTO v_n_rc29 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rc29, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rc30]
    BEGIN
        DECLARE v_key_rc30 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rc30 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rc30' AS VARCHAR(40)), v_key_rc30)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rc31]
    BEGIN
        DECLARE v_so_rc31 INTEGER DEFAULT 0;
        DECLARE v_cust_rc31 INTEGER DEFAULT 0;
        DECLARE v_rk_rc31 INTEGER DEFAULT 0;
        DECLARE v_run_rc31 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc31 INTEGER DEFAULT 0;
        DECLARE c_rc31 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc31 = 1;
        OPEN c_rc31;
        loop_rc31: LOOP
            FETCH c_rc31 INTO v_so_rc31, v_cust_rc31, v_rk_rc31, v_run_rc31;
            IF v_done_rc31 = 1 THEN LEAVE loop_rc31; END IF;
        END LOOP;
        CLOSE c_rc31;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rc31, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rc31)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rc32]
    BEGIN
        DECLARE v_hi_rc32 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rc32
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rc32, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rc33]
    BEGIN
        DECLARE v_pairs_rc33 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rc33
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rc33, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rc34]
    BEGIN
        DECLARE v_rows_rc34 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rc34 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rc34(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rc34 FROM SESSION.TMP_rc34;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rc34, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rc35]
    BEGIN
        DECLARE v_rc_rc35 INTEGER DEFAULT 0;
        DECLARE v_band_rc35 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rc35 = ROW_COUNT;
        SET v_band_rc35 = CASE
                            WHEN v_rc_rc35 = 0 THEN 'NONE'
                            WHEN v_rc_rc35 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rc35, 'COUNT', 'band=' || v_band_rc35, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rc36]
    BEGIN
        DECLARE v_i_rc36 INTEGER DEFAULT 0;
        SAVEPOINT sp_rc36 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rc36 < 4 DO
            SET v_i_rc36 = v_i_rc36 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rc36, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rc36;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rc36, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rc37]
    BEGIN
        DECLARE v_j_rc37 INTEGER DEFAULT 0;
        DECLARE v_sum_rc37 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rc37 = v_j_rc37 + 1;
        UNTIL v_j_rc37 >= 3 END REPEAT;
        FOR row_rc37 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rc37 = v_sum_rc37 + COALESCE(row_rc37.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rc37, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rc37 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rc38]
    BEGIN
        DECLARE v_n_rc38 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rc38
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rc38, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rc39]
    BEGIN
        DECLARE v_levels_rc39 INTEGER DEFAULT 0;
        DECLARE c_rc39 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rc39 = 0;
        OPEN c_rc39;
        FETCH c_rc39 INTO v_levels_rc39;
        CLOSE c_rc39;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rc39,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rc40]
    BEGIN
        DECLARE v_sql_rc40 VARCHAR(1000);
        DECLARE v_n_rc40 INTEGER DEFAULT 0;
        SET v_sql_rc40 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rc40 FROM v_sql_rc40;
        EXECUTE st_rc40;
        SELECT COUNT(*) INTO v_n_rc40 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rc40, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rc41]
    BEGIN
        DECLARE v_key_rc41 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rc41 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rc41' AS VARCHAR(40)), v_key_rc41)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rc42]
    BEGIN
        DECLARE v_so_rc42 INTEGER DEFAULT 0;
        DECLARE v_cust_rc42 INTEGER DEFAULT 0;
        DECLARE v_ctry_rc42 INTEGER DEFAULT 0;
        DECLARE v_ccy_rc42 INTEGER DEFAULT 0;
        DECLARE v_sub_rc42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rc42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rc42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rc42 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rc42 INTEGER DEFAULT 0;
        DECLARE v_done_rc42 INTEGER DEFAULT 0;
        DECLARE c_rc42 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc42 = 1;
        OPEN c_rc42;
        loop_rc42: LOOP
            FETCH c_rc42 INTO v_so_rc42, v_cust_rc42, v_ctry_rc42, v_ccy_rc42, v_sub_rc42;
            IF v_done_rc42 = 1 THEN LEAVE loop_rc42; END IF;
            SET v_tax_rc42 = ERP_FN_TAX(v_ctry_rc42, v_sub_rc42);
            SET v_fx_rc42 = ERP_FN_FX_CONVERT(v_ccy_rc42, 1, v_sub_rc42 + v_tax_rc42);
            SET v_acc_rc42 = v_acc_rc42 + v_fx_rc42;
            SET v_cnt_rc42 = v_cnt_rc42 + 1;
        END LOOP;
        CLOSE c_rc42;
        IF v_cnt_rc42 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rc42, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rc42 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rc43]
    BEGIN
        DECLARE v_pid_rc43 INTEGER DEFAULT 0;
        DECLARE v_oh_rc43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rc43 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rc43 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rc43 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rc43 INTEGER DEFAULT 0;
        DECLARE c_rc43 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc43 = 1;
        OPEN c_rc43;
        loop_rc43: LOOP
            FETCH c_rc43 INTO v_pid_rc43, v_oh_rc43, v_cost_rc43;
            IF v_done_rc43 = 1 THEN LEAVE loop_rc43; END IF;
            SET v_avail_rc43 = ERP_FN_INVENTORY_ONHAND(v_pid_rc43);
            SET v_val_rc43 = v_val_rc43 + CAST(COALESCE(v_oh_rc43,0) * COALESCE(v_cost_rc43,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rc43, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rc43;
        END LOOP;
        CLOSE c_rc43;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rc43 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rc44]
    BEGIN
        DECLARE v_prod_rc44 INTEGER DEFAULT 0;
        DECLARE v_rm_rc44 INTEGER DEFAULT 0;
        DECLARE v_supp_rc44 INTEGER DEFAULT 0;
        DECLARE v_qper_rc44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rc44 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rc44 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rc44 INTEGER DEFAULT 0;
        DECLARE c_rc44 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc44 = 1;
        OPEN c_rc44;
        loop_rc44: LOOP
            FETCH c_rc44 INTO v_prod_rc44, v_rm_rc44, v_supp_rc44, v_qper_rc44, v_uc_rc44;
            IF v_done_rc44 = 1 THEN LEAVE loop_rc44; END IF;
            SET v_roll_rc44 = v_roll_rc44 + COALESCE(v_qper_rc44,0) * COALESCE(v_uc_rc44,0);
        END LOOP;
        CLOSE c_rc44;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rc44 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rc45]
    BEGIN
        DECLARE v_acct_rc45 INTEGER DEFAULT 0;
        DECLARE v_deb_rc45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rc45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rc45 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc45 INTEGER DEFAULT 0;
        DECLARE c_rc45 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc45 = 1;
        OPEN c_rc45;
        loop_rc45: LOOP
            FETCH c_rc45 INTO v_acct_rc45, v_deb_rc45, v_cred_rc45;
            IF v_done_rc45 = 1 THEN LEAVE loop_rc45; END IF;
            SET v_net_rc45 = v_net_rc45 + (v_deb_rc45 - v_cred_rc45);
        END LOOP;
        CLOSE c_rc45;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rc45 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- price list vs list price variance (multi-join) [rc46]
    BEGIN
        DECLARE v_pid_rc46 INTEGER DEFAULT 0;
        DECLARE v_lp_rc46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_pp_rc46 DECIMAL(14,2) DEFAULT 0;
        DECLARE v_var_rc46 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_marg_rc46 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rc46 INTEGER DEFAULT 0;
        DECLARE c_rc46 CURSOR FOR
            SELECT p.id, p.list_price, pp.price
            FROM ERP_PRODUCT p
            JOIN ERP_PRODUCT_PRICE pp ON pp.product_id = p.id
            JOIN ERP_PRICE_LIST pl ON pl.id = pp.price_list_id
            JOIN ERP_PRODUCT_CATEGORY pc ON pc.id = p.category_id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc46 = 1;
        OPEN c_rc46;
        loop_rc46: LOOP
            FETCH c_rc46 INTO v_pid_rc46, v_lp_rc46, v_pp_rc46;
            IF v_done_rc46 = 1 THEN LEAVE loop_rc46; END IF;
            SET v_var_rc46 = v_var_rc46 + (COALESCE(v_lp_rc46,0) - COALESCE(v_pp_rc46,0));
            SET v_marg_rc46 = ERP_FN_MARGIN(v_pid_rc46);
        END LOOP;
        CLOSE c_rc46;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('PRICE_VAR', 0, 'SCAN', 'variance=' || RTRIM(CHAR(CAST(v_var_rc46 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- payment allocation / open AR coverage [rc47]
    BEGIN
        DECLARE v_inv_rc47 INTEGER DEFAULT 0;
        DECLARE v_amt_rc47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_alloc_rc47 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_open_rc47 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc47 INTEGER DEFAULT 0;
        DECLARE c_rc47 CURSOR FOR
            SELECT i.id, COALESCE(i.amount,0), COALESCE(SUM(pa.amount),0)
            FROM ERP_INVOICE i
            LEFT JOIN ERP_PAYMENT_ALLOC pa ON pa.invoice_id = i.id
            LEFT JOIN ERP_PAYMENT pay ON pay.id = pa.payment_id
            GROUP BY i.id, i.amount
            ORDER BY i.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc47 = 1;
        OPEN c_rc47;
        loop_rc47: LOOP
            FETCH c_rc47 INTO v_inv_rc47, v_amt_rc47, v_alloc_rc47;
            IF v_done_rc47 = 1 THEN LEAVE loop_rc47; END IF;
            SET v_open_rc47 = v_open_rc47 + (v_amt_rc47 - v_alloc_rc47);
        END LOOP;
        CLOSE c_rc47;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('AR_OPEN', 0, 'SCAN', 'open_ar=' || RTRIM(CHAR(CAST(v_open_rc47 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- department staffing via RECURSIVE CTE (depth-guarded) [rc48]
    BEGIN
        DECLARE v_lvl_rc48 INTEGER DEFAULT 0;
        DECLARE v_dept_rc48 INTEGER DEFAULT 0;
        DECLARE v_head_rc48 INTEGER DEFAULT 0;
        DECLARE v_done_rc48 INTEGER DEFAULT 0;
        DECLARE c_rc48 CURSOR FOR
            WITH dh (dept_id, parent_id, lvl) AS (
                SELECT d.id, d.parent_id, CAST(1 AS INTEGER)
                FROM ERP_DEPARTMENT d WHERE d.parent_id IS NULL
                UNION ALL
                SELECT d2.id, d2.parent_id, dh.lvl + 1
                FROM ERP_DEPARTMENT d2 JOIN dh ON d2.parent_id = dh.dept_id
                WHERE dh.lvl < 10
            )
            SELECT dh.dept_id, dh.lvl, COUNT(e.id)
            FROM dh LEFT JOIN ERP_EMPLOYEE e ON e.dept_id = dh.dept_id
            GROUP BY dh.dept_id, dh.lvl
            ORDER BY dh.dept_id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc48 = 1;
        OPEN c_rc48;
        loop_rc48: LOOP
            FETCH c_rc48 INTO v_dept_rc48, v_lvl_rc48, v_head_rc48;
            IF v_done_rc48 = 1 THEN LEAVE loop_rc48; END IF;
        END LOOP;
        CLOSE c_rc48;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DEPT_HIER', v_dept_rc48, 'SCAN', 'depth=' || RTRIM(CHAR(v_lvl_rc48)), CURRENT TIMESTAMP);
    END;
    -- shipment fulfilment scan (carrier join) [rc49]
    BEGIN
        DECLARE v_sh_rc49 INTEGER DEFAULT 0;
        DECLARE v_car_rc49 INTEGER DEFAULT 0;
        DECLARE v_qty_rc49 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_tot_rc49 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rc49 INTEGER DEFAULT 0;
        DECLARE c_rc49 CURSOR FOR
            SELECT sh.id, sh.carrier_id, COALESCE(SUM(sl.qty_shipped),0)
            FROM ERP_SHIPMENT sh
            JOIN ERP_CARRIER ca ON ca.id = sh.carrier_id
            LEFT JOIN ERP_SHIPMENT_LINE sl ON sl.shipment_id = sh.id
            GROUP BY sh.id, sh.carrier_id
            ORDER BY sh.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc49 = 1;
        OPEN c_rc49;
        loop_rc49: LOOP
            FETCH c_rc49 INTO v_sh_rc49, v_car_rc49, v_qty_rc49;
            IF v_done_rc49 = 1 THEN LEAVE loop_rc49; END IF;
            SET v_tot_rc49 = v_tot_rc49 + v_qty_rc49;
        END LOOP;
        CLOSE c_rc49;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SHIP_SCAN', 0, 'SCAN', 'units=' || RTRIM(CHAR(CAST(v_tot_rc49 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rc50]
    BEGIN
        DECLARE v_sql_rc50 VARCHAR(1000);
        DECLARE v_n_rc50 INTEGER DEFAULT 0;
        SET v_sql_rc50 = 'UPDATE ERP_SALES_ORDER SET status = status WHERE status IS NOT NULL';
        PREPARE st_rc50 FROM v_sql_rc50;
        EXECUTE st_rc50;
        SELECT COUNT(*) INTO v_n_rc50 FROM ERP_SALES_ORDER WHERE status IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rc50, 'MAINT', 'tbl=ERP_SALES_ORDER', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rc51]
    BEGIN
        DECLARE v_key_rc51 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rc51 FROM ERP_SALES_ORDER_LINE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rc51' AS VARCHAR(40)), v_key_rc51)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_SALES_ORDER_LINE', CURRENT TIMESTAMP);
    END;
    -- OLAP window functions: revenue rank per customer [rc52]
    BEGIN
        DECLARE v_so_rc52 INTEGER DEFAULT 0;
        DECLARE v_cust_rc52 INTEGER DEFAULT 0;
        DECLARE v_rk_rc52 INTEGER DEFAULT 0;
        DECLARE v_run_rc52 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc52 INTEGER DEFAULT 0;
        DECLARE c_rc52 CURSOR FOR
            SELECT so.id, so.customer_id,
                   RANK() OVER (PARTITION BY so.customer_id ORDER BY so.subtotal DESC),
                   SUM(so.subtotal) OVER (PARTITION BY so.customer_id ORDER BY so.id
                        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
            FROM ERP_SALES_ORDER so
            WHERE so.subtotal >= 0
            ORDER BY so.customer_id, so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc52 = 1;
        OPEN c_rc52;
        loop_rc52: LOOP
            FETCH c_rc52 INTO v_so_rc52, v_cust_rc52, v_rk_rc52, v_run_rc52;
            IF v_done_rc52 = 1 THEN LEAVE loop_rc52; END IF;
        END LOOP;
        CLOSE c_rc52;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('OLAP_RANK', v_so_rc52, 'SCAN', 'rank=' || RTRIM(CHAR(v_rk_rc52)), CURRENT TIMESTAMP);
    END;
    -- deeply nested + correlated subqueries [rc53]
    BEGIN
        DECLARE v_hi_rc53 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_hi_rc53
        FROM ERP_CUSTOMER c
        WHERE c.id IN (
            SELECT so.customer_id FROM ERP_SALES_ORDER so
            WHERE so.subtotal > (
                SELECT COALESCE(AVG(so2.subtotal),0) FROM ERP_SALES_ORDER so2
                WHERE so2.customer_id = so.customer_id
                  AND so2.id IN (SELECT sol.so_id FROM ERP_SALES_ORDER_LINE sol
                                 WHERE sol.qty > 0)
            )
        );
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SUBQ', v_hi_rc53, 'SCAN', 'above_avg_customers', CURRENT TIMESTAMP);
    END;
    -- self-join of department parent/child + COALESCE/VALUE [rc54]
    BEGIN
        DECLARE v_pairs_rc54 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_pairs_rc54
        FROM ERP_DEPARTMENT child
        LEFT JOIN ERP_DEPARTMENT parent ON parent.id = child.parent_id
        WHERE COALESCE(parent.id, VALUE(child.parent_id, 0)) >= 0;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SELF_JOIN', v_pairs_rc54, 'SCAN', 'dept_pairs', CURRENT TIMESTAMP);
    END;
    -- DECLARE GLOBAL TEMPORARY TABLE + INSERT/SELECT [rc55]
    BEGIN
        DECLARE v_rows_rc55 INTEGER DEFAULT 0;
        DECLARE GLOBAL TEMPORARY TABLE SESSION.TMP_rc55 (
            product_id INTEGER, on_hand DECIMAL(16,4)
        ) ON COMMIT PRESERVE ROWS NOT LOGGED WITH REPLACE;
        INSERT INTO SESSION.TMP_rc55(product_id, on_hand)
        SELECT p.id, COALESCE(SUM(i.on_hand),0)
        FROM ERP_PRODUCT p LEFT JOIN ERP_INVENTORY i ON i.product_id = p.id
        GROUP BY p.id;
        SELECT COUNT(*) INTO v_rows_rc55 FROM SESSION.TMP_rc55;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GTT', v_rows_rc55, 'STAGE', 'temp rows staged', CURRENT TIMESTAMP);
    END;
    -- GET DIAGNOSTICS row count + CASE banding [rc56]
    BEGIN
        DECLARE v_rc_rc56 INTEGER DEFAULT 0;
        DECLARE v_band_rc56 VARCHAR(10);
        UPDATE ERP_SALES_ORDER SET status = status WHERE subtotal >= 0;
        GET DIAGNOSTICS v_rc_rc56 = ROW_COUNT;
        SET v_band_rc56 = CASE
                            WHEN v_rc_rc56 = 0 THEN 'NONE'
                            WHEN v_rc_rc56 < 5 THEN 'FEW'
                            ELSE 'MANY'
                         END;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DIAG', v_rc_rc56, 'COUNT', 'band=' || v_band_rc56, CURRENT TIMESTAMP);
    END;
    -- SAVEPOINT / ROLLBACK TO SAVEPOINT with retained cursors [rc57]
    BEGIN
        DECLARE v_i_rc57 INTEGER DEFAULT 0;
        SAVEPOINT sp_rc57 ON ROLLBACK RETAIN CURSORS;
        WHILE v_i_rc57 < 4 DO
            SET v_i_rc57 = v_i_rc57 + 1;
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('SP_ITER', v_i_rc57, 'ITER', 'scratch row', CURRENT TIMESTAMP);
        END WHILE;
        ROLLBACK TO SAVEPOINT sp_rc57;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('SP_DONE', v_i_rc57, 'DONE', 'iterations discarded', CURRENT TIMESTAMP);
    END;
    -- REPEAT loop + FOR loop over a query [rc58]
    BEGIN
        DECLARE v_j_rc58 INTEGER DEFAULT 0;
        DECLARE v_sum_rc58 DECIMAL(18,2) DEFAULT 0;
        REPEAT
            SET v_j_rc58 = v_j_rc58 + 1;
        UNTIL v_j_rc58 >= 3 END REPEAT;
        FOR row_rc58 AS
            SELECT id, subtotal FROM ERP_SALES_ORDER WHERE subtotal >= 0 ORDER BY id
        DO
            SET v_sum_rc58 = v_sum_rc58 + COALESCE(row_rc58.subtotal, 0);
        END FOR;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('LOOPS', v_j_rc58, 'DONE', 'sum=' || RTRIM(CHAR(CAST(v_sum_rc58 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- all join types: INNER/LEFT/RIGHT/FULL/CROSS [rc59]
    BEGIN
        DECLARE v_n_rc59 INTEGER DEFAULT 0;
        SELECT COUNT(*) INTO v_n_rc59
        FROM ERP_SALES_ORDER so
        INNER JOIN ERP_CUSTOMER c ON c.id = so.customer_id
        LEFT JOIN ERP_INVOICE i ON i.so_id = so.id
        RIGHT JOIN ERP_SALES_ORDER_LINE sol ON sol.so_id = so.id
        FULL JOIN ERP_SHIPMENT sh ON sh.so_id = so.id
        CROSS JOIN ERP_CURRENCY cur
        WHERE cur.id = so.ccy_id;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('JOINS', v_n_rc59, 'SCAN', 'join_matrix', CURRENT TIMESTAMP);
    END;
    -- RECURSIVE CTE: multi-level BOM explosion (depth-guarded) [rc60]
    BEGIN
        DECLARE v_levels_rc60 INTEGER DEFAULT 0;
        DECLARE c_rc60 CURSOR FOR
            WITH bom_tree (product_id, raw_material_id, lvl) AS (
                SELECT b.product_id, b.raw_material_id, CAST(1 AS INTEGER)
                FROM ERP_BOM b WHERE b.parent_bom_id IS NULL
                UNION ALL
                SELECT b2.product_id, b2.raw_material_id, bt.lvl + 1
                FROM ERP_BOM b2 JOIN bom_tree bt ON b2.parent_bom_id = bt.raw_material_id
                WHERE bt.lvl < 8
            )
            SELECT MAX(lvl) FROM bom_tree;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_levels_rc60 = 0;
        OPEN c_rc60;
        FETCH c_rc60 INTO v_levels_rc60;
        CLOSE c_rc60;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_TREE', COALESCE(v_levels_rc60,0), 'SCAN', 'max_depth', CURRENT TIMESTAMP);
    END;
    -- dynamic SQL maintenance pass (PREPARE/EXECUTE) [rc61]
    BEGIN
        DECLARE v_sql_rc61 VARCHAR(1000);
        DECLARE v_n_rc61 INTEGER DEFAULT 0;
        SET v_sql_rc61 = 'UPDATE ERP_INVENTORY SET reserved = reserved WHERE reserved IS NOT NULL';
        PREPARE st_rc61 FROM v_sql_rc61;
        EXECUTE st_rc61;
        SELECT COUNT(*) INTO v_n_rc61 FROM ERP_INVENTORY WHERE reserved IS NOT NULL;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('DYN_SQL', v_n_rc61, 'MAINT', 'tbl=ERP_INVENTORY', CURRENT TIMESTAMP);
    END;
    -- MERGE upsert of run statistics [rc62]
    BEGIN
        DECLARE v_key_rc62 INTEGER DEFAULT 0;
        SELECT COALESCE(COUNT(*),0) INTO v_key_rc62 FROM ERP_INVOICE;
        MERGE INTO ERP_AUDIT_LOG AS tgt
        USING (VALUES (CAST('STAT_rc62' AS VARCHAR(40)), v_key_rc62)) AS src(ent, cnt)
        ON tgt.entity = src.ent AND tgt.entity_id = src.cnt
        WHEN NOT MATCHED THEN
            INSERT (entity, entity_id, action, detail, logged_ts)
            VALUES (src.ent, src.cnt, 'MERGE', 'rows in ERP_INVOICE', CURRENT TIMESTAMP);
    END;
    -- order/customer/country/currency revenue scan [rc63]
    BEGIN
        DECLARE v_so_rc63 INTEGER DEFAULT 0;
        DECLARE v_cust_rc63 INTEGER DEFAULT 0;
        DECLARE v_ctry_rc63 INTEGER DEFAULT 0;
        DECLARE v_ccy_rc63 INTEGER DEFAULT 0;
        DECLARE v_sub_rc63 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_fx_rc63 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_tax_rc63 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_acc_rc63 DECIMAL(16,2) DEFAULT 0;
        DECLARE v_cnt_rc63 INTEGER DEFAULT 0;
        DECLARE v_done_rc63 INTEGER DEFAULT 0;
        DECLARE c_rc63 CURSOR FOR
            SELECT so.id, so.customer_id, c.country_id, so.ccy_id, so.subtotal
            FROM ERP_SALES_ORDER so
            JOIN ERP_CUSTOMER c ON c.id = so.customer_id
            JOIN ERP_COUNTRY ctry ON ctry.id = c.country_id
            JOIN ERP_CURRENCY cur ON cur.id = so.ccy_id
            WHERE so.subtotal >= 0
            ORDER BY so.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc63 = 1;
        OPEN c_rc63;
        loop_rc63: LOOP
            FETCH c_rc63 INTO v_so_rc63, v_cust_rc63, v_ctry_rc63, v_ccy_rc63, v_sub_rc63;
            IF v_done_rc63 = 1 THEN LEAVE loop_rc63; END IF;
            SET v_tax_rc63 = ERP_FN_TAX(v_ctry_rc63, v_sub_rc63);
            SET v_fx_rc63 = ERP_FN_FX_CONVERT(v_ccy_rc63, 1, v_sub_rc63 + v_tax_rc63);
            SET v_acc_rc63 = v_acc_rc63 + v_fx_rc63;
            SET v_cnt_rc63 = v_cnt_rc63 + 1;
        END LOOP;
        CLOSE c_rc63;
        IF v_cnt_rc63 > 0 THEN
            INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
            VALUES ('REV_SCAN', v_cnt_rc63, 'SCAN',
                    'usd_revenue=' || RTRIM(CHAR(CAST(v_acc_rc63 AS INTEGER))), CURRENT TIMESTAMP);
        END IF;
    END;
    -- inventory valuation across product/location/warehouse [rc64]
    BEGIN
        DECLARE v_pid_rc64 INTEGER DEFAULT 0;
        DECLARE v_oh_rc64 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_cost_rc64 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_val_rc64 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_avail_rc64 DECIMAL(16,4) DEFAULT 0;
        DECLARE v_done_rc64 INTEGER DEFAULT 0;
        DECLARE c_rc64 CURSOR FOR
            SELECT p.id, SUM(i.on_hand), MAX(p.std_cost)
            FROM ERP_INVENTORY i
            JOIN ERP_PRODUCT p ON p.id = i.product_id
            JOIN ERP_LOCATION l ON l.id = i.location_id
            JOIN ERP_WAREHOUSE w ON w.id = l.warehouse_id
            GROUP BY p.id
            ORDER BY p.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc64 = 1;
        OPEN c_rc64;
        loop_rc64: LOOP
            FETCH c_rc64 INTO v_pid_rc64, v_oh_rc64, v_cost_rc64;
            IF v_done_rc64 = 1 THEN LEAVE loop_rc64; END IF;
            SET v_avail_rc64 = ERP_FN_INVENTORY_ONHAND(v_pid_rc64);
            SET v_val_rc64 = v_val_rc64 + CAST(COALESCE(v_oh_rc64,0) * COALESCE(v_cost_rc64,0) AS DECIMAL(18,2));
            INSERT INTO ERP_INVENTORY_TXN(inventory_id, txn_type, qty, txn_ts)
            SELECT MIN(i2.id), 'VALUE', v_avail_rc64, CURRENT TIMESTAMP
            FROM ERP_INVENTORY i2 WHERE i2.product_id = v_pid_rc64;
        END LOOP;
        CLOSE c_rc64;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('INV_VAL', 0, 'VALUE', 'total=' || RTRIM(CHAR(CAST(v_val_rc64 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- BOM explosion supplier cost roll-up [rc65]
    BEGIN
        DECLARE v_prod_rc65 INTEGER DEFAULT 0;
        DECLARE v_rm_rc65 INTEGER DEFAULT 0;
        DECLARE v_supp_rc65 INTEGER DEFAULT 0;
        DECLARE v_qper_rc65 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_uc_rc65 DECIMAL(14,4) DEFAULT 0;
        DECLARE v_roll_rc65 DECIMAL(18,4) DEFAULT 0;
        DECLARE v_done_rc65 INTEGER DEFAULT 0;
        DECLARE c_rc65 CURSOR FOR
            SELECT b.product_id, b.raw_material_id, rm.supplier_id, b.qty_per, rm.unit_cost
            FROM ERP_BOM b
            JOIN ERP_RAW_MATERIAL rm ON rm.id = b.raw_material_id
            JOIN ERP_SUPPLIER sup ON sup.id = rm.supplier_id
            ORDER BY b.product_id, b.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc65 = 1;
        OPEN c_rc65;
        loop_rc65: LOOP
            FETCH c_rc65 INTO v_prod_rc65, v_rm_rc65, v_supp_rc65, v_qper_rc65, v_uc_rc65;
            IF v_done_rc65 = 1 THEN LEAVE loop_rc65; END IF;
            SET v_roll_rc65 = v_roll_rc65 + COALESCE(v_qper_rc65,0) * COALESCE(v_uc_rc65,0);
        END LOOP;
        CLOSE c_rc65;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('BOM_COST', 0, 'ROLLUP', 'material_cost=' || RTRIM(CHAR(CAST(v_roll_rc65 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- GL account reconciliation (LEFT JOIN + GROUP BY) [rc66]
    BEGIN
        DECLARE v_acct_rc66 INTEGER DEFAULT 0;
        DECLARE v_deb_rc66 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_cred_rc66 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_net_rc66 DECIMAL(18,2) DEFAULT 0;
        DECLARE v_done_rc66 INTEGER DEFAULT 0;
        DECLARE c_rc66 CURSOR FOR
            SELECT ga.id, COALESCE(SUM(ge.debit),0), COALESCE(SUM(ge.credit),0)
            FROM ERP_GL_ACCOUNT ga
            LEFT JOIN ERP_GL_ENTRY ge ON ge.account_id = ga.id
            GROUP BY ga.id
            ORDER BY ga.id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done_rc66 = 1;
        OPEN c_rc66;
        loop_rc66: LOOP
            FETCH c_rc66 INTO v_acct_rc66, v_deb_rc66, v_cred_rc66;
            IF v_done_rc66 = 1 THEN LEAVE loop_rc66; END IF;
            SET v_net_rc66 = v_net_rc66 + (v_deb_rc66 - v_cred_rc66);
        END LOOP;
        CLOSE c_rc66;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('GL_RECON', 0, 'RECON', 'net=' || RTRIM(CHAR(CAST(v_net_rc66 AS INTEGER))), CURRENT TIMESTAMP);
    END;
    -- deep linear stage chain: STAGE_01 -> STAGE_02 -> ... -> STAGE_16
    CALL ERP_USP_STAGE_01(1);
    CALL ERP_USP_TOUCH_VIEWS();
    CALL ERP_USP_EDGE_OPS();
    CALL ERP_USP_PROCESS_DAY(CURRENT DATE);
    -- direct self-recursion (depth-guarded) over the BOM tree
    CALL ERP_USP_EXPLODE_BOM(1, 1);
    -- mutual/circular recursion (depth-guarded): WALK_UP <-> WALK_DOWN
    CALL ERP_USP_WALK_UP(6, 1);
    CALL ERP_USP_REPORT_AR();
    CALL ERP_USP_CLOSE_PERIOD(ERP_FN_FISCAL_PERIOD(CURRENT DATE));
    CALL ERP_USP_ARCHIVE_AUDIT(365);
    CALL DB2INST1.ERP_USP_XSCHEMA_TOUCH();
    CALL ERP_USP_AUDIT('CYCLE', ERP_GV_RUN_ID, 'DONE', 'cycle complete');
    COMMIT;
END @

-- ---------------------------------------------------------------------------
-- MODULE (~ package) bundling pricing routines
-- ---------------------------------------------------------------------------
CREATE MODULE ERP_MOD_PRICING @

ALTER MODULE ERP_MOD_PRICING PUBLISH
    FUNCTION NET_PRICE(p_product_id INTEGER, p_qty DECIMAL(16,2))
    RETURNS DECIMAL(16,2)
    BEGIN
        DECLARE v_list DECIMAL(16,2) DEFAULT 0;
        DECLARE v_disc DECIMAL(16,2) DEFAULT 0;
        SET v_list = (SELECT COALESCE(list_price,0) FROM ERP_PRODUCT WHERE id = p_product_id);
        SET v_disc = ERP_FN_DISCOUNT_PCT(0, p_qty);
        RETURN v_list * (1 - v_disc/100) * COALESCE(p_qty,0);
    END @

ALTER MODULE ERP_MOD_PRICING PUBLISH
    PROCEDURE REPRICE_ORDER(IN p_so_id INTEGER)
    BEGIN
        DECLARE v_pid INTEGER DEFAULT 0;
        DECLARE v_qty DECIMAL(16,2) DEFAULT 0;
        DECLARE v_done INTEGER DEFAULT 0;
        DECLARE c_ln CURSOR FOR
            SELECT product_id, qty FROM ERP_SALES_ORDER_LINE WHERE so_id = p_so_id ORDER BY id;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
        OPEN c_ln;
        rp_loop: LOOP
            FETCH c_ln INTO v_pid, v_qty;
            IF v_done = 1 THEN LEAVE rp_loop; END IF;
            UPDATE ERP_SALES_ORDER_LINE
               SET unit_price = ERP_MOD_PRICING.NET_PRICE(v_pid, 1)
             WHERE so_id = p_so_id AND product_id = v_pid;
        END LOOP;
        CLOSE c_ln;
        INSERT INTO ERP_AUDIT_LOG(entity, entity_id, action, detail, logged_ts)
        VALUES ('REPRICE', p_so_id, 'DONE', 'order repriced', CURRENT TIMESTAMP);
    END @

-- ============================================================================
-- End of Db2 ERP demo seed
-- ============================================================================
